-- بيانات مقرر كيمياء 2-2 (المقرر 3، قيد الإعداد) — الجزء 6 من 7. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem22-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L1-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الصيغة العامة لهاليدات الألكيل؟', null, null, '["R–X","R–OH","R–NH₂","R–O–R′"]'::jsonb, 'تذكر', 'تذكر صيغة عامة', 'سهل', 'الكتاب ص 169 — هاليدات الألكيل والجدول 5-1'),
('mcq', 2, 'ما نوع المركبات العضوية التي تمثلها الصيغة العامة الآتية؟', null, '[{"src":"qimg/chem22/c5-l1a-aryl-general.svg","alt":"حلقة بنزين سداسية مرسومة بدائرة داخل السداسي، وترتبط بإحدى ذرات كربون الحلقة (الرأس العلوي) رابطة أحادية تنتهي بالرمز X. وتحت الحلقة مكتوب: X = F, Cl, Br, I."}]'::jsonb, '["هاليدات الألكيل","الهيدروكربونات الأروماتية","هاليدات الأريل","الكحولات الأروماتية"]'::jsonb, 'تذكر', 'تعرف صيغة عامة', 'سهل', 'الكتاب ص 170 — هاليدات الأريل'),
('mcq', 3, 'في الصيغة العامة R–X، ماذا يمثل الرمز X؟', null, null, '["مجموعة الهيدروكسيل OH المرتبطة بالكربون","ذرة هالوجين مثل F أو Cl أو Br أو I","ذرة هيدروجين مرتبطة بذرة الكربون","سلسلة أو حلقة من ذرات الكربون"]'::jsonb, 'تذكر', 'تفسير رموز الصيغة العامة', 'سهل', 'الكتاب ص 169 — هاليدات الألكيل والجدول 5-1'),
('mcq', 4, 'أيّ الصيغ الآتية تمثل هاليد أريل؟', null, '[{"src":"qimg/chem22/c5-l1a-which-aryl.svg","alt":"أربع صيغ في شبكة من عمودين، (أ) أعلى اليمين و(ب) أعلى اليسار و(ج) أسفل اليمين و(د) أسفل اليسار. (أ): حلقة سداسية بخطوط أحادية فقط دون دائرة داخلها (حلقة مشبعة)، ترتبط بإحدى ذراتها ذرة Cl. (ب): الصيغة المكثفة CH₃–CH₂–Cl. (ج): حلقة سداسية بداخلها دائرة (حلقة بنزين) ترتبط بإحدى ذراتها ذرة Cl. (د): حلقة سداسية بداخلها دائرة (حلقة بنزين) ترتبط بإحدى ذراتها مجموعة CH₃."}]'::jsonb, '["(أ)","(ب)","(ج)","(د)"]'::jsonb, 'فهم', 'تمييز نوع المركب من الصيغة', 'متوسط', 'الكتاب ص 170 — هاليدات الأريل'),
('mcq', 5, 'في هاليدات الألكيل، بأيّ ذرة ترتبط ذرة الهالوجين، وما نوع الرابطة؟', null, null, '["بذرة كربون في حلقة بنزين برابطة تساهمية","بذرة كربون أليفاتية برابطة أيونية","بذرة هيدروجين برابطة تساهمية","بذرة كربون أليفاتية برابطة تساهمية"]'::jsonb, 'فهم', 'تفسير الصيغة العامة', 'متوسط', 'الكتاب ص 169 — هاليدات الألكيل والجدول 5-1'),
('mcq', 6, 'صنّف المركبات في الشكل الآتي إلى هاليدات ألكيل وهاليدات أريل.', null, '[{"src":"qimg/chem22/c5-l1a-classify4.svg","alt":"أربع صيغ في شبكة من عمودين، (أ) أعلى اليمين و(ب) أعلى اليسار و(ج) أسفل اليمين و(د) أسفل اليسار. (أ): حلقة بنزين (سداسي بداخله دائرة) ترتبط بإحدى ذراتها ذرة Br. (ب): صيغة مكثفة CH₃–CH–CH₃ ترتبط بذرة الكربون الوسطى CH ذرة Cl من الأعلى. (ج): صيغة بنائية كاملة لذرة كربون واحدة مرتبطة بثلاث ذرات هيدروجين (يسار وأعلى وأسفل) وبذرة I عن يمينها. (د): حلقة بنزين ترتبط بها ذرتا Cl، إحداهما على الذرة العليا والأخرى على الذرة السفلى المقابلة لها."}]'::jsonb, '["الأريل: (أ) و(د)، والألكيل: (ب) و(ج)","الأريل: (أ) فقط، والألكيل: (ب) و(ج) و(د)","الأريل: (ب) و(ج)، والألكيل: (أ) و(د)","الأريل: (أ) و(ب) و(د)، والألكيل: (ج)"]'::jsonb, 'تطبيق', 'تصنيف', 'صعب', 'الكتاب ص 170 — هاليدات الأريل'),
('mcq', 7, 'إلى أيّ صيغة عامة ينتمي المركب الذي يمثله الشكل الآتي، وما نوعه؟', null, '[{"src":"qimg/chem22/c5-l1a-bromoethane.svg","alt":"صيغة بنائية كاملة لذرتي كربون متصلتين برابطة أحادية في خط أفقي. ترتبط ذرة الكربون اليسرى بثلاث ذرات هيدروجين (يسار وأعلى وأسفل)، وترتبط ذرة الكربون اليمنى بذرتي هيدروجين (أعلى وأسفل) وبذرة Br عن يمينها."}]'::jsonb, '["R–X، وهو هاليد أريل","R–OH، وهو كحول","R–NH₂، وهو أمين","R–X، وهو هاليد ألكيل"]'::jsonb, 'تطبيق', 'ربط مركب بصيغته العامة', 'متوسط', 'الكتاب ص 169 — هاليدات الألكيل والجدول 5-1'),
('essay', 1, 'اكتب الصيغة العامة لهاليدات الألكيل، وصِف الصيغة العامة لهاليدات الأريل، موضحًا ما يمثله كل رمز فيهما.', null, null, null, 'تذكر', 'كتابة صيغة عامة وتوضيحها', 'سهل', 'الكتاب ص 169–170 — الجدول 5-1'),
('essay', 2, 'قارن بين هاليدات الألكيل وهاليدات الأريل من حيث: (أ) نوع ذرة الكربون التي ترتبط بها ذرة الهالوجين، (ب) الصيغة العامة، (ج) مثال على كل منهما بالاسم والصيغة.', null, null, null, 'فهم', 'مقارنة', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('essay', 3, 'حلقة بنزين حلت فيها ذرة يود محل ذرة هيدروجين واحدة. (أ) ما نوع هذا المركب؟ (ب) اكتب صيغته الجزيئية. (ج) اكتب الصيغة الجزيئية للمركب 1-أيودو هكسان، وبيّن نوعه والفرق بين الصيغتين، مع أن لكل منهما ست ذرات كربون وذرة يود واحدة.', null, null, null, 'تطبيق', 'كتابة صيغ وتصنيف', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'هاليد الألكيل مركب عضوي تحتوي فيه ذرة هالوجين أو أكثر مرتبطة برابطة تساهمية مع ذرة كربون أليفاتية؛ وصيغته العامة R–X، حيث R سلسلة كربونية وX ذرة هالوجين (F أو Cl أو Br أو I).', '["","R–OH الصيغة العامة للكحولات، ومجموعتها الوظيفية الهيدروكسيل.","R–NH₂ الصيغة العامة للأمينات، ومجموعتها الوظيفية الأمين.","R–O–R′ الصيغة العامة للإيثرات، ومجموعتها الوظيفية الإيثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 2, 2, 'تمثل الصيغة حلقة بنزين حلت فيها ذرة هالوجين X (F أو Cl أو Br أو I) محل ذرة هيدروجين؛ وهاليدات الأريل مركبات عضوية تتكون من هالوجين مرتبط مع حلقة البنزين أو مجموعة أروماتية أخرى.', '["في هاليدات الألكيل ترتبط ذرة الهالوجين بذرة كربون أليفاتية (R–X)، أما هنا فترتبط بحلقة البنزين.","الهيدروكربون يتكون من الكربون والهيدروجين فقط، والصيغة تحتوي على ذرة هالوجين X مكان ذرة هيدروجين.","","الكحولات تحتوي على مجموعة الهيدروكسيل OH، والرمز X في الصيغة يمثل ذرة هالوجين لا مجموعة OH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 3, 1, 'في الصيغة R–X يمثل R سلسلة أو حلقة كربونية، ويمثل X ذرة هالوجين (F أو Cl أو Br أو I) حلت محل ذرة هيدروجين في الألكان.', '["مجموعة OH تميّز الكحولات R–OH، لا هاليدات الألكيل.","","ذرة الهالوجين X هي التي تحل محل ذرة الهيدروجين في الألكان، فلا يمثل X ذرة هيدروجين.","السلسلة أو الحلقة الكربونية يمثلها الرمز R لا الرمز X."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 4, 2, 'هاليد الأريل هالوجين مرتبط مباشرة بحلقة البنزين. في (ج) ترتبط ذرة الكلور بحلقة بنزين (السداسي مع الدائرة)، فهو كلورو بنزين. أما (أ) فالكلور فيه مرتبط بحلقة مشبعة غير أروماتية، فهو هاليد ألكيل.', '["الحلقة في (أ) حلقة سداسية مشبعة (هكسان حلقي) وليست حلقة بنزين، فالمركب هاليد ألكيل.","(ب) CH₃CH₂Cl فيه ذرة الكلور مرتبطة بذرة كربون أليفاتية في سلسلة، فهو هاليد ألكيل.","","(د) حلقة بنزين ترتبط بها مجموعة ميثيل CH₃ لا ذرة هالوجين، فهو هيدروكربون أروماتي (تولوين)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 5, 3, 'هاليدات الألكيل مركبات عضوية تحتوي على ذرة هالوجين أو أكثر مرتبطة برابطة تساهمية مع ذرة كربون أليفاتية، ولذلك تكتب صيغتها العامة R–X.', '["ارتباط الهالوجين بذرة كربون في حلقة البنزين يميّز هاليدات الأريل لا الألكيل.","الرابطة بين الهالوجين والكربون في المركبات العضوية رابطة تساهمية لا أيونية.","ذرة الهالوجين تحل محل ذرة الهيدروجين وترتبط بالكربون، ولا ترتبط بذرة هيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 6, 0, 'في (أ) ترتبط ذرة البروم بحلقة البنزين، وفي (د) ترتبط ذرتا كلور بحلقة البنزين؛ فهما هاليدا أريل. وفي (ب) ترتبط ذرة الكلور بذرة كربون في سلسلة أليفاتية، وفي (ج) ترتبط ذرة اليود بذرة كربون الميثان؛ فهما هاليدا ألكيل R–X.', '["","(د) فيه ذرتا كلور مرتبطتان مباشرة بحلقة البنزين، وتعدد ذرات الهالوجين لا يغيّر كونه هاليد أريل.","هذا عكس التصنيف: (ب) و(ج) لا تحتويان على حلقة بنزين، فالهالوجين فيهما مرتبط بكربون أليفاتي.","(ب) فيه ذرة كلور على ذرة الكربون الوسطى في سلسلة أليفاتية، فهو هاليد ألكيل (2-كلورو بروبان) لا أريل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('mcq', 7, 3, 'يمثل الشكل سلسلة من ذرتي كربون (إيثان) حلت فيها ذرة بروم محل ذرة هيدروجين، أي CH₃CH₂Br. فالجزء CH₃CH₂– هو R والبروم هو X، والمركب هاليد ألكيل صيغته العامة R–X.', '["لا توجد حلقة بنزين في الشكل؛ فذرة البروم مرتبطة بذرة كربون أليفاتية في سلسلة من ذرتين.","لا يحتوي المركب على مجموعة OH، والذرة المرتبطة بالكربون الطرفي هي البروم.","لا يحتوي المركب على مجموعة NH₂، والذرة المرتبطة بالكربون الطرفي هي البروم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.647Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الصيغة العامة لهاليدات الألكيل: R–X، حيث R سلسلة (أو حلقة غير أروماتية) من ذرات الكربون أليفاتية، وX ذرة هالوجين (F أو Cl أو Br أو I) مرتبطة برابطة تساهمية بذرة كربون أليفاتية. الصيغة العامة لهاليدات الأريل: حلقة بنزين ترتبط بإحدى ذرات كربونها ذرة هالوجين X بدلًا من ذرة هيدروجين، ويمكن كتابتها C₆H₅–X، حيث X = F أو Cl أو Br أو I.', '["R–X لهاليدات الألكيل","R سلسلة كربونية أليفاتية","X ذرة هالوجين (F، Cl، Br، I)","هاليد الأريل: X مرتبطة مباشرة بحلقة البنزين"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة R–X","marks":1},{"element":"توضيح معنى R","marks":1},{"element":"توضيح معنى X وأمثلته","marks":1},{"element":"وصف الصيغة العامة لهاليدات الأريل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الصيغتان صحيحتان مع توضيح الرموز كاملًا"},{"level":"2–3 درجات","description":"الصيغتان مع نقص في توضيح الرموز، أو صيغة واحدة كاملة"},{"level":"1 درجة","description":"صيغة واحدة دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة X ذرةَ هيدروجين","وصف الصيغة العامة لهاليد الأريل بحلقة سداسية مشبعة","كتابة R–OH بدل R–X"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) في هاليدات الألكيل ترتبط ذرة الهالوجين برابطة تساهمية مع ذرة كربون أليفاتية (في سلسلة أو حلقة غير أروماتية)، أما في هاليدات الأريل فترتبط ذرة الهالوجين مباشرة بذرة كربون في حلقة البنزين أو مجموعة أروماتية أخرى. (ب) هاليدات الألكيل: R–X، وهاليدات الأريل: حلقة بنزين مرتبطة بـ X (C₆H₅–X). (ج) مثال هاليد ألكيل: كلورو ميثان CH₃Cl (أو 2-كلورو بروبان CH₃CHClCH₃). مثال هاليد أريل: كلورو بنزين C₆H₅Cl (أو فلورو بنزين C₆H₅F).', '["الألكيل: كربون أليفاتي","الأريل: كربون في حلقة البنزين","الصيغتان العامتان","مثال صحيح لكل نوع بالاسم والصيغة"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في نوع ذرة الكربون","marks":2},{"element":"الصيغتان العامتان","marks":2},{"element":"مثالان صحيحان بالاسم والصيغة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مقارنة صحيحة في البنود الثلاثة"},{"level":"4–5 درجات","description":"خطأ أو نقص في بند واحد"},{"level":"2–3 درجات","description":"بند واحد صحيح كامل أو أجزاء متفرقة صحيحة"},{"level":"1 درجة","description":"معلومة صحيحة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ كلورو هكسان حلقي هاليد أريل لأنه حلقي","كتابة صيغة البنزين C₆H₆ مثالًا على هاليد الأريل","الخلط بين الأليفاتي والأروماتي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) هاليد أريل (أيودو بنزين)، لأن ذرة اليود مرتبطة مباشرة بحلقة البنزين. (ب) البنزين C₆H₆، وباستبدال ذرة H بذرة I تصبح الصيغة C₆H₅I. (ج) الهكسان C₆H₁₄، واستبدال ذرة H بذرة I يعطي C₆H₁₃I، وهو هاليد ألكيل R–X لأن اليود مرتبط بذرة كربون أليفاتية في سلسلة مشبعة. الفرق: في هاليد الأريل 5 ذرات هيدروجين فقط لأن حلقة البنزين غير مشبعة (أروماتية)، أما في هاليد الألكيل المشتق من الألكان المشبع فـ 13 ذرة هيدروجين.', '["هاليد أريل","C₆H₅I","C₆H₁₃I وهو هاليد ألكيل","تفسير الفرق بعدد ذرات الهيدروجين (أروماتي مقابل مشبع)"]'::jsonb, '["البنزين C₆H₆ ← استبدال H واحدة بـ I ← C₆H₅I","الهكسان C₆H₁₄ ← استبدال H واحدة بـ I ← C₆H₁₃I","الفرق 13 − 5 = 8 ذرات هيدروجين"]'::jsonb, '[{"element":"تحديد النوع (أ)","marks":1},{"element":"الصيغة C₆H₅I","marks":1},{"element":"الصيغة C₆H₁₃I ونوعه","marks":1},{"element":"تفسير الفرق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة مع التفسير"},{"level":"2–3 درجات","description":"الصيغتان صحيحتان مع نقص في التصنيف أو التفسير"},{"level":"1 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة C₆H₆I دون حذف ذرة الهيدروجين المستبدلة","كتابة C₆H₁₄I للمركب 1-أيودو هكسان","تصنيف المركبين كليهما هاليد ألكيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O02') and x.type = v.type and x.number = v.number
