('mcq', 2, 'يحتوي المركب في الشكل الآتي على ذرتي هالوجين مختلفتين. ما اسمه النظامي؟', null, '[{"src":"qimg/chem22/c5-l1a-n-1br2clbutane.svg","alt":"صيغة بنائية كاملة لسلسلة أفقية من أربع ذرات كربون مرتبطة بروابط أحادية. ذرة الكربون اليسرى (الطرفية) مرتبطة بذرة Br عن يسارها وبذرتي هيدروجين أعلى وأسفل. ذرة الكربون الثانية من اليسار مرتبطة بذرة Cl من الأعلى وذرة هيدروجين من الأسفل. ذرة الكربون الثالثة مرتبطة بذرتي هيدروجين أعلى وأسفل. ذرة الكربون اليمنى مرتبطة بثلاث ذرات هيدروجين (يمين وأعلى وأسفل)."}]'::jsonb, '["1-برومو-2-كلورو بيوتان","2-كلورو-1-برومو بيوتان","4-برومو-3-كلورو بيوتان","1-برومو-2-كلورو بروبان"]'::jsonb, 'تطبيق', 'تسمية هاليد ألكيل بهالوجينين مختلفين', 'متوسط', 'الكتاب ص 170 — تسمية هاليدات الألكيل والشكل 5-3'),
('mcq', 3, 'أيّ الأسماء الآتية هو الصحيح وفق نظام IUPAC للصيغة المكثفة الآتية؟', null, '[{"src":"qimg/chem22/c5-l1a-n-2br5clhexane.svg","alt":"صيغة بنائية مكثفة لسلسلة أفقية من ست مجموعات: CH₃–CH–CH₂–CH₂–CH–CH₃. ترتبط بمجموعة CH الثانية من اليسار ذرة Br من الأعلى، وترتبط بمجموعة CH الخامسة من اليسار (الثانية من اليمين) ذرة Cl من الأعلى."}]'::jsonb, '["5-برومو-2-كلورو هكسان","2-كلورو-5-برومو هكسان","2-برومو-5-كلورو بنتان","2-برومو-5-كلورو هكسان"]'::jsonb, 'تحليل', 'تسمية مع ترقيم متكافئ', 'صعب', 'الكتاب ص 170 — تسمية هاليدات الألكيل والشكل 5-3'),
('mcq', 4, 'تحمل ذرة كربون واحدة في المركب الآتي ثلاث ذرات هالوجين. كيف يُسمّى وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c5-l1a-n-111tcethane.svg","alt":"صيغة بنائية كاملة لذرتي كربون متصلتين برابطة أحادية في خط أفقي. ذرة الكربون اليسرى مرتبطة بثلاث ذرات Cl (يسار وأعلى وأسفل). ذرة الكربون اليمنى مرتبطة بثلاث ذرات هيدروجين (يمين وأعلى وأسفل)."}]'::jsonb, '["2، 2، 2-ثلاثي كلورو إيثان","1، 1، 1-ثلاثي كلورو إيثان","1-ثلاثي كلورو إيثان","ثلاثي كلورو ميثان"]'::jsonb, 'تطبيق', 'تسمية هاليد ألكيل بهالوجين متكرر', 'متوسط', 'الكتاب ص 170 — تسمية هاليدات الألكيل والشكل 5-3'),
('mcq', 5, 'ما الاسم النظامي (IUPAC) لهاليد الأريل الذي يمثله الشكل الآتي؟', null, '[{"src":"qimg/chem22/c5-l1a-n-1br3clbenzene.svg","alt":"حلقة بنزين (سداسي رأسه للأعلى بداخله دائرة). ترتبط ذرة Br بذرة الكربون العليا، وترتبط ذرة Cl بذرة الكربون السفلى اليمنى؛ أي أن بين ذرتي الكربون الحاملتين للهالوجين ذرة كربون واحدة في الحلقة (هي الذرة العليا اليمنى)."}]'::jsonb, '["1-برومو-3-كلورو بنزين","1-كلورو-3-برومو بنزين","1-برومو-5-كلورو بنزين","1-برومو-2-كلورو بنزين"]'::jsonb, 'تطبيق', 'تسمية هاليد أريل', 'متوسط', 'الكتاب ص 170 — تسمية هاليدات الأريل والشكل 5-3d'),
('mcq', 6, 'اختر الاسم المناسب للحلقة المرسومة في الشكل الآتي والمرتبطة بذرة بروم.', null, '[{"src":"qimg/chem22/c5-l1a-n-bromocyclohexane.svg","alt":"صيغة هيكلية لحلقة سداسية بخطوط أحادية فقط (لا دائرة بداخلها ولا روابط ثنائية)، ترتبط بإحدى ذرات الحلقة (الرأس العلوي الأيمن) ذرة Br."}]'::jsonb, '["برومو بنزين","1-برومو هكسان","برومو هكسان حلقي","برومو بنتان حلقي"]'::jsonb, 'تطبيق', 'تسمية هاليد ألكيل حلقي', 'سهل', 'الكتاب ص 170، 201 — تسمية هاليدات الألكيل'),
('mcq', 7, 'ما الصيغة البنائية المكثفة للمركب 1، 2-ثنائي برومو إيثان؟', null, null, '["CH₃CHBr₂","CH₂BrCH₂Br","CH₃CH₂Br","CH₂BrCH₂CH₂Br"]'::jsonb, 'تطبيق', 'كتابة الصيغة من الاسم', 'متوسط', 'الكتاب ص 170 — تسمية هاليدات الألكيل'),
('essay', 1, 'سمِّ المركبات (أ) و(ب) و(ج) في الشكل الآتي وفق نظام IUPAC، مبيّنًا في كل منها السلسلة أو الحلقة الرئيسة وطريقة الترقيم.', null, '[{"src":"qimg/chem22/c5-l1a-n-essay3.svg","alt":"ثلاث صيغ متجاورة، (أ) على اليمين و(ب) في الوسط و(ج) على اليسار. (أ): صيغة بنائية مكثفة CH₃–CH–CH₂–CH₃ ترتبط بمجموعة CH (الثانية من اليسار) ذرة I من الأعلى. (ب): حلقة خماسية بخطوط أحادية فقط (مشبعة) ترتبط بذرتها العليا ذرة Cl. (ج): حلقة بنزين (سداسي بداخله دائرة) ترتبط بذرتها العليا ذرة F، وبالذرة المجاورة لها (العليا اليمنى) ذرة Cl."}]'::jsonb, null, 'تطبيق', 'تسمية', 'متوسط', 'الكتاب ص 170، 201 — تسمية هاليدات الألكيل والأريل'),
('essay', 2, 'سمّى طالب المركب الذي يمثله الشكل الآتي «2-فلور-3-فلور بيوتان». بيّن الأخطاء في هذا الاسم، ثم اكتب الاسم الصحيح وفق نظام IUPAC مع التبرير.', null, '[{"src":"qimg/chem22/c5-l1a-n-23difluorobutane.svg","alt":"صيغة بنائية كاملة لسلسلة أفقية من أربع ذرات كربون مرتبطة بروابط أحادية. ذرتا الكربون الطرفيتان مرتبطة كل منهما بثلاث ذرات هيدروجين. ذرة الكربون الثانية من اليسار مرتبطة بذرة F من الأعلى وذرة هيدروجين من الأسفل، وذرة الكربون الثالثة مرتبطة بذرة F من الأعلى وذرة هيدروجين من الأسفل."}]'::jsonb, null, 'تحليل', 'تصحيح خطأ في التسمية', 'صعب', 'الكتاب ص 170 — مسائل تدريبية 1'),
('essay', 3, '(أ) اقترح طالبان للمركب BrCH₂–CH₂Cl الاسمين «1-برومو-2-كلورو إيثان» و«2-برومو-1-كلورو إيثان». أيّ الاسمين صحيح وفق نظام IUPAC؟ فسّر إجابتك. (ب) حلقة بنزين ترتبط بها ذرتا فلور تفصل بينهما ذرة كربون واحدة. اقترح طالب لها الاسم «1، 5-ثنائي فلورو بنزين»، واقترح آخر «1، 3-ثنائي فلورو بنزين». أيّ الاسمين صحيح؟ فسّر إجابتك.', null, null, null, 'تطبيق', 'كتابة الصيغة من الاسم مع التبرير', 'صعب', 'الكتاب ص 170، 201 — تسمية هاليدات الألكيل والأريل')
