from (values
('mcq', 1, 2, 'السلسلة الرئيسة ثلاث ذرات كربون بروابط أحادية (بروبان)، وذرة الكلور على ذرة الكربون الثانية (الوسطى)، ويُسمّى الكلور «كلورو» (المقطع الأول من اسم الهالوجين مع «و»)؛ فالاسم 2-كلورو بروبان.', '["ذرة الكلور مرتبطة بذرة الكربون الوسطى لا الطرفية؛ فموقعها 2 من أي طرف بدأ الترقيم.","السلسلة فيها ثلاث ذرات كربون فاسمها الأصلي بروبان لا إيثان.","","المقطع «ين» يدل على رابطة ثنائية، وجميع الروابط بين ذرات الكربون في الشكل أحادية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('mcq', 2, 0, 'السلسلة أربع ذرات كربون (بيوتان). نرقم من الطرف الأقرب إلى الهالوجينات فتكون ذرة البروم على C1 والكلور على C2 (المواقع 1 و2 أصغر من 3 و4)، ثم نرتب الأسماء أبجديًّا (برومو قبل كلورو)؛ فالاسم 1-برومو-2-كلورو بيوتان.', '["","الأرقام صحيحة، لكن أسماء الهالوجينات يجب أن تُرتب أبجديًّا بحسب الأحرف الإنجليزية: برومو (Bromo) قبل كلورو (Chloro).","هذا ترقيم من الطرف البعيد عن ذرتي الهالوجين؛ والقاعدة إعطاء أقل الأرقام لمواقع الهالوجينات (1 و2 بدلًا من 3 و4).","السلسلة الرئيسة أربع ذرات كربون، فاسمها الأصلي بيوتان لا بروبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('mcq', 3, 3, 'السلسلة ست ذرات كربون (هكسان). من الطرف الأيسر: Br على C2 وCl على C5، ومن الطرف الأيمن: Cl على C2 وBr على C5؛ المجموعتان متساويتان {2، 5}، فيُعطى الرقم الأقل للذرة التي تأتي أولًا أبجديًّا (برومو). فالاسم 2-برومو-5-كلورو هكسان.', '["المواقع واحدة (2 و5) من الطرفين، فيُعطى الرقم الأصغر للهالوجين الذي يأتي أولًا أبجديًّا وهو البروم، لا الكلور.","الترتيب في الاسم أبجدي بحسب الأحرف الإنجليزية (برومو قبل كلورو)، كما أن الرقم الأصغر (2) يُعطى للبروم لا للكلور لأن مجموعتي المواقع متساويتان من الطرفين.","السلسلة الرئيسة فيها ست ذرات كربون (CH₃ وCH وCH₂ وCH₂ وCH وCH₃)، فاسمها هكسان لا بنتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('mcq', 4, 1, 'في الشكل ذرتا كربون (إيثان)، وترتبط ثلاث ذرات كلور بذرة الكربون نفسها. نرقم من جهتها فتكون مواقعها 1، 1، 1، ونستعمل «ثلاثي» لتكرار الكلور ثلاث مرات؛ فالاسم 1، 1، 1-ثلاثي كلورو إيثان.', '["هذا ترقيم من الطرف الخالي من الهالوجين؛ ويجب الترقيم من الطرف الذي يعطي ذرات الكلور أقل رقم (1).","","عند تكرار الهالوجين يُكتب رقم موقع لكل ذرة منه، فثلاث ذرات كلور تحتاج إلى ثلاثة أرقام: 1، 1، 1.","في الشكل ذرتا كربون مرتبطتان معًا، فالاسم الأصلي إيثان لا ميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.648Z"}'::jsonb),
('mcq', 5, 0, 'نرقم حلقة البنزين بحيث يكون أقل رقم للذرة التي تأتي أولًا أبجديًّا: البروم على C1، ثم نسير في الاتجاه الذي يعطي الكلور أقل رقم فيكون على C3. ونرتب الأسماء أبجديًّا؛ فالاسم 1-برومو-3-كلورو بنزين.', '["","يُعطى الرقم 1 للهالوجين الذي يأتي أولًا أبجديًّا (برومو)، وتُرتب الأسماء أبجديًّا؛ فلا يبدأ الاسم بكلورو.","هذا ترقيم الحلقة في الاتجاه الآخر؛ والمطلوب أقل رقم ممكن لكل موقع، و3 أقل من 5.","بين ذرتي الهالوجين ذرة كربون واحدة في الحلقة، فهما ليستا على ذرتين متجاورتين (الموقع 2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb),
('mcq', 6, 2, 'الشكل حلقة مشبعة من ست ذرات كربون (هكسان حلقي) ترتبط بإحدى ذراتها ذرة بروم. ولا حاجة إلى رقم لأن جميع مواقع الحلقة متكافئة؛ فالاسم برومو هكسان حلقي، وهو هاليد ألكيل.', '["الحلقة لا تحتوي على دائرة ولا روابط ثنائية متبادلة، فهي حلقة مشبعة وليست حلقة بنزين.","ذرات الكربون الست متصلة في حلقة لا في سلسلة مفتوحة، فيلزم وصف «حلقي».","","الحلقة سداسية (ست ذرات كربون) فاسمها هكسان حلقي لا بنتان حلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb),
('mcq', 7, 1, 'إيثان يعني ذرتي كربون، و«ثنائي برومو» يعني ذرتي بروم، والرقمان 1، 2 يعنيان أن كل ذرة بروم على ذرة كربون مختلفة؛ فالصيغة CH₂Br–CH₂Br.', '["في هذه الصيغة ذرتا البروم على ذرة الكربون نفسها، فهي 1، 1-ثنائي برومو إيثان.","","هذه الصيغة فيها ذرة بروم واحدة فقط، فهي برومو إيثان، و«ثنائي» تعني ذرتي بروم.","هذه الصيغة فيها ثلاث ذرات كربون، فهي 1، 3-ثنائي برومو بروبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) السلسلة الرئيسة أربع ذرات كربون (بيوتان)، ونرقم من الطرف الأقرب إلى ذرة اليود فتكون على C2: الاسم 2-أيودو بيوتان. (ب) حلقة مشبعة من خمس ذرات كربون (بنتان حلقي) عليها ذرة كلور واحدة، ولا يلزم رقم: الاسم كلورو بنتان حلقي. (ج) حلقة بنزين عليها ذرتا كلور وفلور متجاورتان؛ يُعطى الرقم 1 للكلور لأنه يسبق الفلور أبجديًّا (Chloro قبل Fluoro)، ثم الفلور على C2: الاسم 1-كلورو-2-فلورو بنزين.', '["(أ) 2-أيودو بيوتان","(ب) كلورو بنتان حلقي","(ج) 1-كلورو-2-فلورو بنزين","تبرير الترقيم والترتيب الأبجدي"]'::jsonb, '["(أ) أطول سلسلة = 4 ذرات C ← بيوتان؛ الترقيم من الطرف الأقرب إلى I ← الموقع 2","(ب) حلقة خماسية مشبعة ← بنتان حلقي؛ بديل واحد ← لا رقم","(ج) حلقة بنزين؛ Cl يسبق F أبجديًّا ← Cl على C1 وF على C2"]'::jsonb, '[{"element":"اسم (أ) مع التبرير","marks":2},{"element":"اسم (ب) مع التبرير","marks":2},{"element":"اسم (ج) مع التبرير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الأسماء الثلاثة صحيحة مع تبرير الترقيم"},{"level":"4–5 درجات","description":"اسمان صحيحان كاملان، أو ثلاثة أسماء دون تبرير كافٍ"},{"level":"2–3 درجات","description":"اسم واحد صحيح كامل أو أخطاء في الترقيم"},{"level":"1 درجة","description":"تحديد السلسلة أو الحلقة الرئيسة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (أ) 3-أيودو بيوتان بالترقيم من الطرف البعيد","تسمية (ب) كلورو بنزين لأنها حلقة","تسمية (ج) 1-فلورو-2-كلورو بنزين دون مراعاة الترتيب الأبجدي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأخطاء: (1) اسم الهالوجين في المركب العضوي يؤخذ مقطعه الأول مع إضافة «و» في نهايته، فيكون «فلورو» لا «فلور». (2) عند تكرار الهالوجين نفسه لا يُكرر اسمه، بل تُجمع أرقام مواقعه بينها فاصلة ويُسبق اسمه بالبادئة «ثنائي». الاسم الصحيح: السلسلة أربع ذرات كربون (بيوتان)، وذرتا الفلور على C2 وC3 من أي طرف بدأ الترقيم؛ فالاسم 2، 3-ثنائي فلورو بيوتان.', '["خطأ «فلور» بدل «فلورو»","خطأ تكرار الاسم بدل «ثنائي»","الاسم الصحيح 2، 3-ثنائي فلورو بيوتان","تبرير الأرقام"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد خطأ المقطع «فلورو»","marks":1},{"element":"تحديد خطأ عدم استعمال «ثنائي»","marks":1},{"element":"الاسم الصحيح","marks":1},{"element":"تبرير الترقيم","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحديد الخطأين والاسم الصحيح مع التبرير"},{"level":"2–3 درجات","description":"الاسم الصحيح مع تحديد خطأ واحد"},{"level":"1 درجة","description":"الاسم الصحيح فقط أو خطأ واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة «2، 3-فلورو بيوتان» دون «ثنائي»","كتابة «ثنائي فلورو بيوتان» دون أرقام المواقع","الترقيم 3، 2 بترتيب تنازلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الاسم الصحيح 1-برومو-2-كلورو إيثان. ذرة البروم على ذرة كربون وذرة الكلور على ذرة الكربون الأخرى، فمواقع الهالوجينين هي 1 و2 مهما كان طرف الترقيم. وعند التساوي يُعطى الرقم الأقل للهالوجين الذي يأتي أولًا أبجديًّا بحسب الأحرف الإنجليزية، والبروم (Bromo) يسبق الكلور (Chloro)؛ لذا يكون البروم على C1. (ب) الاسم الصحيح 1، 3-ثنائي فلورو بنزين. ترتبط ذرتا الفلور بذرتي كربون في الحلقة تفصل بينهما ذرة كربون واحدة، فالترقيم في أحد الاتجاهين يعطي 1 و3، وفي الاتجاه المعاكس يعطي 1 و5، والقاعدة أن تُعطى المواقع أقل أرقام ممكنة، و3 أقل من 5.', '["الاسم الصحيح 1-برومو-2-كلورو إيثان","الأرقام متساوية فيُحسم بالترتيب الأبجدي (Br قبل Cl)","الاسم الصحيح 1، 3-ثنائي فلورو بنزين","قاعدة أقل الأرقام: 3 بدل 5"]'::jsonb, '[]'::jsonb, '[{"element":"اختيار الاسم الصحيح في (أ)","marks":1},{"element":"تفسير الترقيم بالترتيب الأبجدي","marks":2},{"element":"اختيار الاسم الصحيح في (ب)","marks":1},{"element":"تفسير رفض الاسم 1، 5","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الاسمان الصحيحان مع التفسيرين"},{"level":"3–4 درجات","description":"الاسمان الصحيحان مع تفسير واحد"},{"level":"1–2 درجة","description":"اسم صحيح واحد أو الاسمان دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار «2-برومو-1-كلورو إيثان» بالظن أن الكلور يُقدَّم لأنه أخف","تبرير الترتيب بحسب الحروف العربية أو بحسب حجم الذرة","قبول 1، 5 لأن الترقيم يمكن أن يبدأ في أي اتجاه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.649Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
