('mcq', 1, 'كيف تتغير درجة الغليان والكثافة في هاليدات الألكيل التي لها عدد ذرات الكربون نفسه، عند الانتقال من الفلور إلى اليود؟', null, null, '["تقل درجة الغليان وتقل الكثافة","تزداد درجة الغليان وتقل الكثافة","تقل درجة الغليان وتزداد الكثافة","تزداد درجة الغليان وتزداد الكثافة"]'::jsonb, 'فهم', 'وصف نمط', 'سهل', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 2, 'يبيّن المخطط الآتي درجات غليان البنتان وأربعة من هاليدات الألكيل المشتقة منه. ما التفسير الصحيح للزيادة في درجة الغليان من C₅H₁₁F إلى C₅H₁₁I؟', null, '[{"src":"qimg/chem22/c5-l1a-bp-bars.svg","alt":"مخطط أعمدة رأسي. المحور الأفقي عنوانه «المركب» ويحمل خمسة أعمدة من اليسار إلى اليمين: C₅H₁₂ وارتفاع عموده 36، ثم C₅H₁₁F وارتفاعه 62.8، ثم C₅H₁₁Cl وارتفاعه 108، ثم C₅H₁₁Br وارتفاعه 130، ثم C₅H₁₁I وارتفاعه 155. المحور الرأسي عنوانه «درجة الغليان» بوحدة °C، ومدرّج من 0 إلى 180 بفواصل 30. الأعمدة تزداد ارتفاعًا من اليسار إلى اليمين."}]'::jsonb, '["تكوّن روابط هيدروجينية بين جزيئات هاليدات الألكيل تزداد قوتها من الفلور إلى اليود","ازدياد عدد الإلكترونات البعيدة عن النواة التي يسهل إزاحتها، فتتكون ثنائيات قطب مؤقتة تزيد التجاذب بين الجزيئات","ازدياد قوة الرابطة التساهمية C–X التي يجب أن تنكسر داخل الجزيء عند الغليان","نقصان عدد الإلكترونات في ذرة الهالوجين، فيقل تنافر الجزيئات بعضها مع بعض"]'::jsonb, 'فهم', 'تفسير نمط في بيانات', 'متوسط', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 3, 'ادرس البيانات في الجدول الآتي. ما أثر استبدال ذرة كلور بإحدى ذرات الهيدروجين في جزيء الميثان؟', '{"headers":["المركب","الصيغة","درجة الغليان (°C)","الكثافة (g/mL) في الحالة السائلة"],"rows":[["ميثان","CH₄","−162","0.423 (عند −162°C)"],["كلورو ميثان","CH₃Cl","−24","0.911 (عند 25°C)"]]}'::jsonb, null, '["ترتفع درجة الغليان وتزداد الكثافة","تنخفض درجة الغليان وتزداد الكثافة","ترتفع درجة الغليان وتقل الكثافة","لا تتغير درجة الغليان تقريبًا"]'::jsonb, 'فهم', 'تفسير بيانات جدول', 'سهل', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 4, 'تحتوي المركبات الآتية جميعها على ثلاث ذرات كربون وتختلف في نوع ذرة الهالوجين. أيّها يُتوقع أن تكون كثافته في الحالة السائلة هي الأكبر؟', null, null, '["1-كلورو بروبان","1-فلورو بروبان","1-أيودو بروبان","1-برومو بروبان"]'::jsonb, 'تطبيق', 'ترتيب بحسب خاصية', 'متوسط', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 5, 'تُخلط كمية من الماء (كثافته 1.00 g/mL تقريبًا) مع كمية من أحد السوائل الواردة في الجدول الآتي، وهي لا تمتزج بالماء. أيّها يُتوقع أن يكوّن طبقة أسفل طبقة الماء؟', '{"headers":["المركب","الصيغة","درجة الغليان (°C)","الكثافة (g/mL) في الحالة السائلة"],"rows":[["بنتان","CH₃CH₂CH₂CH₂CH₃","36","0.626"],["1-فلورو بنتان","CH₃CH₂CH₂CH₂CH₂F","62.8","0.791"],["1-كلورو بنتان","CH₃CH₂CH₂CH₂CH₂Cl","108","0.882"],["1-برومو بنتان","CH₃CH₂CH₂CH₂CH₂Br","130","1.218"]]}'::jsonb, null, '["1-فلورو بنتان","1-كلورو بنتان","البنتان C₅H₁₂","1-برومو بنتان"]'::jsonb, 'تطبيق', 'استعمال بيانات الكثافة', 'صعب', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 6, 'قال طالب: «لأن ذرة الفلور أصغر الهالوجينات حجمًا، فإن درجة غليان 1-فلورو بنتان أقل من درجة غليان البنتان». إذا علمت أن درجة غليان البنتان 36°C، ودرجة غليان 1-فلورو بنتان 62.8°C، ودرجة غليان 1-كلورو بنتان 108°C، فأيّ العبارات الآتية تقوّم قول الطالب تقويمًا صحيحًا؟', null, null, '["قوله صحيح؛ لأن صغر ذرة الفلور يجعل التجاذب بين جزيئات مركبه أضعف منه بين جزيئات البنتان","قوله خاطئ؛ فصغر ذرة الفلور يجعل مركبه الأقل غليانًا بين هاليدات البنتان، لكنه يبقى أعلى غليانًا من البنتان","قوله خاطئ؛ لأن درجة غليان 1-فلورو بنتان أعلى من درجة غليان 1-كلورو بنتان","قوله صحيح جزئيًّا؛ لأن درجتي غليان البنتان و1-فلورو بنتان متساويتان تقريبًا"]'::jsonb, 'تقويم', 'مقارنة مع تبرير', 'متوسط', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('mcq', 7, 'درجة غليان كلورو ميثان −24°C ودرجة غليان 1-كلورو بنتان 108°C، وكلاهما ينصهر عند درجة حرارة أقل كثيرًا من 0°C. ما الحالة الفيزيائية لكل منهما عند 25°C؟', null, null, '["كلورو ميثان غاز، و1-كلورو بنتان سائل","كلورو ميثان سائل، و1-كلورو بنتان سائل","كلورو ميثان غاز، و1-كلورو بنتان غاز","كلورو ميثان سائل، و1-كلورو بنتان غاز"]'::jsonb, 'تطبيق', 'استعمال درجات الغليان للتنبؤ بالحالة', 'صعب', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('essay', 1, 'فسّر لماذا تزداد درجات غليان هاليدات الألكيل بالتدريج عند الاتجاه إلى أسفل في مجموعة الهالوجينات في الجدول الدوري.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 171، 201 — خواص هاليدات الألكيل والتقويم س29'),
('essay', 2, 'ادرس الجدول الآتي، ثم أجب: (أ) صِف العلاقة بين نوع ذرة الهالوجين وكلٍّ من درجة الغليان والكثافة. (ب) احسب الفرق بين درجة غليان 1-أيودو بنتان ودرجة غليان البنتان، والفرق بين درجة غليان 1-كلورو بنتان ودرجة غليان البنتان. (ج) ماذا تستنتج من المقارنة بين هاليدات الألكيل والألكان المقابل لها؟', '{"headers":["المركب","الصيغة","درجة الغليان (°C)","الكثافة (g/mL) في الحالة السائلة"],"rows":[["بنتان","CH₃CH₂CH₂CH₂CH₃","36","0.626"],["1-فلورو بنتان","CH₃CH₂CH₂CH₂CH₂F","62.8","0.791"],["1-كلورو بنتان","CH₃CH₂CH₂CH₂CH₂Cl","108","0.882"],["1-برومو بنتان","CH₃CH₂CH₂CH₂CH₂Br","130","1.218"],["1-أيودو بنتان","CH₃CH₂CH₂CH₂CH₂I","155","1.516"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات جدول', 'صعب', 'الكتاب ص 171 — الجدول 5-2 وخواص هاليدات الألكيل'),
('essay', 3, 'قوّم: كيف يمكن توقع أيّ المركبين أعلى درجة غليان: البروبان CH₃CH₂CH₃ أم 1-كلورو بروبان CH₃CH₂CH₂Cl؟ استعن بالبيانات الآتية لمركبات أخرى، وفسّر إجابتك: الميثان −162°C، كلورو ميثان −24°C، البنتان 36°C، 1-كلورو بنتان 108°C.', null, null, null, 'تقويم', 'توقع وتبرير', 'سهل', 'الكتاب ص 173 — التقويم 5-1 س7')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O04') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'عند الانتقال عبر الهالوجينات من الفلور إلى اليود تزداد درجة الغليان والكثافة معًا؛ ففي سلسلة 1-هالو بنتان ترتفع درجة الغليان من 62.8°C إلى 155°C، وترتفع الكثافة من 0.791 g/mL إلى 1.516 g/mL.', '["هذا عكس الاتجاه؛ فكلتاهما تزداد مع ازدياد حجم ذرة الهالوجين من الفلور إلى اليود.","درجة الغليان تزداد فعلًا، لكن الكثافة أيضًا تزداد (مثلًا من 0.791 g/mL لمركب الفلور إلى 1.516 g/mL لمركب اليود في سلسلة البنتان).","الكثافة تزداد فعلًا، لكن درجة الغليان لا تقل بل تزداد مع ازدياد حجم ذرة الهالوجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 2, 1, 'عند الانتقال من الفلور إلى اليود يزداد عدد الإلكترونات الخارجية البعيدة عن النواة، وهذه تميل إلى تغيير مكانها بسهولة، فيزداد ميل الجزيئات لتكوين ثنائيات قطب مؤقتة تتجاذب معًا؛ فتزداد الطاقة اللازمة لفصل الجزيئات، وترتفع درجة الغليان.', '["لا توجد ذرة هيدروجين مرتبطة بالهالوجين في هذه المركبات، ولو كانت الروابط الهيدروجينية هي السبب لكان الفلور الأقوى لا الأضعف.","","الغليان تغير فيزيائي يفصل الجزيئات بعضها عن بعض دون كسر الروابط التساهمية داخلها.","عدد الإلكترونات يزداد ولا يقل من الفلور إلى اليود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 3, 0, 'درجة غليان الميثان −162°C ودرجة غليان كلورو ميثان −24°C، أي ارتفعت؛ وكثافة الميثان السائل 0.423 g/mL وكثافة كلورو ميثان السائل 0.911 g/mL، أي زادت. فدرجة غليان هاليد الألكيل وكثافته أعلى من الألكان الذي له عدد ذرات الكربون نفسه.', '["","درجة غليان كلورو ميثان (−24°C) أعلى من درجة غليان الميثان (−162°C)، فهي ارتفعت ولم تنخفض.","كثافة كلورو ميثان (0.911 g/mL) أكبر من كثافة الميثان (0.423 g/mL)، فهي زادت ولم تقل.","الفرق بين −162°C و−24°C كبير جدًّا (138°C)، فلا يصح القول إنها لم تتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 4, 2, 'في هاليدات الألكيل التي لها عدد ذرات الكربون نفسه تزداد الكثافة عند الانتقال عبر الهالوجينات من الفلور إلى اليود (كما في سلسلة 1-هالو بنتان: 0.791 ثم 0.882 ثم 1.218 ثم 1.516 g/mL)؛ فأكبرها كثافة هو مركب اليود: 1-أيودو بروبان.', '["ذرة الكلور أصغر من ذرتي البروم واليود، فكثافة مركبه أقل من كثافة مركبيهما.","ذرة الفلور أصغر الهالوجينات، فمركبه هو الأقل كثافة بين هذه المركبات لا الأكبر.","","كثافة مركب البروم أكبر من كثافة مركبي الفلور والكلور، لكنها أقل من كثافة مركب اليود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 5, 3, 'السائل الذي كثافته أكبر من كثافة الماء (1.00 g/mL) يستقر أسفله. ومن الجدول، 1-برومو بنتان كثافته 1.218 g/mL > 1.00 g/mL، أما البقية فكثافاتها أقل من 1.00 g/mL؛ فيكوّن 1-برومو بنتان الطبقة السفلى.', '["كثافته 0.791 g/mL أقل من كثافة الماء، فيطفو فوقه.","كثافته 0.882 g/mL أقل من كثافة الماء، فيطفو فوقه رغم أنه أكثف من مركب الفلور.","كثافته 0.626 g/mL وهي الأقل في الجدول، فيطفو فوق الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 6, 1, 'درجة غليان 1-فلورو بنتان (62.8°C) أعلى من درجة غليان البنتان (36°C)، فقول الطالب خاطئ. وصغر ذرة الفلور يفسر فقط أن مركبه أقل غليانًا من مركب الكلور (108°C) وبقية هاليدات البنتان، أما مقارنته بالألكان المقابل فدرجة غليانه أعلى.', '["البيانات تنقض قوله: 62.8°C أعلى من 36°C، فالتجاذب بين جزيئات 1-فلورو بنتان أقوى لا أضعف.","","الحكم بخطأ القول صحيح، لكن السبب خاطئ؛ فدرجة غليان 1-فلورو بنتان (62.8°C) أقل من درجة غليان 1-كلورو بنتان (108°C).","الفرق بين 62.8°C و36°C نحو 27°C، فلا يصح القول إنهما متساويتان تقريبًا، والطالب أخطأ في اتجاه المقارنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('mcq', 7, 0, 'المادة تكون غازًا عند درجة حرارة أعلى من درجة غليانها، وسائلًا بين درجتي الانصهار والغليان. عند 25°C: 25 > −24 فكلورو ميثان غاز، و25 < 108 (وأعلى من درجة الانصهار) فـ 1-كلورو بنتان سائل.', '["","كلورو ميثان يغلي عند −24°C، أي أن درجة 25°C أعلى من درجة غليانه، فيكون غازًا لا سائلًا.","1-كلورو بنتان يغلي عند 108°C، و25°C أقل من درجة غليانه وأعلى من درجة انصهاره، فيكون سائلًا.","هذا عكس الصحيح؛ فالمادة تكون غازًا إذا كانت درجة الحرارة أعلى من درجة غليانها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.650Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند الاتجاه إلى أسفل في مجموعة الهالوجينات (من الفلور إلى اليود) يزداد حجم ذرة الهالوجين ويزداد عدد الإلكترونات الخارجية البعيدة عن النواة. وهذه الإلكترونات تميل إلى تغيير مكانها بسهولة، فيزداد ميل جزيئات هاليد الألكيل لتكوين ثنائيات قطب مؤقتة. ولأن الأقطاب تتجاذب معًا تزداد قوى التجاذب بين الجزيئات، فتزداد الطاقة اللازمة لفصل الجزيئات بعضها عن بعض، وبذلك ترتفع درجة الغليان (مثل: 1-فلورو بنتان 62.8°C، 1-كلورو بنتان 108°C، 1-برومو بنتان 130°C، 1-أيودو بنتان 155°C).', '["ازدياد عدد الإلكترونات الخارجية البعيدة عن النواة","سهولة إزاحة هذه الإلكترونات","تكوّن ثنائيات قطب مؤقتة تتجاذب","ازدياد الطاقة اللازمة لفصل الجزيئات فترتفع درجة الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"ازدياد عدد الإلكترونات البعيدة عن النواة","marks":1},{"element":"سهولة إزاحتها وتكوين ثنائيات قطب مؤقتة","marks":1},{"element":"ازدياد التجاذب بين الجزيئات","marks":1},{"element":"ازدياد الطاقة اللازمة لفصلها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متسلسل كامل"},{"level":"2–3 درجات","description":"تفسير صحيح ينقصه عنصر أو عنصران"},{"level":"1 درجة","description":"ذكر ازدياد حجم الذرة فقط دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الارتفاع بكسر الرابطة C–X عند الغليان","نسبة الارتفاع إلى روابط هيدروجينية","القول إن عدد الإلكترونات يقل من الفلور إلى اليود"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.651Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) كلما انتقلنا من الفلور إلى الكلور إلى البروم إلى اليود ازدادت درجة الغليان (62.8 → 108 → 130 → 155°C) وازدادت الكثافة (0.791 → 0.882 → 1.218 → 1.516 g/mL). (ب) 155 − 36 = 119°C، و108 − 36 = 72°C. (ج) درجة غليان كل هاليد ألكيل وكثافته أعلى من درجة غليان الألكان الذي يحتوي على عدد ذرات الكربون نفسه وكثافته، ويكبر الفرق بازدياد حجم ذرة الهالوجين.', '["ازدياد درجة الغليان من F إلى I","ازدياد الكثافة من F إلى I","الفرقان 119°C و72°C","هاليد الألكيل أعلى غليانًا وكثافة من الألكان المقابل"]'::jsonb, '["فرق 1-أيودو بنتان: 155°C − 36°C = 119°C","فرق 1-كلورو بنتان: 108°C − 36°C = 72°C"]'::jsonb, '[{"element":"وصف علاقة درجة الغليان","marks":1},{"element":"وصف علاقة الكثافة","marks":1},{"element":"الحسابان صحيحان بالوحدة","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الوصف والحسابان والاستنتاج صحيحة"},{"level":"3–4 درجات","description":"خطأ في حساب واحد أو نقص في الوصف"},{"level":"1–2 درجة","description":"وصف صحيح لعلاقة واحدة أو حساب واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكثافة تقل بازدياد حجم الهالوجين","إغفال وحدة °C في الفرق","استنتاج أن الألكان أعلى غليانًا لأنه أخف"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.651Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نتوقع أن تكون درجة غليان 1-كلورو بروبان أعلى من درجة غليان البروبان. فالمركبان لهما عدد ذرات الكربون نفسه (3)، والفرق بينهما أن ذرة كلور حلت في 1-كلورو بروبان محل ذرة هيدروجين. وتبيّن البيانات أن درجة غليان كل كلوريد ألكيل أعلى من درجة غليان الألكان الذي له عدد ذرات الكربون نفسه: كلورو ميثان (−24°C) أعلى من الميثان (−162°C)، و1-كلورو بنتان (108°C) أعلى من البنتان (36°C)؛ فنعمّم هذا النمط على البروبان و1-كلورو بروبان. وارتفاع درجة الغليان يعني أن قوى التجاذب بين جزيئات هاليد الألكيل أكبر، فيلزم طاقة أكبر لفصل الجزيئات بعضها عن بعض.', '["1-كلورو بروبان أعلى غليانًا","عدد ذرات الكربون متساوٍ والفرق في ذرة الكلور","الاستناد إلى نمط البيانات (كلوريد الألكيل أعلى من الألكان المقابل)","قوى تجاذب أكبر بين الجزيئات تحتاج إلى طاقة أكبر لفصلها"]'::jsonb, '[]'::jsonb, '[{"element":"التوقع الصحيح","marks":1},{"element":"الاستناد إلى نمط البيانات","marks":1},{"element":"التفسير بقوى التجاذب بين الجزيئات","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"توقع صحيح مستند إلى البيانات مع تفسير بقوى التجاذب"},{"level":"2 درجتان","description":"توقع صحيح مع الاستناد إلى البيانات دون تفسير، أو مع تفسير دون بيانات"},{"level":"1 درجة","description":"توقع صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع تساوي درجتي الغليان لتساوي عدد ذرات الكربون","التفسير بكسر الرابطة C–Cl عند الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.651Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
