insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'حتى أواخر الثمانينيات استُعملت هاليدات الألكيل على نطاق واسع في المبردات وأنظمة التكييف على شكل مركبات تُعرف بـ:', null, null, '["رباعي فلورو بولي إيثين (PTFE)","الكلوروفلوروكربونات (CFCs)","كلوريد البولي فينيل (PVC)","الكلوروميثان CH₃Cl"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 170 — الربط مع علوم الأرض: المبردات وCFCs وHFCs'),
('mcq', 2, 'أيّ مما يأتي من استعمالات بلاستيك كلوريد البولي فينيل (PVC) المسمى «الفينيل»؟', null, null, '["مادة تبريد في الثلاجات وأنظمة التكييف","مذيب لإزالة الدهون والزيوت","مخدر عام في العمليات الجراحية","صفائح رقيقة ونماذج للألعاب"]'::jsonb, 'تذكر', 'تذكر استعمال', 'سهل', 'الكتاب ص 171 — خواص هاليدات الألكيل واستعمالاتها'),
('mcq', 3, 'يمثل الشكل الآتي هاليد ألكيل بسيطًا. في أيّ صناعة يُستعمل؟', null, '[{"src":"qimg/chem22/c5-l1a-chloromethane.svg","alt":"صيغة بنائية كاملة لذرة كربون واحدة في المركز، ترتبط برابطة أحادية بذرة Cl عن يسارها، وبثلاث ذرات هيدروجين H: عن يمينها وفوقها وتحتها."}]'::jsonb, '["صناعة الطلاء غير اللاصق لأواني الطبخ","صناعة غازات التبريد لأنظمة التكييف الحديثة","صناعة المواد اللاصقة المعروفة بالسيليكون","صناعة أدوية التخدير العام الحديثة"]'::jsonb, 'تذكر', 'ربط بنية باستعمال', 'متوسط', 'الكتاب ص 169 — الشكل 5-2 الكلوروميثان'),
('mcq', 4, 'يمثل الشكل الآتي جزيء الهالوثان، وهو هاليد ألكيل. فيمَ استُعمل في خمسينيات القرن العشرين؟', null, '[{"src":"qimg/chem22/c5-l1a-halothane.svg","alt":"صيغة بنائية كاملة لذرتي كربون متصلتين برابطة أحادية في خط أفقي. ذرة الكربون اليسرى مرتبطة بثلاث ذرات F (يسار وأعلى وأسفل). ذرة الكربون اليمنى مرتبطة بذرة Br من الأعلى، وبذرة Cl من الأسفل، وبذرة هيدروجين H عن يمينها."}]'::jsonb, '["مخدر عام للمرضى عند إجراء العمليات الجراحية","مادة أولية لصناعة بلاستيك الفينيل (PVC)","غاز تبريد في الثلاجات وأنظمة التكييف","مادة لاصقة لتثبيت الأبواب والنوافذ"]'::jsonb, 'تذكر', 'ربط مركب باستعماله', 'متوسط', 'الكتاب ص 172–173 — الهالوثان والشكل 5-6'),
('mcq', 5, 'لماذا تُستعمل هاليدات الألكيل مذيبات ومواد تنظيف؟', null, null, '["لأنها تذيب المركبات الأيونية مثل الأملاح بسهولة","لأنها تتفاعل مع الماء فتنتج مواد صابونية","لأنها تذيب الجزيئات غير القطبية بسهولة، ومنها الدهون والزيوت","لأنها مركبات نادرة في الطبيعة وغالية الثمن"]'::jsonb, 'تذكر', 'تذكر استعمال وسببه', 'سهل', 'الكتاب ص 171 — خواص هاليدات الألكيل واستعمالاتها'),
('mcq', 6, 'يبيّن الشكل الآتي الوحدة المتكررة في بلاستيك مصنوع من غاز رباعي فلورو إيثين. ما الاستعمال المناسب له؟', null, '[{"src":"qimg/chem22/c5-l1a-ptfe.svg","alt":"وحدة متكررة لبوليمر: ذرة كربون C في الوسط ترتبط بذرة F فوقها وذرة F تحتها، وترتبط عن يمينها وعن يسارها برابطتين أحاديتين تمتدان خارج قوسين مربعين كبيرين يحيطان بالوحدة، وبعد كل رابطة ثلاث نقاط (···) دلالة على استمرار السلسلة، وأسفل القوس الأيمن الحرف n."}]'::jsonb, '["طلاء سطوح غير لاصقة لأدوات المطبخ مثل صواني الخبز","مادة تبريد في أجهزة التكييف والثلاجات","مخدر عام للمرضى في العمليات الجراحية","مذيب سائل لإزالة البقع الدهنية"]'::jsonb, 'فهم', 'ربط بنية باستعمال', 'متوسط', 'الكتاب ص 171 — الشكل 5-4 رباعي فلورو بولي إيثين'),
('mcq', 7, 'لماذا تُستعمل هاليدات الألكيل كثيرًا مواد أولية في الصناعات الكيميائية بدلًا من الألكانات؟', null, null, '["لأنها متوافرة بكثرة في الطبيعة، فهي أرخص من الألكانات","لأنها أقل نشاطًا من الألكانات فلا تتفكك في أثناء التصنيع","لأن درجات غليانها أقل من درجات غليان الألكانات المقابلة","لأن ذرات الهالوجين المرتبطة بالكربون أكثر نشاطًا من ذرات الهيدروجين التي حلت محلها"]'::jsonb, 'فهم', 'تفسير استعمال', 'صعب', 'الكتاب ص 171 — خواص هاليدات الألكيل واستعمالاتها'),
('essay', 1, 'اذكر أربعة استعمالات لهاليدات الألكيل، مع ذكر مثال على المركب أو المادة المستعملة في كل استعمال.', null, null, null, 'تذكر', 'تعداد استعمالات مع أمثلة', 'سهل', 'الكتاب ص 169–172 — استعمالات هاليدات الألكيل'),
('essay', 2, 'وضّح المقصود بالبلاستيك، ثم اذكر مثالين على بلاستيك مصنوع من هاليدات الألكيل مع استعمال لكل منهما.', null, null, null, 'فهم', 'تعريف وأمثلة', 'متوسط', 'الكتاب ص 171 — خواص هاليدات الألكيل واستعمالاتها'),
('essay', 3, 'تحتوي أدوية كثيرة لعلاج الربو على مركبات الكلوروفلوروكربون (CFCs) غازًا دافعًا في البخاخات، وقد حُظر استعمالها عام 2008م واستُعملت بدلًا منها مركبات أخرى لا تحتوي على الكلور. ووُجد أن جرعة الدواء اللازمة تقل إلى النصف عند استعمال المركبات البديلة للحصول على التركيز نفسه في الدم. (أ) ما سبب التخلي عن مركبات CFCs في المبردات وغيرها؟ (ب) ما الفرق في التركيب بين CFCs ومركبات HFCs التي حلت محلها في المبردات؟ (ج) استنتج ميزتين لاستعمال جرعة أقل من الدواء للحصول على النتيجة نفسها.', null, null, null, 'تحليل', 'تحليل نص واستنتاج', 'صعب', 'الكتاب ص 170، 206 — CFCs وHFCs وأسئلة المستندات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
