from (values
('mcq', 1, 1, 'تُستعمل هاليدات الألكيل على نطاق واسع في المبردات وأنظمة التكييف على شكل كلوروفلوروكربونات (CFCs)، وقد بقيت كذلك حتى أواخر الثمانينيات، ثم استُبدلت بها الهيدروفلوروكربونات (HFCs).', '["PTFE بلاستيك صلب يُستعمل لعمل سطوح غير لاصقة لأدوات المطبخ، لا مادة تبريد.","","PVC بلاستيك يُصنع في صورة لينة أو صلبة على شكل صفائح أو نماذج للألعاب، لا مادة تبريد.","الكلوروميثان يُستعمل في صناعة المواد اللاصقة المعروفة بالسيليكون، وليس هو مركبات التبريد المقصودة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.651Z"}'::jsonb),
('mcq', 2, 3, 'كلوريد البولي فينيل (PVC)، ويسمى الفينيل، بلاستيك شائع يمكن صناعته في صورة لينة أو صلبة، ويمكن تشكيله على شكل صفائح رقيقة أو نماذج للألعاب.', '["مواد التبريد جزيئات صغيرة متطايرة مثل CFCs ثم HFCs، لا بلاستيك صلب أو لين مثل PVC.","إذابة الدهون والزيوت من استعمالات هاليدات الألكيل السائلة بوصفها مذيبات، لا من استعمالات بلاستيك PVC.","المخدر العام الذي استُعمل في خمسينيات القرن الماضي هو الهالوثان، وهو جزيء صغير لا بلاستيك.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.651Z"}'::jsonb),
('mcq', 3, 2, 'الشكل يمثل الكلوروميثان CH₃Cl، وهو هاليد ألكيل يتكون عندما تحل ذرة كلور محل ذرة من ذرات الهيدروجين الأربع في الميثان، ويُستعمل في صناعة المواد اللاصقة المعروفة تجاريًّا بالسيليكون لتثبيت الأبواب والنوافذ.', '["الطلاء غير اللاصق يُصنع من بلاستيك رباعي فلورو بولي إيثين (PTFE)، لا من الكلوروميثان.","غازات التبريد الحديثة من مركبات HFCs التي تحتوي على الهيدروجين والفلور فقط، والمركب في الشكل يحتوي على الكلور ولا يحتوي على الفلور.","","هاليد الألكيل الذي استُعمل مخدرًا عامًّا هو الهالوثان، وهو مركب يحتوي على ذرتي كربون وعلى الفلور والكلور والبروم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('mcq', 4, 0, 'الهالوثان (2-برومو-2-كلورو-1، 1، 1-ثلاثي فلورو إيثان) نوع من الهيدروكربونات المهلجنة، واستُعمل أول مرة في الطب في خمسينيات القرن العشرين مخدرًا عامًّا للمرضى عند إجراء العمليات الجراحية.', '["","الهالوثان جزيء صغير استُعمل في الطب، وبلاستيك الفينيل (PVC) لا يُصنع منه.","غازات التبريد التي شاعت في ذلك الوقت هي مركبات CFCs، أما الهالوثان فاستُعمل في الطب.","المواد اللاصقة المعروفة بالسيليكون يُستعمل في صناعتها الكلوروميثان، لا الهالوثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('mcq', 5, 2, 'كثيرًا ما تُستعمل هاليدات الألكيل مذيبات ومواد تنظيف؛ لأنها تذيب الجزيئات غير القطبية بسهولة، ومنها الدهون والزيوت.', '["الأوساخ الدهنية والزيتية جزيئات غير قطبية، وهاليدات الألكيل تُستعمل لإذابتها لا لإذابة الأملاح الأيونية.","هاليدات الألكيل لا تنظّف بتكوين صابون مع الماء، بل بإذابتها الجزيئات غير القطبية كالدهون والزيوت.","","ندرتها في الطبيعة حقيقة، لكنها لا تفسر استعمالها مذيبات؛ فالتفسير يعود إلى قدرتها على الإذابة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('mcq', 6, 0, 'الوحدة المتكررة –CF₂– هي وحدة رباعي فلورو بولي إيثين (PTFE)، وهو بلاستيك يُصنع من غاز رباعي فلورو إيثين ويتكون من مئات الوحدات، ويوفر سطحًا غير لاصق لكثير من أدوات المطبخ، ومنها أدوات الخبز.', '["","مواد التبريد جزيئات صغيرة متطايرة (CFCs ثم HFCs)، لا بلاستيك مكون من مئات الوحدات.","المخدر الذي استُعمل في الخمسينيات هو الهالوثان، وهو جزيء صغير لا بوليمر.","البلاستيك المكون من مئات الوحدات مادة صلبة، ولا يُستعمل مذيبًا سائلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('mcq', 7, 3, 'ذرات الهالوجين التي ترتبط بذرات الكربون أكثر نشاطًا من ذرات الهيدروجين المستبدلة؛ ولهذا السبب كثيرًا ما تُستعمل هاليدات الألكيل مواد أولية في الصناعات الكيميائية، إذ يمكن تحويلها بتفاعلات الاستبدال إلى مركبات أخرى.', '["من النادر العثور على الهاليدات العضوية في الطبيعة، فلا يصح القول إنها متوافرة بكثرة.","هذا عكس الصحيح؛ فهاليدات الألكيل أنشط من الألكانات، وهذا سبب استعمالها مواد أولية.","درجات غليان هاليدات الألكيل أعلى لا أقل من الألكانات المقابلة، وليست هي سبب استعمالها مواد أولية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من استعمالات هاليدات الألكيل: (1) المبردات وأنظمة التكييف: مركبات CFCs قديمًا، ثم HFCs مثل 1، 1، 1، 2-رباعي فلورو إيثان. (2) المذيبات ومواد التنظيف: لأنها تذيب الجزيئات غير القطبية كالدهون والزيوت. (3) مواد أولية في الصناعات الكيميائية: لأن ذرات الهالوجين المرتبطة بالكربون أنشط من الهيدروجين، مثل تحويل كلورو إيثان إلى إيثانول. (4) صناعة البلاستيك: رباعي فلورو بولي إيثين (PTFE) للسطوح غير اللاصقة، وكلوريد البولي فينيل (PVC) للصفائح الرقيقة ونماذج الألعاب. ويُقبل أيضًا: الكلوروميثان في صناعة المواد اللاصقة المعروفة بالسيليكون، والهالوثان مخدرًا عامًّا في خمسينيات القرن الماضي.', '["المبردات (CFCs/HFCs)","المذيبات ومواد التنظيف","مواد أولية في الصناعة","البلاستيك (PTFE أو PVC)","أمثلة صحيحة"]'::jsonb, '[]'::jsonb, '[{"element":"أربعة استعمالات صحيحة (نصف درجة لكل استعمال)","marks":2},{"element":"أربعة أمثلة صحيحة (نصف درجة لكل مثال)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"أربعة استعمالات صحيحة مع أمثلتها"},{"level":"2–3 درجات","description":"استعمالان أو ثلاثة مع أمثلتها، أو أربعة دون أمثلة"},{"level":"1 درجة","description":"استعمال واحد أو اثنان دون أمثلة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر PTFE مادة تبريد","ذكر HFCs على أنها تحتوي على الكلور","الخلط بين الكلوروميثان والكلوروفلوروكربونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('essay', 2, null::int, null, null, 'البلاستيك مادة يمكن تسخينها وتشكيلها عندما تكون لينة. مثالان: (1) رباعي فلورو بولي إيثين (PTFE): يُصنع من غاز رباعي فلورو إيثين، ويتكون من مئات الوحدات، ويوفر سطحًا غير لاصق لكثير من أدوات المطبخ مثل صواني الخبز. (2) كلوريد البولي فينيل (PVC) ويسمى الفينيل: يمكن صناعته في صورة لينة أو صلبة، ويمكن تشكيله على شكل صفائح رقيقة أو نماذج للألعاب.', '["تعريف البلاستيك: يُسخن ويُشكل وهو لين","PTFE وأصله واستعماله","PVC واستعماله"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف البلاستيك","marks":1},{"element":"المثال الأول مع استعماله","marks":1.5},{"element":"المثال الثاني مع استعماله","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومثالان صحيحان باستعمالاتهما"},{"level":"2–3 درجات","description":"مثالان دون تعريف، أو تعريف مع مثال واحد"},{"level":"1 درجة","description":"تعريف فقط أو مثال واحد دون استعمال"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر البولي إيثيلين مثالًا على بلاستيك من هاليدات الألكيل مع أنه لا يحتوي على هالوجين","نسبة السطح غير اللاصق إلى PVC"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لأن مركبات CFCs تؤثر في طبقة الأوزون. (ب) مركبات CFCs تحتوي على ذرات كلور وفلور مرتبطة بالكربون، أما مركبات HFCs فتحتوي فقط على ذرات هيدروجين وفلور مرتبطة بالكربون (لا كلور فيها)، ومن أشهرها 1، 1، 1، 2-رباعي فلورو إيثان. (ج) من المزايا: استهلاك كمية أقل من المادة الدوائية فتقل التكلفة، وتقل كمية الدواء التي يتعرض لها المريض (فتقل احتمالات آثاره الجانبية)، وتدوم عبوة البخاخ مدة أطول.', '["CFCs تؤثر في طبقة الأوزون","CFCs فيها كلور وفلور، وHFCs فيها هيدروجين وفلور فقط","ميزتان منطقيتان للجرعة الأقل"]'::jsonb, '[]'::jsonb, '[{"element":"سبب التخلي عن CFCs","marks":1},{"element":"الفرق في التركيب","marks":2},{"element":"ميزتان للجرعة الأقل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الأجزاء الثلاثة صحيحة كاملة"},{"level":"3–4 درجات","description":"نقص في الفرق في التركيب أو ميزة واحدة فقط"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن HFCs تحتوي على الكلور","نسبة الضرر إلى ذرات الفلور وحدها","ذكر مزايا لا علاقة لها بكمية الدواء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.652Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
