('mcq', 2, 'يمثل المخطط الآتي تفاعل استبدال بين 1-برومو بيوتان وأيون الهيدروكسيد في محلول قاعدي. ما نواتج هذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l1b-bromobutane-oh.svg","alt":"مخطط تفاعل يُقرأ من اليسار إلى اليمين: الصيغة البنائية الكاملة لجزيء 1-برومو بيوتان، وهي سلسلة أفقية من أربع ذرات كربون C بينها روابط أحادية، ترتبط بكل ذرة كربون ذرتا هيدروجين H أعلاها وأسفلها، وترتبط بذرة الكربون اليسرى ذرة H ثالثة، وبذرة الكربون اليمنى ذرة بروم Br في طرف السلسلة. يليها إشارة + ثم أيون الهيدروكسيد OH⁻، ثم سهم يتجه إلى اليمين، وبعده علامة استفهام مكان النواتج."}]'::jsonb, '["CH₃CH₂CH₂CH₂OH + Br⁻","CH₃CH₂CH₂CH₂OH + HBr","CH₃CH₂CH₂CH₂OH + Br₂","CH₃CH₂CH₂CH₂Br + H₂O"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'متوسط', 'الكتاب ص 173 — تفاعلات استبدال أخرى'),
('mcq', 3, 'يتفاعل 2-كلورو بروبان مع الماء في تفاعل استبدال وفق المعادلة: CH₃CHClCH₃ + H₂O → ……… + HCl. ما الناتج العضوي الذي يكمل المعادلة؟', null, null, '["CH₃CH₂CH₂OH","CH₃CH=CH₂","CH₃CCl(OH)CH₃","CH₃CH(OH)CH₃"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'متوسط', 'الكتاب ص 203 — تقويم الفصل س50'),
('mcq', 4, 'يمثل المخطط الآتي تفاعل استبدال بين 2-برومو بروبان والأمونيا. ما نواتج هذا التفاعل؟', null, '[{"src":"qimg/chem22/c5-l1b-bromopropane-nh3.svg","alt":"مخطط تفاعل يُقرأ من اليسار إلى اليمين: الصيغة البنائية الكاملة لجزيء 2-برومو بروبان، وهي سلسلة أفقية من ثلاث ذرات كربون C بينها روابط أحادية؛ ترتبط بكل من ذرتي الكربون الطرفيتين ثلاث ذرات هيدروجين H، وترتبط بذرة الكربون الوسطى ذرة هيدروجين من أسفل وذرة بروم Br من أعلى. يليها إشارة + ثم الأمونيا NH₃، ثم سهم يتجه إلى اليمين، وبعده علامة استفهام مكان النواتج."}]'::jsonb, '["CH₃CH₂CH₂NH₂ + HBr","CH₃CH(NH₂)CH₃ + HBr","CH₃CHBrCH₂NH₂ + H₂","CH₃CH(NH₂)CH₃ + Br₂"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'متوسط', 'الكتاب ص 173 — تفاعلات استبدال أخرى'),
('mcq', 5, 'أيّ المعادلات الآتية تمثل تفاعل استبدال مكتوبًا بشكل صحيح وموزون؟', null, null, '["CH₃Cl + OH⁻ → CH₃OH + Cl₂","CH₄ + Cl₂ → CH₃Cl + H₂","CH₃Cl + OH⁻ → CH₃OH + Cl⁻","CH₃CH₂Br + NH₃ → CH₃CH₂NH₂ + Br⁻"]'::jsonb, 'تحليل', 'تقويم معادلات', 'صعب', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 6, 'يبيّن المخطط الآتي تحويل الميثان إلى المركب B في خطوتين، كلتاهما تفاعل استبدال. ما المركبان A وB؟', null, '[{"src":"qimg/chem22/c5-l1b-methane-route.svg","alt":"مخطط من خطوتين يُقرأ من اليسار إلى اليمين: CH₄ ثم سهم كُتب فوقه Br₂ يتجه إلى المركب A، ثم سهم ثانٍ كُتب فوقه OH⁻ يتجه إلى المركب B."}]'::jsonb, '["A هو CH₃Br، وB هو CH₃OH","A هو CH₃Br، وB هو CH₂(OH)Br","A هو CH₄Br₂، وB هو CH₄(OH)₂","A هو HBr، وB هو H₂O"]'::jsonb, 'تحليل', 'تتبع سلسلة تفاعلات', 'صعب', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 7, 'أيّ المواد الآتية تُستعمل لتحويل 1-كلورو هكسان CH₃(CH₂)₄CH₂Cl إلى 1-هكسانول CH₃(CH₂)₄CH₂OH بتفاعل استبدال؟', null, null, '["غاز الأمونيا NH₃","غاز الكلور Cl₂","غاز الهيدروجين H₂","محلول قاعدي فيه OH⁻"]'::jsonb, 'تطبيق', 'اختيار مادة متفاعلة', 'سهل', 'الكتاب ص 173 — تفاعلات استبدال أخرى'),
('essay', 1, 'اكتب معادلة كيميائية موزونة بالصيغ البنائية المكثفة لكل تفاعل استبدال مما يأتي، وحدّد نوع المركب العضوي الناتج: (أ) كلورو إيثان مع أيون الهيدروكسيد OH⁻. (ب) 1-برومو أوكتان مع الأمونيا NH₃. (ج) الإيثان مع البروم Br₂ بحيث تُستبدل ذرة هيدروجين واحدة.', null, null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('essay', 2, 'وُضع 1-برومو بنتان CH₃(CH₂)₃CH₂Br في دورقين: أُضيف إلى الدورق (أ) محلول قاعدي يحتوي على أيونات OH⁻، وأُضيفت إلى الدورق (ب) الأمونيا NH₃. (1) اكتب معادلة التفاعل في كل دورق. (2) سمِّ المجموعة الوظيفية في الناتج العضوي في كل دورق. (3) وضّح لماذا يُصنّف التفاعلان كلاهما تفاعلَي استبدال.', null, null, null, 'تحليل', 'مقارنة تفاعلين', 'متوسط', 'الكتاب ص 173 — تفاعلات استبدال أخرى'),
('essay', 3, 'اقترح طريقة لتحضير إيثيل أمين CH₃CH₂NH₂ من الإيثان في خطوتين، كلتاهما تفاعل استبدال. اكتب معادلة كل خطوة، وحدّد المادة المتفاعلة المضافة في كل خطوة ونوع المركب الناتج عنها، ثم بيّن لماذا لا يصلح اليود في الخطوة الأولى.', null, null, null, 'إبداع', 'تصميم مسار تحضير', 'صعب', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'في تفاعل الاستبدال تحل ذرة أو مجموعة ذرية محل ذرة أو مجموعة ذرية أخرى في المركب، مثل حلول ذرة كلور محل ذرة هيدروجين في الإيثان، أو حلول مجموعة OH محل ذرة الهالوجين في هاليد الألكيل.', '["هذا وصف تفاعل الإضافة، وفيه لا تخرج ذرة من المركب بل تُضاف ذرات إليه.","هذا وصف تفاعل الحذف، لا الاستبدال.","","هذا وصف تفاعل التكثف، لا الاستبدال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 2, 0, 'في تفاعل هاليد الألكيل مع المحاليل القاعدية تحل مجموعة OH⁻ محل ذرة الهالوجين فينتج الكحول: CH₃CH₂CH₂CH₂Br + OH⁻ → CH₃CH₂CH₂CH₂OH + Br⁻. والمعادلة موزونة في الذرات والشحنة (−1 في الطرفين)، والناتج العضوي 1-بيوتانول.', '["","الشحنة غير محفوظة: في المتفاعلات شحنة −1 (أيون OH⁻) والنواتج هنا متعادلة، كما أن ذرات الهيدروجين غير موزونة؛ فالبروم يخرج أيونَ بروميد Br⁻.","غير موزونة: ذرة بروم واحدة في المتفاعلات وذرتان في النواتج، والشحنة غير محفوظة.","هذه المعادلة تُبقي ذرة البروم في مكانها فلا يحدث استبدال، ولا تتوازن الشحنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 3, 3, 'تحل مجموعة OH محل ذرة الكلور على ذرة الكربون 2 نفسها، وتتحد ذرة الكلور مع ذرة الهيدروجين المتبقية من الماء مكونة HCl: CH₃CHClCH₃ + H₂O → CH₃CH(OH)CH₃ + HCl، والناتج 2-بروبانول.', '["مجموعة OH تحل في موقع ذرة الكلور نفسه (ذرة الكربون الوسطى)، فالناتج 2-بروبانول لا 1-بروبانول.","هذا ناتج حذف لا استبدال، والمعادلة لا تتوازن به إذ تبقى ذرتا H وذرة O من الماء بلا مقابل في النواتج.","هذا يعني أن OH حلت محل ذرة هيدروجين لا محل الكلور، ولا تتوازن المعادلة به (ذرتا كلور في النواتج مقابل ذرة واحدة في المتفاعلات).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 4, 1, 'يؤدي تفاعل هاليد الألكيل مع الأمونيا إلى أن تحل مجموعة الأمين NH₂ محل ذرة الهالوجين فينتج أمين وHBr: R–X + NH₃ → R–NH₂ + HX. وتحل NH₂ على ذرة الكربون الوسطى نفسها التي كان البروم مرتبطًا بها، فالنواتج CH₃CH(NH₂)CH₃ + HBr.', '["مجموعة NH₂ تحل محل البروم على ذرة الكربون الوسطى نفسها، لا على ذرة كربون طرفية.","","مجموعة الأمين تحل محل ذرة الهالوجين لا محل ذرة هيدروجين، والناتج الثاني HBr لا H₂.","غير موزونة: ذرة بروم واحدة في المتفاعلات وذرتان في النواتج، وتنقص ذرة هيدروجين؛ فذرة H من NH₃ تتحد مع البروم مكونة HBr."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (59%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 5, 2, 'في المعادلة CH₃Cl + OH⁻ → CH₃OH + Cl⁻ حلت مجموعة OH محل ذرة الكلور، وعدد كل نوع من الذرات متساوٍ في الطرفين (C: 1، H: 4، O: 1، Cl: 1)، والشحنة −1 في الطرفين؛ فهي معادلة استبدال صحيحة موزونة.', '["غير موزونة: ذرة كلور واحدة في المتفاعلات وذرتان في النواتج، والشحنة غير محفوظة.","غير موزونة: ذرتا كلور في المتفاعلات وذرة واحدة في النواتج؛ والناتج الثاني الصحيح للهلجنة HCl لا H₂.","","غير موزونة: 8 ذرات هيدروجين في المتفاعلات و7 في النواتج، والشحنة غير محفوظة؛ والصحيح أن ينتج HBr."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 6, 0, 'في الخطوة الأولى (هلجنة) تحل ذرة بروم محل ذرة هيدروجين في الميثان: CH₄ + Br₂ → CH₃Br + HBr، فالمركب A برومو ميثان. وفي الخطوة الثانية تحل مجموعة OH محل ذرة البروم: CH₃Br + OH⁻ → CH₃OH + Br⁻، فالمركب B ميثانول.', '["","في الخطوة الثانية تحل OH محل ذرة الهالوجين لا محل ذرة الهيدروجين.","الخطوة الأولى استبدال لا إضافة؛ فذرة الكربون في الميثان مشبعة بأربع روابط، وتخرج ذرة H مع ذرة Br في صورة HBr.","HBr ناتج ثانوي للهلجنة وليس المركب العضوي الذي يتفاعل مع OH⁻؛ المركب العضوي الناتج برومو ميثان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('mcq', 7, 3, 'عند تفاعل هاليد الألكيل مع المحاليل القاعدية تحل مجموعة OH⁻ محل ذرة الهالوجين فينتج الكحول: CH₃(CH₂)₄CH₂Cl + OH⁻ → CH₃(CH₂)₄CH₂OH + Cl⁻.', '["تفاعل هاليد الألكيل مع الأمونيا يُنتج أمينًا (R–NH₂) لا كحولًا.","الكلور يُحدث هلجنة فتحل ذرات كلور إضافية محل ذرات الهيدروجين، ولا يتكون كحول.","الهيدروجين لا يُدخل مجموعة OH في المركب، فلا يمكن أن يتكون الكحول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.653Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CH₃CH₂Cl + OH⁻ → CH₃CH₂OH + Cl⁻؛ الناتج كحول (إيثانول). (ب) CH₃(CH₂)₆CH₂Br + NH₃ → CH₃(CH₂)₆CH₂NH₂ + HBr؛ الناتج أمين (أوكتيل أمين). (ج) CH₃CH₃ + Br₂ → CH₃CH₂Br + HBr؛ الناتج هاليد ألكيل (برومو إيثان)، والتفاعل هلجنة.', '["معادلة (أ) موزونة وناتجها كحول","معادلة (ب) موزونة وناتجها أمين مع HBr","معادلة (ج) موزونة وناتجها هاليد ألكيل مع HBr"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة (أ)","marks":1},{"element":"نوع ناتج (أ)","marks":1},{"element":"معادلة (ب)","marks":1},{"element":"نوع ناتج (ب)","marks":1},{"element":"معادلة (ج)","marks":1},{"element":"نوع ناتج (ج)","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"ثلاث معادلات صحيحة موزونة مع تحديد نوع كل ناتج"},{"level":"4–5 درجات","description":"معادلتان صحيحتان أو ثلاث معادلات مع خطأ في نوع ناتج"},{"level":"1–3 درجات","description":"معادلة واحدة صحيحة أو تحديد أنواع النواتج دون معادلات صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة HBr ناتجًا في (أ) بدل أيون Cl⁻","كتابة H₂ بدل HBr في (ج)","جعل NH₂ تحل محل ذرة هيدروجين لا محل البروم في (ب)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.654Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الدورق (أ): CH₃(CH₂)₃CH₂Br + OH⁻ → CH₃(CH₂)₃CH₂OH + Br⁻. الدورق (ب): CH₃(CH₂)₃CH₂Br + NH₃ → CH₃(CH₂)₃CH₂NH₂ + HBr. (2) الناتج في (أ) كحول (1-بنتانول) ومجموعته الوظيفية الهيدروكسيل –OH، والناتج في (ب) أمين (بنتيل أمين) ومجموعته الوظيفية الأمين –NH₂. (3) في كلا التفاعلين حلت مجموعة ذرية (OH في الأول وNH₂ في الثاني) محل ذرة البروم في هاليد الألكيل، دون إضافة ذرات إلى رابطة ثنائية أو تكوين رابطة ثنائية جديدة؛ وهذا هو تعريف تفاعل الاستبدال.', '["معادلة الدورق (أ)","معادلة الدورق (ب)","الهيدروكسيل في (أ) والأمين في (ب)","حلول مجموعة محل ذرة البروم في الحالتين"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة (أ)","marks":1},{"element":"معادلة (ب)","marks":1},{"element":"المجموعتان الوظيفيتان","marks":2},{"element":"تبرير التصنيف","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلتان صحيحتان وتسمية صحيحة للمجموعتين وتبرير دقيق"},{"level":"4–5 درجات","description":"معادلتان صحيحتان مع نقص في التسمية أو التبرير"},{"level":"1–3 درجات","description":"معادلة واحدة صحيحة أو تسمية المجموعتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة HBr في الدورق (أ) بدل Br⁻","الخلط بين مجموعة الأمين NH₂ والأمونيا NH₃ في الناتج","تصنيف تفاعل الأمونيا تفاعل إضافة لأن NH₃ تُضاف إلى المركب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.654Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الخطوة الأولى (هلجنة): يتفاعل الإيثان مع الكلور (أو البروم) فتحل ذرة هالوجين محل ذرة هيدروجين: CH₃CH₃ + Cl₂ → CH₃CH₂Cl + HCl، والناتج هاليد ألكيل (كلورو إيثان). الخطوة الثانية: يتفاعل كلورو إيثان مع الأمونيا فتحل مجموعة NH₂ محل ذرة الكلور: CH₃CH₂Cl + NH₃ → CH₃CH₂NH₂ + HCl، والناتج أمين (إيثيل أمين). ولا يصلح اليود في الخطوة الأولى لأنه لا يتفاعل جيدًا مع الألكانات؛ لذا تُستعمل الهالوجينات الفلور أو الكلور أو البروم.', '["هلجنة الإيثان بمعادلة موزونة","تفاعل هاليد الألكيل مع NH₃ بمعادلة موزونة","تحديد المادة المضافة ونوع الناتج في كل خطوة","اليود لا يتفاعل جيدًا مع الألكانات"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الخطوة الأولى","marks":2},{"element":"معادلة الخطوة الثانية","marks":2},{"element":"سبب استبعاد اليود","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"خطوتان صحيحتان بمعادلتين موزونتين وتحديد المواد والنواتج وسبب استبعاد اليود"},{"level":"3–4 درجات","description":"خطوتان صحيحتان مع خطأ في الموازنة أو غياب سبب استبعاد اليود"},{"level":"1–2 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تحويل الإيثان مباشرة إلى أمين بتفاعله مع الأمونيا","استعمال OH⁻ في الخطوة الثانية فيتكون كحول لا أمين","كتابة H₂ ناتجًا ثانويًّا للهلجنة بدل HCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.654Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O06') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L1-O07'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يمكن النظر إلى كلٍّ من 2-برومو بروبان وبرومو بنزين على أنه ناتج من إحلال ذرة بروم محل ذرة هيدروجين في هيدروكربون. ما الهيدروكربونان اللذان يُشتق منهما المركبان على الترتيب؟', null, null, '["البروبين، والبنزين","البروبان، والهكسان الحلقي","البروبان، والبنزين","البروبين، والهكسان الحلقي"]'::jsonb, 'فهم', 'مقارنة أصل التركيب', 'سهل', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('mcq', 2, 'ما عدد الذرات المرتبطة مباشرة بذرة الكربون التي تحمل ذرة الكلور في كلٍّ من كلورو إيثان CH₃CH₂Cl وكلورو بنزين C₆H₅Cl على الترتيب؟', null, null, '["4 ذرات في كلٍّ منهما","4 ذرات، و3 ذرات","3 ذرات، و4 ذرات","4 ذرات، و5 ذرات"]'::jsonb, 'تحليل', 'مقارنة تراكيب', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('mcq', 3, 'يُعرَّف هاليد الأريل بأنه مركب عضوي يتكون من هالوجين مرتبط بحلقة البنزين أو بمجموعة …', null, null, '["أروماتية أخرى","أليفاتية مشبعة","هيدروكسيل","كربونيل"]'::jsonb, 'تذكر', 'إكمال تعريف', 'سهل', 'الكتاب ص 170 — هاليدات الأريل'),
('mcq', 4, 'أيّ أزواج المركبات الآتية يتكون من هاليد ألكيل ثم هاليد أريل على الترتيب؟', null, null, '["كلورو بنزين، ثم 2-كلورو بروبان","برومو هكسان حلقي، ثم 1-برومو بيوتان","1، 3-ثنائي برومو بنزين، ثم فلورو بنزين","1-برومو بروبان، ثم برومو بنزين"]'::jsonb, 'فهم', 'تصنيف من الاسم', 'سهل', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('mcq', 5, 'عند تسمية هاليدات الألكيل وهاليدات الأريل وفق نظام IUPAC، على أيّ أساس تُبنى تسمية كلٍّ منهما على الترتيب؟', null, null, '["على اسم حلقة البنزين، وعلى اسم الألكان المقابل","على اسم الألكان المقابل، وعلى اسم حلقة البنزين","على اسم الألكين المقابل، وعلى اسم الهكسان الحلقي","على اسم الكحول المقابل، وعلى اسم حلقة البنزين"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 170 — تسمية هاليدات الألكيل والأريل'),
('mcq', 6, 'للمركبين (أ) و(ب) في الشكل الآتي الصيغة الجزيئية نفسها C₇H₇Cl. أيّ العبارات الآتية تقارن بينهما مقارنة صحيحة؟', null, '[{"src":"qimg/chem22/c5-l1b-c7h7cl-pair.svg","alt":"مركبان يفصل بينهما خط متقطع رأسي. على اليمين المركب (أ): حلقة بنزين مرسومة سداسيًّا في داخله دائرة، ترتبط بالرأس العلوي للحلقة مجموعة ميثيل CH₃، وترتبط بالرأس السفلي المقابل له مباشرة ذرة كلور Cl. على اليسار المركب (ب): حلقة بنزين مرسومة سداسيًّا في داخله دائرة، ترتبط بالرأس العلوي للحلقة مجموعة CH₂ تقع خارج الحلقة، وترتبط بمجموعة CH₂ هذه من أعلى ذرة كلور Cl، ولا يرتبط بالحلقة نفسها أي هالوجين."}]'::jsonb, '["كلاهما هاليد أريل؛ لأن كلًّا منهما يحتوي على حلقة بنزين","كلاهما من النوع نفسه؛ لأن لهما الصيغة الجزيئية نفسها","(أ) هاليد أريل، و(ب) هاليد ألكيل؛ لاختلاف ذرة الكربون الحاملة للكلور","(أ) هاليد ألكيل، و(ب) هاليد أريل؛ لأن (أ) يحتوي على مجموعة ميثيل"]'::jsonb, 'تحليل', 'مقارنة متشكلين', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('mcq', 7, 'يحتوي الجزيء الذي يمثله الشكل الآتي على ذرة بروم وذرة كلور. أيّ العبارات الآتية تصف نوع ذرة الكربون المرتبطة بكلٍّ منهما؟', null, '[{"src":"qimg/chem22/c5-l1b-mixed-halide.svg","alt":"حلقة بنزين مرسومة سداسيًّا في داخله دائرة. ترتبط بالرأس السفلي للحلقة مباشرة ذرة بروم Br. وترتبط بالرأس العلوي المقابل مجموعة CH₂ تقع خارج الحلقة، وترتبط بمجموعة CH₂ هذه من أعلى ذرة كلور Cl."}]'::jsonb, '["البروم مرتبط بذرة كربون في حلقة البنزين، والكلور مرتبط بذرة كربون أليفاتية","الكلور مرتبط بذرة كربون في حلقة البنزين، والبروم مرتبط بذرة كربون أليفاتية","ذرتا الهالوجين كلتاهما مرتبطتان بذرات كربون في حلقة البنزين","ذرتا الهالوجين كلتاهما مرتبطتان بذرات كربون أليفاتية"]'::jsonb, 'تحليل', 'تحليل بنية', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('essay', 1, 'ارسم الصيغة البنائية لكلٍّ من 1، 2-ثنائي برومو إيثان و1، 2-ثنائي برومو بنزين، ثم قارن بينهما من حيث: (أ) الهيدروكربون الذي يُشتق منه كل مركب بإحلال ذرتي بروم محل ذرتي هيدروجين. (ب) عدد الذرات المرتبطة بكل ذرة كربون تحمل ذرة بروم، ونوع هذه الذرات. (ج) نوع كل مركب: هاليد ألكيل أم هاليد أريل.', null, null, null, 'تحليل', 'رسم ومقارنة', 'متوسط', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('essay', 2, 'اكتب الصيغة البنائية لمركبين مختلفين صيغة كلٍّ منهما الجزيئية C₇H₇Br، أحدهما هاليد ألكيل والآخر هاليد أريل، وبيّن سبب تصنيف كل منهما، ثم استنتج: هل تكفي الصيغة الجزيئية وحدها لتحديد نوع الهاليد العضوي؟', null, null, null, 'إبداع', 'اقتراح متشكلين', 'صعب', 'الكتاب ص 169–170 — هاليدات الألكيل وهاليدات الأريل'),
('essay', 3, 'يمثل الشكل الآتي مركبًا مشتقًّا من النفثالين (حلقتا بنزين ملتحمتان) بإحلال ذرة بروم محل ذرة هيدروجين. (أ) صنّف هذا المركب: هاليد ألكيل أم هاليد أريل؟ وبرّر إجابتك. (ب) ما الجزء من تعريف هاليدات الأريل الذي يسمح بتصنيف هذا المركب مع أنه لا يحتوي على حلقة بنزين منفردة؟ (ج) لو ارتبطت ذرة البروم بمجموعة CH₂ متصلة بالنفثالين بدلًا من ارتباطها بالحلقة مباشرة، فما نوع المركب الناتج؟ ولماذا؟', null, '[{"src":"qimg/chem22/c5-l1b-bromonaphthalene.svg","alt":"حلقتان سداسيتان ملتحمتان جنبًا إلى جنب تشتركان في ضلع رأسي واحد، وفي داخل كل حلقة دائرة (حلقتا بنزين ملتحمتان: النفثالين). ترتبط ذرة بروم Br برابطة أحادية بالرأس العلوي للحلقة اليسرى، وهو الرأس المجاور لذرة الكربون المشتركة بين الحلقتين."}]'::jsonb, null, 'فهم', 'تصنيف وتبرير', 'سهل', 'الكتاب ص 170 — هاليدات الأريل؛ ص 151 — الحلقات الملتحمة (النفثالين)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O07') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'ينتج هاليد الألكيل عندما تحل ذرة هالوجين محل ذرة هيدروجين في ألكان، فـ 2-برومو بروبان مشتق من البروبان (ويُبنى اسمه عليه). أما هاليد الأريل فيُشتق من مركب أروماتي تحل فيه ذرة الهالوجين محل ذرة هيدروجين في الحلقة، فبرومو بنزين مشتق من البنزين. فالهيدروكربونان هما البروبان والبنزين.', '["2-برومو بروبان مشتق من ألكان (البروبان) لا من ألكين؛ فلا رابطة ثنائية في سلسلته.","برومو بنزين هاليد أريل؛ فذرة البروم فيه مرتبطة بحلقة البنزين الأروماتية لا بحلقة الهكسان الحلقي المشبعة.","","كلا الاختيارين خطأ: 2-برومو بروبان مشتق من البروبان لا البروبين، وبرومو بنزين مشتق من البنزين لا الهكسان الحلقي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.654Z"}'::jsonb),
('mcq', 2, 1, 'في كلورو إيثان ترتبط ذرة الكربون الحاملة للكلور (في المجموعة CH₂Cl) بذرة الكلور وذرتي هيدروجين وذرة الكربون المجاورة، أي بـ 4 ذرات بروابط أحادية؛ فهي ذرة كربون أليفاتية مشبعة. أما في كلورو بنزين فكل ذرة كربون في حلقة البنزين ترتبط بذرتي كربون مجاورتين في الحلقة وبذرة ثالثة، وقد حلت ذرة الكلور محل ذرة الهيدروجين الوحيدة على ذرة الكربون الحاملة له، فهي مرتبطة بـ 3 ذرات فقط (Cl وذرتي كربون).', '["ذرة الكربون الحاملة للكلور في حلقة البنزين لا ترتبط إلا بذرتي الكربون المجاورتين لها في الحلقة وبذرة الكلور، أي 3 ذرات.","","الترتيب معكوس: ذرة الكربون الأليفاتية في كلورو إيثان هي المرتبطة بأربع ذرات، وذرة الكربون في الحلقة مرتبطة بثلاث.","ذرة الكربون في حلقة البنزين ترتبط بذرتي كربون مجاورتين فقط في الحلقة، لا بأربع ذرات كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.654Z"}'::jsonb),
('mcq', 3, 0, 'هاليدات الأريل مركبات عضوية تتكون من هالوجين مرتبط بحلقة البنزين أو بمجموعة أروماتية أخرى.', '["","ارتباط الهالوجين بذرة كربون أليفاتية يجعل المركب هاليد ألكيل لا هاليد أريل.","الهيدروكسيل –OH المجموعة الوظيفية للكحولات، والهالوجين يرتبط بالكربون لا بها.","الكربونيل المجموعة الوظيفية للألدهيدات والكيتونات، ولا علاقة له بتعريف هاليد الأريل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.655Z"}'::jsonb),
('mcq', 4, 3, 'في 1-برومو بروبان ترتبط ذرة البروم بذرة كربون أليفاتية في سلسلة البروبان، فهو هاليد ألكيل؛ وفي برومو بنزين ترتبط ذرة البروم بذرة كربون في حلقة البنزين، فهو هاليد أريل. فهذا الزوج هاليد ألكيل ثم هاليد أريل.', '["الترتيب معكوس: كلورو بنزين هاليد أريل، و2-كلورو بروبان هاليد ألكيل.","المركبان كلاهما هاليد ألكيل؛ فحلقة الهكسان الحلقي حلقة أليفاتية مشبعة وليست حلقة بنزين.","المركبان كلاهما هاليد أريل؛ ففي كل منهما ترتبط ذرة الهالوجين بحلقة البنزين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.655Z"}'::jsonb),
('mcq', 5, 1, 'تُسمى هاليدات الألكيل اعتمادًا على السلسلة الرئيسة للألكان (مثل 2-كلورو بروبان)، أما هاليدات الأريل فتُبنى تسميتها على حلقة البنزين مع ترقيمها (مثل كلورو بنزين و1-برومو-3، 5-ثنائي أيودو بنزين).', '["الترتيب معكوس: الألكان أساس تسمية هاليدات الألكيل، وحلقة البنزين أساس تسمية هاليدات الأريل.","","هاليدات الألكيل تُسمى على الألكان لا الألكين، والحلقة في هاليدات الأريل حلقة بنزين لا هكسان حلقي.","هاليدات الألكيل لا تُسمى اعتمادًا على الكحولات، بل على سلسلة الألكان الرئيسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.655Z"}'::jsonb),
('mcq', 6, 2, 'نوع الهاليد يحدده نوع ذرة الكربون المرتبطة بذرة الهالوجين لا الصيغة الجزيئية. في (أ) ترتبط ذرة الكلور مباشرة بذرة كربون في حلقة البنزين، فهو هاليد أريل. وفي (ب) ترتبط ذرة الكلور بذرة الكربون في المجموعة CH₂ الواقعة خارج الحلقة، وهي ذرة كربون أليفاتية، فهو هاليد ألكيل.', '["وجود حلقة البنزين لا يكفي؛ ففي (ب) ترتبط ذرة الكلور بالمجموعة CH₂ خارج الحلقة، وهي ذرة كربون أليفاتية.","تساوي الصيغة الجزيئية لا يعني تساوي النوع؛ فالمعيار نوع ذرة الكربون المرتبطة بالكلور، وهي مختلفة في المركبين.","","الوصف معكوس: مجموعة الميثيل في (أ) لا تحمل الكلور، والكلور فيه مرتبط بالحلقة مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.656Z"}'::jsonb),
('mcq', 7, 0, 'ذرة البروم مرتبطة مباشرة بأحد رؤوس حلقة البنزين، فارتباطها من نوع هاليد الأريل. أما ذرة الكلور فمرتبطة بذرة الكربون في المجموعة CH₂ الواقعة خارج الحلقة، وهي ذرة كربون أليفاتية، فارتباطها من نوع هاليد الألكيل.', '["","الوصف معكوس: البروم هو المرتبط بالحلقة، والكلور مرتبط بالمجموعة CH₂ خارجها.","ذرة الكلور مرتبطة بالمجموعة CH₂ خارج الحلقة لا بالحلقة نفسها.","ذرة البروم مرتبطة مباشرة بذرة كربون في حلقة البنزين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.656Z"}'::jsonb),
('essay', 1, null::int, null, null, '1، 2-ثنائي برومو إيثان BrCH₂–CH₂Br: ذرتا كربون مترابطتان برابطة أحادية، ترتبط بكل منهما ذرة بروم وذرتا هيدروجين. 1، 2-ثنائي برومو بنزين: حلقة بنزين (سداسي في داخله دائرة) ترتبط ذرتا بروم برأسين متجاورين فيها. (أ) الأول مشتق من الإيثان (ألكان)، والثاني مشتق من البنزين (مركب أروماتي). (ب) في الأول ترتبط كل ذرة كربون حاملة للبروم بأربع ذرات بروابط أحادية: ذرة بروم وذرتا هيدروجين وذرة كربون؛ أما في الثاني فترتبط كل ذرة كربون حاملة للبروم بثلاث ذرات فقط: ذرة بروم وذرتا كربون من الحلقة، ولا هيدروجين عليها. (ج) الأول هاليد ألكيل لأن البروم مرتبط بذرات كربون أليفاتية، والثاني هاليد أريل لأن البروم مرتبط بذرات كربون في حلقة البنزين.', '["رسم 1، 2-ثنائي برومو إيثان","رسم 1، 2-ثنائي برومو بنزين","الإيثان والبنزين أصلا المركبين","4 ذرات مقابل 3 ذرات على ذرة الكربون الحاملة للبروم","هاليد ألكيل وهاليد أريل"]'::jsonb, '[]'::jsonb, '[{"element":"الرسمان","marks":2},{"element":"(أ) الهيدروكربونان","marks":1},{"element":"(ب) عدد الذرات ونوعها","marks":2},{"element":"(ج) التصنيف","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"رسمان صحيحان ومقارنة صحيحة في البنود الثلاثة"},{"level":"3–5 درجات","description":"رسمان صحيحان مع خطأ في عدد الذرات أو في أصل أحد المركبين"},{"level":"1–2 درجة","description":"رسم واحد صحيح أو تصنيف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم ذرتي البروم على رأسين غير متجاورين في الحلقة","عدّ ذرة هيدروجين على ذرة الكربون الحاملة للبروم في الحلقة","عدّ 1، 2-ثنائي برومو إيثان مشتقًّا من الإيثين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.656Z"}'::jsonb),
('essay', 2, null::int, null, null, 'هاليد الأريل: حلقة بنزين ترتبط بأحد رؤوسها مجموعة ميثيل CH₃، وترتبط ذرة البروم مباشرة برأس آخر من الحلقة (مثل البروم في الرأس المقابل لمجموعة الميثيل)؛ فهو هاليد أريل لأن البروم مرتبط بذرة كربون في حلقة البنزين. هاليد الألكيل: حلقة بنزين ترتبط بأحد رؤوسها مجموعة CH₂ ترتبط بها ذرة البروم (C₆H₅–CH₂Br)؛ فهو هاليد ألكيل لأن البروم مرتبط بذرة كربون أليفاتية خارج الحلقة. وللمركبين الصيغة الجزيئية نفسها C₇H₇Br؛ فالصيغة الجزيئية وحدها لا تكفي، والمعيار هو نوع ذرة الكربون المرتبطة بذرة الهالوجين، ولا يظهر إلا من الصيغة البنائية. (يُقبل للأريل أي موقع للبروم على الحلقة بالنسبة إلى مجموعة الميثيل.)', '["صيغة هاليد أريل صحيحة C₇H₇Br","صيغة هاليد ألكيل صحيحة C₆H₅CH₂Br","تبرير التصنيفين بنوع ذرة الكربون","الصيغة الجزيئية لا تكفي"]'::jsonb, '[]'::jsonb, '[{"element":"صيغة هاليد الأريل","marks":1},{"element":"صيغة هاليد الألكيل","marks":1},{"element":"تبرير التصنيفين","marks":2},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"صيغتان صحيحتان بالصيغة الجزيئية المطلوبة مع تبرير واستنتاج صحيحين"},{"level":"3–4 درجات","description":"صيغتان صحيحتان مع تبرير ناقص أو دون استنتاج"},{"level":"1–2 درجة","description":"صيغة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغة لا تحقق C₇H₇Br مثل C₆H₅Br","عدّ C₆H₅CH₂Br هاليد أريل لاحتوائه على حلقة بنزين","رسم البروم ومجموعة الميثيل على ذرة الكربون نفسها في الحلقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.656Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) هاليد أريل؛ لأن ذرة البروم مرتبطة مباشرة بذرة كربون في حلقة أروماتية (إحدى حلقتي النفثالين). (ب) تعريف هاليدات الأريل: هالوجين مرتبط بحلقة البنزين «أو بمجموعة أروماتية أخرى»، والنفثالين مجموعة أروماتية. (ج) يصبح هاليد ألكيل؛ لأن ذرة البروم تكون مرتبطة بذرة كربون أليفاتية (في المجموعة CH₂) لا بذرة كربون في الحلقة الأروماتية.', '["(أ) هاليد أريل مع التبرير","(ب) «أو مجموعة أروماتية أخرى»","(ج) هاليد ألكيل لأن الكربون الحامل للبروم أليفاتي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التصنيف والتبرير","marks":2},{"element":"(ب) جزء التعريف","marks":1},{"element":"(ج) النوع والتبرير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصنيفان صحيحان مبرران وتحديد صحيح لجزء التعريف"},{"level":"3–4 درجات","description":"تصنيفان صحيحان مع تبرير ناقص"},{"level":"1–2 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المركب ليس هاليد أريل لأنه لا يحتوي على حلقة بنزين منفردة","عدّ المركب في (ج) هاليد أريل لوجود الحلقات الأروماتية","الخلط بين النفثالين والهكسان الحلقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.656Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O07') and x.type = v.type and x.number = v.number
