insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L1-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ هاليدات الميثيل الآتية يُتوقع أن تكون درجة غليانه الأعلى؟', null, null, '["CH₃F","CH₃Cl","CH₃Br","CH₃I"]'::jsonb, 'فهم', 'توقع', 'سهل', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 2, 'يبيّن المخطط الآتي درجات غليان البيوتان وعدد من هاليدات الألكيل المشتقة منه، وقد أُخفيت قيمة C₄H₉Br. ما القيمة المتوقعة لدرجة غليانه؟', null, '[{"src":"qimg/chem22/c5-l1b-butyl-bars.svg","alt":"مخطط أعمدة رأسي. المحور الأفقي عنوانه «المركب» ويحمل من اليسار إلى اليمين: C₄H₁₀ وقيمته −0.5 (عمود قصير جدًّا عند الصفر تقريبًا)، ثم C₄H₉F وقيمته 32، ثم C₄H₉Cl وقيمته 78، ثم C₄H₉Br ولا يوجد له عمود بل علامة استفهام، ثم C₄H₉I وقيمته 131. المحور الرأسي عنوانه «درجة الغليان» بوحدة °C ومدرّج من −20 إلى 160 بفواصل 20. جميع الهاليدات مشتقة من البيوتان بإحلال ذرة الهالوجين محل ذرة هيدروجين على ذرة كربون طرفية."}]'::jsonb, '["70°C تقريبًا","102°C تقريبًا","30°C تقريبًا","145°C تقريبًا"]'::jsonb, 'تحليل', 'استنتاج من رسم بياني', 'متوسط', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 3, 'أيّ الترتيبات الآتية يمثل الترتيب التصاعدي الصحيح للمركبات CH₃CH₂CH₃ وCH₃CH₂CH₂Cl وCH₃CH₂CH₂Br وCH₃CH₂CH₂I بحسب درجة غليانها المتوقعة؟', null, null, '["CH₃CH₂CH₂I < CH₃CH₂CH₂Br < CH₃CH₂CH₂Cl < CH₃CH₂CH₃","CH₃CH₂CH₂Cl < CH₃CH₂CH₂Br < CH₃CH₂CH₂I < CH₃CH₂CH₃","CH₃CH₂CH₃ < CH₃CH₂CH₂Cl < CH₃CH₂CH₂Br < CH₃CH₂CH₂I","CH₃CH₂CH₃ < CH₃CH₂CH₂I < CH₃CH₂CH₂Br < CH₃CH₂CH₂Cl"]'::jsonb, 'تحليل', 'ترتيب وتوقع', 'متوسط', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 4, 'أيّ هاليدات الأريل الآتية يُتوقع أن تكون درجة غليانه أقرب إلى درجة غليان البنزين؟', null, null, '["فلورو بنزين؛ لأن ذرة الفلور أقل الهالوجينات إلكترونات","أيودو بنزين؛ لأن ذرة اليود أكبر الهالوجينات حجمًا","كلورو بنزين؛ لأن ذرة الكلور أصغر حجمًا من ذرة الفلور","برومو بنزين؛ لأن ذرة البروم تحتوي على أقل عدد من الإلكترونات"]'::jsonb, 'تحليل', 'توقع وتبرير', 'صعب', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 5, 'درجة غليان الهكسان 69°C، ودرجة غليان 1-كلورو بنتان 108°C. ما القيمة الأقرب لدرجة غليان 1-كلورو هكسان؟', null, null, '["45°C","69°C","100°C","135°C"]'::jsonb, 'تحليل', 'توقع من بيانات', 'صعب', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 6, 'أيّ المقارنات الآتية بين درجتي غليان مركبين صحيحة؟', null, null, '["درجة غليان CH₃CH₂Br أعلى من درجة غليان CH₃CH₂I","درجة غليان CH₃CH₂CH₂I أعلى من درجة غليان CH₃CH₂CH₂F","درجة غليان CH₃CH₃ أعلى من درجة غليان CH₃CH₂Cl","درجة غليان CH₄ أعلى من درجة غليان CH₃Br"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('mcq', 7, 'سُخِّن خليط من 1-كلورو بيوتان و1-أيودو بيوتان تسخينًا تدريجيًّا. أيّ المركبين يُتوقع أن يغلي أولًا، ولماذا؟', null, null, '["1-أيودو بيوتان؛ لأن جزيئاته أكبر كتلة فتنفصل أسرع","1-أيودو بيوتان؛ لأن الرابطة C–I أضعف فتنكسر أولًا","1-كلورو بيوتان؛ لأن قوى التجاذب بين جزيئاته أضعف","يغليان معًا؛ لأن لهما السلسلة الكربونية نفسها"]'::jsonb, 'فهم', 'توقع وتبرير', 'سهل', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('essay', 1, 'درجة غليان البنزين 80°C، ودرجة غليان كلورو بنزين 132°C، ودرجة غليان أيودو بنزين 188°C. (أ) توقّع المدى الذي تقع فيه درجة غليان برومو بنزين، وبرّر توقعك. (ب) رتّب البنزين وفلورو بنزين وكلورو بنزين وبرومو بنزين وأيودو بنزين تصاعديًّا بحسب درجة الغليان المتوقعة. (ج) هل تتبع هاليدات الأريل في درجات غليانها النمط نفسه الذي تتبعه هاليدات الألكيل؟ فسّر ذلك.', null, null, null, 'تحليل', 'توقع وتبرير', 'متوسط', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)، ص 173 — تقويم س7'),
('essay', 2, 'يبيّن الجدول الآتي درجات غليان الميثان والإيثان وبعض هاليدات الألكيل المشتقة منهما، وقد أُخفيت قيمتان رُمز لهما بـ «؟». إذا علمت أن القيمتين المخفيتين هما 4°C و72°C: (أ) حدّد قيمة كل من CH₃Br وCH₃CH₂I، وبرّر اختيارك. (ب) توقّع المدى الذي تقع فيه درجة غليان فلورو إيثان CH₃CH₂F، وبرّر توقعك. (ج) قارن درجة غليان كل هاليد ميثيل بدرجة غليان هاليد الإيثيل الذي يحتوي على الهالوجين نفسه، ثم فسّر الفرق.', '{"headers":["المركب","الصيغة","درجة الغليان (°C)"],"rows":[["ميثان","CH₄","−162"],["كلورو ميثان","CH₃Cl","−24"],["برومو ميثان","CH₃Br","؟"],["أيودو ميثان","CH₃I","42"],["إيثان","CH₃CH₃","−89"],["كلورو إيثان","CH₃CH₂Cl","12"],["برومو إيثان","CH₃CH₂Br","38"],["أيودو إيثان","CH₃CH₂I","؟"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات وتوقع', 'صعب', 'الكتاب ص 171 — خواص هاليدات الألكيل (الجدول 5-2)'),
('essay', 3, 'تنتج من الميثان بالهلجنة المتتالية المركبات: CH₃Cl وCH₂Cl₂ وCHCl₃ وCCl₄. (أ) رتّب الميثان وهذه المركبات الأربعة تصاعديًّا بحسب درجة الغليان المتوقعة. (ب) برّر ترتيبك. (ج) إذا علمت أن درجة غليان CH₂Cl₂ تساوي 40°C ودرجة غليان CCl₄ تساوي 77°C، فما المدى المتوقع لدرجة غليان CHCl₃؟', null, null, null, 'تحليل', 'ترتيب وتوقع', 'صعب', 'الكتاب ص 171 — خواص هاليدات الألكيل (توسيع للنمط)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L1-O08') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'تزداد درجة غليان هاليدات الألكيل التي لها السلسلة نفسها عند الانتقال من الفلور إلى اليود، لأن عدد الإلكترونات البعيدة عن النواة يزداد فتتكون ثنائيات قطب مؤقتة أقوى؛ فأعلاها غليانًا CH₃I.', '["ذرة الفلور أقل الهالوجينات إلكترونات، فقوى التجاذب بين جزيئات CH₃F أضعف ودرجة غليانه أقل.","درجة غليان كلورو ميثان (−24°C) أقل من مشتقي البروم واليود لأن ذرة الكلور أصغر وأقل إلكترونات.","ذرة البروم أقل إلكترونات من ذرة اليود، فدرجة غليان CH₃Br أقل من درجة غليان CH₃I.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 2, 1, 'تزداد درجة الغليان من الفلور إلى اليود، فيجب أن تقع درجة غليان C₄H₉Br بين درجة غليان C₄H₉Cl (78°C) ودرجة غليان C₄H₉I (131°C)، والقيمة الوحيدة في هذا المدى 102°C تقريبًا.', '["هذه القيمة أقل من درجة غليان C₄H₉Cl (78°C)، مع أن البروم أكثر إلكترونات من الكلور.","","هذه القيمة أقل حتى من درجة غليان C₄H₉F (32°C)، وهذا يناقض ازدياد درجة الغليان من الفلور إلى البروم.","هذه القيمة أعلى من درجة غليان C₄H₉I (131°C)، مع أن البروم أقل إلكترونات من اليود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 3, 2, 'يُتوقع الترتيب بقاعدتين: (1) درجة غليان هاليد الألكيل أعلى من درجة غليان الألكان المقابل له، فالبروبان أقلها. (2) للهاليدات التي لها السلسلة نفسها تزداد درجة الغليان من الكلور إلى البروم إلى اليود، لازدياد عدد الإلكترونات البعيدة عن النواة وازدياد ثنائيات القطب المؤقتة. فالترتيب: البروبان < 1-كلورو بروبان < 1-برومو بروبان < 1-أيودو بروبان. أي: CH₃CH₂CH₃ < CH₃CH₂CH₂Cl < CH₃CH₂CH₂Br < CH₃CH₂CH₂I.', '["هذا الترتيب تنازلي لا تصاعدي؛ فهو يجعل الألكان أعلاها غليانًا ومشتق اليود أقلها.","الألكان لا يكون أعلاها غليانًا؛ فإحلال ذرة هالوجين محل ذرة هيدروجين يرفع درجة الغليان.","","ترتيب الهاليدات معكوس: درجة الغليان تزداد من الكلور إلى اليود لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 4, 0, 'إحلال ذرة هالوجين محل ذرة هيدروجين يرفع درجة الغليان بمقدار يزداد بازدياد عدد إلكترونات الهالوجين. والفلور أقل الهالوجينات إلكترونات، فيكون الارتفاع في حالته أصغر، وتكون درجة غليان فلورو بنزين أقرب إلى درجة غليان البنزين.', '["","كبر ذرة اليود وكثرة إلكتروناتها يجعلان الفرق عن البنزين أكبر لا أصغر.","ذرة الكلور أكبر من ذرة الفلور لا أصغر، وفيها إلكترونات أكثر.","ذرة البروم تحتوي على إلكترونات أكثر من الفلور والكلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 5, 3, '1-كلورو هكسان هاليد ألكيل، فدرجة غليانه أعلى من درجة غليان الألكان المقابل (الهكسان 69°C). وهو أيضًا أكبر من 1-كلورو بنتان بذرة كربون، فجزيئاته أكبر وفيها إلكترونات أكثر وقوى التجاذب بينها أقوى، فدرجة غليانه أعلى من 108°C؛ والقيمة المناسبة 135°C.', '["هذه القيمة أقل من درجة غليان الهكسان، مع أن هاليد الألكيل يغلي عند درجة أعلى من الألكان المقابل.","هذه درجة غليان الهكسان نفسه، وإحلال ذرة الكلور محل ذرة الهيدروجين يرفع درجة الغليان.","هذه القيمة أقل من درجة غليان 1-كلورو بنتان (108°C)، مع أن 1-كلورو هكسان أكبر منه بذرة كربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 6, 1, 'للمركبين السلسلة نفسها، واليود أكثر إلكترونات من الفلور، فثنائيات القطب المؤقتة بين جزيئات CH₃CH₂CH₂I أقوى، ودرجة غليانه أعلى.', '["العكس صحيح: اليود أكثر إلكترونات من البروم، فدرجة غليان CH₃CH₂I أعلى.","","درجة غليان هاليد الألكيل أعلى من الألكان المقابل، فـ CH₃CH₂Cl هو الأعلى.","إحلال ذرة بروم محل ذرة هيدروجين في الميثان يرفع درجة الغليان، فـ CH₃Br هو الأعلى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('mcq', 7, 2, 'ذرة الكلور أقل إلكترونات من ذرة اليود، فثنائيات القطب المؤقتة بين جزيئات 1-كلورو بيوتان أضعف، وتلزم طاقة أقل لفصلها؛ فدرجة غليانه أقل ويغلي أولًا.', '["الجزيئات الأكبر ذات الإلكترونات الأكثر تتجاذب أكثر، فتحتاج إلى طاقة أكبر لتنفصل.","الغليان تغير فيزيائي يفصل الجزيئات بعضها عن بعض، ولا تنكسر فيه الروابط داخل الجزيء.","","نوع الهالوجين يغير درجة الغليان رغم تساوي السلسلة الكربونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.657Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) بين 132°C و188°C؛ لأن ذرة البروم تقع بين الكلور واليود في عدد الإلكترونات وحجم الذرة، فتكون درجة غليان برومو بنزين أعلى من درجة غليان كلورو بنزين وأقل من درجة غليان أيودو بنزين. (ب) البنزين < فلورو بنزين < كلورو بنزين < برومو بنزين < أيودو بنزين؛ فالبنزين أقلها لأن إحلال أي ذرة هالوجين محل ذرة هيدروجين يرفع درجة الغليان، والفلور أقل الهالوجينات إلكترونات فيكون مشتقه الأقرب إلى البنزين. (ج) نعم؛ فدرجة غليان الهاليد أعلى من درجة غليان الهيدروكربون المقابل، وتزداد من الفلور إلى اليود، لأن عدد الإلكترونات البعيدة عن النواة يزداد، وهي تغير مكانها بسهولة، فيزداد ميل الجزيئات لتكوين ثنائيات قطب مؤقتة تتجاذب معًا، وتزداد الطاقة اللازمة لفصل الجزيئات.', '["المدى بين 132°C و188°C مع التبرير","الترتيب الصحيح للمركبات الخمسة","النمط نفسه مع التفسير بثنائيات القطب المؤقتة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المدى والتبرير","marks":2},{"element":"(ب) الترتيب","marks":2},{"element":"(ج) الحكم والتفسير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"مدى صحيح مبرر وترتيب صحيح وتفسير كامل"},{"level":"3–5 درجات","description":"مدى وترتيب صحيحان مع تفسير ناقص، أو خطأ في موقع البنزين أو فلورو بنزين"},{"level":"1–2 درجة","description":"مدى صحيح فقط أو ترتيب صحيح جزئيًّا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع فلورو بنزين قبل البنزين لصغر ذرة الفلور","توقع درجة غليان لبرومو بنزين أعلى من 188°C","التفسير بقوة الرابطة C–X أو بالروابط الهيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.658Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₃Br = 4°C وCH₃CH₂I = 72°C؛ لأن درجة غليان مشتق البروم يجب أن تقع بين درجتي غليان مشتقي الكلور واليود: بين −24°C و42°C لهاليدات الميثيل، والقيمة 4°C وحدها في هذا المدى. ودرجة غليان CH₃CH₂I يجب أن تكون أعلى من درجة غليان CH₃CH₂Br (38°C)، والقيمة 72°C وحدها تحقق ذلك. (ب) بين −89°C و12°C؛ لأن هاليد الألكيل أعلى غليانًا من الألكان المقابل (الإيثان)، والفلور أقل إلكترونات من الكلور فيكون مشتقه أقل غليانًا من كلورو إيثان. (ج) درجة غليان هاليد الإيثيل أعلى دائمًا: 12 − (−24) = 36°C للكلور، و38 − 4 = 34°C للبروم، و72 − 42 = 30°C لليود. والسبب أن جزيء هاليد الإيثيل أكبر بمجموعة CH₂ وفيه إلكترونات أكثر، فتكون قوى التجاذب بين جزيئاته أقوى والطاقة اللازمة لفصلها أكبر.', '["CH₃Br = 4°C وCH₃CH₂I = 72°C مع التبرير","المدى بين −89°C و12°C مع التبرير","هاليد الإيثيل أعلى بنحو 30–36°C","التفسير بكبر الجزيء وازدياد التجاذب"]'::jsonb, '["CH₃Br بين −24°C و42°C ← 4°C","CH₃CH₂I أعلى من 38°C ← 72°C","الفروق: 12 − (−24) = 36°C، 38 − 4 = 34°C، 72 − 42 = 30°C"]'::jsonb, '[{"element":"(أ) تحديد القيمتين والتبرير","marks":2},{"element":"(ب) المدى والتبرير","marks":2},{"element":"(ج) المقارنة والتفسير","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"قيمتان صحيحتان مبررتان ومدى صحيح ومقارنة مفسرة"},{"level":"3–5 درجات","description":"قيمتان صحيحتان مع خطأ في المدى أو تفسير ناقص"},{"level":"1–2 درجة","description":"تحديد القيمتين دون تبرير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إسناد 72°C إلى CH₃Br لأن البروم أثقل من الكلور","توقع درجة غليان فلورو إيثان أقل من درجة غليان الإيثان","حساب الفرق 12 − 24 بإهمال الإشارة السالبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.658Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) CH₄ < CH₃Cl < CH₂Cl₂ < CHCl₃ < CCl₄. (ب) كلما حلت ذرة كلور إضافية محل ذرة هيدروجين ازداد عدد الإلكترونات في الجزيء، ومنها إلكترونات خارجية بعيدة عن النواة تتحرك بسهولة، فيزداد ميل الجزيئات لتكوين ثنائيات قطب مؤقتة، وتزداد قوى التجاذب بينها والطاقة اللازمة لفصلها، فترتفع درجة الغليان؛ كما أن هاليد الألكيل أعلى غليانًا من الألكان المقابل. (ج) تقع درجة غليان CHCl₃ بين 40°C و77°C، لأن عدد ذرات الكلور فيه (3) بين عددها في CH₂Cl₂ (2) وCCl₄ (4).', '["الترتيب الصحيح","ازدياد عدد ذرات الكلور يزيد الإلكترونات وثنائيات القطب المؤقتة","المدى بين 40°C و77°C"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب","marks":2},{"element":"التبرير","marks":2},{"element":"توقع المدى","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ترتيب صحيح وتبرير كامل وتوقع صحيح للمدى"},{"level":"3–4 درجات","description":"ترتيب صحيح مع تبرير ناقص أو توقع خاطئ"},{"level":"1–2 درجة","description":"ترتيب صحيح جزئيًّا"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الميثان بعد كلورو ميثان","توقع أن تكون درجة غليان CHCl₃ أعلى من CCl₄","التفسير بقوة الرابطة C–Cl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.658Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
