from (values
('mcq', 1, 'ما المقصود بالهلجنة بوصفها تفاعل استبدال في الألكانات؟', null, null, '["تفاعل تحل فيه ذرة هالوجين محل ذرة هيدروجين في الألكان","تفاعل تحل فيه مجموعة OH محل ذرة الهالوجين في هاليد الألكيل","تفاعل تحل فيه مجموعة NH₂ محل ذرة الهالوجين في هاليد الألكيل","تفاعل تُنزع فيه ذرتا هيدروجين من الألكان وتتكون رابطة ثنائية"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 2, 'ما ناتجا تفاعل هلجنة الإيثان بالكلور: C₂H₆ + Cl₂ → ؟', null, null, '["C₂H₆Cl₂","C₂H₄Cl₂ + H₂","C₂H₅Cl + HCl","C₂H₄ + 2HCl"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'سهل', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 3, 'أيّ المعادلات الآتية تمثل المعادلة العامة لهلجنة الألكانات (حيث X ذرة هالوجين)؟', null, null, '["R−CH₃ + X₂ → R−CH₃X₂","R−CH₃ + X₂ → R−CH₂X + HX","R−CH₃ + HX → R−CH₂X + H₂","R−X + OH⁻ → R−OH + X⁻"]'::jsonb, 'فهم', 'تمييز معادلة', 'متوسط', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 4, 'تُكتب المعادلة العامة للهلجنة R−CH₃ + X₂ → R−CH₂X + HX. أيّ الهالوجينات الآتية لا يمكن أن يمثله X فيها، ولماذا؟', null, null, '["الفلور؛ لأنه أصغر الهالوجينات حجمًا","الكلور؛ لأنه غاز في الظروف العادية","البروم؛ لأنه سائل في الظروف العادية","اليود؛ لأنه لا يتفاعل جيدًا مع الألكانات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 5, 'يمثل الشكل الآتي جزيء البروبان. عند هلجنته بالبروم Br₂ بحيث تُستبدل ذرة هيدروجين واحدة فقط، ما النواتج العضوية المختلفة الممكنة؟', null, '[{"src":"qimg/chem22/c5-l1b-propane.svg","alt":"الصيغة البنائية الكاملة لجزيء البروبان: سلسلة أفقية من ثلاث ذرات كربون C بينها روابط أحادية، ترتبط بكل ذرة كربون ذرتا هيدروجين H أعلاها وأسفلها، وترتبط بكل من ذرتي الكربون الطرفيتين ذرة هيدروجين إضافية في طرف السلسلة؛ فمجموع ذرات الهيدروجين ثماني ذرات."}]'::jsonb, '["1-برومو بروبان و2-برومو بروبان","ناتج واحد فقط هو 1-برومو بروبان","1-برومو بروبان و2-برومو بروبان و3-برومو بروبان","1، 2-ثنائي برومو بروبان فقط"]'::jsonb, 'تطبيق', 'توقع نواتج', 'صعب', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('mcq', 6, 'ما المواد المتفاعلة اللازمة لتحويل الميثان إلى برومو ميثان CH₃Br بتفاعل هلجنة؟', null, null, '["الميثان CH₄ وبروميد الهيدروجين HBr","الميثان CH₄ وأيون الهيدروكسيد OH⁻","الميثان CH₄ والبروم Br₂","الميثانول CH₃OH والبروم Br₂"]'::jsonb, 'تطبيق', 'تحديد متفاعلات', 'متوسط', 'الكتاب ص 201 — تقويم الفصل س27'),
('mcq', 7, 'في الهلجنة الثنائية للإيثان تحل ذرتا كلور محل ذرتي هيدروجين. أيّ المعادلات الآتية تمثل ذلك بشكل صحيح وموزون؟', null, null, '["C₂H₆ + Cl₂ → C₂H₄Cl₂ + H₂","C₂H₆ + 2Cl₂ → C₂H₄Cl₂ + 2HCl","C₂H₆ + 2Cl₂ → C₂H₄Cl₂ + HCl","C₂H₆ + Cl₂ → C₂H₆Cl₂"]'::jsonb, 'تطبيق', 'موازنة معادلة', 'صعب', 'الكتاب ص 205 — تقويم الفصل س69'),
('essay', 1, 'عرّف الهلجنة، واكتب المعادلة العامة لها، ثم اكتب معادلة هلجنة الإيثان بالكلور وسمِّ الناتج العضوي، وبيّن لماذا لا يُستعمل اليود في هذا النوع من التفاعلات.', null, null, null, 'تطبيق', 'تعريف وكتابة معادلات', 'سهل', 'الكتاب ص 172 — تفاعلات الاستبدال (الجدول 5-3)'),
('essay', 2, 'يمثل الشكل الآتي جزيء البنتان. (أ) اكتب بالصيغ الجزيئية معادلة الهلجنة الأحادية للبنتان بالكلور Cl₂. (ب) اكتب الصيغ البنائية المكثفة لجميع نواتج الهلجنة الأحادية المختلفة الممكنة، وسمِّ كلًّا منها.', null, '[{"src":"qimg/chem22/c5-l1b-pentane.svg","alt":"الصيغة البنائية الكاملة لجزيء البنتان: سلسلة أفقية مستقيمة من خمس ذرات كربون C بينها روابط أحادية، ترتبط بكل ذرة كربون ذرتا هيدروجين H أعلاها وأسفلها، وترتبط بكل من ذرتي الكربون الطرفيتين ذرة هيدروجين إضافية في طرف السلسلة؛ فمجموع ذرات الهيدروجين اثنتا عشرة ذرة."}]'::jsonb, null, 'تطبيق', 'توقع نواتج', 'صعب', 'الكتاب ص 205 — تقويم الفصل س69'),
('essay', 3, 'يتفاعل الميثان مع الكلور في خطوات متتالية، تحل في كل منها ذرة كلور محل ذرة هيدروجين، حتى يتكون رباعي كلورو ميثان. (أ) اكتب معادلات الخطوات الأربع. (ب) سمِّ الناتج العضوي في كل خطوة. (ج) اكتب المعادلة الكلية، واستنتج عدد مولات Cl₂ اللازمة لتحويل 1 mol من الميثان كليًّا إلى رباعي كلورو ميثان، وعدد مولات HCl الناتجة.', null, null, null, 'تحليل', 'كتابة معادلات متتالية', 'صعب', 'الكتاب ص 205 — تقويم الفصل س69')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
