from (values
('mcq', 1, 0, 'الهلجنة عملية تحل فيها ذرة هالوجين (مثل الكلور أو البروم) محل ذرة هيدروجين في الألكان، فيتكون هاليد ألكيل وهاليد هيدروجين، مثل: C₂H₆ + Cl₂ → C₂H₅Cl + HCl.', '["","هذا تفاعل استبدال يُكوّن الكحولات من هاليدات الألكيل، وليس هلجنة.","هذا تفاعل استبدال يُكوّن الأمينات، وليس هلجنة.","هذا تفاعل حذف الهيدروجين، ولا يدخل فيه هالوجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.658Z"}'::jsonb),
('mcq', 2, 2, 'تحل ذرة كلور محل ذرة هيدروجين في الإيثان، وتتحد ذرة الكلور الأخرى مع ذرة الهيدروجين المستبدلة: C₂H₆ + Cl₂ → C₂H₅Cl + HCl؛ فينتج كلورو إيثان وكلوريد الهيدروجين.', '["هذا يعني إضافة جزيء الكلور كاملًا، والإيثان مشبع لا تحدث فيه إضافة؛ فالتفاعل استبدال.","الهلجنة لا تُنتج H₂؛ فكل ذرة هيدروجين تُستبدل تخرج مع ذرة كلور في صورة HCl، وجزيء Cl₂ واحد يستبدل ذرة هيدروجين واحدة.","","الإيثين C₂H₄ ناتج حذف لا استبدال؛ ففي الهلجنة تبقى ذرة الكلور مرتبطة بالكربون مكونة هاليد ألكيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('mcq', 3, 1, 'في الهلجنة يتفاعل الألكان مع جزيء الهالوجين X₂، فتحل ذرة X محل ذرة هيدروجين، وتتحد ذرة X الأخرى مع ذرة الهيدروجين المستبدلة مكونة HX: R−CH₃ + X₂ → R−CH₂X + HX.', '["ذرة الكربون في الألكان مشبعة بأربع روابط، فلا يُضاف إليها جزيء X₂؛ التفاعل استبدال لا إضافة.","","المادة المتفاعلة في الهلجنة جزيء الهالوجين X₂، وHX ناتج لا متفاعل.","هذه المعادلة العامة لتكوين الكحولات من هاليدات الألكيل، لا للهلجنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('mcq', 4, 3, 'يمكن أن تكون X في معادلة الهلجنة الفلور أو الكلور أو البروم، ولكن ليس اليود؛ لأن اليود لا يتفاعل جيدًا مع الألكانات.', '["الفلور يمكن أن يكون X في الهلجنة، وصغر حجمه لا يمنع التفاعل.","الكلور من أشهر الهالوجينات في الهلجنة، مثل هلجنة الإيثان لتكوين كلورو إيثان.","البروم يمكن أن يكون X في الهلجنة، وحالته الفيزيائية لا تمنع التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('mcq', 5, 0, 'في البروبان نوعان من مواقع ذرات الهيدروجين: على ذرتي الكربون الطرفيتين (متكافئتان)، وعلى ذرة الكربون الوسطى. فإحلال البروم محل هيدروجين طرفي يعطي 1-برومو بروبان CH₃CH₂CH₂Br، ومحل هيدروجين على الكربون الوسطى يعطي 2-برومو بروبان CH₃CHBrCH₃؛ وينتج HBr في الحالتين.', '["","ذرات الهيدروجين على ذرة الكربون الوسطى يمكن استبدالها أيضًا فيتكون 2-برومو بروبان.","«3-برومو بروبان» هو 1-برومو بروبان نفسه مرقّمًا من الطرف الآخر، والترقيم الصحيح يعطي أقل رقم.","المطلوب استبدال ذرة هيدروجين واحدة، فيحتوي الناتج على ذرة بروم واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('mcq', 6, 2, 'الهلجنة إحلال ذرة هالوجين محل ذرة هيدروجين في الألكان، فيتفاعل الميثان مع البروم: CH₄ + Br₂ → CH₃Br + HBr.', '["HBr ناتج من نواتج الهلجنة وليس مادة متفاعلة فيها.","أيون OH⁻ يحوّل هاليد الألكيل إلى كحول، ولا يُدخل البروم في الميثان.","","المطلوب تحويل الميثان نفسه، والهلجنة تبدأ من الألكان لا من الكحول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('mcq', 7, 1, 'كل ذرة هيدروجين تُستبدل تحتاج إلى جزيء Cl₂ واحد: ذرة كلور تحل محلها وأخرى تخرج معها في صورة HCl. فاستبدال ذرتي هيدروجين يحتاج إلى 2Cl₂ وينتج 2HCl: C₂H₆ + 2Cl₂ → C₂H₄Cl₂ + 2HCl، والمعادلة موزونة (C: 2، H: 6، Cl: 4 في الطرفين).', '["المعادلة موزونة عدديًّا لكنها لا تمثل الهلجنة؛ فذرات الهيدروجين المستبدلة تخرج في صورة HCl لا H₂.","","غير موزونة: أربع ذرات كلور في المتفاعلات وثلاث في النواتج، وست ذرات هيدروجين مقابل خمس.","الإيثان مشبع ولا تحدث فيه إضافة؛ فالهلجنة استبدال تُفقد فيه ذرات هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الهلجنة: عملية تحل فيها ذرة هالوجين محل ذرة هيدروجين في الألكان، وهي من تفاعلات الاستبدال. المعادلة العامة: R−CH₃ + X₂ → R−CH₂X + HX، حيث X فلور أو كلور أو بروم. هلجنة الإيثان: C₂H₆ + Cl₂ → C₂H₅Cl + HCl، والناتج العضوي كلورو إيثان (هاليد ألكيل). ولا يُستعمل اليود لأنه لا يتفاعل جيدًا مع الألكانات.', '["تعريف الهلجنة","المعادلة العامة","معادلة الإيثان والناتج كلورو إيثان","اليود لا يتفاعل جيدًا مع الألكانات"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المعادلة العامة","marks":1},{"element":"معادلة الإيثان وتسمية الناتج","marks":1},{"element":"سبب استبعاد اليود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ومعادلتان صحيحتان وسبب استبعاد اليود"},{"level":"2–3 درجات","description":"تعريف صحيح مع معادلة واحدة صحيحة"},{"level":"1 درجة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H₂ بدل HX في المعادلة العامة","تعريف الهلجنة بأنها إضافة الهالوجين إلى الألكان","تسمية الناتج كلوريد الإيثان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) C₅H₁₂ + Cl₂ → C₅H₁₁Cl + HCl. (ب) في البنتان ثلاثة مواقع مختلفة لذرات الهيدروجين، فتنتج ثلاثة مركبات: CH₃CH₂CH₂CH₂CH₂Cl واسمه 1-كلورو بنتان؛ وCH₃CHClCH₂CH₂CH₃ واسمه 2-كلورو بنتان؛ وCH₃CH₂CHClCH₂CH₃ واسمه 3-كلورو بنتان. (استبدال ذرة هيدروجين على ذرة الكربون 4 أو 5 يعطي 2-كلورو بنتان أو 1-كلورو بنتان نفسيهما بعد الترقيم من الطرف الأقرب.)', '["معادلة موزونة بالصيغ الجزيئية","1-كلورو بنتان","2-كلورو بنتان","3-كلورو بنتان"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الصيغ المكثفة الثلاث","marks":3},{"element":"الأسماء الثلاثة","marks":3}]'::jsonb, '[{"level":"7 درجات","description":"معادلة صحيحة وثلاث صيغ وأسماء صحيحة دون تكرار"},{"level":"4–6 درجات","description":"معادلة صحيحة مع صيغتين أو ثلاث بأخطاء في التسمية"},{"level":"1–3 درجات","description":"المعادلة فقط أو صيغة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ 4-كلورو بنتان و5-كلورو بنتان مركبين مختلفين","كتابة H₂ ناتجًا بدل HCl","كتابة ناتج يحتوي على ذرتي كلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.659Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) CH₄ + Cl₂ → CH₃Cl + HCl؛ CH₃Cl + Cl₂ → CH₂Cl₂ + HCl؛ CH₂Cl₂ + Cl₂ → CHCl₃ + HCl؛ CHCl₃ + Cl₂ → CCl₄ + HCl. (ب) كلورو ميثان، ثنائي كلورو ميثان، ثلاثي كلورو ميثان، رباعي كلورو ميثان. (ج) بجمع المعادلات الأربع: CH₄ + 4Cl₂ → CCl₄ + 4HCl؛ فيلزم 4 mol من Cl₂ لكل 1 mol من الميثان، وينتج 4 mol من HCl.', '["أربع معادلات موزونة","أسماء النواتج الأربعة","المعادلة الكلية","4 mol من Cl₂ و4 mol من HCl"]'::jsonb, '["كل خطوة تستهلك 1 mol من Cl₂ وتنتج 1 mol من HCl","عدد الخطوات اللازمة لاستبدال 4 ذرات هيدروجين = 4","Cl₂ اللازم = 4 × 1 mol = 4 mol، وHCl الناتج = 4 mol"]'::jsonb, '[{"element":"المعادلات الأربع","marks":2},{"element":"الأسماء","marks":2},{"element":"المعادلة الكلية والمولات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"معادلات وأسماء صحيحة ومعادلة كلية ومولات صحيحة"},{"level":"4–5 درجات","description":"معادلات صحيحة مع خطأ في الأسماء أو المولات"},{"level":"1–3 درجات","description":"معادلة أو معادلتان صحيحتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة المعادلة الكلية CH₄ + 2Cl₂ → CCl₄ + 2H₂","تسمية CHCl₃ ثلاثي كلوريد الميثان","حساب 2 mol من Cl₂ لأن كل جزيء فيه ذرتا كلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.660Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
