select (select id from public.objectives where code = 'K22-C5-L1-O10'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'من أيّ العناصر تتكون جزيئات مركبات الكلوروفلوروكربون (CFCs)؟', null, null, '["الكربون والهيدروجين والفلور فقط","الكربون والهيدروجين والكلور فقط","الكلور والفلور فقط دون الكربون","الكربون والكلور والفلور"]'::jsonb, 'تذكر', 'استدعاء حقيقة', 'سهل', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('mcq', 2, 'أيّ المركبات في الشكل الآتي من الهيدروفلوروكربونات (HFCs) التي استُعملت بديلًا لمركبات CFCs؟', null, '[{"src":"qimg/chem22/c5-l1b-which-hfc.svg","alt":"أربع صيغ بنائية في شبكة من صفين وعمودين. أعلى اليمين (أ): ذرة كربون واحدة ترتبط بها ثلاث ذرات كلور Cl (يمينًا ويسارًا وأعلى) وذرة فلور F من أسفل. أعلى اليسار (ب): ذرة كربون واحدة ترتبط بها ذرتا كلور Cl يمينًا ويسارًا وذرتا هيدروجين H أعلى وأسفل. أسفل اليمين (ج): ذرتا كربون مترابطتان؛ ترتبط باليسرى ثلاث ذرات هيدروجين H، وترتبط باليمنى ذرتا فلور F (أعلى ويمينًا) وذرة هيدروجين H من أسفل. أسفل اليسار (د): ذرتا كربون مترابطتان؛ ترتبط بكل منهما ذرة كلور Cl في الطرف وذرتا فلور F أعلى وأسفل."}]'::jsonb, '["(أ)","(ب)","(ج)","(د)"]'::jsonb, 'فهم', 'تصنيف من رسم', 'متوسط', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('mcq', 3, 'تنتمي مركبات CFCs ومركبات HFCs كلتاهما إلى نوع واحد من المركبات العضوية. ما هذا النوع؟', null, null, '["هاليدات الألكيل","هاليدات الأريل","الألكانات","الكحولات"]'::jsonb, 'فهم', 'تصنيف', 'سهل', 'الكتاب ص 169–170 — هاليدات الألكيل؛ الربط مع علوم الأرض'),
('mcq', 4, 'اقتُرح استعمال المركب CHClF₂ بديلًا من مركبات CFCs في أجهزة التكييف. أيّ العبارات الآتية تقوّم هذا الاقتراح تقويمًا صحيحًا وفق أساس استبدال مركبات CFCs بمركبات HFCs؟', null, null, '["مناسب؛ لأن وجود ذرة هيدروجين في جزيئه يكفي لجعله من مركبات HFCs","غير مناسب؛ لأنه يحتوي على الكلور، وHFCs تخلو من الكلور تمامًا","مناسب؛ لأن احتواء جزيئه على ذرتي فلور يكفي ليكون من مركبات HFCs","غير مناسب؛ لأن جزيئه يحتوي على ذرة كربون واحدة فقط لا ذرتين"]'::jsonb, 'تقويم', 'تقويم اقتراح', 'صعب', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('mcq', 5, 'ما المركبات التي استُعملت بدلًا من مركبات CFCs غازًا دافعًا في بخاخات أدوية الربو بعد حظرها؟', null, null, '["رباعي فلورو بولي إيثين (PTFE)","كلورو ميثان CH₃Cl","غاز الهالوثان","الهيدروفلوروألكانات (HFAs)"]'::jsonb, 'تذكر', 'استدعاء حقيقة', 'سهل', 'الكتاب ص 206 — أسئلة المستندات'),
('mcq', 6, 'بعد حظر استعمال مركبات CFCs عام 2008م في بخاخات أدوية الربو استُعملت بدلًا منها مركبات الهيدروفلوروألكانات (HFAs). ما المشكلة التي ظهرت في بعض هذه المركبات البديلة؟', null, null, '["وُجد أن اثنين منها غير فعّالين في توصيل الدواء إلى الرئتين","لزم مضاعفة جرعة الدواء للحصول على التركيز نفسه منه في الدم","تبيّن أنها تحتوي على الكلور فتؤثر في طبقة الأوزون","تفاعلت مع الدواء داخل البخاخ فكوّنت مركبات من نوع CFCs"]'::jsonb, 'تذكر', 'استدعاء حقيقة', 'متوسط', 'الكتاب ص 206 — أسئلة المستندات'),
('mcq', 7, 'تمتص طبقة الأوزون في الغلاف الجوي معظم الأشعة فوق البنفسجية الضارة القادمة من الشمس، ومركبات CFCs التي تصل إلى هذه الطبقة تقلل كمية الأوزون فيها. ما النتيجة المتوقعة لاستمرار انطلاق مركبات CFCs إلى الجو؟', null, null, '["زيادة سمك طبقة الأوزون فيقل ما يصل من الأشعة فوق البنفسجية","تحوّل CFCs في الجو إلى HFCs فيختفي أثرها في الأوزون","وصول كمية أكبر من الأشعة فوق البنفسجية الضارة إلى سطح الأرض","انخفاض كمية الأشعة فوق البنفسجية التي تصل إلى سطح الأرض"]'::jsonb, 'فهم', 'استنتاج أثر', 'متوسط', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('essay', 1, 'ارسم الصيغة البنائية لكلٍّ من CCl₂F₂ و1، 1، 1، 2-رباعي فلورو إيثان، ثم حدّد إلى أيّ فئة (CFCs أو HFCs) ينتمي كلٌّ منهما، ووضّح أيهما أنسب للاستعمال في أجهزة التكييف الحديثة ولماذا.', null, null, null, 'فهم', 'رسم ومقارنة', 'متوسط', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('essay', 2, 'صنّف كل مركب في الشكل الآتي إلى: من مركبات CFCs، أو من مركبات HFCs، أو ليس من أيٍّ منهما، مع ذكر السبب، ثم حدّد المركب الذي يُتوقع أن يؤثر في طبقة الأوزون لو استُعمل في المبردات.', null, '[{"src":"qimg/chem22/c5-l1b-classify-cfc.svg","alt":"أربع صيغ بنائية في شبكة من صفين وعمودين. أعلى اليمين (أ): ذرة كربون واحدة ترتبط بها ذرة كلور Cl من اليسار وثلاث ذرات فلور F (يمينًا وأعلى وأسفل). أعلى اليسار (ب): ذرة كربون واحدة ترتبط بها ذرتا فلور F يمينًا ويسارًا وذرتا هيدروجين H أعلى وأسفل. أسفل اليمين (ج): ذرة كربون واحدة ترتبط بها ثلاث ذرات كلور Cl (يمينًا ويسارًا وأعلى) وذرة هيدروجين H من أسفل. أسفل اليسار (د): ذرتا كربون مترابطتان؛ ترتبط باليسرى ثلاث ذرات هيدروجين H، وترتبط باليمنى ثلاث ذرات فلور F (أعلى ويمينًا وأسفل)."}]'::jsonb, null, 'تحليل', 'تصنيف وتبرير', 'صعب', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)'),
('essay', 3, 'تمتص طبقة الأوزون معظم الأشعة فوق البنفسجية الضارة القادمة من الشمس. وعندما تصل جزيئات CFCs إلى طبقات الجو العليا تتفكك بفعل هذه الأشعة، فتنطلق منها ذرات كلور تفكك جزيئات الأوزون. (أ) استنادًا إلى هذه المعلومات، وضّح لماذا يقل الأثر في طبقة الأوزون عند استعمال مركبات HFCs بدلًا من CFCs. (ب) يحتوي جهاز تبريد قديم على المركب CCl₃F. اقترح صيغة جزيئية لمركب من HFCs يحتوي على ذرة كربون واحدة يمكن أن يحل محله، وارسم صيغته البنائية. (ج) هل يبقى المركب الذي اقترحته من هاليدات الألكيل؟ برّر إجابتك.', null, null, null, 'تحليل', 'تفسير واقتراح', 'صعب', 'الكتاب ص 170 — الربط مع علوم الأرض (CFCs وHFCs)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
