insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يدل الاسم كلوروفلوروكربون على مكونات هذه المركبات: ذرات كلور وفلور مرتبطة بذرات الكربون.', '["هذه مكونات مركبات الهيدروفلوروكربون (HFCs) التي حلت محل CFCs.","لا يحتوي هذا الاختيار على الفلور، وهو جزء من اسم CFCs ومكوناتها.","CFCs مركبات عضوية ترتبط فيها ذرات الكلور والفلور بذرات الكربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.660Z"}'::jsonb),
('mcq', 2, 2, 'مركبات HFCs تحتوي فقط على ذرات هيدروجين وفلور مرتبطة بالكربون. والمركب (ج) CH₃–CHF₂ يحتوي على ذرات كربون وهيدروجين وفلور فقط، فهو من HFCs.', '["(أ) CCl₃F يحتوي على كلور وفلور مرتبطين بالكربون، فهو من CFCs.","(ب) CH₂Cl₂ يحتوي على الكلور ولا يحتوي على الفلور، فليس من HFCs.","","(د) يحتوي على ذرات كلور وفلور مرتبطة بالكربون ولا هيدروجين فيه، فهو من CFCs."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.660Z"}'::jsonb),
('mcq', 3, 0, 'في المجموعتين ترتبط ذرات هالوجين (الفلور في كلتيهما، والكلور أيضًا في CFCs) برابطة تساهمية بذرات كربون أليفاتية، ولا تحتوي على حلقة بنزين؛ فهي هاليدات ألكيل، ولذلك يُذكر استعمال هاليدات الألكيل في المبردات وأنظمة التكييف على شكل CFCs.', '["","لا تحتوي CFCs ولا HFCs على حلقة بنزين أو مجموعة أروماتية يرتبط بها الهالوجين.","الألكانات هيدروكربونات لا تحتوي إلا على الكربون والهيدروجين، وهذه المركبات تحتوي على الهالوجينات.","الكحولات تحتوي على مجموعة الهيدروكسيل –OH، وهذه المركبات لا تحتوي عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.660Z"}'::jsonb),
('mcq', 4, 1, 'استُبدلت مركبات CFCs، التي تحتوي على الكلور والفلور مرتبطين بالكربون، بمركبات HFCs التي تحتوي فقط على ذرات الهيدروجين والفلور المرتبطة مع الكربون. والمركب CHClF₂ ما زال يحتوي على ذرة كلور، فهو ليس من HFCs ولا يحقق أساس الاستبدال. فالاقتراح غير مناسب؛ لأنه يحتوي على الكلور، وHFCs تخلو من الكلور تمامًا.', '["وجود الهيدروجين وحده لا يكفي؛ فمركبات HFCs لا تحتوي على الكلور، وهذا المركب يحتوي عليه.","","وجود الفلور لا يكفي؛ فمركبات CFCs نفسها تحتوي على الفلور، والمعيار خلو المركب من الكلور.","عدد ذرات الكربون ليس معيارًا؛ فمن مركبات HFCs ما يحتوي على ذرة كربون واحدة مثل CH₂F₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.660Z"}'::jsonb),
('mcq', 5, 3, 'احتوت أدوية كثيرة لعلاج الربو على CFCs، ثم حُظر استعمالها عام 2008م واستُعملت مركبات الهيدروفلوروألكانات (HFAs) بدلًا منها.', '["PTFE بلاستيك يُستعمل سطحًا غير لاصق لأدوات المطبخ، وليس غازًا دافعًا.","كلورو ميثان يُستعمل في صناعة المواد اللاصقة المعروفة بالسيليكون.","الهالوثان استُعمل مخدرًا عامًّا في العمليات الجراحية في خمسينيات القرن الماضي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb),
('mcq', 6, 0, 'وُجد أن اثنين من مركبات الهيدروفلوروألكانات (HFAs) غير فعّالين في توصيل أدوية الربو إلى الرئتين، وفي المقابل لزم خفض جرعة الدواء إلى النصف عند استعمال HFAs للحصول على التركيز نفسه في الدم.', '["","العكس هو الصحيح: لزم خفض جرعة الدواء إلى النصف عند استعمال HFAs لا مضاعفتها.","مركبات HFAs لا تحتوي على الكلور؛ فهي تحتوي على الهيدروجين والفلور مرتبطين بالكربون.","لا تتكون CFCs من HFAs؛ فهي لا تحتوي على الكلور اللازم لتكوينها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb),
('mcq', 7, 2, 'مركبات CFCs تقلل كمية الأوزون في طبقة الأوزون، فتضعف قدرة هذه الطبقة على امتصاص الأشعة فوق البنفسجية، فتصل كمية أكبر من هذه الأشعة الضارة إلى سطح الأرض؛ ولهذا استُبدلت بها مركبات HFCs.', '["مركبات CFCs تقلل كمية الأوزون لا تزيدها، فلا يزداد سمك الطبقة.","لا تتحول CFCs إلى HFCs في الجو؛ فـ HFCs مركبات مختلفة صُنعت لتحل محلها.","","نقص الأوزون يقلل امتصاص الأشعة فوق البنفسجية، فيزداد ما يصل منها إلى سطح الأرض لا يقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb),
('essay', 1, null::int, null, null, 'CCl₂F₂: ذرة كربون مركزية ترتبط بها ذرتا كلور وذرتا فلور برابطة أحادية لكل منها؛ وهو من CFCs لاحتوائه على الكلور والفلور مرتبطين بالكربون. 1، 1، 1، 2-رباعي فلورو إيثان (CF₃–CH₂F): ذرتا كربون مترابطتان، ترتبط بالأولى ثلاث ذرات فلور، وبالثانية ذرة فلور وذرتا هيدروجين؛ وهو من HFCs لأنه يحتوي على الهيدروجين والفلور فقط مرتبطين بالكربون. والأنسب للأجهزة الحديثة 1، 1، 1، 2-رباعي فلورو إيثان، لأن مركبات CFCs تؤثر في طبقة الأوزون، فاستُبدلت بمركبات HFCs التي لا تحتوي على الكلور، وهذا المركب أكثرها شيوعًا.', '["صيغة CCl₂F₂ صحيحة","صيغة CF₃–CH₂F صحيحة","التصنيف: CFCs وHFCs","اختيار HFC مع التبرير بطبقة الأوزون"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغتان البنائيتان","marks":2},{"element":"التصنيف","marks":1},{"element":"الاختيار والتبرير","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"صيغتان صحيحتان وتصنيف صحيح واختيار مبرر"},{"level":"3–4 درجات","description":"صيغتان صحيحتان مع تبرير ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح فقط أو صيغة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم ذرات الفلور الأربع موزعة 2 و2 على ذرتي الكربون","تصنيف CCl₂F₂ من HFCs لاحتوائه على الفلور","التبرير بأن HFCs لا تحتوي على الفلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CClF₃: من CFCs لأنه يحتوي على الكلور والفلور مرتبطين بالكربون. (ب) CH₂F₂: من HFCs لأنه يحتوي على الهيدروجين والفلور فقط مرتبطين بالكربون. (ج) CHCl₃: ليس من أيٍّ منهما، لأنه لا يحتوي على الفلور (يحتوي على الكلور والهيدروجين). (د) CH₃CF₃: من HFCs لأنه يحتوي على الهيدروجين والفلور فقط مرتبطين بالكربون. والمركب الذي يُتوقع أن يؤثر في طبقة الأوزون (أ)، لأنه من CFCs.', '["(أ) CFC","(ب) HFC","(ج) ليس منهما لغياب الفلور","(د) HFC","المؤثر في الأوزون (أ)"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف المركبات الأربعة مع السبب","marks":4},{"element":"تحديد المركب المؤثر في الأوزون","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح ومبرر للأربعة وتحديد صحيح"},{"level":"3–4 درجات","description":"تصنيف صحيح لثلاثة مركبات أو تبرير ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح لمركب أو مركبين"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (ج) من CFCs لاحتوائه على الكلور فقط","تصنيف (د) من CFCs لخلوّه من الكلور","اختيار (ج) مركبًا مؤثرًا في الأوزون بوصفه من CFCs"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الضرر ناتج عن ذرات الكلور التي تنطلق من جزيئات CFCs وتفكك الأوزون. أما مركبات HFCs فتحتوي فقط على ذرات الهيدروجين والفلور المرتبطة مع الكربون ولا كلور فيها، فلا تنطلق منها ذرات كلور تفكك الأوزون، فيقل الأثر في الطبقة. (ب) مثال: CHF₃، وصيغته البنائية ذرة كربون مركزية ترتبط بها ذرة هيدروجين وثلاث ذرات فلور برابطة أحادية لكل منها. (يُقبل CH₂F₂ أو CH₃F.) (ج) نعم؛ لأن الفلور هالوجين مرتبط برابطة تساهمية بذرة كربون أليفاتية، فالمركب هاليد ألكيل وإن خلا من الكلور.', '["HFCs لا تحتوي على الكلور فلا تنطلق منها ذرات كلور","صيغة صحيحة لمركب HFC بذرة كربون واحدة مع رسمها","يبقى هاليد ألكيل لارتباط الفلور بكربون أليفاتي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التوضيح","marks":2},{"element":"(ب) الصيغة الجزيئية والبنائية","marks":2},{"element":"(ج) الحكم والتبرير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"توضيح مرتبط بغياب الكلور وصيغة صحيحة مرسومة وحكم مبرر"},{"level":"3–4 درجات","description":"توضيح صحيح وصيغة صحيحة مع نقص في الرسم أو التبرير"},{"level":"1–2 درجة","description":"توضيح صحيح فقط أو صيغة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح CHCl₂F أو CHClF₂ مع أنهما يحتويان على الكلور","اقتراح CF₄ أو CCl₄ بوصفه من HFCs مع أنه لا يحتوي على الهيدروجين","القول إن HFCs ليست هاليدات ألكيل لخلوها من الكلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.661Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
