('mcq', 2, 3, 'ترتبط ذرة الأكسجين في الإيثر بمجموعتين كربونيتين R وR′، فتكون الصيغة العامة للإيثرات ROR′.', '["هذه صيغة الكحولات؛ ذرة الأكسجين فيها مرتبطة بذرة كربون واحدة وذرة هيدروجين.","هذه صيغة الأمينات، ولا تحتوي على ذرة أكسجين أصلًا.","هذه صيغة هاليدات الألكيل؛ X ذرة هالوجين لا أكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('mcq', 3, 0, 'تحتوي الأمينات على ذرة نيتروجين مرتبطة بذرة كربون في سلسلة أليفاتية أو حلقة أروماتية، وصيغتها العامة RNH₂، وهي تنتج من إحلال مجموعة عضوية R محل ذرة هيدروجين في الأمونيا NH₃.', '["","هذه صيغة الأمونيا نفسها، وهي مركب غير عضوي لا يحتوي على سلسلة كربونية R.","هذه الصيغة العامة للكحولات، والمجموعة الوظيفية فيها OH لا NH₂.","هذه الصيغة العامة للإيثرات، ولا تحتوي على نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('mcq', 4, 2, 'ترتبط ذرة الأكسجين في المركب بذرة كربون من جهة وبذرة هيدروجين من الجهة الأخرى، أي أنه يحتوي على مجموعة هيدروكسيل –OH مرتبطة بسلسلة كربونية (CH₃CH₂–)، فهو كحول صيغته العامة R–OH.', '["ذرة الأكسجين في المركب مرتبطة بذرة كربون واحدة وذرة هيدروجين، وليست بين ذرتي كربون كما في الإيثرات.","لا يحتوي المركب على ذرة نيتروجين.","","لا يحتوي المركب على ذرة هالوجين؛ الذرة المميزة فيه أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('mcq', 5, 1, 'في الصيغ العامة ROH وROR′ وRNH₂ يمثل R (وكذلك R′) سلسلة أو حلقة كربونية مرتبطة بالمجموعة الوظيفية.', '["لو كان R ذرة هيدروجين لما بقي الجزء الكربوني في المركب؛ فالكحول مثلًا يصبح ماءً H–O–H.","","مجموعة الهيدروكسيل هي المجموعة الوظيفية للكحولات، أما R فتمثل الجزء الكربوني من الجزيء.","الهالوجين يُرمز إليه بالرمز X في الصيغ العامة، أما R فتمثل الجزء الكربوني من الجزيء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('mcq', 6, 2, 'في المركب (1) ترتبط ذرة الأكسجين بمجموعتين كربونيتين (CH₃ وCH₂CH₃) فهو إيثر ROR′، وفي المركب (2) ترتبط مجموعة NH₂ بسلسلة كربونية فهو أمين RNH₂، وفي المركب (3) ترتبط مجموعة OH بذرة الكربون الوسطى فهو كحول ROH.', '["عكس هذا البديل صيغتي المركبين (1) و(3)؛ فالأكسجين في (1) بين ذرتي كربون، وفي (3) مرتبط بذرة هيدروجين.","المركب (2) يحتوي على مجموعة NH₂ فهو أمين، والمركب (3) يحتوي على OH فهو كحول.","","المركب (1) لا يحتوي على نيتروجين، والمركب (2) لا يحتوي على أكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('mcq', 7, 0, 'في الكحول ROH ترتبط ذرة الأكسجين بمجموعة كربونية واحدة وبذرة هيدروجين، أما في الإيثر ROR′ فترتبط ذرة الأكسجين نفسها بمجموعتين كربونيتين R وR′، ولا توجد ذرة هيدروجين مرتبطة بالأكسجين.', '["","في الإيثر ذرة أكسجين واحدة فقط، ترتبط بمجموعتين كربونيتين.","الرابطة الثنائية C=O تميز مركبات الكربونيل، أما الأكسجين في الإيثر فيرتبط بذرتي كربون برابطتين أحاديتين.","النيتروجين يميز الأمينات RNH₂، أما الإيثرات فتحتوي على الأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكحولات: ROH، والذرة المميزة الأكسجين، ترتبط بمجموعة كربونية واحدة R (وبذرة هيدروجين). الإيثرات: ROR′، والذرة المميزة الأكسجين، ترتبط بمجموعتين كربونيتين R وR′. الأمينات: RNH₂، والذرة المميزة النيتروجين، ترتبط بمجموعة كربونية واحدة R (وبذرتي هيدروجين).', '["الصيغة العامة للكحولات ROH","الأكسجين في الكحول مرتبط بمجموعة كربونية واحدة وذرة H","الصيغة العامة للإيثرات ROR′","الأكسجين في الإيثر مرتبط بمجموعتين كربونيتين","الصيغة العامة للأمينات RNH₂","النيتروجين في الأمين مرتبط بمجموعة كربونية واحدة وذرتي H"]'::jsonb, '[]'::jsonb, '[{"element":"الصيغة العامة للكحولات ROH","marks":1},{"element":"الأكسجين في الكحول مرتبط بمجموعة كربونية واحدة وذرة H","marks":1},{"element":"الصيغة العامة للإيثرات ROR′","marks":1},{"element":"الأكسجين في الإيثر مرتبط بمجموعتين كربونيتين","marks":1},{"element":"الصيغة العامة للأمينات RNH₂","marks":1},{"element":"النيتروجين في الأمين مرتبط بمجموعة كربونية واحدة وذرتي H","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الصيغة العامة للكحولات ROH؛ الأكسجين في الكحول مرتبط بمجموعة كربونية واحدة وذرة H؛ الصيغة العامة للإيثرات ROR′؛ الأكسجين في الإيثر مرتبط بمجموعتين كربونيتين؛ الصيغة العامة للأمينات RNH₂؛ النيتروجين في الأمين مرتبط بمجموعة كربونية واحدة وذرتي H"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة ROR′ للكحولات وROH للإيثرات (الخلط بين الصنفين)","كتابة صيغة الأمونيا NH₃ صيغةً عامة للأمينات","عدّ R′ ذرة أكسجين ثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ROH (كحول)، وR هي CH₃CH₂CH₂–. (ب) ROR′ (إيثر)، وR وR′ هما CH₃CH₂– وCH₃CH₂CH₂CH₂–. (ج) RNH₂ (أمين)، وR هي CH₃CH₂–. (د) ROH (كحول)، وR هي CH₃– (الميثانول أبسط الكحولات).', '["(أ) ROH","(أ) R = CH₃CH₂CH₂–","(ب) ROR′","(ب) R وR′ = CH₃CH₂– وCH₃CH₂CH₂CH₂–","(ج) RNH₂","(ج) R = CH₃CH₂–","(د) ROH","(د) R = CH₃–"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) ROH","marks":1},{"element":"(أ) R = CH₃CH₂CH₂–","marks":1},{"element":"(ب) ROR′","marks":1},{"element":"(ب) R وR′ = CH₃CH₂– وCH₃CH₂CH₂CH₂–","marks":1},{"element":"(ج) RNH₂","marks":1},{"element":"(ج) R = CH₃CH₂–","marks":1},{"element":"(د) ROH","marks":1},{"element":"(د) R = CH₃–","marks":1}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) ROH؛ (أ) R = CH₃CH₂CH₂–؛ (ب) ROR′؛ (ب) R وR′ = CH₃CH₂– وCH₃CH₂CH₂CH₂–؛ (ج) RNH₂؛ (ج) R = CH₃CH₂–؛ (د) ROH؛ (د) R = CH₃–"},{"level":"1–7 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المركب (ب) كحولًا لاحتوائه على أكسجين دون ملاحظة ارتباطه بذرتي كربون","إدخال ذرة الأكسجين أو مجموعة NH₂ ضمن R","عدّ الميثانول غير كحول لأنه يحتوي على ذرة كربون واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في ROH ترتبط ذرة الأكسجين بمجموعة كربونية واحدة وبذرة هيدروجين (مجموعة الهيدروكسيل –OH)، أما في ROR′ فترتبط ذرة الأكسجين بمجموعتين كربونيتين ولا يرتبط بها هيدروجين. وتُشتق RNH₂ من NH₃ بإحلال مجموعة عضوية R محل ذرة هيدروجين واحدة من ذرات الهيدروجين الثلاث في الأمونيا، فتبقى ذرتا هيدروجين مرتبطتين بالنيتروجين.', '["ROH: الأكسجين مرتبط بمجموعة كربونية وذرة هيدروجين","ROR′: الأكسجين مرتبط بمجموعتين كربونيتين دون هيدروجين","RNH₂: إحلال مجموعة عضوية R محل ذرة H في NH₃","تبقى ذرتا H مرتبطتين بالنيتروجين"]'::jsonb, '[]'::jsonb, '[{"element":"ROH: الأكسجين مرتبط بمجموعة كربونية وذرة هيدروجين","marks":1},{"element":"ROR′: الأكسجين مرتبط بمجموعتين كربونيتين دون هيدروجين","marks":1},{"element":"RNH₂: إحلال مجموعة عضوية R محل ذرة H في NH₃","marks":1},{"element":"تبقى ذرتا H مرتبطتين بالنيتروجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: ROH: الأكسجين مرتبط بمجموعة كربونية وذرة هيدروجين؛ ROR′: الأكسجين مرتبط بمجموعتين كربونيتين دون هيدروجين؛ RNH₂: إحلال مجموعة عضوية R محل ذرة H في NH₃؛ تبقى ذرتا H مرتبطتين بالنيتروجين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإيثر يحتوي على ذرتي أكسجين","القول إن الأمين ينتج من إضافة R إلى NH₃ دون نزع ذرة هيدروجين","الخلط بين NH₂ وNH₃ في الصيغة العامة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-14T13:39:20.662Z"}'::jsonb)
