from (values
('mcq', 1, 1, 'الاسم 2-بروبانول يعني سلسلة من ثلاث ذرات كربون (بروبان) ترتبط فيها مجموعة الهيدروكسيل OH بذرة الكربون الثانية، أي CH₃CH(OH)CH₃، وهي الصيغة (2).', '["مجموعة OH في الصيغة (1) مرتبطة بذرة الكربون الطرفية، فهي 1-بروبانول.","","الصيغة (3) إيثر؛ ذرة الأكسجين فيها بين ذرتي كربون ولا توجد مجموعة OH، مع أن صيغتها الجزيئية C₃H₈O مثل البروبانول.","الصيغة (4) تحتوي على مجموعة NH₂ فهي أمين لا كحول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 2, 0, 'الاسم 1، 3-بروبان ثنائي أمين يعني سلسلة من ثلاث ذرات كربون ترتبط فيها مجموعتا أمين NH₂ بذرتي الكربون الأولى والثالثة: H₂N–CH₂–CH₂–CH₂–NH₂، وهي الصيغة (1).', '["","مجموعتا الأمين في الصيغة (2) على ذرتي الكربون الأولى والثانية، فهي 1، 2-بروبان ثنائي أمين.","مجموعتا الأمين في الصيغة (3) على ذرة الكربون نفسها (الأولى)، فلا تقعان على الموقعين 1 و3.","السلسلة في الصيغة (4) من ذرتي كربون فقط (إيثان)، لا من ثلاث ذرات (بروبان)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 3, 2, 'هكسيل حلقي أمين حلقة سداسية من ذرات الكربون بروابط أحادية (هكسان حلقي) ترتبط بها مجموعة أمين NH₂، وهي الصيغة (3). أما الحلقة التي بداخلها دائرة فهي حلقة بنزين.', '["المجموعة المرتبطة بالحلقة في الصيغة (1) هي OH، فهي هكسانول حلقي.","الحلقة في الصيغة (2) حلقة بنزين أروماتية، فالمركب هو الأنيلين لا هكسيل حلقي أمين.","","الصيغة (4) إيثر فيه حلقتان مرتبطتان بذرة أكسجين، ولا تحتوي على نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 4, 3, '1-بيوتانول: سلسلة من أربع ذرات كربون (بيوتان) ترتبط مجموعة الهيدروكسيل فيها بذرة الكربون الأولى، فصيغته CH₃CH₂CH₂CH₂OH.', '["مجموعة OH هنا على ذرة الكربون الثانية، فهذه صيغة 2-بيوتانول.","هذه صيغة إيثر (ثنائي إيثيل إيثر)؛ الأكسجين فيه بين ذرتي كربون ولا توجد مجموعة OH.","هذه صيغة أمين؛ المجموعة الوظيفية فيها NH₂ لا OH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 5, 2, 'إيثيل ميثيل إيثر: ذرة أكسجين ترتبط بمجموعة إيثيل CH₃CH₂– من جهة وبمجموعة ميثيل CH₃– من الجهة الأخرى، فصيغته CH₃CH₂–O–CH₃.', '["هذه صيغة ثنائي ميثيل إيثر؛ المجموعتان المرتبطتان بالأكسجين كلتاهما ميثيل.","هذه صيغة ثنائي إيثيل إيثر؛ المجموعتان كلتاهما إيثيل.","","هذه صيغة كحول (1-بروبانول)، وهو متشكل للإيثر المطلوب لكن الأكسجين فيه مرتبط بذرة هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 6, 3, '«بروبان» سلسلة من ثلاث ذرات كربون، و«ترايول» ثلاث مجموعات هيدروكسيل، والأرقام 1، 2، 3 مواقعها؛ فتُرسم مجموعة OH واحدة على كل ذرة كربون: HOCH₂–CH(OH)–CH₂OH.', '["الأرقام 1، 2، 3 تدل على ثلاث ذرات كربون مختلفة، لا على ذرة واحدة.","المقطع «ترايول» يعني ثلاث مجموعات هيدروكسيل لا اثنتين.","الأرقام 1، 2، 3 تحدد موقع كل مجموعة، فهي على ثلاث ذرات مختلفة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('mcq', 7, 1, '2-ميثيل-1-بيوتانول: سلسلة من أربع ذرات كربون تُرقَّم من الطرف الأقرب إلى OH؛ مجموعة OH على ذرة الكربون 1 ومجموعة الميثيل على ذرة الكربون 2: HO–CH₂–CH(CH₃)–CH₂–CH₃.', '["مجموعتا OH وCH₃ هنا على ذرة الكربون الثانية نفسها، فهذا 2-ميثيل-2-بيوتانول.","","مجموعة الميثيل هنا على ذرة الكربون الثالثة من طرف OH، فهذا 3-ميثيل-1-بيوتانول.","مجموعة OH هنا على ذرة الكربون الثانية لا الأولى، فهذا 3-ميثيل-2-بيوتانول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) CH₃–CH₂–CH₂–OH. (ب) CH₃–CH₂–CH₂–O–CH₂–CH₂–CH₃. (ج) H₂N–CH₂–CH(NH₂)–CH₃، أي سلسلة من ثلاث ذرات كربون ترتبط مجموعة NH₂ بكل من ذرتي الكربون الأولى والثانية.', '["(أ) سلسلة من 3 ذرات كربون وOH على ذرة الكربون الطرفية","(ب) ذرة أكسجين بين مجموعتي بروبيل","(ج) سلسلة من 3 ذرات كربون","(ج) مجموعتا NH₂ على ذرتي الكربون 1 و2"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) سلسلة من 3 ذرات كربون وOH على ذرة الكربون الطرفية","marks":1},{"element":"(ب) ذرة أكسجين بين مجموعتي بروبيل","marks":1},{"element":"(ج) سلسلة من 3 ذرات كربون","marks":1},{"element":"(ج) مجموعتا NH₂ على ذرتي الكربون 1 و2","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) سلسلة من 3 ذرات كربون وOH على ذرة الكربون الطرفية؛ (ب) ذرة أكسجين بين مجموعتي بروبيل؛ (ج) سلسلة من 3 ذرات كربون؛ (ج) مجموعتا NH₂ على ذرتي الكربون 1 و2"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع OH على ذرة الكربون الوسطى في 1-بروبانول","رسم ثنائي بروبيل إيثر بمجموعة بروبيل واحدة وميثيل","وضع مجموعتي الأمين على ذرتي الكربون 1 و3 أو على الذرة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.663Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) حلقة سداسية من ذرات الكربون بروابط أحادية (هكسان حلقي) ترتبط بإحدى ذراتها مجموعة OH. (ب) حلقة بنزين أروماتية C₆H₅ ترتبط بها مجموعة NH₂: C₆H₅–NH₂. (ج) CH₃–CH(NH₂)–CH₂–CH₂–CH₂–CH₃. (د) H₂N–CH₂–CH₂–CH(NH₂)–CH₃.', '["(أ) حلقة هكسان حلقي (روابط أحادية) + OH","(ب) حلقة بنزين + NH₂","(ج) سلسلة من 6 ذرات كربون وNH₂ على ذرة الكربون الثانية","(د) سلسلة من 4 ذرات كربون","(د) مجموعتا NH₂ على ذرتي الكربون 1 و3"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) حلقة هكسان حلقي (روابط أحادية) + OH","marks":1},{"element":"(ب) حلقة بنزين + NH₂","marks":1},{"element":"(ج) سلسلة من 6 ذرات كربون وNH₂ على ذرة الكربون الثانية","marks":1},{"element":"(د) سلسلة من 4 ذرات كربون","marks":1},{"element":"(د) مجموعتا NH₂ على ذرتي الكربون 1 و3","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) حلقة هكسان حلقي (روابط أحادية) + OH؛ (ب) حلقة بنزين + NH₂؛ (ج) سلسلة من 6 ذرات كربون وNH₂ على ذرة الكربون الثانية؛ (د) سلسلة من 4 ذرات كربون؛ (د) مجموعتا NH₂ على ذرتي الكربون 1 و3"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم حلقة بنزين للهكسانول الحلقي أو حلقة هكسان حلقي للأنيلين","وضع NH₂ على ذرة الكربون الطرفية في 2-أمينوهكسان","رسم سلسلة من ثلاث ذرات كربون في 1، 3-ثنائي أمينو بيوتان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكحولان: CH₃–CH₂–CH₂–OH (1-بروبانول)، وCH₃–CH(OH)–CH₃ (2-بروبانول). الإيثر: CH₃–O–CH₂–CH₃ (إيثيل ميثيل إيثر). التحقق: في كل منها 3 ذرات C؛ وذرات H في 1-بروبانول 3 + 2 + 2 + 1 = 8، وفي 2-بروبانول 3 + 1 + 3 + 1 = 8، وفي الإيثر 3 + 2 + 3 = 8؛ وذرة O واحدة.', '["صيغة 1-بروبانول","اسم 1-بروبانول","صيغة 2-بروبانول","اسم 2-بروبانول","صيغة إيثيل ميثيل إيثر","اسم إيثيل ميثيل إيثر","التحقق من عدد الذرات C₃H₈O"]'::jsonb, '["عدّ ذرات الهيدروجين في 1-بروبانول: 3 + 2 + 2 + 1 = 8","عدّ ذرات الهيدروجين في 2-بروبانول: 3 + 1 + 3 + 1 = 8","عدّ ذرات الهيدروجين في إيثيل ميثيل إيثر: 3 + 2 + 3 = 8"]'::jsonb, '[{"element":"صيغة 1-بروبانول","marks":1},{"element":"اسم 1-بروبانول","marks":1},{"element":"صيغة 2-بروبانول","marks":1},{"element":"اسم 2-بروبانول","marks":1},{"element":"صيغة إيثيل ميثيل إيثر","marks":1},{"element":"اسم إيثيل ميثيل إيثر","marks":1},{"element":"التحقق من عدد الذرات C₃H₈O","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"إجابة كاملة صحيحة تشمل: صيغة 1-بروبانول؛ اسم 1-بروبانول؛ صيغة 2-بروبانول؛ اسم 2-بروبانول؛ صيغة إيثيل ميثيل إيثر؛ اسم إيثيل ميثيل إيثر؛ التحقق من عدد الذرات C₃H₈O"},{"level":"1–6 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم 3-بروبانول على أنه مركب مختلف عن 1-بروبانول","نسيان ذرة الهيدروجين في مجموعة OH عند العد","تسمية الإيثر ميثيل إيثيل إيثر بترتيب غير ألفبائي أو بروبيل إيثر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb)
