('mcq', 1, 'لماذا يصعب فصل الإيثانول عن الماء فصلًا كاملًا بعد مزجهما؟', null, null, '["لأن الإيثانول يتفاعل مع الماء مكوّنًا مركبًا جديدًا لا ينفصل بالتقطير","لأن جزيئات الإيثانول غير قطبية فتنتشر بين جزيئات الماء","لأنه يمتزج بالماء تمامًا بسبب قطبيته وتكوينه روابط هيدروجينية معه","لأن الإيثانول مركب أيوني يتفكك في الماء إلى أيونات"]'::jsonb, 'فهم', 'تفسير خاصية فيزيائية', 'متوسط', 'الكتاب ص 175 — خواص الكحولات'),
('mcq', 2, 'أيّ العبارات الآتية تصف الخواص الفيزيائية للإيثرات وصفًا صحيحًا؟', null, null, '["شديدة التطاير، ودرجات غليانها منخفضة مقارنة بالكحولات المماثلة لها في الحجم والكتلة","تكوّن روابط هيدروجينية قوية بين جزيئاتها، فدرجات غليانها مرتفعة","تمتزج بالماء امتزاجًا تامًا كما تمتزج الكحولات","عديمة الرائحة، وغير قابلة للاشتعال عند درجة حرارة الغرفة"]'::jsonb, 'فهم', 'وصف خواص', 'سهل', 'الكتاب ص 176 — الإيثرات'),
('mcq', 3, 'ما الخاصية الفيزيائية التي تميز الأمينات المتطايرة؟', null, null, '["رائحتها حلوة تشبه رائحة الإيثرات","رائحتها غير مقبولة لدى الإنسان","عديمة الرائحة؛ لذا يصعب الكشف عنها","رائحتها عطرية تمنح الفواكه والأزهار روائحها"]'::jsonb, 'تذكر', 'وصف خاصية', 'سهل', 'الكتاب ص 177 — الأمينات'),
('mcq', 4, 'يكون قياس الزاوية بين رابطتي الأكسجين التساهميتين في جزيء الإيثانول مساويًا تقريبًا لقياسها في جزيء الماء. ما الذي يترتب على ذلك؟', null, null, '["يصبح جزيء الإيثانول غير قطبي تمامًا كجزيئات الألكانات","تكون للإيثانول درجة الغليان نفسها التي للماء","يتفكك الإيثانول في الماء إلى أيونات كالمركبات الأيونية","تكون مجموعة الهيدروكسيل قطبية وقادرة على تكوين روابط هيدروجينية"]'::jsonb, 'فهم', 'ربط التركيب بالخواص', 'متوسط', 'الكتاب ص 174–175 — الكحولات (الشكل 5-7)'),
('mcq', 5, 'يبين الجدول الآتي درجتي غليان الميثانول وثنائي ميثيل إيثر، وكلاهما ينصهر عند درجة حرارة أقل من −90°C. ما الحالة الفيزيائية لكل منهما عند 25°C؟', '{"headers":["المركب","الصيغة","درجة الغليان"],"rows":[["الميثانول","CH₃OH","65°C"],["ثنائي ميثيل إيثر","CH₃–O–CH₃","−25°C"]]}'::jsonb, null, '["الميثانول سائل، وثنائي ميثيل إيثر سائل","الميثانول غاز، وثنائي ميثيل إيثر سائل","الميثانول سائل، وثنائي ميثيل إيثر غاز","الميثانول غاز، وثنائي ميثيل إيثر غاز"]'::jsonb, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 176 — الجدول 5-5'),
('mcq', 6, 'لماذا يُعد الكحول مذيبًا جيدًا للمواد العضوية القطبية؟', null, null, '["لأنه مركب أيوني يتفكك إلى أيونات تجذب المواد القطبية","بسبب قطبية مجموعة الهيدروكسيل فيه","لأن جزيئاته غير قطبية فتذيب جميع المواد","لأن درجة غليانه منخفضة جدًا مقارنة بالألكانات"]'::jsonb, 'فهم', 'تفسير خاصية', 'سهل', 'الكتاب ص 175 — خواص الكحولات'),
('mcq', 7, 'يبين الجدول الآتي المحتوى الحراري المولي للتبخر لثلاثة كحولات عند 25°C. أي استنتاج تدعمه هذه البيانات؟', '{"headers":["الكحول","الصيغة","المحتوى الحراري المولي للتبخر"],"rows":[["الميثانول","CH₃OH","37.4 kJ/mol"],["الإيثانول","CH₃CH₂OH","42.3 kJ/mol"],["2-بروبانول","CH₃CH(OH)CH₃","45.4 kJ/mol"]]}'::jsonb, null, '["تقل قوى الترابط بين جزيئات الكحول بزيادة حجم الجزيء","الميثانول أبطأ الكحولات الثلاثة تبخرًا","قوى الترابط متساوية في الكحولات الثلاثة؛ لأن كلًّا منها يحتوي على مجموعة OH واحدة","تزداد قوى الترابط بين جزيئات الكحول بزيادة حجم الجزيء، فيقل تبخره"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 198 — مختبر الكيمياء: خواص الكحولات'),
('essay', 1, 'صف الخواص الفيزيائية لكل من الكحولات والإيثرات والأمينات من حيث: القطبية والروابط الهيدروجينية، ودرجة الغليان أو التطاير، والذوبان في الماء، والرائحة حيث وردت.', null, null, null, 'فهم', 'وصف ومقارنة خواص', 'صعب', 'الكتاب ص 174–177 — التقويم 5-2 (س11)'),
('essay', 2, 'تحذّر إرشادات السلامة من استنشاق ثنائي إيثيل إيثر ومن تقريبه إلى مصادر اللهب. اربط هذا التحذير بالخواص الفيزيائية للإيثرات، مفسرًا سبب سرعة انتشار أبخرته.', null, null, null, 'تطبيق', 'ربط الخواص بالسلامة', 'صعب', 'الكتاب ص 176 — الإيثرات (الربط مع الصحة)'),
('essay', 3, 'تُستعمل الكلاب البوليسية المدربة لتحديد مكان الرفات البشري بعد الكوارث مثل الزلازل. ما الخاصيتان الفيزيائيتان للأمينات اللتان تعتمد عليهما هذه الطريقة؟ وضّح إجابتك.', null, null, null, 'فهم', 'تفسير تطبيق حياتي', 'متوسط', 'الكتاب ص 177 — الأمينات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
