select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يمتزج الكحول بالماء امتزاجًا تامًا بسبب قطبية مجموعة الهيدروكسيل وتكوين روابط هيدروجينية مع الماء؛ لذلك حتى بعد عملية التقطير يبقى نحو 5% من الماء في مزيج الإيثانول والماء.', '["امتزاج الإيثانول بالماء ذوبان فيزيائي وليس تفاعلًا كيميائيًّا ينتج مركبًا جديدًا.","جزيء الإيثانول متوسط القطبية بسبب مجموعة الهيدروكسيل، وليس غير قطبي.","","الإيثانول مركب جزيئي تساهمي لا يتفكك إلى أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 2, 0, 'لعدم وجود ذرات هيدروجين مرتبطة بذرة الأكسجين في الإيثرات لا تكوّن جزيئاتها روابط هيدروجينية بعضها مع بعض، ولذلك فهي شديدة التطاير ودرجات غليانها منخفضة مقارنة بالكحولات التي لها الحجم والكتلة الجزيئية نفسها.', '["","لا ترتبط ذرات هيدروجين بذرة الأكسجين في الإيثر، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض.","الإيثرات قليلة الذوبان في الماء مقارنة بالكحولات.","للإيثرات رائحة حلوة عند درجة حرارة الغرفة، وهي قابلة للاشتعال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 3, 1, 'تُعد رائحة الأمينات المتطايرة غير مقبولة من قبل الإنسان، والأمينات هي المسؤولة عن الكثير من الروائح المميزة للمخلوقات الميتة والمتحللة.', '["الرائحة الحلوة من صفات الإيثرات، أما رائحة الأمينات المتطايرة فغير مقبولة.","","رائحة الأمينات المتطايرة مميزة وقوية، وتعتمد عليها الكلاب المدربة في الكشف.","الروائح العطرية للفواكه والأزهار ترتبط بالإسترات لا بالأمينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 4, 3, 'بسبب تشابه الزاوية مع الماء تكون مجموعة الهيدروكسيل في جزيء الكحول متوسطة القطبية كما في الماء، وقادرة على تكوين روابط هيدروجينية مع جزيئات الماء ومع جزيئات كحول أخرى.', '["تشابه الزاوية مع الماء يجعل مجموعة الهيدروكسيل قطبية، لا غير قطبية.","تشابه الزاوية لا يعني تساوي درجتي الغليان؛ فقوى التجاذب الكلية بين الجزيئات مختلفة.","الإيثانول مركب جزيئي لا يتفكك إلى أيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 5, 2, 'عند 25°C: هذه الدرجة أقل من درجة غليان الميثانول (65°C) وأعلى من درجة انصهاره فهو سائل، وأعلى من درجة غليان ثنائي ميثيل إيثر (−25°C) فهو غاز؛ وهذا يعكس تطاير الإيثرات مقارنة بالكحولات.', '["درجة غليان ثنائي ميثيل إيثر −25°C أقل من 25°C، فهو غاز عند هذه الدرجة.","عُكست الحالتان؛ فالميثانول يغلي عند 65°C وهي أعلى من 25°C فيبقى سائلًا.","","الميثانول لا يغلي إلا عند 65°C، فهو سائل عند 25°C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 6, 1, 'بسبب قطبية مجموعة الهيدروكسيل في الكحول فإنه يعد مذيبًا جيدًا للمواد العضوية القطبية، وفق مبدأ أن المذيب القطبي يذيب المواد القطبية.', '["الكحول مركب جزيئي لا يتفكك إلى أيونات.","","جزيء الكحول قطبي بسبب مجموعة OH، والمادة غير القطبية لا تذيب المواد القطبية جيدًا.","درجة غليان الكحول أعلى من الهيدروكربونات المماثلة، ودرجة الغليان ليست سبب قدرته على الإذابة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.664Z"}'::jsonb),
('mcq', 7, 3, 'كلما زاد المحتوى الحراري المولي للتبخر زادت الطاقة اللازمة للتغلب على قوى الترابط بين الجزيئات؛ والقيم تزداد من الميثانول (37.4 kJ/mol) إلى الإيثانول (42.3 kJ/mol) إلى 2-بروبانول (45.4 kJ/mol)، أي أن قوى الترابط تزداد بزيادة حجم جزيء الكحول، فيصبح تبخره أبطأ.', '["البيانات تُظهر زيادة الطاقة اللازمة للتبخر بزيادة حجم الجزيء، أي أن قوى الترابط تزداد لا تقل.","الميثانول يحتاج إلى أقل طاقة للتبخر (37.4 kJ/mol)، فهو أسرعها تبخرًا.","لو تساوت قوى الترابط لتقاربت قيم المحتوى الحراري للتبخر، لكنها تزداد من 37.4 إلى 45.4 kJ/mol.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.665Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكحولات: مجموعة الهيدروكسيل فيها متوسطة القطبية وتكوّن روابط هيدروجينية بين جزيئاتها ومع الماء؛ لذا درجات غليانها أعلى من الهيدروكربونات المماثلة لها في الشكل والحجم، وتمتزج بالماء تمامًا وتعد مذيبات جيدة للمواد القطبية. الإيثرات: لا ترتبط ذرات هيدروجين بذرة الأكسجين فيها فلا تكوّن روابط هيدروجينية بين جزيئاتها؛ لذا هي شديدة التطاير ودرجات غليانها منخفضة مقارنة بالكحولات، وأقل قطبية وقليلة الذوبان في الماء، ولها رائحة حلوة وهي قابلة للاشتعال. الأمينات: المتطايرة منها ذات رائحة غير مقبولة، وهي مسؤولة عن روائح المخلوقات الميتة والمتحللة.', '["الكحولات قطبية وتكوّن روابط هيدروجينية","الكحولات درجات غليانها مرتفعة نسبيًّا","الكحولات تمتزج بالماء تمامًا","الإيثرات لا تكوّن روابط هيدروجينية بين جزيئاتها، شديدة التطاير ودرجات غليانها منخفضة","الإيثرات قليلة الذوبان في الماء، ورائحتها حلوة وقابلة للاشتعال","الأمينات المتطايرة رائحتها غير مقبولة"]'::jsonb, '[]'::jsonb, '[{"element":"الكحولات قطبية وتكوّن روابط هيدروجينية","marks":1},{"element":"الكحولات درجات غليانها مرتفعة نسبيًّا","marks":1},{"element":"الكحولات تمتزج بالماء تمامًا","marks":1},{"element":"الإيثرات لا تكوّن روابط هيدروجينية بين جزيئاتها، شديدة التطاير ودرجات غليانها منخفضة","marks":1},{"element":"الإيثرات قليلة الذوبان في الماء، ورائحتها حلوة وقابلة للاشتعال","marks":1},{"element":"الأمينات المتطايرة رائحتها غير مقبولة","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: الكحولات قطبية وتكوّن روابط هيدروجينية؛ الكحولات درجات غليانها مرتفعة نسبيًّا؛ الكحولات تمتزج بالماء تمامًا؛ الإيثرات لا تكوّن روابط هيدروجينية بين جزيئاتها، شديدة التطاير ودرجات غليانها منخفضة؛ الإيثرات قليلة الذوبان في الماء، ورائحتها حلوة وقابلة للاشتعال؛ الأمينات المتطايرة رائحتها غير مقبولة"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإيثرات تكوّن روابط هيدروجينية بين جزيئاتها","القول إن الإيثرات تمتزج بالماء تمامًا كالكحولات","الخلط بين رائحة الإيثرات الحلوة ورائحة الأمينات غير المقبولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.665Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الإيثرات شديدة التطاير؛ لأن جزيئاتها لا تكوّن روابط هيدروجينية بعضها مع بعض (لا توجد ذرات هيدروجين مرتبطة بذرة الأكسجين)، فدرجات غليانها منخفضة وتتبخر بسرعة فتنتشر أبخرتها في المكان. وهي مواد قابلة للاشتعال وشديدة الاشتعال، فاقتراب أبخرتها من اللهب خطر. كما أن لها رائحة حلوة، وقد تكون سامة ولها تأثير سلبي في الجهاز التنفسي عند استنشاقها، لذا يجب الحذر منها.', '["الإيثرات شديدة التطاير ودرجات غليانها منخفضة","التفسير: لا روابط هيدروجينية بين جزيئاتها","شديدة الاشتعال فتُبعد عن اللهب","استنشاقها ضار بالجهاز التنفسي (سميتها)"]'::jsonb, '[]'::jsonb, '[{"element":"الإيثرات شديدة التطاير ودرجات غليانها منخفضة","marks":1},{"element":"التفسير: لا روابط هيدروجينية بين جزيئاتها","marks":1},{"element":"شديدة الاشتعال فتُبعد عن اللهب","marks":1},{"element":"استنشاقها ضار بالجهاز التنفسي (سميتها)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الإيثرات شديدة التطاير ودرجات غليانها منخفضة؛ التفسير: لا روابط هيدروجينية بين جزيئاتها؛ شديدة الاشتعال فتُبعد عن اللهب؛ استنشاقها ضار بالجهاز التنفسي (سميتها)"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير التطاير بضعف الروابط التساهمية داخل الجزيء","عدّ الرائحة الحلوة دليلًا على أمان المادة","إغفال ربط التطاير بانتشار الأبخرة نحو اللهب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.665Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تعتمد الطريقة على أن بعض الأمينات متطايرة فتنتشر أبخرتها في الهواء، وأن رائحتها مميزة وغير مقبولة؛ إذ إن الأمينات مسؤولة عن الكثير من الروائح المميزة للمخلوقات الميتة والمتحللة، فتتعرف الكلاب المدربة هذه الرائحة وتحدد مكان الرفات.', '["الخاصية الأولى: تطاير بعض الأمينات","الخاصية الثانية: رائحتها المميزة غير المقبولة","الربط: الأمينات مسؤولة عن روائح المخلوقات المتحللة فتكشفها الكلاب"]'::jsonb, '[]'::jsonb, '[{"element":"الخاصية الأولى: تطاير بعض الأمينات","marks":1},{"element":"الخاصية الثانية: رائحتها المميزة غير المقبولة","marks":1},{"element":"الربط: الأمينات مسؤولة عن روائح المخلوقات المتحللة فتكشفها الكلاب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"إجابة كاملة صحيحة تشمل: الخاصية الأولى: تطاير بعض الأمينات؛ الخاصية الثانية: رائحتها المميزة غير المقبولة؛ الربط: الأمينات مسؤولة عن روائح المخلوقات المتحللة فتكشفها الكلاب"},{"level":"1–2 درجتان","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر خاصية كيميائية (تفاعل) بدل خاصية فيزيائية","القول إن رائحة الأمينات حلوة","إغفال خاصية التطاير"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-11-14T13:39:20.665Z"}'::jsonb)
