('mcq', 1, 0, 'يُستخدم الإيثانول في الطب بسبب فاعليته بوصفه مطهرًا، ولذلك يُستعمل لتعقيم الجلد قبل إعطاء الحقن.', '["","المادة التي استُعملت مخدرًا في العمليات الجراحية هي ثنائي إيثيل إيثر، لا الإيثانول.","المادة المستعملة مانعًا للتجمد هي الجليسرول، ولا علاقة لذلك بتعقيم الجلد.","الإيثانول سائل عديم اللون، والأصباغ ذات الظلال العميقة تُنتج من الأنيلين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 2, 1, 'المركب (2) حلقة بنزين مرتبطة بمجموعة NH₂، وهو الأنيلين الذي يُستعمل في إنتاج الأصباغ ذات الظلال العميقة اللون، واسمه الشائع مستمد من النباتات التي عُرفت في تلك الفترة التاريخية.', '["المركب (1) هو هكسانول حلقي، ويُستعمل مذيبًا لبعض المواد البلاستيكية وفي صناعة المبيدات الحشرية.","","المركب (3) هو هكسيل حلقي أمين، ويُستعمل في صناعة المبيدات الحشرية والمواد البلاستيكية والأدوية والمطاط.","المركب (4) إيثر (هكسيل حلقي إيثر) لا يحتوي على نيتروجين، وليس المركب المستعمل في إنتاج الأصباغ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 3, 3, 'المركب سلسلة من ثلاث ذرات كربون ترتبط بكل منها مجموعة OH، أي 1، 2، 3-بروبان ترايول، واسمه الشائع الجليسرول، ويُستعمل غالبًا مانعًا لتجمد الوقود في الطائرات.', '["المادة التي استُعملت مخدرًا هي ثنائي إيثيل إيثر، والمركب المعروض كحول فيه ثلاث مجموعات OH.","الأصباغ ذات الظلال العميقة تُنتج من الأنيلين، وهو أمين أروماتي.","الكحول الذي يُضاف إلى البنزين هو الإيثانول، وفيه مجموعة OH واحدة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 4, 0, 'استُعمل المصطلح إيثر أول مرة للمركب ثنائي إيثيل إيثر، وهو مادة متطايرة شديدة الاشتعال استُعملت مادة مخدرة في العمليات الجراحية منذ عام 1842م حتى القرن العشرين.', '["","الإيثانول يُستعمل مطهرًا لتعقيم الجلد، لا مخدرًا في العمليات الجراحية.","الأنيلين أمين يُستعمل في إنتاج الأصباغ.","الجليسرول يُستعمل مانعًا لتجمد الوقود في الطائرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 5, 2, 'الميثانول أبسط الكحولات، وهو من المذيبات الشائعة الاستعمال في الصناعة، ومن ذلك استعماله في بعض الدهانات.', '["الجليسرول يُستعمل مانعًا لتجمد الوقود في الطائرات.","هكسانول حلقي مذيب لبعض المواد البلاستيكية ويدخل في صناعة المبيدات الحشرية، لا في الدهانات.","","2-بيوتانول يُستعمل مذيبًا في بعض الأصباغ، لا في الدهانات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 6, 0, 'لكل من هكسيل حلقي أمين والإيثيل أمين دور مهم في صناعة المبيدات الحشرية والمواد البلاستيكية والأدوية والمطاط المستعمل في صناعة الإطارات.', '["","المخدر المذكور هو ثنائي إيثيل إيثر، ومانع التجمد هو الجليسرول، وكلاهما ليس أمينًا.","المطهر المستعمل لتعقيم الجلد هو الإيثانول، وهو كحول لا أمين.","الكحول المضاف إلى البنزين هو الإيثانول، والمذيب الصناعي الشائع هو الميثانول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('mcq', 7, 3, 'هكسانول حلقي مركب سام يُستعمل مذيبًا لبعض المواد البلاستيكية، ويدخل في صناعة المبيدات الحشرية؛ أما بقية البدائل فتبادلت فيها الاستعمالات بين المركبات.', '["الأنيلين يُستعمل في إنتاج الأصباغ، ومانع التجمد هو الجليسرول.","الجليسرول مانع لتجمد الوقود، والمخدر هو ثنائي إيثيل إيثر.","ثنائي إيثيل إيثر استُعمل مخدرًا، والمطهر هو الإيثانول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الإيثانول. (ب) الميثانول. (ج) الجليسرول (1، 2، 3-بروبان ترايول). (د) ثنائي إيثيل إيثر. (هـ) الأنيلين.', '["(أ) الإيثانول","(ب) الميثانول","(ج) الجليسرول","(د) ثنائي إيثيل إيثر","(هـ) الأنيلين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الإيثانول","marks":1},{"element":"(ب) الميثانول","marks":1},{"element":"(ج) الجليسرول","marks":1},{"element":"(د) ثنائي إيثيل إيثر","marks":1},{"element":"(هـ) الأنيلين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الإيثانول؛ (ب) الميثانول؛ (ج) الجليسرول؛ (د) ثنائي إيثيل إيثر؛ (هـ) الأنيلين"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الإيثانول مخدرًا","ذكر هكسيل حلقي أمين لإنتاج الأصباغ بدل الأنيلين","الخلط بين الميثانول والجليسرول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ينتج الإيثانول وثاني أكسيد الكربون من عملية تخمر السكر الموجود في العنب، وفي عجين الخبز. ومن استعمالاته: مطهر في الطب يُعقَّم به الجلد قبل إعطاء الحقن، ويُضاف إلى البنزين (وقود)، ومادة أولية مهمة لتحضير مركبات عضوية أخرى أكثر تعقيدًا.', '["المصدر الأول: تخمر السكر في العنب","المصدر الثاني: عجين الخبز","مطهر لتعقيم الجلد قبل الحقن","يُضاف إلى البنزين","مادة أولية لتحضير مركبات عضوية أكثر تعقيدًا"]'::jsonb, '[]'::jsonb, '[{"element":"المصدر الأول: تخمر السكر في العنب","marks":1},{"element":"المصدر الثاني: عجين الخبز","marks":1},{"element":"مطهر لتعقيم الجلد قبل الحقن","marks":1},{"element":"يُضاف إلى البنزين","marks":1},{"element":"مادة أولية لتحضير مركبات عضوية أكثر تعقيدًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: المصدر الأول: تخمر السكر في العنب؛ المصدر الثاني: عجين الخبز؛ مطهر لتعقيم الجلد قبل الحقن؛ يُضاف إلى البنزين؛ مادة أولية لتحضير مركبات عضوية أكثر تعقيدًا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر استعمال الإيثانول مخدرًا","ذكر منع التجمد استعمالًا للإيثانول (وهو للجليسرول)","عدّ التطهير وتعقيم الجلد استعمالين منفصلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الميثانول: من المذيبات الشائعة في الصناعة، ويُستعمل في بعض الدهانات. 2-بيوتانول: مذيب في بعض الأصباغ. هكسانول حلقي: مذيب لبعض المواد البلاستيكية. والتفسير: مجموعة الهيدروكسيل في الكحول قطبية، فيكون الكحول مذيبًا جيدًا للمواد العضوية القطبية.', '["الميثانول: مذيب صناعي وفي الدهانات","2-بيوتانول: مذيب في بعض الأصباغ","هكسانول حلقي: مذيب لبعض المواد البلاستيكية","التفسير: قطبية مجموعة الهيدروكسيل"]'::jsonb, '[]'::jsonb, '[{"element":"الميثانول: مذيب صناعي وفي الدهانات","marks":1},{"element":"2-بيوتانول: مذيب في بعض الأصباغ","marks":1},{"element":"هكسانول حلقي: مذيب لبعض المواد البلاستيكية","marks":1},{"element":"التفسير: قطبية مجموعة الهيدروكسيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الميثانول: مذيب صناعي وفي الدهانات؛ 2-بيوتانول: مذيب في بعض الأصباغ؛ هكسانول حلقي: مذيب لبعض المواد البلاستيكية؛ التفسير: قطبية مجموعة الهيدروكسيل"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الجليسرول مذيبًا للدهانات","تفسير الإذابة بأن الكحول غير قطبي","ذكر ثنائي إيثيل إيثر بوصفه كحولًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.666Z"}'::jsonb)
