select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تُعد الأمينات أولية أو ثانوية أو ثالثية اعتمادًا على ما إذا كانت واحدة أو اثنتان أو ثلاث من ذرات الهيدروجين في الأمونيا NH₃ قد حل محلها مجموعات عضوية.', '["طول السلسلة الكربونية لا يحدد التصنيف؛ فالمهم عدد المجموعات العضوية المرتبطة بالنيتروجين.","عدد مجموعات الأمين يُعبَّر عنه في الاسم بالمقاطع ثنائي وثلاثي، ولا علاقة له بالتصنيف.","","التصنيف يعتمد على ما يرتبط بذرة النيتروجين، لا على نوع ذرة الكربون المرتبطة بها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 2, 1, 'في المركب (2) ترتبط ذرة النيتروجين بمجموعتي ميثيل وبذرة هيدروجين واحدة؛ أي أن مجموعتين عضويتين حلتا محل ذرتي هيدروجين من الأمونيا، فهو أمين ثانوي.', '["في المركب (1) مجموعة عضوية واحدة (إيثيل) مرتبطة بالنيتروجين ومعها ذرتا هيدروجين، فهو أمين أولي.","","في المركب (3) ثلاث مجموعات ميثيل حلت محل ذرات الهيدروجين الثلاث، فهو أمين ثالثي.","في المركب (4) ترتبط بالنيتروجين مجموعة عضوية واحدة وذرتا هيدروجين (NH₂)، فهو أمين أولي مهما تفرعت السلسلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 3, 0, 'في المركب (4) ترتبط ذرة النيتروجين بمجموعة عضوية واحدة (C(CH₃)₃) وبذرتي هيدروجين، أي أن ذرة هيدروجين واحدة فقط من ذرات الأمونيا حلت محلها مجموعة عضوية، فهو أمين أولي، ولا أثر لتفرع ذرة الكربون في التصنيف.', '["","التصنيف يعتمد على المجموعات المرتبطة بذرة النيتروجين لا بذرة الكربون؛ والنيتروجين هنا يرتبط بمجموعة عضوية واحدة.","ذرتا الهيدروجين على النيتروجين تعنيان أن ذرة هيدروجين واحدة فقط استُبدلت، فهو أولي لا ثانوي.","المركب يحتوي على مجموعة NH₂ مرتبطة بذرة كربون فهو أمين، وتفرع السلسلة لا يغير ذلك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 4, 3, 'حلقة البنزين مجموعة عضوية واحدة. في (1) يرتبط النيتروجين بمجموعة عضوية واحدة وذرتي H فهو أولي، وفي (2) بمجموعتين (الحلقة والميثيل) وذرة H واحدة فهو ثانوي، وفي (3) بثلاث مجموعات (الحلقة ومجموعتي ميثيل) دون H فهو ثالثي.', '["عُدّت مجموعات الميثيل فقط وأُهملت حلقة البنزين، مع أنها مجموعة عضوية مرتبطة بالنيتروجين.","عُدّت حلقة البنزين مجموعتين عضويتين، مع أنها مجموعة عضوية واحدة.","عُكس تصنيف (2) و(3)؛ ففي (2) ذرة هيدروجين باقية على النيتروجين، وفي (3) لا توجد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 5, 0, 'في (CH₃CH₂)₂NH ترتبط ذرة النيتروجين بمجموعتي إيثيل وبذرة هيدروجين واحدة؛ أي أن اثنتين من ذرات الهيدروجين الثلاث في الأمونيا حلت محلها مجموعات عضوية، فهو أمين ثانوي.', '["","الأمين الأولي يبقى فيه على النيتروجين ذرتا هيدروجين، لا ذرة واحدة.","النيتروجين يرتبط بثلاث ذرات في كل الأمينات؛ والمعيار عدد المجموعات العضوية، وهي هنا اثنتان.","لا يعتمد التصنيف على عدد ذرات الكربون، ولا يوجد صنف رباعي في هذا التصنيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 6, 2, 'في الأمين الثالثي حلت مجموعات عضوية محل ذرات الهيدروجين الثلاث في الأمونيا، فترتبط ذرة النيتروجين بثلاث مجموعات عضوية ولا تبقى عليها أي ذرة هيدروجين.', '["هذا وصف الأمين الأولي.","هذا وصف الأمين الثانوي.","","هذه هي الأمونيا NH₃ نفسها، وليست أمينًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('mcq', 7, 3, 'في (CH₃)₂CHNH₂ ترتبط ذرة النيتروجين بمجموعة عضوية واحدة (CH(CH₃)₂) وبذرتي هيدروجين، فهو أمين أولي، مع أن ذرة الكربون المرتبطة بالنيتروجين متفرعة.', '["يرتبط النيتروجين هنا بمجموعتي ميثيل وذرة هيدروجين واحدة، فهو أمين ثانوي.","يرتبط النيتروجين هنا بثلاث مجموعات عضوية ولا ذرة هيدروجين، فهو أمين ثالثي.","يرتبط النيتروجين هنا بمجموعة ميثيل ومجموعة إيثيل وذرة هيدروجين واحدة، فهو أمين ثانوي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأمين الأولي: حلت فيه مجموعة عضوية واحدة محل ذرة هيدروجين واحدة في الأمونيا، مثل CH₃CH₂NH₂. الأمين الثانوي: حلت فيه مجموعتان عضويتان محل ذرتي هيدروجين، مثل CH₃–NH–CH₃. الأمين الثالثي: حلت فيه ثلاث مجموعات عضوية محل ذرات الهيدروجين الثلاث، مثل (CH₃)₃N.', '["تعريف الأمين الأولي","مثال أمين أولي","تعريف الأمين الثانوي","مثال أمين ثانوي","تعريف الأمين الثالثي","مثال أمين ثالثي"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الأمين الأولي","marks":1},{"element":"مثال أمين أولي","marks":1},{"element":"تعريف الأمين الثانوي","marks":1},{"element":"مثال أمين ثانوي","marks":1},{"element":"تعريف الأمين الثالثي","marks":1},{"element":"مثال أمين ثالثي","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف الأمين الأولي؛ مثال أمين أولي؛ تعريف الأمين الثانوي؛ مثال أمين ثانوي؛ تعريف الأمين الثالثي؛ مثال أمين ثالثي"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الأصناف بعدد ذرات الكربون في الجزيء","عدّ الأمين المتفرع السلسلة ثانويًّا أو ثالثيًّا","كتابة مثال للأمين الثالثي تبقى فيه ذرة هيدروجين على النيتروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) أولي: مجموعة عضوية واحدة (بروبيل). (ب) ثانوي: مجموعتان (ميثيل وإيثيل). (ج) ثالثي: ثلاث مجموعات إيثيل. (د) أولي: مجموعة واحدة (حلقة البنزين). (هـ) أولي: مجموعة واحدة (حلقة الهكسيل الحلقي).', '["(أ) أولي – مجموعة واحدة","(ب) ثانوي – مجموعتان","(ج) ثالثي – ثلاث مجموعات","(د) أولي – مجموعة واحدة","(هـ) أولي – مجموعة واحدة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) أولي – مجموعة واحدة","marks":1},{"element":"(ب) ثانوي – مجموعتان","marks":1},{"element":"(ج) ثالثي – ثلاث مجموعات","marks":1},{"element":"(د) أولي – مجموعة واحدة","marks":1},{"element":"(هـ) أولي – مجموعة واحدة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) أولي – مجموعة واحدة؛ (ب) ثانوي – مجموعتان؛ (ج) ثالثي – ثلاث مجموعات؛ (د) أولي – مجموعة واحدة؛ (هـ) أولي – مجموعة واحدة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ حلقة البنزين أو الهكسيل الحلقي أكثر من مجموعة عضوية","تصنيف (ب) أوليًّا لوجود ذرة H على النيتروجين","الخلط بين عدد ذرات الكربون وعدد المجموعات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.667Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) CH₃CH₂CH₂NH₂: أمين أولي. 2) (CH₃)₂CHNH₂ أي CH₃–CH(NH₂)–CH₃: أمين أولي. 3) CH₃–NH–CH₂CH₃: أمين ثانوي. 4) (CH₃)₃N: أمين ثالثي. وفي كل منها 3 ذرات C و9 ذرات H وذرة N واحدة.', '["صيغة CH₃CH₂CH₂NH₂","تصنيفه: أولي","صيغة CH₃CH(NH₂)CH₃","تصنيفه: أولي","صيغة CH₃NHCH₂CH₃","تصنيفه: ثانوي","صيغة (CH₃)₃N","تصنيفه: ثالثي"]'::jsonb, '["عدّ ذرات H في CH₃CH₂CH₂NH₂: 3 + 2 + 2 + 2 = 9","عدّ ذرات H في CH₃CH(NH₂)CH₃: 3 + 1 + 2 + 3 = 9","عدّ ذرات H في CH₃NHCH₂CH₃: 3 + 1 + 2 + 3 = 9","عدّ ذرات H في (CH₃)₃N: 3 × 3 = 9"]'::jsonb, '[{"element":"صيغة CH₃CH₂CH₂NH₂","marks":1},{"element":"تصنيفه: أولي","marks":1},{"element":"صيغة CH₃CH(NH₂)CH₃","marks":1},{"element":"تصنيفه: أولي","marks":1},{"element":"صيغة CH₃NHCH₂CH₃","marks":1},{"element":"تصنيفه: ثانوي","marks":1},{"element":"صيغة (CH₃)₃N","marks":1},{"element":"تصنيفه: ثالثي","marks":1}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة صحيحة تشمل: صيغة CH₃CH₂CH₂NH₂؛ تصنيفه: أولي؛ صيغة CH₃CH(NH₂)CH₃؛ تصنيفه: أولي؛ صيغة CH₃NHCH₂CH₃؛ تصنيفه: ثانوي؛ صيغة (CH₃)₃N؛ تصنيفه: ثالثي"},{"level":"1–7 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف CH₃CH(NH₂)CH₃ ثانويًّا لأن ذرة الكربون ثانوية","كتابة CH₃CH₂NHCH₃ وCH₃NHCH₂CH₃ على أنهما مركبان مختلفان","نسيان الأمين الثالثي (CH₃)₃N"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.668Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L2-O05') and x.type = v.type and x.number = v.number
