insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L2-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'للمركبين الآتيين الصيغة الجزيئية نفسها C₂H₆O. أيّهما أكثر ذوبانية في الماء، ولماذا؟', null, '[{"src":"qimg/chem22/c5-l2a-c2h6o-pair.svg","alt":"صيغتان بنائيتان كاملتان مرقمتان لمركبين صيغة كل منهما الجزيئية C₂H₆O. (1): H–C–C–O–H، ترتبط بكل ذرة كربون ذرتا هيدروجين أعلاها وأسفلها، وذرة الأكسجين ترتبط بذرة كربون وذرة هيدروجين. (2): H–C–O–C–H، ترتبط بكل ذرة كربون ذرتا هيدروجين أعلاها وأسفلها، وذرة الأكسجين بين ذرتي الكربون ولا ترتبط بأي ذرة هيدروجين."}]'::jsonb, '["المركب (2)؛ لأن ذرة الأكسجين فيه بين ذرتي كربون فتزداد قطبيته","المركب (1)؛ لأن مجموعة الهيدروكسيل فيه تكوّن روابط هيدروجينية مع الماء","يتساويان في الذوبانية؛ لأن لهما الصيغة الجزيئية والكتلة المولية نفسيهما","المركب (2)؛ لأن جزيئاته لا يجذب بعضها بعضًا فتنتشر بين جزيئات الماء"]'::jsonb, 'فهم', 'مقارنة ذائبية من صيغ بنائية', 'متوسط', 'الكتاب ص 175–177 — التقويم 5-2 (س12)'),
('mcq', 2, 'يمثل الخط المتقطع في الشكل الآتي تجاذبًا بين جزيء إيثر وجزيء ماء. ما الذي يفسره هذا التجاذب؟', null, '[{"src":"qimg/chem22/c5-l2a-ether-water.svg","alt":"جزيء CH₃–O–CH₃ مرسوم أفقيًّا، وأسفله جزيء ماء H–O–H. يصل خط أزرق متقطع رأسي بين ذرة الأكسجين O في جزيء CH₃–O–CH₃ وإحدى ذرتي الهيدروجين H في جزيء الماء."}]'::jsonb, '["امتزاج الإيثرات بالماء امتزاجًا تامًا كما تمتزج الكحولات","تكوين روابط هيدروجينية بين جزيئات الإيثر نفسها","عدم ذوبان الإيثرات في الماء مطلقًا","ذوبان الإيثرات في الماء ذوبانًا قليلًا"]'::jsonb, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 176 — الإيثرات'),
('mcq', 3, 'أيّ العبارات الآتية تقارن بين ذائبية الكحولات والإيثرات في الماء مقارنة صحيحة؟', null, null, '["الكحولات الصغيرة تمتزج بالماء امتزاجًا تامًا، أما الإيثرات فقليلة الذوبان فيه","الإيثرات تمتزج بالماء امتزاجًا تامًا، أما الكحولات فقليلة الذوبان فيه","الكحولات والإيثرات كلتاهما تمتزجان بالماء امتزاجًا تامًا","الكحولات والإيثرات كلتاهما لا تذوبان في الماء"]'::jsonb, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 175–176 — الكحولات والإيثرات'),
('mcq', 4, 'ما الترتيب الصحيح للمركبات الآتية تصاعديًّا حسب ذائبيتها في الماء (من الأقل إلى الأكثر): البروبان CH₃CH₂CH₃، وثنائي ميثيل إيثر CH₃OCH₃، والإيثانول CH₃CH₂OH؟', null, null, '["الإيثانول، ثم ثنائي ميثيل إيثر، ثم البروبان","البروبان، ثم ثنائي ميثيل إيثر، ثم الإيثانول","ثنائي ميثيل إيثر، ثم البروبان، ثم الإيثانول","البروبان، ثم الإيثانول، ثم ثنائي ميثيل إيثر"]'::jsonb, 'تحليل', 'ترتيب حسب الذائبية', 'صعب', 'الكتاب ص 175–176 — الكحولات والإيثرات'),
('mcq', 5, 'يبين الجدول الآتي ذائبية بعض الكحولات في الماء (بوحدة mol/100 g H₂O). ماذا تعني العبارة «غير محدودة» في ذائبية الكحولات الثلاثة الأولى؟', '{"headers":["الكحول","الصيغة","الذائبية (mol/100 g H₂O)"],"rows":[["ميثانول","CH₃OH","غير محدودة"],["إيثانول","C₂H₅OH","غير محدودة"],["بروبانول","C₃H₇OH","غير محدودة"],["بيوتانول","C₄H₉OH","0.11"],["بنتانول","C₅H₁₁OH","0.030"]]}'::jsonb, null, '["أنها لا تذوب في الماء مطلقًا","أن ذائبيتها لم تُقَس بعد","أنها تمتزج بالماء امتزاجًا تامًا بأي نسبة","أنها تتفاعل مع الماء فلا يمكن قياس ذائبيتها"]'::jsonb, 'فهم', 'تفسير بيانات جدول', 'سهل', 'الكتاب ص 205 — الجدول 5-15'),
('mcq', 6, 'تذوب الأمينات الصغيرة مثل الإيثيل أمين CH₃CH₂NH₂ في الماء بدرجة كبيرة. ما التفسير الأنسب لذلك، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر؟', null, null, '["لأنها مركبات أيونية تتفكك في الماء إلى أيونات","لأن ذرات H المرتبطة بالنيتروجين تكوّن روابط هيدروجينية مع الماء","لأنها مركبات غير قطبية، مثل جزيئات الماء","لأن ذرة النيتروجين فيها لا ترتبط بأي ذرة هيدروجين"]'::jsonb, 'فهم', 'تفسير ذائبية', 'متوسط', 'الكتاب ص 174، 177 — الكحولات والأمينات (معطيات الرابطة الهيدروجينية في نص السؤال)'),
('mcq', 7, 'خُلط حجم من الماء مع حجم مساوٍ له من سائل X فتكوّنت طبقتان منفصلتان، وعند تكرار ذلك مع سائل Y تكوّن محلول متجانس. إذا علمت أن X وY هما الإيثانول وثنائي إيثيل إيثر، فأيّ مما يأتي صحيح؟', null, null, '["X ثنائي إيثيل إيثر لأنه قليل الذوبان في الماء، وY الإيثانول لأنه يمتزج بالماء تمامًا","X الإيثانول لأنه أقل قطبية من الماء، وY ثنائي إيثيل إيثر لأنه قطبي","X الإيثانول لأن جزيئاته ترتبط بروابط هيدروجينية بعضها مع بعض فلا تختلط بالماء","X ثنائي إيثيل إيثر لأنه لا يذوب في الماء مطلقًا، وY الإيثانول لأنه أيوني"]'::jsonb, 'تطبيق', 'تفسير مشاهدة تجريبية', 'صعب', 'الكتاب ص 175–176 — الكحولات والإيثرات'),
('essay', 1, 'فسّر لماذا تكون ذوبانية الإيثانول CH₃CH₂OH في الماء أكبر من ذوبانية ثنائي ميثيل إيثر CH₃OCH₃، رغم أن الكتلة المولية لكل منهما 46.07 g/mol.', null, null, null, 'فهم', 'تفسير مقارنة', 'متوسط', 'الكتاب ص 202 — تقويم الفصل (س37)'),
('essay', 2, 'قارن بين الكحولات والإيثرات والأمينات من حيث قدرة جزيئاتها على تكوين روابط هيدروجينية مع الماء وكيفية ذلك، ثم قارن بين ذائبية الكحولات الصغيرة وذائبية الإيثرات في الماء، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر.', null, null, null, 'تحليل', 'مقارنة ثلاثية', 'صعب', 'الكتاب ص 175–177 — الكحولات والإيثرات والأمينات'),
('essay', 3, 'حدّد في كل زوج مما يأتي المركب الأكثر ذوبانية في الماء، مع التعليل، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر:
(أ) الميثانول CH₃OH وثنائي ميثيل إيثر CH₃OCH₃
(ب) الإيثيل أمين CH₃CH₂NH₂ والبروبان CH₃CH₂CH₃', null, null, null, 'فهم', 'مقارنة أزواج', 'سهل', 'الكتاب ص 175–177 — الكحولات والإيثرات والأمينات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L2-O06') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'المركب (1) كحول (الإيثانول) فيه مجموعة هيدروكسيل قطبية تكوّن روابط هيدروجينية مع جزيئات الماء فيمتزج بالماء تمامًا، أما المركب (2) فإيثر (ثنائي ميثيل إيثر) أقل قطبية ولا توجد فيه ذرة هيدروجين مرتبطة بالأكسجين، فهو أقل ذوبانية في الماء.', '["المركب (2) إيثر، والإيثرات أقل قطبية من الكحولات وقليلة الذوبان في الماء.","","تساوي الكتلة المولية لا يعني تساوي الذوبانية؛ فالتركيب البنائي يحدد القطبية والقدرة على تكوين الروابط الهيدروجينية.","ضعف التجاذب بين جزيئات الإيثر يفسر تطايره، لكنه لا يجعله أكثر ذوبانًا؛ فهو قليل الذوبان في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.668Z"}'::jsonb),
('mcq', 2, 3, 'يمكن لذرة الأكسجين في الإيثر أن تعمل مستقبلًا لذرات الهيدروجين من جزيئات الماء، وهو ما يفسر ذوبان الإيثرات في الماء بشكل قليل، مع أنها أقل ذوبانًا من الكحولات.', '["الإيثرات قليلة الذوبان في الماء؛ فهي لا تمتزج به امتزاجًا تامًا.","التجاذب المرسوم بين الإيثر والماء، أما جزيئات الإيثر فلا تكوّن روابط هيدروجينية بعضها مع بعض لعدم وجود H مرتبط بالأكسجين.","هذا التجاذب نفسه هو ما يجعل الإيثرات تذوب في الماء ولو بشكل قليل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.668Z"}'::jsonb),
('mcq', 3, 0, 'يمكن أن يمتزج الكحول تمامًا مع الماء بسبب قطبيته وتكوينه روابط هيدروجينية معه، أما الإيثرات فقليلة الذوبان في الماء لأنها أقل قطبية، ولا تكوّن إلا روابط محدودة مع الماء عبر ذرة الأكسجين.', '["","عُكست المقارنة؛ فالكحولات هي التي تكوّن روابط هيدروجينية مع الماء وتمتزج به.","الإيثرات أقل قطبية ولا تمتزج بالماء امتزاجًا تامًا، بل تذوب فيه بشكل قليل.","الكحولات تمتزج بالماء، والإيثرات تذوب فيه بشكل قليل؛ فكلاهما يذوب بدرجة ما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.668Z"}'::jsonb),
('mcq', 4, 1, 'البروبان هيدروكربون غير قطبي لا يذوب في الماء تقريبًا، وثنائي ميثيل إيثر أقل قطبية من الكحول لكن ذرة الأكسجين فيه تستقبل ذرات هيدروجين من الماء فيذوب قليلًا، والإيثانول يكوّن روابط هيدروجينية مع الماء فيمتزج به تمامًا؛ فالترتيب: البروبان، ثم ثنائي ميثيل إيثر، ثم الإيثانول.', '["هذا ترتيب تنازلي لا تصاعدي؛ فالإيثانول هو الأكثر ذوبانية.","","البروبان غير قطبي فهو أقل ذوبانية من الإيثر الذي تستقبل ذرة الأكسجين فيه ذرات الهيدروجين من الماء.","الإيثانول يمتزج بالماء تمامًا، فهو أكثر ذوبانية من الإيثر القليل الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.668Z"}'::jsonb),
('mcq', 5, 2, 'الكحولات الصغيرة (الميثانول والإيثانول والبروبانول) سوائل تامة الامتزاج بالماء؛ أي يذوب كل منهما في الآخر بأي نسبة، لذا لا يوجد حد لذائبيتها، بخلاف الكحولات الأكبر التي لها ذائبية محددة صغيرة.', '["«غير محدودة» عكس «لا تذوب»؛ فهي تعني أن الذوبان لا حد له.","العبارة تصف خاصية للمادة (الامتزاج التام)، لا نقصًا في القياس.","","ذوبان الكحول في الماء عملية فيزيائية لا تفاعل كيميائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb),
('mcq', 6, 1, 'مجموعة الأمين –NH₂ قطبية، وذرات الهيدروجين المرتبطة بالنيتروجين تكوّن روابط هيدروجينية مع جزيئات الماء؛ لذا تذوب الأمينات الصغيرة في الماء بدرجة كبيرة.', '["الأمينات مركبات جزيئية تساهمية، وليست مركبات أيونية.","","الماء مذيب قطبي، والمواد غير القطبية لا تذوب فيه جيدًا.","في الإيثيل أمين ترتبط بالنيتروجين ذرتا هيدروجين (NH₂)، ووجودهما هو سبب تكوين الروابط الهيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb),
('mcq', 7, 0, 'تكوّن الطبقتين يعني أن السائل لا يمتزج بالماء امتزاجًا تامًا، وهذا شأن ثنائي إيثيل إيثر القليل الذوبان لعدم تكوينه روابط هيدروجينية كافية وقلة قطبيته؛ أما المحلول المتجانس فيدل على الامتزاج التام، وهذا شأن الإيثانول الذي يكوّن روابط هيدروجينية مع الماء.', '["","عُكس التحديد؛ فالإيثانول قطبي يمتزج بالماء، والإيثر أقل قطبية.","الروابط الهيدروجينية التي يكوّنها الإيثانول مع الماء هي سبب امتزاجه به لا انفصاله عنه.","الإيثر يذوب في الماء بشكل قليل، والإيثانول مركب جزيئي لا أيوني."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تساوي الكتلتين يعني أن الفرق يعود إلى التركيب لا إلى حجم الجزيء. في الإيثانول ترتبط ذرة هيدروجين بذرة الأكسجين (مجموعة –OH)، فتكون المجموعة قطبية وتكوّن روابط هيدروجينية مع جزيئات الماء (تمنح الماء ذرة H وتستقبل منه)، فيمتزج بالماء تمامًا. أما في ثنائي ميثيل إيثر فذرة الأكسجين مرتبطة بذرتي كربون ولا توجد ذرة هيدروجين مرتبطة بها، فالجزيء أقل قطبية، ولا يتجاذب مع الماء إلا باستقبال ذرة الأكسجين ذرة هيدروجين من الماء، لذا فهو قليل الذوبان.', '["الفرق يعود إلى التركيب البنائي لا إلى الكتلة","الإيثانول فيه OH قطبية تكوّن روابط هيدروجينية مع الماء","الإيثر لا ترتبط ذرة H بأكسجينه وهو أقل قطبية","الأكسجين في الإيثر يستقبل H من الماء فقط فيذوب قليلًا"]'::jsonb, '["حساب الكتلة المولية لـ C₂H₆O: 2(12.01) + 6(1.008) + 16.00 = 46.07 g/mol لكل من المركبين"]'::jsonb, '[{"element":"الفرق يعود إلى التركيب البنائي لا إلى الكتلة","marks":1},{"element":"الإيثانول فيه OH قطبية تكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"الإيثر لا ترتبط ذرة H بأكسجينه وهو أقل قطبية","marks":1},{"element":"الأكسجين في الإيثر يستقبل H من الماء فقط فيذوب قليلًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الفرق يعود إلى التركيب البنائي لا إلى الكتلة؛ الإيثانول فيه OH قطبية تكوّن روابط هيدروجينية مع الماء؛ الإيثر لا ترتبط ذرة H بأكسجينه وهو أقل قطبية؛ الأكسجين في الإيثر يستقبل H من الماء فقط فيذوب قليلًا"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق باختلاف الكتلة المولية","القول إن الإيثر لا يذوب في الماء مطلقًا","القول إن الإيثر يكوّن روابط هيدروجينية بين جزيئاته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكحولات: ترتبط ذرة H بذرة O في مجموعة –OH القطبية، فتكوّن روابط هيدروجينية مع الماء. الأمينات: ترتبط ذرات H بذرة N في مجموعة –NH₂، فتكوّن روابط هيدروجينية مع الماء. الإيثرات: لا ترتبط ذرة H بذرة O، فلا تتجاذب مع الماء إلا باستقبال ذرة الأكسجين فيها ذرة هيدروجين من الماء. أما الذائبية: فالكحولات الصغيرة تمتزج بالماء امتزاجًا تامًا، والإيثرات قليلة الذوبان فيه لأنها أقل قطبية.', '["الكحولات: OH تكوّن روابط هيدروجينية مع الماء","الأمينات: NH₂ تكوّن روابط هيدروجينية مع الماء","الإيثرات: الأكسجين يستقبل H من الماء فقط","الكحولات الصغيرة تامة الامتزاج","الإيثرات قليلة الذوبان لقلة قطبيتها"]'::jsonb, '[]'::jsonb, '[{"element":"الكحولات: OH تكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"الأمينات: NH₂ تكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"الإيثرات: الأكسجين يستقبل H من الماء فقط","marks":1},{"element":"الكحولات الصغيرة تامة الامتزاج","marks":1},{"element":"الإيثرات قليلة الذوبان لقلة قطبيتها","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الكحولات: OH تكوّن روابط هيدروجينية مع الماء؛ الأمينات: NH₂ تكوّن روابط هيدروجينية مع الماء؛ الإيثرات: الأكسجين يستقبل H من الماء فقط؛ الكحولات الصغيرة تامة الامتزاج؛ الإيثرات قليلة الذوبان لقلة قطبيتها"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأمينات لا تكوّن روابط هيدروجينية لأنها لا تحتوي على أكسجين","القول إن الإيثرات لا تتجاذب مع الماء مطلقًا","عدّ الإيثرات أذوب من الكحولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الميثانول؛ لأن مجموعة الهيدروكسيل القطبية تكوّن روابط هيدروجينية مع الماء فيمتزج به تمامًا، أما الإيثر فأقل قطبية ولا ترتبط ذرة H بأكسجينه فهو قليل الذوبان. (ب) الإيثيل أمين؛ لأن مجموعة –NH₂ القطبية تكوّن روابط هيدروجينية مع الماء، أما البروبان فهيدروكربون غير قطبي لا يذوب في الماء.', '["(أ) الميثانول","(أ) التعليل: روابط هيدروجينية مع الماء مقابل قلة قطبية الإيثر","(ب) الإيثيل أمين","(ب) التعليل: NH₂ قطبية تكوّن روابط هيدروجينية، والبروبان غير قطبي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الميثانول","marks":1},{"element":"(أ) التعليل: روابط هيدروجينية مع الماء مقابل قلة قطبية الإيثر","marks":1},{"element":"(ب) الإيثيل أمين","marks":1},{"element":"(ب) التعليل: NH₂ قطبية تكوّن روابط هيدروجينية، والبروبان غير قطبي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الميثانول؛ (أ) التعليل: روابط هيدروجينية مع الماء مقابل قلة قطبية الإيثر؛ (ب) الإيثيل أمين؛ (ب) التعليل: NH₂ قطبية تكوّن روابط هيدروجينية، والبروبان غير قطبي"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اختيار الإيثر لأنه أكبر كتلة من الميثانول","اختيار البروبان لتقارب كتلته مع الإيثيل أمين","إغفال التعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-11-14T13:39:20.669Z"}'::jsonb)
