('mcq', 1, 'ما سبب ارتفاع درجات غليان الكحولات مقارنة بالإيثرات المماثلة لها في الحجم والكتلة الجزيئية؟', null, null, '["جزيئات الكحول أكبر كتلة من جزيئات الإيثر المماثلة لها","الروابط التساهمية داخل جزيء الكحول أقوى، فيصعب كسرها عند الغليان","جزيئات الكحول تكوّن روابط هيدروجينية بعضها مع بعض، ولا تكوّنها جزيئات الإيثر","جزيئات الإيثر أكثر قطبية من جزيئات الكحول"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 174، 176 — الكحولات والإيثرات'),
('mcq', 2, 'يمثل الخط المتقطع في الشكل الآتي التجاذب بين جزيئين من الإيثانول. ما هذا التجاذب، وما أثره في درجة غليان الإيثانول؟', null, '[{"src":"qimg/chem22/c5-l2a-hbond-ethanol.svg","alt":"جزيئان من المركب CH₃–CH₂–O–H. في الجزيء العلوي: CH₃–CH₂–O–H مرسوم أفقيًّا. في الجزيء السفلي: O ترتبط بمجموعة CH₂–CH₃ يمينًا وبذرة H إلى أسفل. يصل خط أزرق متقطع بين ذرة الهيدروجين H المرتبطة بالأكسجين في الجزيء العلوي وذرة الأكسجين O في الجزيء السفلي."}]'::jsonb, '["رابطة تساهمية تخفض درجة غليان الإيثانول","رابطة أيونية بين أيونات الإيثانول ترفع درجة غليانه","رابطة هيدروجينية تخفض درجة الغليان لأنها تزيد تطاير الإيثانول","رابطة هيدروجينية ترفع درجة الغليان؛ لأن التغلب عليها يحتاج إلى طاقة إضافية"]'::jsonb, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 174 — الكحولات'),
('mcq', 3, 'للمركبين الآتيين الصيغة الجزيئية نفسها C₂H₆O. أيّهما درجة غليانه أعلى، ولماذا؟', null, '[{"src":"qimg/chem22/c5-l2a-c2h6o-pair.svg","alt":"صيغتان بنائيتان كاملتان مرقمتان لمركبين صيغة كل منهما الجزيئية C₂H₆O. (1): H–C–C–O–H، ترتبط بكل ذرة كربون ذرتا هيدروجين أعلاها وأسفلها، وذرة الأكسجين ترتبط بذرة كربون وذرة هيدروجين. (2): H–C–O–C–H، ترتبط بكل ذرة كربون ذرتا هيدروجين أعلاها وأسفلها، وذرة الأكسجين بين ذرتي الكربون ولا ترتبط بأي ذرة هيدروجين."}]'::jsonb, '["المركب (1)؛ لأن جزيئاته تكوّن روابط هيدروجينية بعضها مع بعض","المركب (2)؛ لأن ذرة الأكسجين فيه ترتبط بذرتي كربون فتقوى قوى التجاذب","لهما درجة الغليان نفسها؛ لتساوي كتلتيهما الموليتين","المركب (2)؛ لأن عدد روابط C–H فيه أكبر من المركب (1)"]'::jsonb, 'فهم', 'مقارنة من صيغ بنائية', 'متوسط', 'الكتاب ص 174، 176 — الجدول 5-5'),
('mcq', 4, 'درجة غليان الإيثانول (46.07 g/mol) هي 78°C، ودرجة غليان البروبان (44.09 g/mol) هي −42°C. أيّ مما يأتي يفسر هذا الفرق الكبير؟', null, null, '["كتلة الإيثانول المولية أكبر قليلًا، وهذا وحده يفسر فرقًا يتجاوز 100°C","جزيئات البروبان قطبية، وجزيئات الإيثانول غير قطبية","جزيئات الإيثانول قطبية وترتبط بروابط هيدروجينية، أما جزيئات البروبان فغير قطبية ولا تكوّنها","البروبان يحتوي على روابط ثنائية تضعف التجاذب بين جزيئاته"]'::jsonb, 'فهم', 'تعليل من بيانات', 'متوسط', 'الكتاب ص 174 — الكحولات'),
('mcq', 5, 'درجة غليان الميثانول CH₃OH (32.04 g/mol) هي 65°C، ودرجة غليان الميثيل أمين CH₃NH₂ (31.06 g/mol) هي −6°C. ما التفسير الأنسب لهذا الفرق، علمًا بأن كهروسالبية الأكسجين 3.44 وكهروسالبية النيتروجين 3.04؟', null, null, '["الميثيل أمين لا يكوّن روابط هيدروجينية مطلقًا لأنه لا يحتوي على أكسجين","الروابط الهيدروجينية بين جزيئات الأمين أقوى، فتنخفض درجة غليانه","جزيء الميثانول غير قطبي، فتقوى قوى التشتت بين جزيئاته","الروابط الهيدروجينية بين جزيئات الميثانول أقوى؛ لأن O–H أكثر قطبية من N–H"]'::jsonb, 'فهم', 'تعليل مقارنة', 'صعب', 'الكتاب ص 174، 202 — (س38) (قيم الكهروسالبية ودرجات الغليان في نص السؤال)'),
('mcq', 6, 'عند غليان الكحول، ما الذي يتطلب طاقة أكبر مقارنة بغليان هيدروكربون مماثل له في الشكل والحجم؟', null, null, '["كسر الروابط التساهمية بين ذرتي الكربون والأكسجين داخل الجزيء","التغلب على الروابط الهيدروجينية بين جزيئات الكحول","التغلب على قوى التجاذب الأيونية بين جزيئات الكحول","فصل ذرات الهيدروجين عن جزيئات الكحول"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 174 — الكحولات'),
('mcq', 7, 'أيّ المركبات الآتية يُتوقع أن تكون درجة غليانه الأعلى، علمًا بأن كتلها المولية متقاربة (بين 58 g/mol و61 g/mol)، وأن الروابط الهيدروجينية بين الجزيئات لا تتكون إلا إذا ارتبطت ذرة H مباشرة بذرة O أو N؟', null, null, '["1-بروبانول CH₃CH₂CH₂OH","إيثيل ميثيل إيثر CH₃OCH₂CH₃","ثلاثي ميثيل أمين (CH₃)₃N","البيوتان CH₃CH₂CH₂CH₃"]'::jsonb, 'تحليل', 'توقع ومقارنة', 'صعب', 'الكتاب ص 174، 176، 202 — (س38)'),
('essay', 1, 'درجة غليان الميثانول CH₃OH هي 65°C، ودرجة غليان ثنائي ميثيل إيثر CH₃OCH₃ هي −25°C. فسّر هذا الفرق بالاعتماد على تركيب جزيء كل منهما، ثم حدّد أيّهما أكثر تطايرًا.', null, null, null, 'فهم', 'تعليل من بيانات', 'سهل', 'الكتاب ص 176 — الإيثرات (الجدول 5-5)'),
('essay', 2, 'فسّر لماذا تكون درجة غليان الإيثانول CH₃CH₂OH أعلى كثيرًا من درجة غليان الأمينو إيثان (الإيثيل أمين) CH₃CH₂NH₂، رغم أن كتلتيهما الموليتين متساويتان تقريبًا (كهروسالبية الأكسجين 3.44، وكهروسالبية النيتروجين 3.04).', null, null, null, 'فهم', 'تعليل مقارنة', 'متوسط', 'الكتاب ص 202 — تقويم الفصل (س38)'),
('essay', 3, 'المركبات الآتية متقاربة في كتلها المولية: 1-بروبانول CH₃CH₂CH₂OH (60.09 g/mol)، وإيثيل ميثيل إيثر CH₃OCH₂CH₃ (60.09 g/mol)، وبروبيل أمين CH₃CH₂CH₂NH₂ (59.11 g/mol)، والبيوتان CH₃CH₂CH₂CH₃ (58.12 g/mol). ودرجات غليانها (بترتيب عشوائي): 7°C، و97°C، و−1°C، و48°C. انسب كل درجة غليان إلى مركبها، وفسّر ترتيبك (كهروسالبية الأكسجين 3.44، وكهروسالبية النيتروجين 3.04).', null, null, null, 'تحليل', 'توقع وترتيب مع تعليل', 'صعب', 'الكتاب ص 174، 176، 202 — الكحولات والإيثرات (س38)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
