insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تكوّن مجموعة الهيدروكسيل في الكحول روابط هيدروجينية بين جزيئاته، أما الإيثرات فلا ترتبط بذرة الأكسجين فيها ذرات هيدروجين فلا تكوّن جزيئاتها روابط هيدروجينية بعضها مع بعض؛ لذا تحتاج الكحولات إلى طاقة أكبر للغليان.', '["المقارنة بين جزيئات متماثلة في الكتلة، فالكتلة ليست سبب الفرق.","لا تُكسر الروابط التساهمية داخل الجزيء عند الغليان؛ بل يُتغلب على قوى التجاذب بين الجزيئات.","","الإيثرات أقل قطبية من الكحولات، لا أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 2, 3, 'الخط المتقطع يصل ذرة H المرتبطة بالأكسجين في جزيء بذرة O في جزيء آخر، وهذه رابطة هيدروجينية؛ ولأن فصل الجزيئات عند الغليان يتطلب التغلب على هذه الروابط فإن درجة غليان الكحول أعلى من درجة غليان المركبات المماثلة له في الشكل والحجم.', '["الخط المتقطع يمثل تجاذبًا بين جزيئين منفصلين، لا رابطة تساهمية داخل الجزيء، وهو يرفع درجة الغليان لا يخفضها.","الإيثانول مركب جزيئي لا يحتوي على أيونات.","الروابط الهيدروجينية تقلل التطاير؛ لأنها تمسك الجزيئات بعضها ببعض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 3, 0, 'المركب (1) كحول (الإيثانول) تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض عبر مجموعة –OH، أما المركب (2) فإيثر (ثنائي ميثيل إيثر) لا ترتبط ذرة هيدروجين بأكسجينه فلا تكوّن جزيئاته روابط هيدروجينية؛ لذا درجة غليان المركب (1) أعلى.', '["","ارتباط الأكسجين بذرتي كربون يمنع تكوين روابط هيدروجينية بين جزيئات الإيثر، فتكون درجة غليانه منخفضة.","تساوي الكتلة المولية لا يعني تساوي درجة الغليان؛ فقوى التجاذب بين الجزيئات مختلفة.","زيادة روابط C–H لا تكوّن روابط هيدروجينية؛ والعامل الحاسم هنا وجود H مرتبط بالأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 4, 2, 'الإيثانول والبروبان متقاربان في الكتلة والحجم، لكن مجموعة الهيدروكسيل في الإيثانول متوسطة القطبية وتكوّن روابط هيدروجينية بين جزيئاته، بينما البروبان غير قطبي؛ لذا درجة غليان الكحول أعلى بكثير من درجة غليان الهيدروكربون المماثل له.', '["فرق الكتلة صغير جدًا (نحو 2 g/mol)، ولا يفسر فرقًا كبيرًا في درجة الغليان.","عُكست القطبية؛ فالبروبان هيدروكربون غير قطبي، والإيثانول قطبي بسبب مجموعة OH.","","البروبان ألكان مشبع روابطه أحادية فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 5, 3, 'كلا المركبين يكوّن روابط هيدروجينية بين جزيئاته، لكن الأكسجين (3.44) أعلى كهروسالبية من النيتروجين (3.04)، فالرابطة O–H أكثر قطبية من N–H، وتكون الروابط الهيدروجينية بين جزيئات الميثانول أقوى؛ فيحتاج إلى طاقة أكبر للغليان، ودرجة غليانه أعلى بنحو 71°C.', '["ترتبط ذرتا هيدروجين بالنيتروجين في الميثيل أمين، فيكوّن روابط هيدروجينية لكنها أضعف.","الروابط الأقوى بين الجزيئات ترفع درجة الغليان لا تخفضها، والروابط في الأمين هي الأضعف لأن النيتروجين أقل كهروسالبية.","جزيء الميثانول قطبي بسبب مجموعة OH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 6, 1, 'عند الغليان تنفصل جزيئات الكحول بعضها عن بعض دون أن تتغير، وبسبب الروابط الهيدروجينية بين جزيئات الكحول يحتاج فصلها إلى طاقة أكبر، فتكون درجة غليان الكحول أعلى من درجة غليان الهيدروكربون المماثل له.', '["الغليان تغير فيزيائي لا تُكسر فيه الروابط التساهمية داخل الجزيء.","","الكحول مركب جزيئي لا توجد فيه أيونات.","لا تنفصل ذرات من الجزيء عند الغليان؛ يبقى الجزيء كما هو في الحالة الغازية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.670Z"}'::jsonb),
('mcq', 7, 0, 'عند تقارب الكتل المولية يحدد نوع التجاذب بين الجزيئات درجة الغليان. في 1-بروبانول وحده ترتبط ذرة H بذرة O، فتكوّن جزيئاته روابط هيدروجينية؛ أما الإيثر فأكسجينه مرتبط بذرتي كربون، وثلاثي ميثيل أمين لا H على نيتروجينه، والبيوتان غير قطبي؛ لذا أعلاها درجة غليان 1-بروبانول.', '["","لا ترتبط ذرة هيدروجين بالأكسجين في الإيثر، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض، فدرجة غليانه منخفضة.","لا ترتبط أي ذرة هيدروجين بذرة النيتروجين في هذا الأمين الثالثي، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض.","البيوتان هيدروكربون غير قطبي لا يكوّن روابط هيدروجينية، فدرجة غليانه هي الأدنى."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.671Z"}'::jsonb),
('essay', 1, null::int, null, null, 'في الميثانول ترتبط ذرة هيدروجين بذرة الأكسجين (مجموعة –OH)، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض، ويحتاج التغلب عليها عند الغليان إلى طاقة أكبر، فدرجة غليانه مرتفعة. أما في ثنائي ميثيل إيثر فذرة الأكسجين مرتبطة بذرتي كربون ولا توجد ذرة هيدروجين مرتبطة بها، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض، فدرجة غليانه منخفضة. لذا ثنائي ميثيل إيثر أكثر تطايرًا (وهو غاز عند درجة حرارة الغرفة).', '["الميثانول فيه H مرتبط بالأكسجين","جزيئات الميثانول تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر","الإيثر لا H على أكسجينه فلا روابط هيدروجينية بين جزيئاته","ثنائي ميثيل إيثر أكثر تطايرًا"]'::jsonb, '[]'::jsonb, '[{"element":"الميثانول فيه H مرتبط بالأكسجين","marks":1},{"element":"جزيئات الميثانول تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر","marks":1},{"element":"الإيثر لا H على أكسجينه فلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"ثنائي ميثيل إيثر أكثر تطايرًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الميثانول فيه H مرتبط بالأكسجين؛ جزيئات الميثانول تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر؛ الإيثر لا H على أكسجينه فلا روابط هيدروجينية بين جزيئاته؛ ثنائي ميثيل إيثر أكثر تطايرًا"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق باختلاف الكتلة المولية","القول إن الغليان يكسر الروابط التساهمية","عدّ الميثانول أكثر تطايرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.671Z"}'::jsonb),
('essay', 2, null::int, null, null, 'كلا المركبين قطبي ويكوّن روابط هيدروجينية بين جزيئاته؛ ففي الإيثانول ترتبط ذرة H بذرة O، وفي الأمين ترتبط ذرتا H بذرة N. لكن الأكسجين أعلى كهروسالبية من النيتروجين، فالرابطة O–H أكثر قطبية من N–H، وتكون الروابط الهيدروجينية بين جزيئات الإيثانول أقوى، فيحتاج فصلها عند الغليان إلى طاقة أكبر، فتكون درجة غليان الإيثانول أعلى.', '["كلا المركبين يكوّن روابط هيدروجينية","الأكسجين أعلى كهروسالبية من النيتروجين","O–H أكثر قطبية من N–H فالروابط الهيدروجينية في الكحول أقوى","الحاجة إلى طاقة أكبر لفصل جزيئات الإيثانول"]'::jsonb, '["حساب الكتلتين: الإيثانول C₂H₆O = 46.07 g/mol، والإيثيل أمين C₂H₇N = 45.09 g/mol (متقاربتان)"]'::jsonb, '[{"element":"كلا المركبين يكوّن روابط هيدروجينية","marks":1},{"element":"الأكسجين أعلى كهروسالبية من النيتروجين","marks":1},{"element":"O–H أكثر قطبية من N–H فالروابط الهيدروجينية في الكحول أقوى","marks":1},{"element":"الحاجة إلى طاقة أكبر لفصل جزيئات الإيثانول","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: كلا المركبين يكوّن روابط هيدروجينية؛ الأكسجين أعلى كهروسالبية من النيتروجين؛ O–H أكثر قطبية من N–H فالروابط الهيدروجينية في الكحول أقوى؛ الحاجة إلى طاقة أكبر لفصل جزيئات الإيثانول"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأمينات لا تكوّن روابط هيدروجينية","تفسير الفرق بالكتلة المولية","القول إن النيتروجين أعلى كهروسالبية من الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.671Z"}'::jsonb),
('essay', 3, null::int, null, null, '1-بروبانول: 97°C؛ لأنه يكوّن أقوى روابط هيدروجينية بين جزيئاته عبر O–H. بروبيل أمين: 48°C؛ لأنه يكوّن روابط هيدروجينية عبر N–H لكنها أضعف لأن النيتروجين أقل كهروسالبية من الأكسجين. إيثيل ميثيل إيثر: 7°C؛ لأن جزيئاته لا تكوّن روابط هيدروجينية بعضها مع بعض (لا H على الأكسجين)، لكنها أكثر قطبية من الألكان. البيوتان: −1°C؛ لأنه غير قطبي ولا يكوّن روابط هيدروجينية. فالترتيب التصاعدي: البيوتان < إيثيل ميثيل إيثر < بروبيل أمين < 1-بروبانول.', '["1-بروبانول 97°C مع التعليل","بروبيل أمين 48°C مع التعليل","إيثيل ميثيل إيثر 7°C مع التعليل","البيوتان −1°C مع التعليل","ربط الترتيب بقوة التجاذب بين الجزيئات لا بالكتلة"]'::jsonb, '[]'::jsonb, '[{"element":"1-بروبانول 97°C مع التعليل","marks":1},{"element":"بروبيل أمين 48°C مع التعليل","marks":1},{"element":"إيثيل ميثيل إيثر 7°C مع التعليل","marks":1},{"element":"البيوتان −1°C مع التعليل","marks":1},{"element":"ربط الترتيب بقوة التجاذب بين الجزيئات لا بالكتلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: 1-بروبانول 97°C مع التعليل؛ بروبيل أمين 48°C مع التعليل؛ إيثيل ميثيل إيثر 7°C مع التعليل؛ البيوتان −1°C مع التعليل؛ ربط الترتيب بقوة التجاذب بين الجزيئات لا بالكتلة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة أعلى درجة غليان إلى الأمين أو الإيثر","ترتيب المركبات حسب الكتلة المولية","عدّ الإيثر مكوّنًا روابط هيدروجينية بين جزيئاته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.671Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
