from (values
('mcq', 1, 1, 'ترتبط ذرة الأكسجين في المركب بمجموعة إيثيل من جهة وبمجموعة بيوتيل من الجهة الأخرى، أي بذرتي كربون، وهذه المجموعة الوظيفية (–O–) تميز الإيثرات ROR′.', '["لا توجد ذرة هيدروجين مرتبطة بذرة الأكسجين؛ فالأكسجين مرتبط بذرتي كربون.","","لا يحتوي المركب على ذرة نيتروجين.","لا يحتوي المركب على أي ذرة هالوجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 2, 0, 'ترتبط بذرة الكربون الثانية في السلسلة مجموعة NH₂، وهي مجموعة الأمين؛ لذا ينتمي المركب إلى الأمينات RNH₂.', '["","لا يحتوي المركب على ذرة أكسجين.","لا يحتوي المركب على ذرة أكسجين بين ذرتي كربون.","المركب ليس هيدروكربونًا؛ فهو يحتوي على مجموعة NH₂ مرتبطة بذرة كربون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 3, 2, 'في طرف السلسلة مجموعة HO (أكسجين مرتبط بكربون وهيدروجين) وهي مجموعة الهيدروكسيل، وفي الطرف الآخر مجموعة NH₂ وهي مجموعة الأمين.', '["ذرة الأكسجين مرتبطة بذرة كربون واحدة وذرة هيدروجين، لا بذرتي كربون؛ فهي مجموعة هيدروكسيل.","المجموعة الثانية NH₂ تحتوي على نيتروجين، فهي مجموعة أمين لا إيثر.","","لا يحتوي المركب على ذرة هالوجين؛ والمجموعة NH₂ مجموعة أمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 4, 3, 'تُسمى مجموعة الأكسجين–الهيدروجين (–OH) المرتبطة تساهميًّا بذرة كربون مجموعة الهيدروكسيل، وهي المجموعة الوظيفية للكحولات.', '["مجموعة الأمين هي –NH₂ وتحتوي على نيتروجين لا أكسجين.","في الإيثر ترتبط ذرة الأكسجين بذرتي كربون، ولا ترتبط بهيدروجين.","أيون الهيدروكسيد OH⁻ أيون سالب في القواعد الأيونية، أما –OH في الكحولات فمرتبطة تساهميًّا بالكربون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 5, 1, 'الأكسجين والنيتروجين من أكثر الذرات شيوعًا في المجموعات الوظيفية العضوية؛ فالأكسجين في الهيدروكسيل والإيثر، والنيتروجين في الأمين.', '["الكربون والهيدروجين يكوّنان الهيكل الهيدروكربوني نفسه، لا المجموعات الوظيفية التي تحل محل الهيدروجين.","","الهالوجينات توجد في هاليدات الألكيل فقط، والأكسجين والنيتروجين أكثر شيوعًا منها في المجموعات الوظيفية.","يوجدان في بعض المركبات العضوية، لكنهما ليسا الأكثر شيوعًا في المجموعات الوظيفية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 6, 2, 'في المركب (2) ترتبط ذرة الأكسجين بمجموعتي إيثيل، أي بذرتي كربون (ROR′)، وهذه صفة الإيثرات.', '["المركب (1) يحتوي على مجموعة –OH، فهو كحول.","المركب (3) يحتوي على مجموعة –NH₂، فهو أمين.","","المركب (4) يحتوي على ذرة كلور مرتبطة بالكربون، فهو هاليد ألكيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('mcq', 7, 3, 'في CH₃CH₂OCH₃ (إيثيل ميثيل إيثر) ترتبط ذرة الأكسجين بذرتي كربون ولا ترتبط بأي ذرة هيدروجين، فهو إيثر لا يحتوي على مجموعة الهيدروكسيل، أما المركبات الأخرى فكحولات.', '["الإيثانول يحتوي على مجموعة –OH مرتبطة بذرة الكربون.","يحتوي هذا المركب على مجموعة –OH في نهاية السلسلة، فهو كحول.","هذا الهكسانول الحلقي، وهو كحول ترتبط فيه مجموعة –OH بإحدى ذرات الكربون في الحلقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) مجموعة الهيدروكسيل –OH، فهو كحول. (ب) ذرة أكسجين مرتبطة بذرتي كربون –O–، فهو إيثر. (ج) مجموعة الأمين –NH₂، فهو أمين. (د) مجموعة الأمين –NH₂ مرتبطة بحلقة بنزين، فهو أمين.', '["(أ) –OH هيدروكسيل؛ كحول","(ب) –O– بين ذرتي كربون؛ إيثر","(ج) –NH₂؛ أمين","(د) –NH₂ على حلقة بنزين؛ أمين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) –OH هيدروكسيل؛ كحول","marks":1},{"element":"(ب) –O– بين ذرتي كربون؛ إيثر","marks":1},{"element":"(ج) –NH₂؛ أمين","marks":1},{"element":"(د) –NH₂ على حلقة بنزين؛ أمين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) –OH هيدروكسيل؛ كحول؛ (ب) –O– بين ذرتي كربون؛ إيثر؛ (ج) –NH₂؛ أمين؛ (د) –NH₂ على حلقة بنزين؛ أمين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CH₃–O–CH₂CH₃ كحولًا لوجود الأكسجين فيه","عدّ الأنيلين هيدروكربونًا أروماتيًّا وإهمال مجموعة NH₂","الخلط بين مجموعة الهيدروكسيل وأيون الهيدروكسيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الكحولات: مركبات عضوية تحتوي على مجموعة الهيدروكسيل –OH مرتبطة تساهميًّا بذرة كربون، وتنتج عن إحلال مجموعة –OH محل ذرة هيدروجين في الهيدروكربون (مثل CH₄ ← CH₃OH). الإيثرات: مركبات عضوية تحتوي على ذرة أكسجين مرتبطة بذرتي كربون (ROR′). الأمينات: مركبات تحتوي على ذرة نيتروجين مرتبطة بذرات كربون (مجموعة الأمين –NH₂ في RNH₂)، وقد اشتُق اسمها من الأمونيا NH₃، وتنتج عن حلول مجموعة عضوية أو أكثر محل ذرات الهيدروجين في الأمونيا.', '["تعريف الكحول: –OH مرتبطة تساهميًّا بالكربون","تعريف الإيثر: أكسجين مرتبط بذرتي كربون","تعريف الأمين: نيتروجين مرتبط بكربون (–NH₂)","الكحول = إحلال –OH محل H في الهيدروكربون","الأمين = حلول مجموعة عضوية محل H في NH₃"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الكحول: –OH مرتبطة تساهميًّا بالكربون","marks":1},{"element":"تعريف الإيثر: أكسجين مرتبط بذرتي كربون","marks":1},{"element":"تعريف الأمين: نيتروجين مرتبط بكربون (–NH₂)","marks":1},{"element":"الكحول = إحلال –OH محل H في الهيدروكربون","marks":1},{"element":"الأمين = حلول مجموعة عضوية محل H في NH₃","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تعريف الكحول: –OH مرتبطة تساهميًّا بالكربون؛ تعريف الإيثر: أكسجين مرتبط بذرتي كربون؛ تعريف الأمين: نيتروجين مرتبط بكربون (–NH₂)؛ الكحول = إحلال –OH محل H في الهيدروكربون؛ الأمين = حلول مجموعة عضوية محل H في NH₃"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الإيثر بأنه أكسجين مرتبط بكربون وهيدروجين","القول إن الأمين ينتج من إحلال NH₃ كاملة محل ذرة كربون","إهمال كون الرابطة في الكحول تساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المجموعة الأولى: مجموعة الهيدروكسيل –OH في الطرف الأيسر، وتميز الكحولات. المجموعة الثانية: ذرة أكسجين مرتبطة بذرتي كربون –O– في وسط السلسلة، وتميز الإيثرات. المجموعة الثالثة: مجموعة الأمين –NH₂ في الطرف الأيمن، وتميز الأمينات.', '["–OH هيدروكسيل في الطرف؛ تميز الكحولات","–O– بين ذرتي كربون في الوسط؛ تميز الإيثرات","–NH₂ أمين في الطرف الآخر؛ تميز الأمينات"]'::jsonb, '[]'::jsonb, '[{"element":"–OH هيدروكسيل في الطرف؛ تميز الكحولات","marks":2},{"element":"–O– بين ذرتي كربون في الوسط؛ تميز الإيثرات","marks":2},{"element":"–NH₂ أمين في الطرف الآخر؛ تميز الأمينات","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: –OH هيدروكسيل في الطرف؛ تميز الكحولات؛ –O– بين ذرتي كربون في الوسط؛ تميز الإيثرات؛ –NH₂ أمين في الطرف الآخر؛ تميز الأمينات"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ ذرتي الأكسجين مجموعتي هيدروكسيل","إغفال مجموعة الإيثر في وسط السلسلة","وصف –O– بأنها مجموعة هيدروكسيل لأنها تحتوي على أكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.672Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
