from (values
('mcq', 1, 'يمثل الخط المتقطع في كل شكل مما يأتي تجاذبًا مقترحًا بين جزيئين. في أيّ الأشكال يمثل الخط المتقطع رابطة هيدروجينية؟', null, '[{"src":"qimg/chem22/c5-l2b-o09-candidates.svg","alt":"أربعة أشكال مرقمة، في كل منها جزيئان وخط أزرق متقطع بينهما. (1) جزيء CH₃–O–H وجزيء ميثانول آخر؛ الخط المتقطع يصل ذرة H المرتبطة بالأكسجين في الجزيء الأول بذرة O في الجزيء الثاني. (2) جزيء ميثانول مرسوم بصيغة بنائية كاملة (ذرة C تحيط بها ثلاث ذرات H، ومرتبطة بمجموعة O–H)؛ الخط المتقطع يصل إحدى ذرات H المرتبطة بالكربون بذرة O في جزيء ميثانول آخر. (3) جزيئا ثنائي ميثيل إيثر CH₃–O–CH₃ أحدهما فوق الآخر؛ الخط المتقطع يصل ذرة O في أحدهما بذرة O في الآخر. (4) جزيئا ميثانول CH₃–O–H أحدهما فوق الآخر؛ الخط المتقطع يصل ذرة H في مجموعة OH للأول بذرة H في مجموعة OH للثاني."}]'::jsonb, '["الشكل (2)","الشكل (3)","الشكل (1)","الشكل (4)"]'::jsonb, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 174 — الكحولات'),
('mcq', 2, 'يمثل الخط المتقطع في الشكل الآتي تجاذبًا بين جزيئين من الميثيل أمين CH₃NH₂. أيّ مما يأتي يصفه وصفًا صحيحًا، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر؟', null, '[{"src":"qimg/chem22/c5-l2b-o09-methylamine.svg","alt":"جزيئان من الميثيل أمين CH₃NH₂. في الجزيء العلوي: CH₃ مرتبطة بذرة N، وترتبط N بذرتي هيدروجين (واحدة إلى أعلى وواحدة إلى اليمين). في الجزيء السفلي: N مرتبطة بمجموعة CH₃ يمينًا وبذرتي هيدروجين. يصل خط أزرق متقطع بين ذرة H المرتبطة بالنيتروجين في الجزيء العلوي وذرة N في الجزيء السفلي."}]'::jsonb, '["رابطة هيدروجينية بين ذرة H مرتبطة بالنيتروجين في جزيء وذرة N في جزيء آخر","رابطة تساهمية بين ذرتي نيتروجين في جزيئين متجاورين","رابطة هيدروجينية بين ذرة H من مجموعة CH₃ وذرة N في جزيء آخر","رابطة أيونية بين أيونين موجب وسالب من الأمين"]'::jsonb, 'فهم', 'تفسير من شكل', 'سهل', 'الكتاب ص 177 — الأمينات'),
('mcq', 3, 'قيم السالبية الكهربائية: O 3.44، وN 3.04، وC 2.55، وH 2.20. والرابطة الهيدروجينية تجاذب بين ذرة H تحمل شحنة جزئية موجبة كبيرة لارتباطها بذرة عالية السالبية الكهربائية، وذرة عالية السالبية الكهربائية في جزيء آخر. ما الشرط اللازم في تركيب الجزيء لكي تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض؟', null, null, '["وجود ذرة أكسجين في الجزيء أيًّا كانت الذرات المرتبطة بها","وجود عدد كبير من ذرات الهيدروجين المرتبطة بالكربون","أن تكون الكتلة المولية للمركب كبيرة","وجود ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين"]'::jsonb, 'فهم', 'مفهوم', 'سهل', 'الكتاب ص 174 و176 — الكحولات والإيثرات'),
('mcq', 4, 'أيّ المركبات الآتية لا تستطيع جزيئاته تكوين روابط هيدروجينية بعضها مع بعض، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر؟', null, null, '["CH₃OH","CH₃OCH₃","CH₃NH₂","CH₃CH₂OH"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 176 — الإيثرات'),
('mcq', 5, 'يبين الشكل الآتي جزيء إيثانول وجزيئي ماء (أ) و(ب)، والخطوط المتقطعة روابط هيدروجينية. أيّ العبارات الآتية تصف الشكل وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c5-l2b-o09-ethanol-water.svg","alt":"جزيء إيثانول CH₃–CH₂–O–H مرسوم أفقيًّا في الوسط، وجزيئا ماء. جزيء الماء (أ) فوق أكسجين الإيثانول، وإحدى ذرتي الهيدروجين فيه متجهة إلى أسفل، ويصل خط أزرق متقطع بين ذرة H هذه وذرة O في الإيثانول. جزيء الماء (ب) يمين الإيثانول، ويصل خط أزرق متقطع بين ذرة H في مجموعة OH للإيثانول وذرة O في جزيء الماء (ب)."}]'::jsonb, '["في (أ) يستقبل أكسجين الإيثانول ذرة H من الماء، وفي (ب) يمنح الإيثانول ذرة H من مجموعة OH لأكسجين الماء","في (أ) و(ب) يمنح الإيثانول ذرات H من مجموعة CH₂ لجزيئي الماء","في (أ) يمنح الإيثانول ذرة H للماء، وفي (ب) يستقبل الإيثانول ذرة H من الماء","الخطان المتقطعان رابطتان تساهميتان تربطان الإيثانول بالماء في جزيء واحد"]'::jsonb, 'فهم', 'تفسير من شكل', 'متوسط', 'الكتاب ص 174–175 — الكحولات'),
('mcq', 6, 'ما الذي يجعل ذرة الهيدروجين في مجموعة الهيدروكسيل قادرة على تكوين رابطة هيدروجينية مع جزيء مجاور؟', null, null, '["الهيدروجين أعلى سالبية كهربائية من الأكسجين، فيحمل شحنة جزئية سالبة","تنفصل H على هيئة أيون H⁺ فترتبط أيونيًّا بالجزيء المجاور","الأكسجين أعلى سالبية كهربائية، فتحمل H شحنة جزئية موجبة تنجذب إلى أكسجين جزيء مجاور","الرابطة O–H غير قطبية، فتتجاذب الجزيئات بقوى تشتت فقط"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 174 — الكحولات'),
('mcq', 7, 'صيغة ثلاثي ميثيل أمين (CH₃)₃N، وفيه ترتبط ذرة النيتروجين بثلاث مجموعات ميثيل. ماذا تتوقع بشأن قدرة جزيئاته على تكوين روابط هيدروجينية بعضها مع بعض، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر؟', null, null, '["تكوّنها؛ لأن كل أمين يحتوي على ذرة نيتروجين","لا تكوّنها؛ لعدم وجود ذرة H مرتبطة بذرة النيتروجين","تكوّنها بين ذرات H في مجموعات CH₃ وذرة N المجاورة","لا تكوّنها؛ لأن ذرة النيتروجين لا تجذب ذرات الهيدروجين أبدًا"]'::jsonb, 'تطبيق', 'توقع وتعليل', 'متوسط', 'الكتاب ص 176–177 — الإيثرات والأمينات'),
('essay', 1, 'وضّح كيف تكوّن جزيئات الميثيل أمين CH₃NH₂ روابط هيدروجينية بعضها مع بعض، وكيف تكوّنها مع جزيئات الماء، محددًا في كل حالة الذرة التي تحمل ذرة H الممنوحة والذرة المستقبلة لها. (علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر، والسالبية الكهربائية: O 3.44، وN 3.04، وH 2.20.)', null, null, null, 'فهم', 'توضيح', 'صعب', 'الكتاب ص 177 — الأمينات'),
('essay', 2, 'اشرح كيف تكوّن جزيئات الإيثانول روابط هيدروجينية مع جزيئات الماء ومع جزيئات إيثانول أخرى، مستعينًا بالتشابه بين جزيئي الماء والإيثانول في الزاوية بين رابطتي الأكسجين التساهميتين، وبقطبية مجموعة الهيدروكسيل.', null, null, null, 'فهم', 'شرح', 'سهل', 'الكتاب ص 174–175 — الكحولات (الشكل 5-7)'),
('essay', 3, 'للبروبيل أمين CH₃CH₂CH₂NH₂ ولثلاثي ميثيل أمين (CH₃)₃N الكتلة المولية نفسها 59.11 g/mol، ودرجة غليان الأول 48°C، أما الثاني فدرجة غليانه 3°C. فسّر هذا الفرق بالاعتماد على قدرة جزيئات كل منهما على تكوين روابط هيدروجينية بعضها مع بعض، علمًا بأن الرابطة الهيدروجينية تتكون بين ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين في جزيء، وذرة أكسجين أو نيتروجين في جزيء آخر.', null, null, null, 'تحليل', 'تفسير من بيانات', 'صعب', 'الكتاب ص 177 — الأمينات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L2-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'تتكون الرابطة الهيدروجينية بين ذرة H مرتبطة بذرة أكسجين (موجبة جزئيًّا) وذرة أكسجين في جزيء آخر (سالبة جزئيًّا)، وهذا ما يمثله الشكل (1).', '["ذرة H في هذا الشكل مرتبطة بالكربون، والرابطة C–H ضعيفة القطبية فلا تكوّن رابطة هيدروجينية.","لا توجد ذرة هيدروجين بين ذرتي الأكسجين، والرابطة الهيدروجينية تحتاج إلى H مرتبطة بأكسجين أو نيتروجين.","","ذرتا H في مجموعتي OH تحملان شحنتين جزئيتين موجبتين فتتنافران ولا تتجاذبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.673Z"}'::jsonb),
('mcq', 2, 0, 'ترتبط ذرة H بذرة النيتروجين ذات السالبية الكهربائية العالية فتصبح موجبة جزئيًّا، فتنجذب إلى ذرة N في جزيء مجاور مكوّنة رابطة هيدروجينية بين الجزيئين.', '["","الخط المتقطع يصل ذرة H بذرة N، ولا يمثل رابطة تساهمية داخل جزيء.","ذرة H المعنية مرتبطة بالنيتروجين لا بالكربون، والرابطة C–H لا تكوّن روابط هيدروجينية.","الميثيل أمين مركب جزيئي، والتجاذب بين جزيئيه ليس بين أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.673Z"}'::jsonb),
('mcq', 3, 3, 'الأكسجين (3.44) والنيتروجين (3.04) أعلى كثيرًا في السالبية الكهربائية من الهيدروجين (2.20)، فإذا ارتبطت ذرة H مباشرة بأحدهما حملت شحنة جزئية موجبة كبيرة وانجذبت إلى ذرة O أو N في جزيء آخر؛ أما الكربون (2.55) فقريب من الهيدروجين. لذا الشرط وجود ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين أو نيتروجين، ولهذا تكوّن جزيئات الكحولات والأمينات روابط هيدروجينية فيما بينها ولا تكوّنها جزيئات الإيثرات.', '["تحتوي الإيثرات على أكسجين، لكن جزيئاتها لا تكوّن روابط هيدروجينية فيما بينها لعدم وجود H مرتبطة بالأكسجين.","الفرق في السالبية الكهربائية بين C (2.55) وH (2.20) صغير، فالرابطة C–H ضعيفة القطبية ولا تكوّن ذرة H المرتبطة بالكربون روابط هيدروجينية.","الكتلة المولية لا تحدد القدرة على تكوين الروابط الهيدروجينية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.673Z"}'::jsonb),
('mcq', 4, 1, 'ذرة الأكسجين في ثنائي ميثيل إيثر CH₃OCH₃ مرتبطة بذرتي كربون، وجميع ذرات الهيدروجين مرتبطة بالكربون؛ فلا توجد H مرتبطة بأكسجين، ولذلك لا تكوّن جزيئاته روابط هيدروجينية فيما بينها.', '["في الميثانول ذرة H مرتبطة بالأكسجين، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض.","","في الميثيل أمين ذرتا H مرتبطتان بالنيتروجين، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض.","في الإيثانول مجموعة –OH، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.673Z"}'::jsonb),
('mcq', 5, 0, 'في (أ) تتجه ذرة H من جزيء الماء إلى ذرة O في الإيثانول، فالإيثانول مستقبل؛ وفي (ب) تتجه ذرة H في مجموعة OH للإيثانول إلى ذرة O في الماء، فالإيثانول مانح. لذا يكوّن الكحول روابط هيدروجينية مع الماء بالطريقتين.', '["","ذرات الهيدروجين المرتبطة بالكربون لا تكوّن روابط هيدروجينية، والرابطتان في الشكل تشملان أكسجين الإيثانول وهيدروجين مجموعة OH.","عكس الوصف: في (أ) ذرة H تعود إلى الماء وتتجه إلى أكسجين الإيثانول، وفي (ب) ذرة H تعود إلى الإيثانول.","الروابط الهيدروجينية تجاذب بين جزيئات منفصلة، لا روابط تساهمية تكوّن جزيئًا جديدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.674Z"}'::jsonb),
('mcq', 6, 2, 'لأن الأكسجين أعلى سالبية كهربائية من الهيدروجين تكون الرابطة O–H قطبية؛ فتحمل ذرة H شحنة جزئية موجبة تنجذب إلى ذرة أكسجين (سالبة جزئيًّا) في جزيء كحول آخر أو جزيء ماء، وهذه هي الرابطة الهيدروجينية.', '["الأكسجين هو الأعلى سالبية كهربائية، فيحمل الشحنة الجزئية السالبة ويحمل الهيدروجين الشحنة الموجبة.","الكحول لا يتأين بهذه الطريقة، والرابطة الهيدروجينية تجاذب بين جزيئات لا رابطة أيونية.","","الرابطة O–H قطبية، ومجموعة الهيدروكسيل متوسطة القطبية، وهذا أساس الرابطة الهيدروجينية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.674Z"}'::jsonb),
('mcq', 7, 1, 'لكي تكوّن جزيئات متماثلة روابط هيدروجينية فيما بينها يلزم وجود H مرتبطة بذرة N أو O في الجزيء نفسه. في (CH₃)₃N ترتبط ذرة N بثلاث ذرات كربون، فلا توجد H مرتبطة بها، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض (كما في الإيثرات).', '["وجود النيتروجين وحده لا يكفي؛ يلزم أن ترتبط به ذرة H ليكوّن الجزيء روابط هيدروجينية مع جزيئات مثله.","","ذرات H المرتبطة بالكربون لا تكوّن روابط هيدروجينية لضعف قطبية الرابطة C–H.","التعليل خاطئ: ذرة N تستطيع أن تستقبل ذرة H من جزيء آخر (كالماء)؛ والسبب الحقيقي غياب H المرتبطة بالنيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.674Z"}'::jsonb),
('essay', 1, null::int, null, null, 'بين جزيئات الميثيل أمين: ترتبط ذرتا H بالنيتروجين في المجموعة –NH₂، وتحمل كل منهما شحنة جزئية موجبة لأن النيتروجين أعلى سالبية كهربائية؛ فتنجذب ذرة H المرتبطة بـ N في جزيء إلى ذرة N في جزيء آخر (N–H···N). مع الماء: تتكون الرابطة بطريقتين: ذرة H من جزيء الماء تنجذب إلى ذرة N في الأمين (O–H···N)، وذرة H المرتبطة بالنيتروجين في الأمين تنجذب إلى ذرة O في الماء (N–H···O).', '["قطبية الرابطة N–H وشحنة H الجزئية الموجبة","بين جزيئات الأمين: H على N في جزيء ··· N في جزيء آخر","مع الماء: H الماء ··· N الأمين","مع الماء: H على N الأمين ··· O الماء"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية الرابطة N–H وشحنة H الجزئية الموجبة","marks":1},{"element":"بين جزيئات الأمين: H على N في جزيء ··· N في جزيء آخر","marks":1},{"element":"مع الماء: H الماء ··· N الأمين","marks":1},{"element":"مع الماء: H على N الأمين ··· O الماء","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: قطبية الرابطة N–H وشحنة H الجزئية الموجبة؛ بين جزيئات الأمين: H على N في جزيء ··· N في جزيء آخر؛ مع الماء: H الماء ··· N الأمين؛ مع الماء: H على N الأمين ··· O الماء"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل ذرات H المرتبطة بالكربون في CH₃ تكوّن الروابط الهيدروجينية","ذكر طريقة واحدة فقط للترابط مع الماء","وصف الرابطة الهيدروجينية بأنها رابطة تساهمية بين الجزيئين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.675Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قياس الزاوية بين رابطتي الأكسجين التساهميتين في جزيء الإيثانول يساوي تقريبًا قياسها في جزيء الماء، فمجموعة الهيدروكسيل في الكحول تشبه جزيء الماء في شكلها، وهي متوسطة القطبية: ذرة الأكسجين سالبة جزئيًّا وذرة الهيدروجين موجبة جزئيًّا. لذلك تنجذب ذرة H في مجموعة OH للإيثانول إلى ذرة O في جزيء ماء أو في جزيء إيثانول آخر، وتنجذب ذرة H في جزيء الماء (أو في OH لكحول آخر) إلى ذرة O في الإيثانول، فتتكون روابط هيدروجينية مع الماء ومع جزيئات الكحول الأخرى.', '["تشابه زاوية الأكسجين في الإيثانول والماء","قطبية مجموعة OH (O سالب جزئيًّا وH موجب جزئيًّا)","رابطة هيدروجينية مع الماء","رابطة هيدروجينية بين جزيئات الإيثانول نفسها"]'::jsonb, '[]'::jsonb, '[{"element":"تشابه زاوية الأكسجين في الإيثانول والماء","marks":1},{"element":"قطبية مجموعة OH (O سالب جزئيًّا وH موجب جزئيًّا)","marks":1},{"element":"رابطة هيدروجينية مع الماء","marks":1},{"element":"رابطة هيدروجينية بين جزيئات الإيثانول نفسها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: تشابه زاوية الأكسجين في الإيثانول والماء؛ قطبية مجموعة OH (O سالب جزئيًّا وH موجب جزئيًّا)؛ رابطة هيدروجينية مع الماء؛ رابطة هيدروجينية بين جزيئات الإيثانول نفسها"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن ذرات H في مجموعتي CH₃ وCH₂ تشارك في الروابط الهيدروجينية","إغفال الروابط بين جزيئات الإيثانول نفسها","عدّ مجموعة الهيدروكسيل غير قطبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.675Z"}'::jsonb),
('essay', 3, null::int, null, null, 'في البروبيل أمين ترتبط ذرتا هيدروجين بذرة النيتروجين (–NH₂)، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض (N–H···N)، ويحتاج التغلب عليها عند الغليان إلى طاقة أكبر، فدرجة غليانه أعلى. أما في ثلاثي ميثيل أمين فترتبط ذرة النيتروجين بثلاث مجموعات ميثيل ولا توجد ذرة H مرتبطة بها، فلا تكوّن جزيئاته روابط هيدروجينية فيما بينها، فتكون قوى التجاذب بينها أضعف ودرجة غليانه أقل. ولأن الكتلتين الموليتين متساويتان فالفرق لا يرجع إلى الكتلة.', '["البروبيل أمين فيه H مرتبطة بالنيتروجين","جزيئاته تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر للتغلب عليها","ثلاثي ميثيل أمين لا H على نيتروجينه فلا روابط هيدروجينية بين جزيئاته","الفرق لا يرجع إلى الكتلة المولية لتساويها"]'::jsonb, '[]'::jsonb, '[{"element":"البروبيل أمين فيه H مرتبطة بالنيتروجين","marks":1},{"element":"جزيئاته تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر للتغلب عليها","marks":1},{"element":"ثلاثي ميثيل أمين لا H على نيتروجينه فلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"الفرق لا يرجع إلى الكتلة المولية لتساويها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: البروبيل أمين فيه H مرتبطة بالنيتروجين؛ جزيئاته تكوّن روابط هيدروجينية تحتاج إلى طاقة أكبر للتغلب عليها؛ ثلاثي ميثيل أمين لا H على نيتروجينه فلا روابط هيدروجينية بين جزيئاته؛ الفرق لا يرجع إلى الكتلة المولية لتساويها"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بالتفرع أو بالكتلة المولية فقط","القول إن ثلاثي ميثيل أمين يكوّن روابط هيدروجينية عبر ذرات H في مجموعات CH₃","القول إن الغليان يكسر الروابط التساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.675Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
