from (values
('mcq', 1, 0, 'السلسلة خمس ذرات كربون (بنتان)، وتُرقّم من الطرف الأقرب إلى مجموعة OH (من اليمين) فتقع على ذرة الكربون 2، والاسم 2-بنتانول.', '["","رُقّمت السلسلة من الطرف الأبعد عن مجموعة OH؛ والترقيم يبدأ من الطرف الأقرب إليها.","السلسلة تحتوي على خمس ذرات كربون لا أربع.","مجموعة OH ليست مرتبطة بذرة الكربون الطرفية، بل بالثانية من اليمين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 2, 3, 'الحلقة من خمس ذرات كربون بروابط أحادية (بنتان حلقي)، وترتبط بها مجموعة OH فيضاف المقطع «ول»، ولا يلزم رقم لأن ذرات الحلقة متكافئة: بنتانول حلقي.', '["الحلقة خماسية (خمس ذرات كربون) لا سداسية.","المركب حلقي، و1-بنتانول سلسلة مفتوحة.","هذا اسم الهيدروكربون؛ ووجود مجموعة OH يتطلب إضافة المقطع «ول».",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 3, 1, 'السلسلة ذرتا كربون (إيثان)، وعلى كل منهما مجموعة OH، فيُكتب رقما الموقعين 1، 2 ويضاف «داي» للدلالة على مجموعتين: 1، 2-إيثاندايول.', '["مجموعتا OH مرتبطتان بذرتي كربون مختلفتين (1 و2)، لا بذرة الكربون نفسها.","","في الجزيء مجموعتا هيدروكسيل، فيلزم المقطع «داي» ورقما الموقعين.","عند وجود مجموعتي OH يضاف المقطع «داي» قبل «ول» ليدل على عددهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 4, 2, 'السلسلة ست ذرات كربون (هكسان)، ومجموعة OH على الذرة الرابعة من اليسار وهي الثالثة من اليمين؛ وتُرقّم السلسلة من الطرف الأقرب إلى مجموعة OH، فالاسم الصحيح 3-هكسانول، أما «4-هكسانول» فناتج عن الترقيم من الطرف الأبعد.', '["الترقيم لا يبدأ من اليسار دائمًا، بل من الطرف الأقرب إلى مجموعة الهيدروكسيل؛ و«4-هكسانول» ناتج عن الترقيم من الطرف الأبعد.","في الكحولات من ثلاث ذرات كربون فأكثر يلزم رقم الموقع لتعدد المواقع الممكنة لمجموعة OH.","","الاسم صحيح لكن التعليل خاطئ: الترقيم لا يبدأ من طرف ثابت، بل من الطرف الأقرب إلى مجموعة OH أيًّا كان موضعه في الرسم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 5, 3, 'أطول سلسلة تحتوي على ذرة الكربون المرتبطة بـ OH هي ثلاث ذرات (بروبانول)، وتُرقّم من جهة OH فتكون على الكربون 1، ويقع فرع الميثيل على الكربون 2: 2-ميثيل-1-بروبانول.', '["رُقّمت السلسلة من الطرف الأبعد عن مجموعة OH؛ والصحيح أن تأخذ OH الرقم 1.","السلسلة الرئيسة ثلاث ذرات كربون، ومجموعة CH₃ فرع؛ فالأصل بروبانول لا بيوتانول.","عُدّت ذرات الكربون الأربع سلسلة واحدة، مع أن إحداها فرع ميثيل على ذرة الكربون الثانية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 6, 0, 'السلسلة ثلاث ذرات كربون (بروبان)، ومجموعتا OH على ذرة الكربون الطرفية والوسطى؛ وبالترقيم من جهة الطرف الذي عليه OH تكونان على 1 و2، ويضاف «داي»: 1، 2-بروباندايول.', '["","رُقّمت السلسلة من الطرف الأبعد؛ والترقيم الصحيح يعطي مجموعتي OH أصغر رقمين (1، 2).","في الجزيء مجموعتا OH، فيلزم المقطع «داي» قبل «ول».","في الجزيء مجموعتا OH فقط، أما الكربون الثالث فمجموعة CH₃ بلا هيدروكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('mcq', 7, 2, 'في الهكسانول الحلقي جميع ذرات الكربون في الحلقة متكافئة، فأي ذرة ترتبط بها OH تعطي المركب نفسه؛ لذا لا يلزم ترقيم، أما الكحولات المفتوحة من ثلاث ذرات كربون فأكثر فتحتاج إلى رقم الموقع.', '["سلسلة من ثلاث ذرات كربون، ويمكن أن تقع OH على الكربون 1 أو 2، فيلزم الرقم: 1-بروبانول.","يلزم رقم الموقع للتمييز بين 1-بيوتانول و2-بيوتانول؛ فاسمه 2-بيوتانول.","","يلزم رقم الموقع لتمييزه من 2-بيوتانول؛ فاسمه 1-بيوتانول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) سلسلة من خمس ذرات كربون، ومجموعة OH على الكربون 3 من أي طرف: 3-بنتانول. (ب) السلسلة الرئيسة أربع ذرات كربون، وتُرقّم من جهة OH فتكون على الكربون 2، ومجموعة الميثيل على الكربون 3: 3-ميثيل-2-بيوتانول. (ج) سلسلة من ثلاث ذرات كربون وعلى طرفيها مجموعتا OH (الموقعان 1 و3): 1، 3-بروباندايول.', '["(أ) 3-بنتانول","(ب) 3-ميثيل-2-بيوتانول","(ج) 1، 3-بروباندايول"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) 3-بنتانول","marks":2},{"element":"(ب) 3-ميثيل-2-بيوتانول","marks":2},{"element":"(ج) 1، 3-بروباندايول","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) 3-بنتانول؛ (ب) 3-ميثيل-2-بيوتانول؛ (ج) 1، 3-بروباندايول"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (ب) «2-ميثيل-3-بيوتانول» بالترقيم من الطرف الأبعد عن OH","تسمية (ب) «2-بنتانول» بعدّ فرع الميثيل من السلسلة","إغفال المقطع «داي» في (ج)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.676Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تُرقّم السلسلة من الطرف الأقرب إلى مجموعة OH؛ فـ«3-بيوتانول» هو نفسه 2-بيوتانول مرقّمًا من الطرف الأبعد، و«4-بيوتانول» هو 1-بيوتانول مرقّمًا من الطرف الأبعد. (ب) جميع ذرات الكربون في الحلقة متكافئة، فأي موقع لمجموعة OH يعطي المركب نفسه، فلا حاجة إلى الترقيم. (ج) «ترايول» تعني وجود ثلاث مجموعات هيدروكسيل، والأرقام 1، 2، 3 تعني أن كل ذرة كربون من ذرات البروبان الثلاث ترتبط بمجموعة OH.', '["(أ) الترقيم من الطرف الأقرب إلى OH؛ الاسمان الصحيحان 2-بيوتانول و1-بيوتانول","(ب) تكافؤ ذرات الكربون في الحلقة","(ج) ثلاث مجموعات OH على ذرات الكربون 1 و2 و3"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الترقيم من الطرف الأقرب إلى OH؛ الاسمان الصحيحان 2-بيوتانول و1-بيوتانول","marks":2},{"element":"(ب) تكافؤ ذرات الكربون في الحلقة","marks":1},{"element":"(ج) ثلاث مجموعات OH على ذرات الكربون 1 و2 و3","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الترقيم من الطرف الأقرب إلى OH؛ الاسمان الصحيحان 2-بيوتانول و1-بيوتانول؛ (ب) تكافؤ ذرات الكربون في الحلقة؛ (ج) ثلاث مجموعات OH على ذرات الكربون 1 و2 و3"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن 4-بيوتانول خطأ لأن الرقم كبير دون ذكر قاعدة الطرف الأقرب","القول إن الحلقة لا تُرقم لأنها لا تحتوي على أطراف دون ذكر التكافؤ","تفسير «ترايول» بثلاث ذرات أكسجين في مجموعة واحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('essay', 3, null::int, null, null, '1) CH₃CH₂CH₂CH₂OH: 1-بيوتانول. 2) CH₃CH(OH)CH₂CH₃: 2-بيوتانول. 3) CH₃CH(CH₃)CH₂OH: 2-ميثيل-1-بروبانول. 4) (CH₃)₃COH أي CH₃C(OH)(CH₃)CH₃: 2-ميثيل-2-بروبانول. وكل منها يحتوي على 4 ذرات C و10 ذرات H وذرة O واحدة.', '["1-بيوتانول بصيغته","2-بيوتانول بصيغته","2-ميثيل-1-بروبانول بصيغته","2-ميثيل-2-بروبانول بصيغته"]'::jsonb, '[]'::jsonb, '[{"element":"1-بيوتانول بصيغته","marks":1},{"element":"2-بيوتانول بصيغته","marks":1},{"element":"2-ميثيل-1-بروبانول بصيغته","marks":1},{"element":"2-ميثيل-2-بروبانول بصيغته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: 1-بيوتانول بصيغته؛ 2-بيوتانول بصيغته؛ 2-ميثيل-1-بروبانول بصيغته؛ 2-ميثيل-2-بروبانول بصيغته"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة 3-بيوتانول بوصفه متشكلًا جديدًا وهو 2-بيوتانول نفسه","كتابة إيثر (مثل ثنائي إيثيل إيثر) ضمن الكحولات","تسمية الكحولات المتفرعة بعدّ الفرع من السلسلة الرئيسة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb)
