from (values
('mcq', 1, 3, 'ترتبط ذرة الأكسجين بمجموعة ميثيل (CH₃) ومجموعة بروبيل (CH₂CH₂CH₃)، ولأنهما مختلفتان تُرتبان أبجديًّا بالحروف الإنجليزية (m قبل p) ثم تضاف كلمة إيثر: ميثيل بروبيل إيثر.', '["تُرتب مجموعتا الألكيل أبجديًّا بحسب الحروف الإنجليزية: methyl قبل propyl.","المجموعة يمين الأكسجين ثلاث ذرات كربون (بروبيل) لا اثنتان.","المجموعتان مختلفتان: ميثيل وبروبيل، فلا يُستعمل «ثنائي».",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 2, 1, 'ترتبط ذرة الأكسجين بمجموعتين متماثلتين كل منهما ذرتا كربون (إيثيل)، فالاسم ثنائي إيثيل إيثر، وهو أول مركب استُعمل له المصطلح إيثر.', '["على جانبي الأكسجين ذرتا كربون في كل جهة، فالمجموعتان إيثيل وإيثيل، لا ميثيل.","","كل مجموعة تحتوي على ذرتي كربون (إيثيل) لا ذرة واحدة.","ذرة الأكسجين تفصل ذرات الكربون الأربع إلى مجموعتين، فلا تُعد سلسلة بيوتيل واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 3, 0, 'ترتبط ذرة الأكسجين بحلقة من ست ذرات كربون (هكسيل حلقي) وبمجموعة ميثيل، وتُرتبان أبجديًّا بالإنجليزية (cyclohexyl قبل methyl) كما في «بيوتيل حلقي ميثيل إيثر»: هكسيل حلقي ميثيل إيثر.', '["","الترتيب الأبجدي بالحروف الإنجليزية يضع cyclohexyl قبل methyl.","هذا اسم الإيثر الذي ترتبط ذرة أكسجينه بحلقتي هكسيل، أما هنا فإحدى المجموعتين ميثيل.","الحلقة سداسية (ست ذرات كربون) لا خماسية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 4, 2, 'إذا كانت مجموعتا الألكيل مختلفتين تُرتبان بحسب الحروف الإنجليزية، ثم يتبع الاسم بكلمة إيثر، مثل: إيثيل ميثيل إيثر (ethyl قبل methyl).', '["الترتيب أبجدي لا بحسب الحجم.","يُعتمد ترتيب الحروف الإنجليزية لأسماء المجموعات، لا الترتيب الهجائي العربي.","","المقطع «ثنائي» يُستعمل عندما تكون المجموعتان متماثلتين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 5, 0, 'يسار الأكسجين أربع ذرات كربون (بيوتيل) ويمينه خمس (بنتيل)، وتُرتبان أبجديًّا بالإنجليزية (b قبل p) ثم كلمة إيثر: بيوتيل بنتيل إيثر.', '["","الترتيب الأبجدي بالإنجليزية يضع butyl قبل pentyl.","المجموعتان مختلفتان: أربع ذرات كربون وخمس، فلا يُستعمل «ثنائي».","المجموعة اليمنى خمس ذرات كربون (بنتيل) لا ست."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 6, 3, 'في «ميثيل إيثيل إيثر» قُدّمت methyl على ethyl، وهذا يخالف الترتيب الأبجدي الإنجليزي؛ والاسم الصحيح إيثيل ميثيل إيثر.', '["اسم صحيح: ethyl قبل methyl أبجديًّا.","اسم صحيح: butyl قبل ethyl أبجديًّا.","اسم صحيح لإيثر مجموعتاه متماثلتان (ميثيل).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('mcq', 7, 1, 'ترتبط ذرة الأكسجين بحلقة من خمس ذرات كربون (بنتيل حلقي) وبمجموعة إيثيل (CH₂CH₃)، وتُرتبان أبجديًّا بالإنجليزية (cyclopentyl قبل ethyl) ثم كلمة إيثر: بنتيل حلقي إيثيل إيثر.', '["الترتيب الأبجدي بالإنجليزية يضع cyclopentyl قبل ethyl.","","الحلقة خماسية (خمس ذرات كربون) لا رباعية.","أُغفلت كلمة «حلقي»؛ فالمجموعة حلقة لا سلسلة مفتوحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.677Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) مجموعتا ميثيل متماثلتان: ثنائي ميثيل إيثر. (ب) مجموعة بروبيل (ثلاث ذرات كربون) ومجموعة إيثيل (ذرتان)، وتُرتبان أبجديًّا بالإنجليزية (ethyl قبل propyl): إيثيل بروبيل إيثر. (ج) مجموعة بيوتيل (أربع ذرات كربون) ومجموعة ميثيل: بيوتيل ميثيل إيثر.', '["(أ) ثنائي ميثيل إيثر","(ب) إيثيل بروبيل إيثر","(ج) بيوتيل ميثيل إيثر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) ثنائي ميثيل إيثر","marks":1},{"element":"(ب) إيثيل بروبيل إيثر","marks":2},{"element":"(ج) بيوتيل ميثيل إيثر","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) ثنائي ميثيل إيثر؛ (ب) إيثيل بروبيل إيثر؛ (ج) بيوتيل ميثيل إيثر"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة (ب) «بروبيل إيثيل إيثر» بترتيب الحجم لا الأبجدية","عدّ ذرات الكربون في (ج) سلسلة واحدة وتسميتها «بنتيل إيثر»","إغفال «ثنائي» في (أ)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₃CH₂–O–CH₂CH₃: ثنائي إيثيل إيثر؛ وCH₃–O–CH₂CH₂CH₃: ميثيل بروبيل إيثر. وكلاهما C₄H₁₀O مثل 1-بيوتانول. (ب) أي واحد مما يأتي: CH₃CH₂CH₂–O–CH₂CH₂CH₃ ثنائي بروبيل إيثر، أو CH₃CH₂CH₂CH₂–O–CH₂CH₃ بيوتيل إيثيل إيثر، أو CH₃(CH₂)₄–O–CH₃ ميثيل بنتيل إيثر؛ وكل منها C₆H₁₄O.', '["ثنائي إيثيل إيثر بصيغته","ميثيل بروبيل إيثر بصيغته","إيثر صحيح للصيغة C₆H₁₄O بصيغته","تسميته الصحيحة بالترتيب الأبجدي"]'::jsonb, '[]'::jsonb, '[{"element":"ثنائي إيثيل إيثر بصيغته","marks":1},{"element":"ميثيل بروبيل إيثر بصيغته","marks":1},{"element":"إيثر صحيح للصيغة C₆H₁₄O بصيغته","marks":1},{"element":"تسميته الصحيحة بالترتيب الأبجدي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: ثنائي إيثيل إيثر بصيغته؛ ميثيل بروبيل إيثر بصيغته؛ إيثر صحيح للصيغة C₆H₁₄O بصيغته؛ تسميته الصحيحة بالترتيب الأبجدي"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة كحول بدل الإيثر","إغفال أن مجموع ذرات الكربون في المجموعتين يجب أن يساوي عدد ذرات الكربون في الكحول","ترتيب المجموعتين بحسب الحجم في الاسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الخطأ في الترتيب؛ فالمجموعتان تُرتبان أبجديًّا بالإنجليزية (ethyl قبل methyl): إيثيل ميثيل إيثر. (ب) الخطأ أنه عدّ ذرات الكربون الست سلسلة واحدة، مع أن الأكسجين يفصلها إلى مجموعتي بروبيل متماثلتين: ثنائي بروبيل إيثر. (ج) الخطأ في الترتيب الأبجدي (butyl قبل ethyl): بيوتيل إيثيل إيثر.', '["(أ) الخطأ والاسم الصحيح: إيثيل ميثيل إيثر","(ب) الخطأ والاسم الصحيح: ثنائي بروبيل إيثر","(ج) الخطأ والاسم الصحيح: بيوتيل إيثيل إيثر"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الخطأ والاسم الصحيح: إيثيل ميثيل إيثر","marks":2},{"element":"(ب) الخطأ والاسم الصحيح: ثنائي بروبيل إيثر","marks":2},{"element":"(ج) الخطأ والاسم الصحيح: بيوتيل إيثيل إيثر","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الخطأ والاسم الصحيح: إيثيل ميثيل إيثر؛ (ب) الخطأ والاسم الصحيح: ثنائي بروبيل إيثر؛ (ج) الخطأ والاسم الصحيح: بيوتيل إيثيل إيثر"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على (ج) بالصحة لأن المجموعة الأصغر كُتبت أولًا","تصحيح (ب) إلى «بروبيل هكسيل إيثر»","الاكتفاء بالاسم الصحيح دون بيان الخطأ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
