('mcq', 2, 'ما اسم الأمين الآتي؟', null, '[{"src":"qimg/chem22/c5-l2b-o12-cyclopentylamine.svg","alt":"صيغة هيكلية: حلقة خماسية الأضلاع (خمس ذرات كربون)، وترتبط برأسها العلوي مجموعة NH₂."}]'::jsonb, '["هكسيل حلقي أمين","أنيلين","بنتيل حلقي أمين","بنتيل أمين"]'::jsonb, 'تطبيق', 'تسمية من شكل', 'سهل', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('mcq', 3, 'تقع مجموعتا أمين على طرفي السلسلة في المركب الآتي. ما اسمه النظامي؟', null, '[{"src":"qimg/chem22/c5-l2b-o12-butanediamine.svg","alt":"صيغة بنائية مكثفة مرسومة أفقيًّا: H₂N–CH₂–CH₂–CH₂–CH₂–NH₂؛ أربع مجموعات CH₂ بين مجموعتي NH₂ في الطرفين."}]'::jsonb, '["1، 4-بيوتان ثنائي أمين","1، 4-بيوتان أمين","1، 4-بنتان ثنائي أمين","1، 2-بيوتان ثنائي أمين"]'::jsonb, 'تطبيق', 'تسمية من شكل', 'متوسط', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('mcq', 4, 'ما اسم الأمين CH₃(CH₂)₃CH₂NH₂ وفق نظام IUPAC؟', null, null, '["1-أمينوبيوتان","5-أمينوبنتان","1-أمينوهكسان","1-أمينوبنتان"]'::jsonb, 'تطبيق', 'تسمية', 'متوسط', 'الكتاب ص 201 — تقويم الفصل (س28)'),
('mcq', 5, 'كيف يُشار إلى مجموعة الأمين –NH₂ في أسماء الأمينات وفق نظام IUPAC؟', null, null, '["بالمقطع «ول» في نهاية اسم الألكان، مع رقم موقعها","بكلمة «إيثر» بعد أسماء المجموعات المرتبطة بالنيتروجين","بالمقطع «أمينو» في بداية الاسم أو «أمين» في نهايته، مع رقم موقعها عند الحاجة","بالمقطع «أميد» في نهاية الاسم دائمًا، دون أي رقم"]'::jsonb, 'تذكر', 'قاعدة تسمية', 'سهل', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('mcq', 6, 'كيف يُسمى المركب متعدد مجموعات الأمين الآتي وفق نظام IUPAC؟', null, '[{"src":"qimg/chem22/c5-l2b-o12-triamine.svg","alt":"صيغة بنائية مكثفة: H₂N–CH₂–CH–CH₂–NH₂ مرسومة أفقيًّا، وترتبط بذرة الكربون الوسطى (CH) مجموعة NH₂ ثالثة مرسومة إلى أسفل."}]'::jsonb, '["1، 2، 3-بروبان أمين","1، 2، 3-بروبان ثلاثي أمين","1، 3-بروبان ثنائي أمين","1، 2، 3-بيوتان ثلاثي أمين"]'::jsonb, 'تطبيق', 'تسمية من شكل', 'متوسط', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('mcq', 7, 'أمين سلسلته الكربونية غير متفرعة ومكوّنة من 6 ذرات كربون، وترتبط مجموعة أمين واحدة بالذرة الثالثة من أحد طرفيها. ما اسمه وفق نظام IUPAC؟', null, null, '["3-أمينوهكسان","4-أمينوهكسان","3-أمينوبنتان","هكسيل أمين"]'::jsonb, 'تطبيق', 'تسمية', 'صعب', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('essay', 1, 'سمِّ الأمينات الآتية وفق نظام IUPAC، موضحًا عدد ذرات الكربون في السلسلة وموقع مجموعة الأمين: (أ) CH₃(CH₂)₅CH₂NH₂ (ب) CH₃(CH₂)₈CH₂NH₂ (ج) CH₃CH₂CH(NH₂)CH₂CH₃', null, null, null, 'تطبيق', 'تسمية', 'متوسط', 'الكتاب ص 201 — تقويم الفصل (س28)'),
('essay', 2, 'سمِّ الأمينات (أ) و(ب) و(ج) الآتية وفق نظام IUPAC، مبينًا كيف استعملت الأرقام والمقاطع الدالة على عدد مجموعات الأمين.', null, '[{"src":"qimg/chem22/c5-l2b-o12-essay.svg","alt":"ثلاث صيغ بنائية مكثفة: (أ) H₂N–CH₂–CH₂–NH₂. (ب) CH₃–CH–CH₂–CH₂–CH–CH₃ وترتبط مجموعة NH₂ إلى أسفل بكل من ذرة الكربون الثانية والخامسة من اليسار. (ج) CH₃–CH₂–NH₂."}]'::jsonb, null, 'تطبيق', 'تسمية من شكل', 'صعب', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)'),
('essay', 3, 'سمّى طالب المركبات الآتية كما يأتي: (أ) CH₃CH₂CH₂CH₂CH₂CH(NH₂)CH₃ «6-أمينوهبتان» (ب) H₂NCH₂CH₂CH₂CH₂CH₂NH₂ «1، 5-بنتان أمين» (ج) C₆H₅NH₂ (حلقة بنزين ترتبط بها مجموعة NH₂) «هكسيل حلقي أمين». بيّن الخطأ في كل اسم، واكتب الاسم الصحيح.', null, null, null, 'تقويم', 'تصحيح أسماء', 'صعب', 'الكتاب ص 177 — تسمية الأمينات (الجدول 5-6)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
