from (values
('mcq', 1, 1, 'السلسلة خمس ذرات كربون (بنتان)، وتُرقّم من الطرف الأقرب إلى مجموعة –NH₂ فتقع على الكربون 2، ويُشار إليها بالمقطع «أمينو» في بداية الاسم: 2-أمينوبنتان.', '["رُقّمت السلسلة من الطرف الأبعد عن مجموعة الأمين؛ والترقيم يبدأ من الطرف الأقرب إليها.","","السلسلة خمس ذرات كربون لا أربع.","مجموعة الأمين ليست على ذرة كربون طرفية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 2, 2, 'ترتبط مجموعة NH₂ بحلقة مشبعة من خمس ذرات كربون (بنتيل حلقي)، فيُسمى المركب بنتيل حلقي أمين، على نمط هكسيل حلقي أمين.', '["الحلقة خماسية (خمس ذرات كربون) لا سداسية.","الأنيلين حلقة بنزين أروماتية ترتبط بها مجموعة NH₂، أما هنا فحلقة مشبعة خماسية.","","أُغفلت كلمة «حلقي»؛ فالمجموعة حلقة لا سلسلة مفتوحة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 3, 0, 'السلسلة أربع ذرات كربون (بيوتان)، وعلى ذرتيها الطرفيتين مجموعتا أمين، فيُكتب الموقعان 1، 4 ويستعمل «ثنائي» قبل «أمين»: 1، 4-بيوتان ثنائي أمين، على نمط 1، 3-بروبان ثنائي أمين.', '["","في الجزيء مجموعتا أمين، فيلزم المقطع «ثنائي» قبل «أمين».","السلسلة أربع ذرات كربون فقط؛ فذرتا النيتروجين لا تُعدّان من السلسلة.","مجموعتا الأمين على ذرتي الكربون الطرفيتين 1 و4، لا على 1 و2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 4, 3, 'عدد ذرات الكربون: CH₃ (1) + (CH₂)₃ (3) + CH₂ (1) = 5 (بنتان)، ومجموعة –NH₂ على الكربون الطرفي، فترقيمها 1: 1-أمينوبنتان (ويُسمى أيضًا بنتيل أمين).', '["لم تُحسب مجموعة CH₂ المرتبطة بالنيتروجين؛ فالسلسلة CH₃ + 3 CH₂ + CH₂ = خمس ذرات كربون.","رُقّمت السلسلة من الطرف الأبعد عن مجموعة الأمين.","عُدّت ذرة النيتروجين ذرة كربون؛ والسلسلة خمس ذرات كربون فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 5, 2, 'يُشار إلى مجموعة الأمين بالمقطع «أمينو» في بداية الاسم (مثل 2-أمينوهكسان) أو «أمين» في نهايته (مثل إيثيل أمين)، ويُكتب رقم الموقع في بعض الحالات، ويستعمل «ثنائي» أو «ثلاثي»… عند تعدد المجموعات.', '["المقطع «ول» خاص بالكحولات التي تحتوي على مجموعة الهيدروكسيل.","كلمة «إيثر» تُستعمل لتسمية الإيثرات لا الأمينات.","","المقطع المستعمل للأمينات «أمين» أو «أمينو»، والرقم يُكتب عند الحاجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 6, 1, 'السلسلة ثلاث ذرات كربون (بروبان)، وعلى كل منها مجموعة أمين، فالمواقع 1، 2، 3 ويُستعمل «ثلاثي» للدلالة على عدد المجموعات: 1، 2، 3-بروبان ثلاثي أمين.', '["في الجزيء ثلاث مجموعات أمين، فيلزم المقطع «ثلاثي».","","أُغفلت مجموعة الأمين المرتبطة بذرة الكربون الوسطى.","السلسلة ثلاث ذرات كربون (بروبان) لا أربع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-11-14T13:39:20.678Z"}'::jsonb),
('mcq', 7, 0, 'السلسلة ست ذرات كربون (هكسان)، وبالترقيم من الطرف الأقرب تقع مجموعة الأمين على الكربون 3 (ولو رُقّمت من الطرف الآخر لكانت 4)، فيؤخذ الرقم الأصغر: 3-أمينوهكسان.', '["","الذرة الثالثة من طرف هي الرابعة من الطرف الآخر؛ ويُختار الترقيم الأصغر 3.","السلسلة ست ذرات كربون (هكسان) لا خمس.","هذا الاسم يدل على مجموعة أمين على ذرة كربون طرفية، لا على الذرة الثالثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.679Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) ذرات الكربون: 1 + 5 + 1 = 7 (هبتان)، ومجموعة الأمين على الكربون الطرفي: 1-أمينوهبتان (هبتيل أمين). (ب) 1 + 8 + 1 = 10 (ديكان)، والأمين على الكربون الطرفي: 1-أمينوديكان (ديسيل أمين). (ج) خمس ذرات كربون (بنتان)، والأمين على الكربون 3 من أي طرف: 3-أمينوبنتان.', '["(أ) 1-أمينوهبتان","(ب) 1-أمينوديكان","(ج) 3-أمينوبنتان","عدّ ذرات الكربون في الصيغ المختصرة عدًّا صحيحًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) 1-أمينوهبتان","marks":1},{"element":"(ب) 1-أمينوديكان","marks":1},{"element":"(ج) 3-أمينوبنتان","marks":1},{"element":"عدّ ذرات الكربون في الصيغ المختصرة عدًّا صحيحًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) 1-أمينوهبتان؛ (ب) 1-أمينوديكان؛ (ج) 3-أمينوبنتان؛ عدّ ذرات الكربون في الصيغ المختصرة عدًّا صحيحًا"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال CH₂ المرتبطة بالنيتروجين عند العد فيُسمى (أ) أمينوهكسان","تسمية (ج) «3-أمينوبيوتان» بعدّ خاطئ","عدّ ذرة النيتروجين ضمن السلسلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.679Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) سلسلة من ذرتي كربون وعلى كل منهما مجموعة أمين: 1، 2-إيثان ثنائي أمين (أو 1، 2-ثنائي أمينو إيثان). (ب) سلسلة من ست ذرات كربون، ومجموعتا أمين على الكربونين 2 و5 (والترقيم من الطرفين يعطي النتيجة نفسها): 2، 5-هكسان ثنائي أمين (أو 2، 5-ثنائي أمينو هكسان). (ج) مجموعة إيثيل مرتبطة بمجموعة أمين: إيثيل أمين (أو أمينو إيثان). ويُستعمل «ثنائي» للدلالة على مجموعتي أمين، والأرقام لتحديد مواقعها.', '["(أ) 1، 2-إيثان ثنائي أمين","(ب) 2، 5-هكسان ثنائي أمين","(ج) إيثيل أمين","توضيح دور الأرقام و«ثنائي»"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) 1، 2-إيثان ثنائي أمين","marks":2},{"element":"(ب) 2، 5-هكسان ثنائي أمين","marks":2},{"element":"(ج) إيثيل أمين","marks":1},{"element":"توضيح دور الأرقام و«ثنائي»","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) 1، 2-إيثان ثنائي أمين؛ (ب) 2، 5-هكسان ثنائي أمين؛ (ج) إيثيل أمين؛ توضيح دور الأرقام و«ثنائي»"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال «ثنائي» عند وجود مجموعتي أمين","كتابة (ب) «2، 5-بيوتان ثنائي أمين» بعدّ خاطئ للسلسلة","كتابة أرقام المواقع دون فاصلة بينها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-14T13:39:20.679Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) السلسلة سبع ذرات كربون، وقد رُقّمت من الطرف الأبعد عن مجموعة الأمين، والصحيح الترقيم من الطرف الأقرب فتقع على الكربون 2: 2-أمينوهبتان. (ب) في الجزيء مجموعتا أمين على الكربونين 1 و5 من سلسلة خماسية، فيجب استعمال «ثنائي»: 1، 5-بنتان ثنائي أمين. (ج) «هكسيل حلقي» حلقة مشبعة من ست ذرات كربون، أما هذه فحلقة بنزين أروماتية، والأمين المرتبط بحلقة بنزين هو الأنيلين.', '["(أ) الخطأ والاسم الصحيح: 2-أمينوهبتان","(ب) الخطأ والاسم الصحيح: 1، 5-بنتان ثنائي أمين","(ج) الخطأ والاسم الصحيح: أنيلين"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الخطأ والاسم الصحيح: 2-أمينوهبتان","marks":2},{"element":"(ب) الخطأ والاسم الصحيح: 1، 5-بنتان ثنائي أمين","marks":2},{"element":"(ج) الخطأ والاسم الصحيح: أنيلين","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الخطأ والاسم الصحيح: 2-أمينوهبتان؛ (ب) الخطأ والاسم الصحيح: 1، 5-بنتان ثنائي أمين؛ (ج) الخطأ والاسم الصحيح: أنيلين"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على (أ) بالصحة لأن الرقم يحدد موقعًا موجودًا","الخلط بين حلقة البنزين والحلقة المشبعة","تصحيح (ب) بتغيير الأرقام بدل إضافة «ثنائي»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.679Z"}'::jsonb)
