('mcq', 1, 'يبين المخطط الآتي درجات غليان ثلاثة أزواج من المركبات؛ في كل زوج كحول وإيثر لهما الصيغة الجزيئية نفسها. أيّ استنتاج يدعمه المخطط؟', null, '[{"src":"qimg/chem22/c5-l2b-o13-bp-chart.svg","alt":"مخطط أعمدة لدرجات الغليان (°C) على المحور الرأسي من −40 إلى 120، لثلاثة أزواج على المحور الأفقي؛ في كل زوج عمود أزرق للكحول ذي السلسلة غير المتفرعة وعمود أحمر للإيثر الذي له الصيغة الجزيئية نفسها. الزوج C₂H₆O: الإيثانول 78، وثنائي ميثيل إيثر −25. الزوج C₃H₈O: 1-بروبانول 97، وإيثيل ميثيل إيثر 7. الزوج C₄H₁₀O: 1-بيوتانول 118، وثنائي إيثيل إيثر 35."}]'::jsonb, '["درجة غليان الكحول في كل زوج أعلى بكثير؛ لأن جزيئاته تكوّن روابط هيدروجينية بعضها مع بعض","الفرق في كل زوج ناتج عن اختلاف الكتلة المولية بين الكحول والإيثر","درجة غليان الإيثر أعلى؛ لأن ذرة أكسجينه ترتبط بذرتي كربون","يزول الفرق بين الكحول والإيثر تمامًا عند الصيغة C₄H₁₀O"]'::jsonb, 'تحليل', 'تحليل رسم بياني', 'متوسط', 'الكتاب ص 176 — الإيثرات'),
('mcq', 2, 'درجة غليان ثنائي بروبيل إيثر (102.17 g/mol) هي 90°C، ودرجة غليان 1-بيوتانول (74.12 g/mol) هي 118°C. ماذا تستنتج من هذه المقارنة؟', null, null, '["درجة الغليان في المركبات العضوية تعتمد على الكتلة المولية وحدها، فالأثقل أعلى درجة غليان","جزيئات الإيثر تكوّن روابط هيدروجينية بعضها مع بعض أقوى من التي تكوّنها جزيئات الكحول","الكحولات أكثر تطايرًا من الإيثرات المماثلة لها في الحجم لأن جزيئاتها أخف كتلة","أثر الروابط الهيدروجينية بين جزيئات الكحول في رفع درجة الغليان يفوق أثر الكتلة المولية الأكبر للإيثر"]'::jsonb, 'تحليل', 'استنتاج من بيانات', 'صعب', 'الكتاب ص 176 — الإيثرات'),
('mcq', 3, 'يبين الجدول الآتي الكتلة المولية ودرجة الغليان لثلاثة مركبات. أيّ تفسير يتفق مع هذه البيانات؟', '{"headers":["المركب","الصيغة","الكتلة المولية (g/mol)","درجة الغليان (°C)"],"rows":[["الميثانول","CH₃OH","32.04","65"],["ثنائي ميثيل إيثر","CH₃OCH₃","46.07","−25"],["ثنائي إيثيل إيثر","CH₃CH₂OCH₂CH₃","74.12","35"]]}'::jsonb, null, '["درجة الغليان تزداد بزيادة الكتلة المولية في جميع المركبات دون استثناء، فالترتيب يتبع الكتلة","جزيئات الإيثرات تكوّن روابط هيدروجينية بعضها مع بعض تزداد قوتها كلما زادت كتلتها المولية","الروابط الهيدروجينية بين جزيئات الميثانول تجعل درجة غليانه أعلى من درجتي غليان الإيثرين رغم كتلته المولية الأصغر","درجة غليان الميثانول أعلى لأن جزيئاته غير قطبية، فتتجاذب بقوى أكبر من جزيئات الإيثرين"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 176 — الإيثرات'),
('mcq', 4, 'مركب صيغته الجزيئية C₃H₈O، ودرجة غليانه 7°C، وذائبيته في الماء أقل من ذائبية الكحولين اللذين لهما الصيغة الجزيئية نفسها. ما صيغته البنائية المكثفة الأرجح؟', null, null, '["CH₃CH₂CH₂OH","CH₃OCH₂CH₃","CH₃CH(OH)CH₃","CH₃CH₂CH₂NH₂"]'::jsonb, 'تحليل', 'استنتاج تركيب', 'سهل', 'الكتاب ص 176 — الإيثرات'),
('mcq', 5, 'يمثل الشكل الآتي متشكلين صيغتهما الجزيئية C₃H₈O. أيّ العبارات الآتية تقارن بينهما مقارنة صحيحة؟', null, '[{"src":"qimg/chem22/c5-l2b-o13-c3h8o.svg","alt":"صيغتان بنائيتان كاملتان لمتشكلين صيغتهما C₃H₈O. (1) سلسلة H–C–C–C–O–H: ثلاث ذرات كربون كل منها مرتبطة بذرتي هيدروجين فوقها وتحتها، وذرة H في الطرف الأيسر، ثم ذرة أكسجين مرتبطة بذرة H في الطرف الأيمن. (2) H–C–O–C–C–H: ذرة كربون (مع ثلاث ذرات H) مرتبطة بذرة أكسجين، والأكسجين مرتبط بسلسلة من ذرتي كربون تنتهي بذرة H، ولا توجد ذرة H مرتبطة بالأكسجين."}]'::jsonb, '["المركب (1) أعلى درجة غليان، والمركب (2) أكثر ذوبانية في الماء","المركب (2) أعلى درجة غليان وأكثر ذوبانية في الماء من المركب (1)","يتساويان في درجة الغليان والذوبانية لتساوي كتلتيهما الموليتين","المركب (1) أعلى درجة غليان وأكثر ذوبانية في الماء من المركب (2)"]'::jsonb, 'تحليل', 'مقارنة من شكل', 'سهل', 'الكتاب ص 176 و202 — الإيثرات (س37)'),
('mcq', 6, 'يكوّن كل من الكحول والإيثر روابط هيدروجينية مع جزيئات الماء. ما الفرق بينهما في ذلك الذي يفسر كون الكحولات أكثر ذوبانية في الماء؟', null, null, '["الكحول يمنح ذرة H من مجموعة OH ويستقبل H على أكسجينه، أما الإيثر فيستقبل H من الماء فقط","الإيثر يمنح ذرات H من مجموعات الألكيل للماء، أما الكحول فلا يمنح","الكحول يتأين في الماء إلى أيونات OH⁻، أما الإيثر فلا يتأين","الإيثر يكوّن روابط هيدروجينية أكثر لأن أكسجينه مرتبط بذرتي كربون"]'::jsonb, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 176 و202 — الإيثرات (س37)'),
('mcq', 7, 'قال طالب: «الإيثرات لا تذوب في الماء مطلقًا؛ لأنها لا تكوّن روابط هيدروجينية بين جزيئاتها». ما التقييم الصحيح لهذه العبارة؟', null, null, '["صحيحة؛ لأن جزيئات الإيثرات غير قطبية تمامًا فلا تتجاذب مع جزيئات الماء القطبية","غير دقيقة؛ لأن جزيئات الإيثرات تكوّن روابط هيدروجينية قوية بعضها مع بعض ومع الماء","غير دقيقة؛ فالإيثرات قليلة الذوبان لأن أكسجينها يستقبل H من الماء، وإن لم تكوّن هذه الروابط فيما بينها","صحيحة؛ لأن الذوبان في الماء يحتاج دائمًا إلى وجود أيونات موجبة وسالبة في المذاب"]'::jsonb, 'تقويم', 'تقويم ادعاء', 'صعب', 'الكتاب ص 176 — الإيثرات'),
('essay', 1, 'يبين الجدول الآتي درجات غليان ثلاثة أزواج من المتشكلات (كحول وإيثر لهما الصيغة الجزيئية نفسها). (أ) صف النمط الذي تظهره البيانات في كل زوج. (ب) فسّر هذا النمط بالاعتماد على الروابط الهيدروجينية. (ج) توقّع أيّ المركبين أعلى درجة غليان: 1-بنتانول أم بيوتيل ميثيل إيثر (C₅H₁₂O لكليهما)، مع التعليل.', '{"headers":["الصيغة الجزيئية","الكحول","درجة غليانه (°C)","الإيثر","درجة غليانه (°C)"],"rows":[["C₂H₆O","الإيثانول","78","ثنائي ميثيل إيثر","−25"],["C₃H₈O","1-بروبانول","97","إيثيل ميثيل إيثر","7"],["C₄H₁₀O","1-بيوتانول","118","ثنائي إيثيل إيثر","35"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 176 — الإيثرات'),
('essay', 2, 'قارن بين 1-بيوتانول CH₃CH₂CH₂CH₂OH وثنائي إيثيل إيثر CH₃CH₂OCH₂CH₃ (كلاهما 74.12 g/mol) من حيث: (أ) قدرة جزيئات كل منهما على تكوين روابط هيدروجينية بعضها مع بعض ومع الماء (ب) درجة الغليان (ج) الذائبية في الماء، مع التعليل.', null, null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 176 و202 — الإيثرات (س37)'),
('essay', 3, 'قارن بين الكحولات والإيثرات في جدول من حيث: المجموعة الوظيفية، ووجود ذرة H مرتبطة بالأكسجين، وقدرة جزيئاتها على تكوين روابط هيدروجينية فيما بينها، ودرجة الغليان مقارنة بالأخرى المماثلة لها في الكتلة، والذائبية في الماء.', null, null, null, 'تحليل', 'مقارنة', 'سهل', 'الكتاب ص 176 — الإيثرات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L2-O13') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'في كل زوج الكتلة المولية واحدة، ومع ذلك درجة غليان الكحول أعلى بنحو 80–100°C؛ لأن جزيئات الكحول تكوّن روابط هيدروجينية بعضها مع بعض، أما الإيثر فلا ذرة H مرتبطة بأكسجينه فلا تكوّن جزيئاته هذه الروابط.', '["","المركبان في كل زوج لهما الصيغة الجزيئية نفسها، فكتلتاهما الموليتان متساويتان.","المخطط يبين العكس: درجة غليان الإيثر في كل زوج أقل.","الفرق عند C₄H₁₀O ما يزال كبيرًا (118°C مقابل 35°C)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.679Z"}'::jsonb),
('mcq', 2, 3, 'رغم أن الكتلة المولية لثنائي بروبيل إيثر أكبر، فإن درجة غليان 1-بيوتانول أعلى بـ 28°C؛ لأن الروابط الهيدروجينية بين جزيئات الكحول تحتاج إلى طاقة إضافية للتغلب عليها، ولا تتكون بين جزيئات الإيثر. إذن أثر الروابط الهيدروجينية في رفع درجة الغليان يفوق أثر الكتلة المولية الأكبر للإيثر.', '["لو كان ذلك صحيحًا لكان الإيثر الأكبر كتلة أعلى درجة غليان، والبيانات تبين العكس.","جزيئات الإيثر لا تكوّن روابط هيدروجينية فيما بينها لعدم وجود H مرتبطة بالأكسجين.","درجة غليان الكحول أعلى، فهو أقل تطايرًا لا أكثر، وخفة كتلته لم تجعله يغلي عند درجة أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('mcq', 3, 2, 'الميثانول (32.04 g/mol) يغلي عند 65°C، وهي أعلى من درجتي غليان الإيثرين: ثنائي ميثيل إيثر (−25°C) وثنائي إيثيل إيثر (35°C)، رغم كتلته المولية الأصغر؛ لأن الروابط الهيدروجينية بين جزيئات الميثانول تحتاج إلى طاقة إضافية للتغلب عليها، أما جزيئات الإيثرات فلا تكوّنها فيما بينها.', '["الميثانول أصغر المركبات كتلة لكنه الأعلى درجة غليان، فالقاعدة لا تنطبق هنا.","جزيئات الإيثرات لا تكوّن روابط هيدروجينية فيما بينها أصلًا.","","الميثانول قطبي بسبب مجموعة الهيدروكسيل، وقطبيته وروابطه الهيدروجينية هي سبب ارتفاع درجة غليانه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('mcq', 4, 1, 'انخفاض درجة الغليان وقلة الذائبية مقارنة بالكحولين المتشكلين تدلان على مركب لا تكوّن جزيئاته روابط هيدروجينية فيما بينها، أي إيثر: CH₃OCH₂CH₃ (إيثيل ميثيل إيثر).', '["هذا 1-بروبانول، وهو كحول تكوّن جزيئاته روابط هيدروجينية، فدرجة غليانه مرتفعة (97°C) لا 7°C.","","هذا 2-بروبانول، وهو كحول تكوّن جزيئاته روابط هيدروجينية، فلا تكون درجة غليانه منخفضة إلى 7°C.","صيغته الجزيئية C₃H₉N لا C₃H₈O، فهو أمين لا يطابق المعطيات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('mcq', 5, 3, 'المركب (1) كحول (1-بروبانول) فيه H مرتبطة بالأكسجين، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض ومع الماء؛ والمركب (2) إيثر (إيثيل ميثيل إيثر) لا تكوّن جزيئاته هذه الروابط فيما بينها؛ لذا (1) أعلى درجة غليان وأكثر ذوبانية.', '["المركب (1) كحول يمنح H ويستقبلها مع الماء، فهو الأكثر ذوبانية أيضًا.","المركب (2) إيثر لا تكوّن جزيئاته روابط هيدروجينية فيما بينها، فدرجة غليانه وذوبانيته أقل.","تساوي الكتلة المولية لا يعني تساوي الخواص؛ فالفرق في الروابط الهيدروجينية يغيرها كثيرًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('mcq', 6, 0, 'ذرة الأكسجين في الإيثر تعمل مستقبلًا لذرات H من الماء فقط، فيذوب بشكل قليل؛ أما الكحول فيستقبل H على أكسجينه ويمنح H مجموعة الهيدروكسيل لأكسجين الماء، فيكوّن روابط هيدروجينية أكثر مع الماء ويذوب أكثر.', '["","ذرات H المرتبطة بالكربون لا تكوّن روابط هيدروجينية؛ والكحول هو الذي يمنح H من مجموعة OH.","ذوبان الكحول ناتج عن الروابط الهيدروجينية لا عن تأينه إلى أيونات هيدروكسيد.","ارتباط الأكسجين بذرتي كربون يحرم الإيثر من ذرة H يمنحها، فروابطه مع الماء أقل لا أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('mcq', 7, 2, 'صحيح أن جزيئات الإيثر لا تكوّن روابط هيدروجينية فيما بينها، لكن ذرة الأكسجين فيها تستطيع أن تستقبل ذرات H من جزيئات الماء، فتذوب الإيثرات بشكل قليل؛ لذا عبارة «لا تذوب مطلقًا» غير دقيقة.', '["الإيثرات أقل قطبية من الكحولات لكنها ليست غير قطبية تمامًا، وهي تذوب قليلًا في الماء.","جزيئات الإيثرات لا تكوّن روابط هيدروجينية فيما بينها، فهذا التعليل خاطئ.","","كثير من المركبات الجزيئية تذوب في الماء، مثل الكحولات، دون أن تكون أيونية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) في كل زوج درجة غليان الكحول أعلى كثيرًا من درجة غليان الإيثر (بفرق 103°C و90°C و83°C) مع أن الكتلة المولية واحدة. (ب) في الكحول ذرة H مرتبطة بالأكسجين، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض تحتاج إلى طاقة إضافية عند الغليان؛ أما في الإيثر فالأكسجين مرتبط بذرتي كربون ولا H مرتبطة به، فلا تكوّن جزيئاته هذه الروابط. (ج) 1-بنتانول أعلى درجة غليان؛ لأنه كحول تكوّن جزيئاته روابط هيدروجينية، وبيوتيل ميثيل إيثر لا تكوّنها، والكتلة المولية متساوية (88.15 g/mol).', '["(أ) الكحول أعلى درجة غليان في كل زوج رغم تساوي الكتلة","(ب) H مرتبطة بالأكسجين في الكحول فتتكون روابط هيدروجينية","(ب) لا H على أكسجين الإيثر فلا روابط هيدروجينية بين جزيئاته","(ج) 1-بنتانول أعلى مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الكحول أعلى درجة غليان في كل زوج رغم تساوي الكتلة","marks":1},{"element":"(ب) H مرتبطة بالأكسجين في الكحول فتتكون روابط هيدروجينية","marks":1},{"element":"(ب) لا H على أكسجين الإيثر فلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"(ج) 1-بنتانول أعلى مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الكحول أعلى درجة غليان في كل زوج رغم تساوي الكتلة؛ (ب) H مرتبطة بالأكسجين في الكحول فتتكون روابط هيدروجينية؛ (ب) لا H على أكسجين الإيثر فلا روابط هيدروجينية بين جزيئاته؛ (ج) 1-بنتانول أعلى مع التعليل"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بالكتلة المولية مع أنها متساوية في كل زوج","القول إن الغليان يكسر الروابط التساهمية في الجزيء","توقع أن الإيثر أعلى لأن سلسلته أطول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.680Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 1-بيوتانول: فيه H مرتبطة بالأكسجين، فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض، ومع الماء يمنح H ويستقبلها. ثنائي إيثيل إيثر: لا H مرتبطة بالأكسجين، فلا تكوّن جزيئاته روابط هيدروجينية فيما بينها، لكن أكسجينه يستقبل H من الماء. (ب) درجة غليان 1-بيوتانول أعلى؛ لأن التغلب على الروابط الهيدروجينية بين جزيئاته يحتاج إلى طاقة أكبر، والإيثر أكثر تطايرًا. (ج) 1-بيوتانول أكثر ذوبانية في الماء؛ لأنه يكوّن مع الماء روابط هيدروجينية أكثر (مانحًا ومستقبلًا)، والإيثر مستقبل فقط فذوبانه قليل.', '["(أ) الكحول: روابط بين جزيئاته ومع الماء (مانح ومستقبل)","(أ) الإيثر: لا روابط بين جزيئاته، ومستقبل فقط مع الماء","(ب) الكحول أعلى درجة غليان مع التعليل","(ج) الكحول أكثر ذوبانية مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الكحول: روابط بين جزيئاته ومع الماء (مانح ومستقبل)","marks":1},{"element":"(أ) الإيثر: لا روابط بين جزيئاته، ومستقبل فقط مع الماء","marks":1},{"element":"(ب) الكحول أعلى درجة غليان مع التعليل","marks":1},{"element":"(ج) الكحول أكثر ذوبانية مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الكحول: روابط بين جزيئاته ومع الماء (مانح ومستقبل)؛ (أ) الإيثر: لا روابط بين جزيئاته، ومستقبل فقط مع الماء؛ (ب) الكحول أعلى درجة غليان مع التعليل؛ (ج) الكحول أكثر ذوبانية مع التعليل"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الإيثر لا يكوّن أي رابطة هيدروجينية حتى مع الماء","ربط الفرق بالكتلة المولية مع أنها متساوية","القول إن الإيثر أكثر ذوبانية لأنه أكثر تطايرًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.681Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الكحولات: المجموعة الوظيفية –OH؛ توجد H مرتبطة بالأكسجين؛ تكوّن جزيئاتها روابط هيدروجينية فيما بينها؛ درجة غليانها أعلى؛ ذائبيتها في الماء أكبر. الإيثرات: المجموعة الوظيفية –O– (أكسجين بين ذرتي كربون)؛ لا توجد H مرتبطة بالأكسجين؛ لا تكوّن جزيئاتها روابط هيدروجينية فيما بينها؛ درجة غليانها أقل (شديدة التطاير)؛ ذائبيتها في الماء قليلة.', '["المجموعة الوظيفية لكل منهما","وجود H على الأكسجين وأثره في الروابط الهيدروجينية","درجة الغليان: الكحول أعلى","الذائبية: الكحول أكبر والإيثر قليل الذوبان"]'::jsonb, '[]'::jsonb, '[{"element":"المجموعة الوظيفية لكل منهما","marks":1},{"element":"وجود H على الأكسجين وأثره في الروابط الهيدروجينية","marks":1},{"element":"درجة الغليان: الكحول أعلى","marks":1},{"element":"الذائبية: الكحول أكبر والإيثر قليل الذوبان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: المجموعة الوظيفية لكل منهما؛ وجود H على الأكسجين وأثره في الروابط الهيدروجينية؛ درجة الغليان: الكحول أعلى؛ الذائبية: الكحول أكبر والإيثر قليل الذوبان"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس المقارنة في درجة الغليان","القول إن الإيثرات لا تذوب في الماء مطلقًا","إغفال سبب الاختلاف (وجود H على الأكسجين)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.681Z"}'::jsonb)
