insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L2-O14'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يبين الجدول الآتي ذائبية بعض الكحولات غير المتفرعة في الماء. ما العلاقة بين عدد ذرات الكربون في الكحول وذائبيته في الماء كما تبينها البيانات؟', '{"headers":["الكحول","الصيغة","الذائبية (mol/100 g H₂O)"],"rows":[["الميثانول","CH₃OH","غير محدودة"],["الإيثانول","C₂H₅OH","غير محدودة"],["1-بروبانول","C₃H₇OH","غير محدودة"],["1-بيوتانول","C₄H₉OH","0.11"],["1-بنتانول","C₅H₁₁OH","0.030"],["1-هبتانول","C₇H₁₅OH","0.0008"]]}'::jsonb, null, '["تزداد الذائبية بزيادة عدد ذرات الكربون","لا تتأثر الذائبية بعدد ذرات الكربون","تقل الذائبية بزيادة عدد ذرات الكربون","تزداد الذائبية حتى البروبانول ثم تبقى ثابتة"]'::jsonb, 'تحليل', 'تحليل جدول', 'سهل', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 2, 'يبين الشكل الآتي ثلاثة كحولات؛ ظُلل الجزء الهيدروكربوني في كل منها بالرمادي ومجموعة OH بالأحمر. ما التفسير الأنسب لتناقص ذائبيتها في الماء من (1) إلى (3)؟', null, '[{"src":"qimg/chem22/c5-l2b-o14-chain.svg","alt":"ثلاث صيغ بنائية مكثفة مرقمة لكحولات غير متفرعة، وفي كل منها ظُلل الجزء الهيدروكربوني بمستطيل رمادي متقطع ومجموعة OH بمستطيل أحمر: (1) CH₃–OH (جزء هيدروكربوني من ذرة كربون واحدة). (2) CH₃–CH₂–CH₂–CH₂–OH (جزء هيدروكربوني من أربع ذرات كربون). (3) CH₃–CH₂–CH₂–CH₂–CH₂–CH₂–CH₂–OH (جزء هيدروكربوني من سبع ذرات كربون). في كل جزيء مجموعة OH واحدة فقط."}]'::jsonb, '["يزداد عدد مجموعات OH فتضعف الروابط الهيدروجينية مع الماء","يكبر الجزء الهيدروكربوني غير القطبي بينما تبقى مجموعة OH واحدة، فيقل أثرها في الجزيء كله","تفقد مجموعة OH قدرتها على تكوين روابط هيدروجينية في الكحولات الكبيرة","يصبح الجزء الهيدروكربوني أكثر قطبية فيتنافر مع جزيئات الماء"]'::jsonb, 'تحليل', 'تفسير من شكل', 'متوسط', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 3, 'اعتمادًا على بيانات الجدول الآتي، ما التوقع الأنسب لذائبية 1-أوكتانول C₈H₁₇OH في الماء؟', '{"headers":["الكحول","الصيغة","الذائبية (mol/100 g H₂O)"],"rows":[["الميثانول","CH₃OH","غير محدودة"],["الإيثانول","C₂H₅OH","غير محدودة"],["1-بروبانول","C₃H₇OH","غير محدودة"],["1-بيوتانول","C₄H₉OH","0.11"],["1-بنتانول","C₅H₁₁OH","0.030"],["1-هبتانول","C₇H₁₅OH","0.0008"]]}'::jsonb, null, '["بين 0.030 و0.11 mol/100 g H₂O","أكبر من 0.11 mol/100 g H₂O","غير محدودة مثل الميثانول","أقل من 0.0008 mol/100 g H₂O"]'::jsonb, 'تحليل', 'توقع', 'صعب', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 4, 'ذائبية 1-بيوتانول في الماء 0.11 mol/100 g H₂O، وذائبية 1-بنتانول 0.030 mol/100 g H₂O. كم مرة تقريبًا تفوق ذائبية 1-بيوتانول ذائبية 1-بنتانول؟', null, null, '["3.7 مرة","0.27 مرة","37 مرة","140 مرة"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 5, 'ذائبية 1-بيوتانول C₄H₉OH في الماء 0.11 mol/100 g H₂O، وكتلته المولية 74.12 g/mol. ما أكبر كتلة منه تذوب في 100 g من الماء؟', null, null, '["0.11 g","8.2 g","670 g","0.0015 g"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 6, 'ما نوع الرابطة التي تتكون بين مجموعة –OH في الكحول وجزيئات الماء عند ذوبانه؟', null, null, '["رابطة أيونية","رابطة تساهمية جديدة","رابطة فلزية","رابطة هيدروجينية"]'::jsonb, 'فهم', 'مفهوم', 'سهل', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('mcq', 7, 'أُضيف 5 g من 1-بروبانول إلى 100 g من الماء في كأس، وأُضيف 5 g من 1-هبتانول (116.20 g/mol، وذائبيته 0.0008 mol/100 g H₂O) إلى 100 g من الماء في كأس أخرى، ثم رُجّت الكأسان. ماذا تتوقع؟', null, null, '["محلول متجانس مع 1-بروبانول، وطبقتان منفصلتان مع 1-هبتانول","طبقتان منفصلتان مع 1-بروبانول، ومحلول متجانس مع 1-هبتانول","محلول متجانس في الكأسين؛ لأن كليهما يحتوي على مجموعة OH","طبقتان منفصلتان في الكأسين؛ لأن الكحولات لا تذوب في الماء"]'::jsonb, 'تحليل', 'توقع وتعليل', 'صعب', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('essay', 1, 'ادرس الجدول الآتي، ثم أجب: (أ) ما نوع الرابطة المتكونة بين مجموعة –OH في الكحول والماء؟ (ب) ما العلاقة بين ذائبية الكحول في الماء وحجم جزيئه؟ (ج) قدّم تفسيرًا لهذه العلاقة.', '{"headers":["الكحول","الصيغة","الذائبية (mol/100 g H₂O)"],"rows":[["الميثانول","CH₃OH","غير محدودة"],["الإيثانول","C₂H₅OH","غير محدودة"],["1-بروبانول","C₃H₇OH","غير محدودة"],["1-بيوتانول","C₄H₉OH","0.11"],["1-بنتانول","C₅H₁₁OH","0.030"],["1-هبتانول","C₇H₁₅OH","0.0008"]]}'::jsonb, null, null, 'تحليل', 'تحليل جدول', 'سهل', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('essay', 2, 'ذائبية 1-بنتانول C₅H₁₁OH (88.15 g/mol) في الماء 0.030 mol/100 g H₂O، وذائبية 1-هبتانول C₇H₁₅OH (116.20 g/mol) هي 0.0008 mol/100 g H₂O. احسب أكبر كتلة من كل منهما تذوب في 250 g من الماء، ثم وضّح ما تدل عليه النتيجتان بشأن أثر طول السلسلة الكربونية.', null, null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 205 — الجدول 5-15 (س70)'),
('essay', 3, '(أ) رتّب الكحولات الآتية تنازليًّا حسب ذائبيتها في الماء: 1-هبتانول، الميثانول، 1-بنتانول، 1-بيوتانول. (ب) توقّع موقع 1-أوكتانول C₈H₁₇OH في هذا الترتيب، مع التعليل. (ج) فسّر لماذا تمتزج الكحولات الصغيرة (الميثانول والإيثانول والبروبانول) مع الماء امتزاجًا تامًّا.', null, null, null, 'تحليل', 'ترتيب وتوقع', 'متوسط', 'الكتاب ص 205 — الجدول 5-15 (س70)')
