from (values
('mcq', 1, 2, 'الكحولات الصغيرة (ميثانول، إيثانول، بروبانول) ذائبيتها غير محدودة، ثم تتناقص: 1-بيوتانول 0.11، و1-بنتانول 0.030، و1-هبتانول 0.0008 mol/100 g H₂O؛ أي تقل الذائبية بزيادة طول السلسلة الكربونية.', '["البيانات تبين العكس: من 0.11 للبيوتانول إلى 0.0008 للهبتانول.","الذائبية تتغير من غير محدودة إلى 0.0008 mol/100 g H₂O، فهي تتأثر كثيرًا.","","بعد البروبانول تتناقص الذائبية بوضوح ولا تبقى ثابتة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.681Z"}'::jsonb),
('mcq', 2, 1, 'تكوّن مجموعة OH روابط هيدروجينية مع الماء، لكن الجزء الهيدروكربوني غير قطبي ولا يتجاذب مع الماء جيدًا؛ وبزيادة طول السلسلة يكبر هذا الجزء بينما تبقى مجموعة OH واحدة، فتقل الذائبية.', '["في كل جزيء مجموعة OH واحدة فقط، فعددها لا يتغير.","","مجموعة OH تبقى قادرة على تكوين روابط هيدروجينية، لكن الجزء غير القطبي الكبير يقلل الذوبان.","الجزء الهيدروكربوني غير قطبي، وطوله لا يجعله قطبيًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.681Z"}'::jsonb),
('mcq', 3, 3, 'الأوكتانول (8 ذرات كربون) أطول سلسلة من الهبتانول (7 ذرات)، وبما أن الذائبية تتناقص بزيادة طول السلسلة فيُتوقع أن تكون ذائبيته أقل من 0.0008 mol/100 g H₂O.', '["هذه ذائبية كحولات أقصر سلسلة (البيوتانول والبنتانول)، والأوكتانول أطول منها.","زيادة طول السلسلة تقلل الذائبية، فلا تكون أكبر من ذائبية البيوتانول.","الذائبية غير المحدودة للكحولات الصغيرة فقط، والأوكتانول ذو سلسلة طويلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.681Z"}'::jsonb),
('mcq', 4, 0, 'النسبة = 0.11 ÷ 0.030 ≈ 3.7؛ أي إن زيادة ذرة كربون واحدة في السلسلة خفضت الذائبية إلى نحو ربعها تقريبًا.', '["","قُسمت ذائبية البنتانول على ذائبية البيوتانول (قسمة معكوسة).","خطأ في موضع الفاصلة العشرية عند القسمة: 0.11 ÷ 0.030 = 3.7 لا 37.","استُعملت ذائبية 1-هبتانول (0.0008) بدل ذائبية 1-بنتانول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('mcq', 5, 1, 'الكتلة = عدد المولات × الكتلة المولية = 0.11 mol × 74.12 g/mol ≈ 8.2 g في كل 100 g من الماء.', '["عُدّ عدد المولات كتلة بالغرامات دون الضرب في الكتلة المولية.","","قُسمت الكتلة المولية على عدد المولات بدل الضرب: 74.12 ÷ 0.11.","قُسم عدد المولات على الكتلة المولية بدل الضرب: 0.11 ÷ 74.12."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('mcq', 6, 3, 'مجموعة الهيدروكسيل قطبية، فتكوّن مع جزيئات الماء روابط هيدروجينية؛ وهذا سبب ذوبان الكحولات، وخاصة الصغيرة منها، في الماء.', '["الكحول والماء مركبان جزيئيان، ولا تتكون بينهما روابط بين أيونات.","الذوبان لا يكوّن روابط تساهمية جديدة بين الكحول والماء؛ فالتجاذب بين جزيئات منفصلة.","الرابطة الفلزية بين ذرات الفلزات، ولا علاقة لها بالكحول والماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('mcq', 7, 0, '1-بروبانول ذائبيته غير محدودة فيذوب كله ويتكون محلول متجانس. أما 1-هبتانول فأقصى ما يذوب منه 0.0008 mol × 116.20 g/mol ≈ 0.09 g في 100 g ماء، وهذا أقل بكثير من 5 g، فيبقى معظمه طبقة منفصلة.', '["","التوقع معكوس: 1-بروبانول ذائبيته غير محدودة، و1-هبتانول قليل الذوبان جدًّا.","وجود OH لا يكفي؛ فالسلسلة الطويلة في 1-هبتانول تجعل ما يذوب منه نحو 0.09 g فقط في 100 g ماء.","الكحولات الصغيرة مثل 1-بروبانول تمتزج مع الماء امتزاجًا تامًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) رابطة هيدروجينية. (ب) كلما زاد حجم جزيء الكحول (طول السلسلة الكربونية) قلت ذائبيته في الماء: الكحولات من ذرة إلى ثلاث ذرات كربون ذائبيتها غير محدودة، ثم 0.11 للبيوتانول، و0.030 للبنتانول، و0.0008 mol/100 g H₂O للهبتانول. (ج) مجموعة OH تكوّن روابط هيدروجينية مع الماء، أما الجزء الهيدروكربوني فغير قطبي؛ وبزيادة طول السلسلة يكبر الجزء غير القطبي وتبقى مجموعة OH واحدة، فيقل أثرها وتقل الذائبية.', '["(أ) رابطة هيدروجينية","(ب) تقل الذائبية بزيادة حجم الجزيء، مع الاستشهاد بالبيانات","(ج) OH قطبية تتجاذب مع الماء، والجزء الهيدروكربوني غير قطبي","(ج) كبر الجزء غير القطبي مع بقاء OH واحدة يقلل الذائبية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) رابطة هيدروجينية","marks":1},{"element":"(ب) تقل الذائبية بزيادة حجم الجزيء، مع الاستشهاد بالبيانات","marks":1},{"element":"(ج) OH قطبية تتجاذب مع الماء، والجزء الهيدروكربوني غير قطبي","marks":1},{"element":"(ج) كبر الجزء غير القطبي مع بقاء OH واحدة يقلل الذائبية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) رابطة هيدروجينية؛ (ب) تقل الذائبية بزيادة حجم الجزيء، مع الاستشهاد بالبيانات؛ (ج) OH قطبية تتجاذب مع الماء، والجزء الهيدروكربوني غير قطبي؛ (ج) كبر الجزء غير القطبي مع بقاء OH واحدة يقلل الذائبية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذائبية تزداد بزيادة الكتلة المولية","تفسير التناقص بنقص عدد مجموعات OH","وصف الرابطة بين OH والماء بأنها أيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('essay', 2, null::int, null, null, '1-بنتانول: عدد المولات في 250 g ماء = 0.030 × (250 ÷ 100) = 0.075 mol، والكتلة = 0.075 × 88.15 ≈ 6.6 g. 1-هبتانول: عدد المولات = 0.0008 × 2.5 = 0.002 mol، والكتلة = 0.002 × 116.20 ≈ 0.23 g. يذوب من 1-بنتانول كتلة أكبر بنحو 28 مرة؛ فزيادة ذرتي كربون في السلسلة خفضت الذائبية كثيرًا، لأن الجزء الهيدروكربوني غير القطبي كبر مع بقاء مجموعة OH واحدة.', '["مولات 1-بنتانول = 0.075 mol","كتلة 1-بنتانول ≈ 6.6 g","مولات 1-هبتانول = 0.002 mol","كتلة 1-هبتانول ≈ 0.23 g","الاستنتاج: السلسلة الأطول أقل ذائبية مع التفسير"]'::jsonb, '["عامل التحويل = 250 g ÷ 100 g = 2.5","مولات 1-بنتانول = 0.030 mol × 2.5 = 0.075 mol","كتلة 1-بنتانول = 0.075 mol × 88.15 g/mol ≈ 6.6 g","مولات 1-هبتانول = 0.0008 mol × 2.5 = 0.002 mol","كتلة 1-هبتانول = 0.002 mol × 116.20 g/mol ≈ 0.23 g","المقارنة: 6.6 g ÷ 0.23 g ≈ 28"]'::jsonb, '[{"element":"مولات 1-بنتانول = 0.075 mol","marks":1},{"element":"كتلة 1-بنتانول ≈ 6.6 g","marks":1},{"element":"مولات 1-هبتانول = 0.002 mol","marks":1},{"element":"كتلة 1-هبتانول ≈ 0.23 g","marks":1},{"element":"الاستنتاج: السلسلة الأطول أقل ذائبية مع التفسير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: مولات 1-بنتانول = 0.075 mol؛ كتلة 1-بنتانول ≈ 6.6 g؛ مولات 1-هبتانول = 0.002 mol؛ كتلة 1-هبتانول ≈ 0.23 g؛ الاستنتاج: السلسلة الأطول أقل ذائبية مع التفسير"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال التحويل من 100 g إلى 250 g من الماء","قسمة عدد المولات على الكتلة المولية بدل الضرب","الاستنتاج أن الكحول الأكبر كتلة أكثر ذوبانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.682Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الميثانول (غير محدودة) > 1-بيوتانول (0.11) > 1-بنتانول (0.030) > 1-هبتانول (0.0008 mol/100 g H₂O). (ب) يأتي 1-أوكتانول في آخر الترتيب بعد 1-هبتانول؛ لأن سلسلته أطول (8 ذرات كربون) فجزؤه غير القطبي أكبر وذائبيته أقل. (ج) في الكحولات الصغيرة يكون الجزء الهيدروكربوني صغيرًا، فيغلب أثر مجموعة OH القطبية التي تكوّن روابط هيدروجينية مع الماء، فتمتزج معه في جميع النسب.', '["(أ) الترتيب الصحيح","(ب) 1-أوكتانول في آخر الترتيب","(ب) التعليل بطول السلسلة","(ج) صغر الجزء غير القطبي وغلبة الروابط الهيدروجينية لمجموعة OH"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الترتيب الصحيح","marks":1},{"element":"(ب) 1-أوكتانول في آخر الترتيب","marks":1},{"element":"(ب) التعليل بطول السلسلة","marks":1},{"element":"(ج) صغر الجزء غير القطبي وغلبة الروابط الهيدروجينية لمجموعة OH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الترتيب الصحيح؛ (ب) 1-أوكتانول في آخر الترتيب؛ (ب) التعليل بطول السلسلة؛ (ج) صغر الجزء غير القطبي وغلبة الروابط الهيدروجينية لمجموعة OH"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترتيب الكحولات تصاعديًّا بدل تنازليًّا","وضع 1-أوكتانول قبل 1-هبتانول لأن كتلته أكبر","تفسير الامتزاج التام بأن الكحولات الصغيرة أيونية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb)
