('mcq', 3, 'يبين الشكل الآتي أربع صيغ عامة مرقمة لمركبات تحتوي على مجموعة الكربونيل. أيّ هذه الصيغ تمثل الصيغة العامة للكيتونات؟', null, '[{"src":"qimg/chem22/c5-l3a-gen4.svg","alt":"أربع صيغ عامة مرقمة، في كل منها ذرة كربون C ترتبط من أعلى بذرة أكسجين O برابطة ثنائية: (1) R–C(=O)–R′: ذرة الكربون ترتبط من اليسار بمجموعة R ومن اليمين بمجموعة R′. (2) R–C(=O)–H: ذرة الكربون ترتبط من اليسار بمجموعة R ومن اليمين بذرة هيدروجين H. (3) R–C(=O)–OH: ذرة الكربون ترتبط من اليسار بمجموعة R ومن اليمين بمجموعة OH. (4) R–C(=O)–O–R′: ذرة الكربون ترتبط من اليسار بمجموعة R ومن اليمين بذرة أكسجين O ترتبط بدورها بمجموعة R′."}]'::jsonb, '["الصيغة (1)","الصيغة (2)","الصيغة (3)","الصيغة (4)"]'::jsonb, 'تذكر', 'تعرف صيغة عامة من شكل', 'متوسط', 'الكتاب ص 179 — الكيتونات (الجدول 5-8)'),
('mcq', 4, 'أيّ الصيغ العامة الآتية تمثل مركبًا ترتبط فيه ذرة كربون الكربونيل بمجموعة هيدروكسيل؟', null, null, '["RCHO","R–COO–R′","RCOOH","R–CO–R′"]'::jsonb, 'فهم', 'ربط تركيب بصيغة عامة', 'متوسط', 'الكتاب ص 180 — الأحماض الكربوكسيلية (الجدول 5-9)'),
('mcq', 5, 'يبين الشكل الآتي الصيغة العامة للألدهيدات. ماذا يمكن أن تمثل R فيها؟', null, '[{"src":"qimg/chem22/c5-l3a-gen-aldehyde.svg","alt":"صيغة عامة: ذرة كربون C في الوسط ترتبط من اليسار بمجموعة R برابطة أحادية، ومن اليمين بذرة هيدروجين H برابطة أحادية، ومن أعلى بذرة أكسجين O برابطة ثنائية."}]'::jsonb, '["مجموعة ألكيل فقط، ولا يمكن أن تكون ذرة هيدروجين","مجموعة ألكيل أو ذرة هيدروجين","مجموعة هيدروكسيل أو ذرة هالوجين","ذرة أكسجين ترتبط بمجموعة ألكيل"]'::jsonb, 'تذكر', 'تذكر مكونات صيغة عامة', 'متوسط', 'الكتاب ص 178 — الصيغة العامة للألدهيدات'),
('mcq', 6, 'إذا كانت الصيغة العامة للألكانات CₙH₂ₙ₊₂، فأيّ مما يأتي يمثل الصيغة الجزيئية العامة للألدهيدات المشبعة مفتوحة السلسلة؟', null, null, '["CₙH₂ₙO","CₙH₂ₙ₊₂O","CₙH₂ₙO₂","CₙH₂ₙ₋₂O"]'::jsonb, 'فهم', 'اشتقاق صيغة عامة', 'صعب', 'الكتاب ص 183 — التقويم 5-3 (س15)'),
('mcq', 7, 'أيّ مما يأتي يمثل الصيغة العامة للأميدات؟', null, null, '["R–NH₂","R–CO–NH–R","R–COO–R′","R–CO–R′"]'::jsonb, 'تذكر', 'تذكر تركيب', 'متوسط', 'الكتاب ص 182 — الأميدات (الجدول 5-11)'),
('essay', 1, 'اكتب الصيغة العامة لكل نوع من أنواع المركبات العضوية الآتية، وحدد مجموعة الكربونيل في كل منها: (أ) ألدهيد (ب) كيتون (ج) حمض كربوكسيلي (د) إستر (هـ) أميد.', null, null, null, 'تذكر', 'كتابة صيغ عامة', 'سهل', 'الكتاب ص 169، 202 — الجدول 5-1 (س41)'),
('essay', 2, 'الصيغة العامة للألكانات CₙH₂ₙ₊₂. اشتق منها الصيغة الجزيئية العامة لكل من الألدهيدات والكيتونات والأحماض الكربوكسيلية المشبعة مفتوحة السلسلة، ووضح كل اشتقاق بمثال.', null, null, null, 'فهم', 'اشتقاق صيغ عامة', 'صعب', 'الكتاب ص 183 — التقويم 5-3 (س15)'),
('essay', 3, 'قارن بين الصيغتين العامتين للألدهيدات والكيتونات من حيث: (أ) موقع مجموعة الكربونيل في السلسلة (ب) الذرات المرتبطة بذرة كربون الكربونيل. ثم اكتب مثالًا لكل منهما بصيغته البنائية المكثفة واسمه.', null, null, null, 'فهم', 'مقارنة صيغ عامة', 'متوسط', 'الكتاب ص 178–179 — الألدهيدات والكيتونات')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
