insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يسمى الترتيب الذي ترتبط فيه ذرة الأكسجين برابطة ثنائية مع ذرة كربون مجموعة الكربونيل C=O، وهي المجموعة الوظيفية في الألدهيدات والكيتونات.', '["هذه مجموعة الهيدروكسيل المميزة للكحولات، والرابطة فيها أحادية بين الأكسجين والهيدروجين، ولا توجد فيها رابطة ثنائية مع الكربون.","","هذا الترتيب يميز الإيثرات؛ فذرة الأكسجين فيه مرتبطة بروابط أحادية فقط.","هذه مجموعة الأمين، ولا تحتوي على ذرة أكسجين أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 2, 3, 'مركبات الكربونيل تحتوي على ذرة أكسجين ترتبط برابطة ثنائية مع ذرة كربون (C=O)، والصيغة R–CO–R′ (أي R–C(=O)–R′) فيها مجموعة كربونيل، فهي الصيغة العامة للكيتونات.', '["ROH الصيغة العامة للكحولات؛ ذرة الأكسجين فيها مرتبطة بذرة هيدروجين برابطة أحادية، ولا توجد مجموعة C=O.","R–O–R′ الصيغة العامة للإيثرات؛ ذرة الأكسجين فيها مرتبطة بذرتي كربون برابطتين أحاديتين، ولا توجد مجموعة C=O.","R–NH₂ الصيغة العامة للأمينات، ولا تحتوي على ذرة أكسجين أصلًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 3, 0, 'في الكيتونات ترتبط ذرة كربون الكربونيل بذرتي كربون في السلسلة، فتكون الصيغة العامة R–CO–R′، وهي الصيغة (1).', '["","الصيغة (2) ترتبط فيها ذرة كربون الكربونيل بذرة هيدروجين، فهي الصيغة العامة للألدهيدات RCHO.","الصيغة (3) ترتبط فيها ذرة كربون الكربونيل بمجموعة OH، فهي الصيغة العامة للأحماض الكربوكسيلية RCOOH.","الصيغة (4) ترتبط فيها ذرة كربون الكربونيل بذرة أكسجين متصلة بمجموعة R′، فهي الصيغة العامة للإسترات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 4, 2, 'مجموعة الكربوكسيل هي مجموعة كربونيل مرتبطة بمجموعة هيدروكسيل، وتكتب ‎–COOH؛ لذا فالصيغة العامة للأحماض الكربوكسيلية RCOOH.', '["ترتبط ذرة كربون الكربونيل هنا بذرة هيدروجين لا بمجموعة هيدروكسيل؛ فهذه صيغة الألدهيدات.","حلّت هنا مجموعة ألكيل R′ محل ذرة هيدروجين الهيدروكسيل؛ فهذه صيغة الإسترات.","","ترتبط ذرة كربون الكربونيل هنا بذرتي كربون؛ فهذه صيغة الكيتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 5, 1, 'في الصيغة العامة للألدهيدات RCHO تمثل R مجموعة ألكيل أو ذرة هيدروجين؛ ففي الإيثانال CH₃CHO هي مجموعة الميثيل، وفي الميثانال HCHO هي ذرة هيدروجين.', '["في الميثانال HCHO تكون R ذرة هيدروجين؛ فيمكن أن تكون R مجموعة ألكيل أو ذرة هيدروجين.","","لو كانت R مجموعة هيدروكسيل لكان المركب حمضًا كربوكسيليًّا لا ألدهيدًا، وR لا تمثل ذرة هالوجين.","ارتباط ذرة كربون الكربونيل بذرة أكسجين متصلة بمجموعة ألكيل يميز الإسترات لا الألدهيدات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 6, 0, 'تحل ذرة أكسجين برابطة ثنائية محل ذرتي هيدروجين على ذرة الكربون الطرفية: CₙH₂ₙ₊₂ − 2H + O = CₙH₂ₙO؛ فالإيثانال مثلًا C₂H₄O (n = 2).', '["","هذه صيغة الكحولات المشبعة؛ إذ تحل فيها مجموعة OH محل ذرة H فلا يتغير عدد ذرات الهيدروجين، أما في الألدهيد فتحل ذرة O برابطة ثنائية محل ذرتي H.","هذه صيغة الأحماض الكربوكسيلية المشبعة؛ ففيها ذرتا أكسجين.","نقص هنا أربع ذرات هيدروجين، بينما تكوين مجموعة الكربونيل يحذف ذرتي هيدروجين فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('mcq', 7, 1, 'الأميدات مركبات عضوية تنتج عن إحلال ذرة نيتروجين (مرتبطة بذرات أخرى) محل مجموعة الهيدروكسيل ‎–OH في الحمض الكربوكسيلي؛ فترتبط ذرة كربون الكربونيل بذرة نيتروجين، وصيغتها العامة R–CO–NH–R.', '["R–NH₂ الصيغة العامة للأمينات؛ ذرة النيتروجين فيها مرتبطة بذرة كربون لا ترتبط بأكسجين برابطة ثنائية، فلا توجد مجموعة كربونيل.","","R–COO–R′ الصيغة العامة للإسترات؛ ترتبط فيها ذرة كربون الكربونيل بذرة أكسجين متصلة بمجموعة ألكيل، لا بذرة نيتروجين.","R–CO–R′ الصيغة العامة للكيتونات؛ ترتبط فيها ذرة كربون الكربونيل بذرتي كربون، ولا يوجد نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تحتوي الصيغ الخمس جميعها على مجموعة الكربونيل C=O: (أ) الألدهيد: RCHO أي R–C(=O)–H. (ب) الكيتون: R–CO–R′ أي R–C(=O)–R′. (ج) الحمض الكربوكسيلي: RCOOH أي R–C(=O)–OH. (د) الإستر: R–COO–R′ أي R–C(=O)–O–R′. (هـ) الأميد: R–CO–NH–R أي R–C(=O)–NH–R.', '["الألدهيد RCHO مع تحديد C=O","الكيتون R–CO–R′ مع تحديد C=O","الحمض الكربوكسيلي RCOOH مع تحديد C=O","الإستر R–COO–R′ مع تحديد C=O","الأميد R–CO–NH–R مع تحديد C=O"]'::jsonb, '[]'::jsonb, '[{"element":"الألدهيد RCHO مع تحديد C=O","marks":1},{"element":"الكيتون R–CO–R′ مع تحديد C=O","marks":1},{"element":"الحمض الكربوكسيلي RCOOH مع تحديد C=O","marks":1},{"element":"الإستر R–COO–R′ مع تحديد C=O","marks":1},{"element":"الأميد R–CO–NH–R مع تحديد C=O","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الألدهيد RCHO مع تحديد C=O؛ الكيتون R–CO–R′ مع تحديد C=O؛ الحمض الكربوكسيلي RCOOH مع تحديد C=O؛ الإستر R–COO–R′ مع تحديد C=O؛ الأميد R–CO–NH–R مع تحديد C=O"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة صيغة الكحول ROH بدل صيغة الألدهيد RCHO","الخلط بين صيغة الإستر R–COO–R′ وصيغة الإيثر R–O–R′","تحديد ذرة الأكسجين المرتبطة برابطة أحادية في الحمض أو الإستر على أنها مجموعة الكربونيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.683Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الألدهيد: تحل ذرة أكسجين برابطة ثنائية محل ذرتي هيدروجين على ذرة كربون طرفية: CₙH₂ₙ₊₂ − 2H + O = CₙH₂ₙO، مثل الإيثانال C₂H₄O. الكيتون: تحل ذرة أكسجين برابطة ثنائية محل ذرتي هيدروجين على ذرة كربون في وسط السلسلة، فتكون الصيغة أيضًا CₙH₂ₙO (n ≥ 3)، مثل 2-بروبانون C₃H₆O. الحمض الكربوكسيلي: على ذرة الكربون الطرفية تحل ذرة أكسجين برابطة ثنائية محل ذرتي هيدروجين، وتحل مجموعة OH محل الذرة الثالثة: CₙH₂ₙ₊₂ − 3H + O + OH = CₙH₂ₙO₂، مثل حمض الإيثانويك C₂H₄O₂.', '["صيغة الألدهيدات CₙH₂ₙO مع الاشتقاق ومثال","صيغة الكيتونات CₙH₂ₙO مع الاشتقاق ومثال","صيغة الأحماض الكربوكسيلية CₙH₂ₙO₂ مع الاشتقاق ومثال"]'::jsonb, '["الألدهيد: CₙH₂ₙ₊₂ − 2H + O → CₙH₂ₙO (الإيثانال C₂H₄O)","الكيتون: CₙH₂ₙ₊₂ − 2H + O → CₙH₂ₙO (2-بروبانون C₃H₆O)","الحمض: CₙH₂ₙ₊₂ − 3H + O + OH → CₙH₂ₙO₂ (حمض الإيثانويك C₂H₄O₂)"]'::jsonb, '[{"element":"صيغة الألدهيدات CₙH₂ₙO مع الاشتقاق ومثال","marks":2},{"element":"صيغة الكيتونات CₙH₂ₙO مع الاشتقاق ومثال","marks":2},{"element":"صيغة الأحماض الكربوكسيلية CₙH₂ₙO₂ مع الاشتقاق ومثال","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: صيغة الألدهيدات CₙH₂ₙO مع الاشتقاق ومثال؛ صيغة الكيتونات CₙH₂ₙO مع الاشتقاق ومثال؛ صيغة الأحماض الكربوكسيلية CₙH₂ₙO₂ مع الاشتقاق ومثال"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حذف ذرة هيدروجين واحدة فقط عند تكوين الرابطة الثنائية C=O فتكتب الصيغة CₙH₂ₙ₊₁O","كتابة صيغة الحمض CₙH₂ₙ₊₂O₂ بإهمال ذرات الهيدروجين المحذوفة","عدم ملاحظة أن للألدهيدات والكيتونات الصيغة الجزيئية العامة نفسها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الألدهيدات صيغتها العامة RCHO: تقع مجموعة الكربونيل في آخر السلسلة، وترتبط ذرة كربونها بمجموعة R (ألكيل أو هيدروجين) وبذرة هيدروجين. الكيتونات صيغتها العامة R–CO–R′: تقع مجموعة الكربونيل في وسط السلسلة، وترتبط ذرة كربونها بذرتي كربون. مثال الألدهيد: CH₃CHO إيثانال. مثال الكيتون: CH₃COCH₃ ‏2-بروبانون.', '["الموقع: آخر السلسلة في الألدهيد ووسطها في الكيتون","الذرات المرتبطة: R وذرة H في الألدهيد، وذرتا كربون في الكيتون","الصيغتان العامتان RCHO وR–CO–R′","مثال ألدهيد صحيح مع اسمه","مثال كيتون صحيح مع اسمه"]'::jsonb, '[]'::jsonb, '[{"element":"الموقع: آخر السلسلة في الألدهيد ووسطها في الكيتون","marks":1},{"element":"الذرات المرتبطة: R وذرة H في الألدهيد، وذرتا كربون في الكيتون","marks":1},{"element":"الصيغتان العامتان RCHO وR–CO–R′","marks":1},{"element":"مثال ألدهيد صحيح مع اسمه","marks":1},{"element":"مثال كيتون صحيح مع اسمه","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الموقع: آخر السلسلة في الألدهيد ووسطها في الكيتون؛ الذرات المرتبطة: R وذرة H في الألدهيد، وذرتا كربون في الكيتون؛ الصيغتان العامتان RCHO وR–CO–R′؛ مثال ألدهيد صحيح مع اسمه؛ مثال كيتون صحيح مع اسمه"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر أن مجموعة الكربونيل في الكيتون قد تقع في طرف السلسلة","كتابة 1-بروبانون اسمًا لكيتون","كتابة CH₃CH₂OH مثالًا على الألدهيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
