from (values
('mcq', 1, 2, 'المركب ألدهيد (مجموعة الكربونيل في آخر السلسلة مرتبطة بذرة H)، والسلسلة من أربع ذرات كربون؛ فيضاف المقطع «ال» إلى اسم الألكان بيوتان: بيوتانال، ولا يلزم رقم لأن مجموعة الكربونيل في نهاية السلسلة.', '["لم تُحسب ذرة كربون الكربونيل ضمن السلسلة؛ والسلسلة تتكون من أربع ذرات كربون.","المقطع «ون» خاص بالكيتونات، ومجموعة الكربونيل هنا في آخر السلسلة مرتبطة بذرة هيدروجين فالمركب ألدهيد.","","لا توجد مجموعة OH مرتبطة بذرة كربون الكربونيل، فالمركب ليس حمضًا كربوكسيليًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 2, 0, 'السلسلة من خمس ذرات كربون (بنتان)، ومجموعة الكربونيل في وسطها فالمركب كيتون يأخذ المقطع «ون»، وبالترقيم من الطرف الأقرب إليها تكون ذرة الكربونيل رقم 2: 2-بنتانون.', '["","رُقّمت السلسلة من الطرف الأبعد عن مجموعة الكربونيل؛ والقاعدة أن تأخذ ذرة كربون الكربونيل أصغر رقم ممكن.","ذرة كربون الكربونيل هي الثانية في السلسلة لا الثالثة؛ و3-بنتانون صيغته CH₃CH₂COCH₂CH₃.","المقطع «ال» للألدهيدات، ومجموعة الكربونيل هنا في وسط السلسلة مرتبطة بذرتي كربون فالمركب كيتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 3, 3, 'السلسلة من ست ذرات كربون بما فيها ذرة كربون مجموعة الكربوكسيل ‎–COOH؛ فيضاف المقطع «ويك» إلى اسم الألكان هكسان مع كلمة حمض: حمض الهكسانويك.', '["لم تُحسب ذرة كربون مجموعة الكربوكسيل؛ والسلسلة تتكون من ست ذرات كربون.","المقطع «ال» للألدهيدات، أما هنا فترتبط ذرة كربون الكربونيل بمجموعة OH فالمركب حمض.","المقطع «ون» للكيتونات التي تقع مجموعة الكربونيل فيها في وسط السلسلة، وليس هذا حال المركب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 4, 1, 'الاسم 3-بنتانون يعني سلسلة من خمس ذرات كربون (بنتان) فيها مجموعة كربونيل («ون») على ذرة الكربون الثالثة، أي في منتصف السلسلة: CH₃CH₂COCH₂CH₃.', '["مجموعة الكربونيل هنا على ذرة الكربون الثانية، فهذا 2-بنتانون.","","مجموعة الكربونيل هنا في آخر السلسلة مرتبطة بذرة H، فهذا ألدهيد اسمه بنتانال.","هذا حمض كربوكسيلي اسمه حمض البنتانويك، وليس كيتونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 5, 2, 'أطول سلسلة تحتوي على مجموعة الكربونيل من أربع ذرات كربون (بيوتانال)، وترقّم بدءًا من ذرة كربون الكربونيل (1)، فتقع مجموعة الميثيل على الذرة 3: 3-ميثيل بيوتانال. ويستعمل الترقيم في الألدهيدات عند وجود التفرعات.', '["رُقّمت السلسلة من الطرف الخطأ؛ ففي الألدهيدات تأخذ ذرة كربون الكربونيل الرقم 1، فيقع التفرع على ذرة الكربون 3.","حُسبت ذرات الكربون الخمس كلها سلسلة مستقيمة، لكن أطول سلسلة تحتوي على مجموعة الكربونيل أربع ذرات وعليها تفرع ميثيل.","","المقطع «ون» للكيتونات، ومجموعة الكربونيل هنا في آخر السلسلة مرتبطة بذرة H فالمركب ألدهيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 6, 3, 'السلسلة من ثلاث ذرات كربون، ومجموعة الكربونيل على ذرة الكربون الوسطى فالمركب كيتون: يضاف المقطع «ون» ورقم الموقع: 2-بروبانون.', '["البروبانال ألدهيد تقع فيه مجموعة الكربونيل في آخر السلسلة، أما هنا فهي في الوسط.","المقطع «ول» للكحولات التي تحتوي على مجموعة OH، أما هنا فذرة الأكسجين مرتبطة برابطة ثنائية.","لا توجد مجموعة كربوكسيل ‎–COOH في المركب، فهو ليس حمضًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('mcq', 7, 0, 'في الصيغة ثلاث ذرات كربون (منها ذرة كربون الكربوكسيل)، فيضاف المقطع «ويك» إلى اسم الألكان بروبان مع كلمة حمض: حمض البروبانويك.', '["","لم تُحسب ذرة كربون مجموعة الكربوكسيل؛ وحمض الإيثانويك صيغته CH₃COOH.","البروبانال ألدهيد صيغته CH₃CH₂CHO، ولا يحتوي على مجموعة OH.","حُسبت ذرة كربون زائدة؛ فحمض البيوتانويك صيغته CH₃CH₂CH₂COOH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) بروبانال: ألدهيد سلسلته من ثلاث ذرات كربون. (2) 2-بيوتانون: كيتون سلسلته من أربع ذرات كربون ومجموعة الكربونيل على الذرة 2. (3) حمض البنتانويك: حمض كربوكسيلي سلسلته من خمس ذرات كربون. (4) 2-ميثيل بروبانال: ألدهيد سلسلته الرئيسة من ثلاث ذرات كربون، تبدأ بذرة كربون الكربونيل (1)، وعلى الذرة 2 مجموعة ميثيل.', '["(1) بروبانال","(2) 2-بيوتانون","(3) حمض البنتانويك","(4) 2-ميثيل بروبانال"]'::jsonb, '[]'::jsonb, '[{"element":"(1) بروبانال","marks":1},{"element":"(2) 2-بيوتانون","marks":1},{"element":"(3) حمض البنتانويك","marks":1},{"element":"(4) 2-ميثيل بروبانال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (1) بروبانال؛ (2) 2-بيوتانون؛ (3) حمض البنتانويك؛ (4) 2-ميثيل بروبانال"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال ذرة كربون الكربونيل أو الكربوكسيل عند عد ذرات السلسلة","تسمية المركب (4) بيوتانال بعد ذرة كربون التفرع ضمن السلسلة","كتابة 3-بيوتانون للمركب (2) بالترقيم من الطرف الأبعد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-11-14T13:39:20.684Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 3-هكسانون: سلسلة من ست ذرات كربون ومجموعة كربونيل على الذرة 3: CH₃CH₂COCH₂CH₂CH₃. (ب) 4-ميثيل بنتانال: ألدهيد من خمس ذرات كربون تبدأ بذرة كربون الكربونيل (1) ومجموعة ميثيل على الذرة 4: CH₃CH(CH₃)CH₂CH₂CHO. (ج) حمض البيوتانويك: CH₃CH₂CH₂COOH. (د) ميثانال: HCHO.', '["(أ) CH₃CH₂COCH₂CH₂CH₃","(ب) CH₃CH(CH₃)CH₂CH₂CHO","(ج) CH₃CH₂CH₂COOH","(د) HCHO"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) CH₃CH₂COCH₂CH₂CH₃","marks":1},{"element":"(ب) CH₃CH(CH₃)CH₂CH₂CHO","marks":1},{"element":"(ج) CH₃CH₂CH₂COOH","marks":1},{"element":"(د) HCHO","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) CH₃CH₂COCH₂CH₂CH₃؛ (ب) CH₃CH(CH₃)CH₂CH₂CHO؛ (ج) CH₃CH₂CH₂COOH؛ (د) HCHO"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترقيم الألدهيد من الطرف البعيد عن مجموعة الكربونيل فتوضع مجموعة الميثيل على الذرة 2","كتابة حمض البيوتانويك بخمس ذرات كربون بإضافة ذرة الكربوكسيل إلى أربع ذرات أخرى","كتابة CH₃OH للميثانال (وهو الميثانول)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الاسم الأول: لا يستعمل رقم لموقع مجموعة الكربونيل في الألدهيدات؛ لأنها تقع دائمًا في نهاية السلسلة، فالاسم الصحيح بيوتانال. الاسم الثاني: رُقّمت السلسلة من الطرف الأبعد عن مجموعة الكربونيل؛ وبالترقيم من الطرف الأقرب تكون على الذرة 3، فالاسم الصحيح 3-هكسانون.', '["الخطأ الأول: الألدهيد لا يحتاج إلى رقم لأن الكربونيل في نهاية السلسلة","الاسم الصحيح: بيوتانال","الخطأ الثاني: الترقيم من الطرف الأبعد عن الكربونيل","الاسم الصحيح: 3-هكسانون"]'::jsonb, '[]'::jsonb, '[{"element":"الخطأ الأول: الألدهيد لا يحتاج إلى رقم لأن الكربونيل في نهاية السلسلة","marks":1},{"element":"الاسم الصحيح: بيوتانال","marks":1},{"element":"الخطأ الثاني: الترقيم من الطرف الأبعد عن الكربونيل","marks":1},{"element":"الاسم الصحيح: 3-هكسانون","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الخطأ الأول: الألدهيد لا يحتاج إلى رقم لأن الكربونيل في نهاية السلسلة؛ الاسم الصحيح: بيوتانال؛ الخطأ الثاني: الترقيم من الطرف الأبعد عن الكربونيل؛ الاسم الصحيح: 3-هكسانون"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول «1-بيوتانال» صحيحًا","تصحيح الاسم الثاني إلى 2-هكسانون بعدّ خاطئ لذرات الكربون","عدم ذكر سبب الخطأ والاكتفاء بالاسم الصحيح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb)
