from (values
('mcq', 1, 3, 'في المركب (4) تقع مجموعة الكربونيل في آخر السلسلة وترتبط ذرة كربونها بذرة هيدروجين (‎–CHO)، فهو ألدهيد (إيثانال).', '["المركب (1) يحتوي على مجموعة هيدروكسيل ‎–OH مرتبطة بذرة كربون مشبعة، فهو كحول (إيثانول).","المركب (2) ترتبط فيه ذرة كربون الكربونيل بذرتي كربون، فهو كيتون (2-بروبانون).","المركب (3) فيه ذرة أكسجين مرتبطة بذرتي كربون بروابط أحادية، فهو إيثر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb),
('mcq', 2, 1, 'تحتوي الصيغة على مجموعة كربونيل مرتبطة بمجموعة هيدروكسيل، أي مجموعة الكربوكسيل ‎–COOH، فالمركب حمض كربوكسيلي، وسلسلته من أربع ذرات كربون: حمض البيوتانويك.', '["ترتبط بذرة كربون الكربونيل مجموعة OH لا ذرة H، فالمجموعة الوظيفية كربوكسيل لا ألدهيد.","","النوع صحيح، لكن ذرة كربون الكربوكسيل لم تُحسب؛ فالسلسلة أربع ذرات كربون.","مجموعة OH هنا مرتبطة بذرة كربون الكربونيل فتكوّن مجموعة الكربوكسيل، وليست مجموعة هيدروكسيل كحولية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb),
('mcq', 3, 2, 'ترتبط ذرة نيتروجين (مجموعة NH₂) بذرة كربون الكربونيل، أي حلت محل مجموعة OH في الحمض الكربوكسيلي؛ فالمركب أميد (بيوتان أميد).', '["في الأمين ترتبط ذرة النيتروجين بذرات كربون لا ترتبط بأكسجين برابطة ثنائية، أما هنا فالنيتروجين مرتبط بذرة كربون الكربونيل.","في الإستر ترتبط ذرة كربون الكربونيل بذرة أكسجين متصلة بمجموعة ألكيل، ولا يوجد نيتروجين.","","في الكيتون ترتبط ذرة كربون الكربونيل بذرتي كربون، أما هنا فإحداهما ذرة نيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb),
('mcq', 4, 0, 'مجموعة الكربوكسيل هنا حلت فيها مجموعة ألكيل (بروبيل) محل ذرة الهيدروجين، فالمركب إستر؛ ويسمى باسم الحمض (إيثانويك) بالمقطع «وات» متبوعًا بالألكيل: إيثانوات البروبيل.', '["","النوع صحيح، لكن عُكس الجزءان: الجزء المشتق من الحمض CH₃CO (ذرتا كربون: إيثانوات) والمجموعة المرتبطة بالأكسجين بروبيل.","ذرة الأكسجين الأحادية هنا مرتبطة بذرة كربون الكربونيل، فالمجموعة إستر لا إيثر.","ذرة كربون الكربونيل مرتبطة بذرة أكسجين لا بذرتي كربون، فالمركب ليس كيتونًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.685Z"}'::jsonb),
('mcq', 5, 1, 'وجود مجموعة الكربونيل في وسط السلسلة يعني أن ذرة كربونها مرتبطة بذرتي كربون، فالمركب كيتون من ثلاث ذرات كربون: CH₃COCH₃، واسمه 2-بروبانون.', '["للبروبانال الصيغة الجزيئية نفسها، لكن مجموعة الكربونيل فيه في آخر السلسلة.","","الكحول لا يحتوي على مجموعة كربونيل، وصيغة 2-بروبانول C₃H₈O.","الإيثر لا يحتوي على مجموعة كربونيل، وصيغة إيثيل ميثيل إيثر C₃H₈O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('mcq', 6, 2, 'في الصيغة R–COO–R′ حلت مجموعة ألكيل R′ محل ذرة هيدروجين مجموعة الكربوكسيل، وهذا تعريف الإسترات.', '["صيغتها العامة RCOOH؛ فيرتبط الأكسجين الأحادي فيها بذرة هيدروجين لا بمجموعة ألكيل.","صيغتها العامة R–O–R′، ولا تحتوي على مجموعة كربونيل.","","صيغتها العامة R–CO–R′، وفيها ذرة أكسجين واحدة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('mcq', 7, 3, 'كربونيل مرتبط بمجموعة OH = مجموعة الكربوكسيل (حمض كربوكسيلي)، وكربونيل مرتبط بذرة H ومجموعة ألكيل = ‎–CHO (ألدهيد)؛ فالترتيب: حمض كربوكسيلي ثم ألدهيد.', '["مجموعة OH المرتبطة بذرة كربون الكربونيل تكوّن مجموعة الكربوكسيل، فالمركب الأول حمض لا كحول.","في الكيتون ترتبط ذرة كربون الكربونيل بذرتي كربون، لا بذرة هيدروجين.","عُكس الترتيب؛ فالمركب الأول هو الذي يحتوي على مجموعة الكربوكسيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) إستر: ترتبط ذرة كربون الكربونيل بذرة أكسجين متصلة بمجموعة إيثيل، والجزء المشتق من الحمض CH₃CO؛ اسمه إيثانوات الإيثيل. (2) أميد: ترتبط ذرة كربون الكربونيل بمجموعة NH₂، والسلسلة أربع ذرات كربون؛ اسمه بيوتان أميد. (3) كيتون: ذرة كربون الكربونيل في الحلقة مرتبطة بذرتي كربون. (4) ألدهيد: الكربونيل في آخر السلسلة مرتبط بذرة H؛ اسمه بيوتانال.', '["(1) إستر","(2) أميد","(3) كيتون","(4) ألدهيد","اسم (1): إيثانوات الإيثيل","اسم (2): بيوتان أميد","اسم (4): بيوتانال"]'::jsonb, '[]'::jsonb, '[{"element":"(1) إستر","marks":1},{"element":"(2) أميد","marks":1},{"element":"(3) كيتون","marks":1},{"element":"(4) ألدهيد","marks":1},{"element":"اسم (1): إيثانوات الإيثيل","marks":1},{"element":"اسم (2): بيوتان أميد","marks":1},{"element":"اسم (4): بيوتانال","marks":1}]'::jsonb, '[{"level":"7 درجات","description":"إجابة كاملة صحيحة تشمل: (1) إستر؛ (2) أميد؛ (3) كيتون؛ (4) ألدهيد؛ اسم (1): إيثانوات الإيثيل؛ اسم (2): بيوتان أميد؛ اسم (4): بيوتانال"},{"level":"1–6 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف المركب (1) إيثرًا لوجود ذرة أكسجين بين ذرتي كربون","تصنيف المركب (2) أمينًا لوجود مجموعة NH₂","تسمية المركب (1) إيثانوات البروبيل أو بروبانوات الميثيل بخلط جزأي الإستر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (7 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) مجموعة ‎–CHO على الرأس العلوي: مجموعة كربونيل مرتبطة بذرة هيدروجين، وهي المجموعة الوظيفية للألدهيدات. (2) مجموعة ‎–O–CH₃: ذرة أكسجين مرتبطة بذرتي كربون (كربون الحلقة وكربون الميثيل)، وهي مجموعة الإيثر المميزة للإيثرات. (3) مجموعة ‎–OH: مجموعة الهيدروكسيل، وهي المجموعة الوظيفية المميزة للكحولات (وهنا ترتبط بحلقة البنزين).', '["تحديد ‎–CHO وتسميتها مجموعة كربونيل (ألدهيد)","تحديد ‎–O–CH₃ وتسميتها مجموعة إيثر","تحديد ‎–OH وتسميتها مجموعة هيدروكسيل"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد ‎–CHO وتسميتها مجموعة كربونيل (ألدهيد)","marks":2},{"element":"تحديد ‎–O–CH₃ وتسميتها مجموعة إيثر","marks":2},{"element":"تحديد ‎–OH وتسميتها مجموعة هيدروكسيل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: تحديد ‎–CHO وتسميتها مجموعة كربونيل (ألدهيد)؛ تحديد ‎–O–CH₃ وتسميتها مجموعة إيثر؛ تحديد ‎–OH وتسميتها مجموعة هيدروكسيل"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية ‎–CHO مجموعة كيتون","تسمية ‎–O–CH₃ مجموعة إستر رغم عدم ارتباط الأكسجين بذرة كربون كربونيل","عدّ مجموعة ‎–OH في الفانيلين مجموعة كربوكسيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) ألدهيد (‎–CHO في آخر السلسلة): بنتانال. (ب) كيتون (C=O بين ذرتي كربون): 3-بنتانون. (ج) حمض كربوكسيلي (‎–COOH): حمض الميثانويك. (د) كحول (‎–OH): 1-بيوتانول.', '["(أ) ألدهيد — بنتانال","(ب) كيتون — 3-بنتانون","(ج) حمض كربوكسيلي — حمض الميثانويك","(د) كحول — 1-بيوتانول"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) ألدهيد — بنتانال","marks":2},{"element":"(ب) كيتون — 3-بنتانون","marks":2},{"element":"(ج) حمض كربوكسيلي — حمض الميثانويك","marks":2},{"element":"(د) كحول — 1-بيوتانول","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) ألدهيد — بنتانال؛ (ب) كيتون — 3-بنتانون؛ (ج) حمض كربوكسيلي — حمض الميثانويك؛ (د) كحول — 1-بيوتانول"},{"level":"1–7 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (أ) بيوتانال بإهمال ذرة كربون الكربونيل","تسمية (ب) 2-بنتانون","تسمية (ج) ميثانال أو حمض الإيثانويك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
