from (values
('mcq', 1, 'أيّ العبارات الآتية تصف الألدهيدات وصفًا صحيحًا؟', null, null, '["مركبات قطبية ونشطة في التفاعل","مركبات غير قطبية وخاملة في التفاعل","مركبات تكوّن روابط هيدروجينية بين جزيئاتها","مركبات أيونية تتفكك في الماء إلى أيونات"]'::jsonb, 'تذكر', 'وصف خواص', 'سهل', 'الكتاب ص 179 — خواص الألدهيدات'),
