('mcq', 3, 'يبين الجدول الآتي الكتل المولية ودرجات الغليان لثلاثة مركبات متقاربة في الكتلة المولية. أيّ العبارات الآتية تصف درجة غليان البروبانال وصفًا صحيحًا؟', '{"headers":["المركب","الصيغة","الكتلة المولية (g/mol)","درجة الغليان (°C)"],"rows":[["البيوتان","CH₃CH₂CH₂CH₃","58.12","−0.5"],["البروبانال","CH₃CH₂CHO","58.08","48"],["1-بروبانول","CH₃CH₂CH₂OH","60.09","97"]]}'::jsonb, null, '["أعلى من درجتي غليان البيوتان و1-بروبانول","أعلى من درجة غليان البيوتان، وأقل من درجة غليان 1-بروبانول","أقل من درجتي غليان البيوتان و1-بروبانول","مساوية لدرجة غليان 1-بروبانول لتقارب الكتلتين الموليتين"]'::jsonb, 'فهم', 'وصف خاصية من بيانات', 'سهل', 'الكتاب ص 179 — درجة غليان الألدهيدات'),
('mcq', 4, 'أيّ مما يأتي يصف الخواص الفيزيائية للإسترات؟', null, null, '["مركبات غير قطبية، عديمة الرائحة","مركبات قطبية غير متطايرة، رائحتها كريهة","مركبات أيونية صلبة، درجات انصهارها مرتفعة","مركبات قطبية متطايرة، رائحتها عطرة"]'::jsonb, 'تذكر', 'وصف خواص', 'متوسط', 'الكتاب ص 181 — خواص الإسترات'),
('mcq', 5, 'أيّ مما يأتي من الخواص المميزة لمحاليل الأحماض الكربوكسيلية في الماء؟', null, null, '["تتأين جزئيًّا، وتحوّل لون ورقة تباع الشمس الزرقاء إلى الحمراء","تتأين كليًّا، وتحوّل لون ورقة تباع الشمس الحمراء إلى الزرقاء","لا تتأين، ولا تؤثر في لون ورقة تباع الشمس","تتأين جزئيًّا، وتحوّل لون ورقة تباع الشمس الحمراء إلى الزرقاء"]'::jsonb, 'فهم', 'وصف خواص', 'متوسط', 'الكتاب ص 180 — خواص الأحماض الكربوكسيلية'),
('mcq', 6, 'أيّ العبارات الآتية تصف جزيئات الكيتونات وصفًا صحيحًا؟', null, null, '["قطبية، وتكوّن روابط هيدروجينية قوية بعضها مع بعض","قطبية، ولا تكوّن روابط هيدروجينية بعضها مع بعض","غير قطبية، ولا تكوّن روابط هيدروجينية مع الماء","غير قطبية، وتكوّن روابط هيدروجينية مع الماء"]'::jsonb, 'فهم', 'وصف خواص', 'صعب', 'الكتاب ص 179 — خواص الكيتونات'),
('mcq', 7, 'يبين الشكل الآتي الصيغة البنائية المكثفة لمركب عضوي. أيّ الخواص الآتية تتوقعها لهذا المركب؟', null, '[{"src":"qimg/chem22/c5-l3a-ethyl-butanoate.svg","alt":"صيغة بنائية مكثفة: سلسلة CH₃–CH₂–CH₂ ترتبط بذرة كربون C، وهذه ترتبط من أعلى بذرة أكسجين O برابطة ثنائية ومن اليمين بذرة أكسجين O برابطة أحادية ترتبط بمجموعة CH₂–CH₃، أي CH₃–CH₂–CH₂–C(=O)–O–CH₂–CH₃."}]'::jsonb, '["غير متطاير، وعديم الرائحة","يتأين في الماء، فمحلوله حمضي لاذع","متطاير، وله رائحة عطرة","أيوني، ودرجة انصهاره مرتفعة"]'::jsonb, 'تحليل', 'توقع خواص من تركيب', 'صعب', 'الكتاب ص 181 — خواص الإسترات'),
('essay', 1, 'قارن بين الألدهيدات والكيتونات من حيث: (أ) القطبية (ب) النشاط الكيميائي (ج) قدرة جزيئاتها على تكوين روابط هيدروجينية بعضها مع بعض (د) قدرتها على تكوين روابط هيدروجينية مع الماء (هـ) الذوبان في الماء.', null, null, null, 'فهم', 'مقارنة خواص', 'متوسط', 'الكتاب ص 179 — خواص الألدهيدات والكيتونات'),
('essay', 2, 'صف خواص الأحماض الكربوكسيلية، واكتب معادلة تأين حمض الإيثانويك في الماء.', null, null, null, 'فهم', 'وصف خواص مع معادلة', 'سهل', 'الكتاب ص 180، 204 — الأحماض الكربوكسيلية (س59)'),
('essay', 3, 'يبين الشكل الآتي مركبين مرقمين يوجدان في نكهات بعض الفواكه. (أ) ما نوع المركبين؟ (ب) سمِّ كلًّا منهما. (ج) صف خاصيتين فيزيائيتين لهذا النوع من المركبات تفسران وجوده في روائح الفواكه ونكهاتها.', null, '[{"src":"qimg/chem22/c5-l3a-fruit-esters.svg","alt":"صيغتان بنائيتان مكثفتان مرقمتان: (1) CH₃(CH₂)₄–C(=O)–O–CH₃: مجموعة CH₃(CH₂)₄ ترتبط بذرة كربون مرتبطة من أعلى بذرة أكسجين برابطة ثنائية ومن اليمين بذرة أكسجين ترتبط بمجموعة CH₃. (2) CH₃CH₂CH₂–C(=O)–O–CH₂CH₃: مجموعة CH₃CH₂CH₂ ترتبط بذرة كربون مرتبطة من أعلى بذرة أكسجين برابطة ثنائية ومن اليمين بذرة أكسجين ترتبط بمجموعة CH₂CH₃."}]'::jsonb, null, 'فهم', 'تصنيف ووصف خواص', 'صعب', 'الكتاب ص 181 — الإسترات (الشكل 5-11)')
