('mcq', 1, 0, 'يحتوي جزيء الألدهيد على مجموعة قطبية (الكربونيل) ونشطة في التفاعل؛ فالألدهيدات مركبات قطبية نشطة.', '["","جزيء الألدهيد يحتوي على مجموعة الكربونيل القطبية، والألدهيدات نشطة في التفاعل.","لا تحتوي جزيئات الألدهيد على ذرة هيدروجين مرتبطة بذرة الأكسجين، فلا تكوّن روابط هيدروجينية بعضها مع بعض.","الألدهيدات مركبات جزيئية تساهمية، ولا تتفكك إلى أيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('mcq', 2, 2, 'تشترك الكيتونات والألدهيدات في كثير من الخواص لتشابه تركيبهما؛ فالكيتونات مركبات قطبية، لكنها أقل نشاطًا من الألدهيدات.', '["الكيتونات تحتوي على مجموعة الكربونيل القطبية، وهي أقل نشاطًا من الألدهيدات لا أكثر.","وصف القطبية صحيح، لكن الكيتونات أقل نشاطًا من الألدهيدات.","","وصف النشاط صحيح، لكن الكيتونات مركبات قطبية لاحتوائها على مجموعة الكربونيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.686Z"}'::jsonb),
('mcq', 3, 1, 'درجة غليان البروبانال 48 °C، فهي أعلى من درجة غليان البيوتان (−0.5 °C) لأن الألدهيد قطبي، وأقل من درجة غليان 1-بروبانول (97 °C) لأن جزيئات الألدهيد لا تكوّن روابط هيدروجينية بعضها مع بعض.', '["درجة غليان البروبانال 48 °C أقل من درجة غليان 1-بروبانول 97 °C.","","درجة غليان البروبانال 48 °C أعلى من درجة غليان البيوتان −0.5 °C.","تقارب الكتل المولية لا يعني تساوي درجات الغليان؛ فالبيانات تُظهر فرقًا كبيرًا (48 °C مقابل 97 °C)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('mcq', 4, 3, 'الإسترات مركبات قطبية متطايرة رائحتها عطرة، وتوجد في العطور والنكهات الطبيعية وفي الفواكه والأزهار.', '["الإسترات قطبية لاحتوائها على مجموعة الكربونيل، ولها روائح عطرة تعطي الفواكه والأزهار روائحها.","الإسترات متطايرة ورائحتها عطرة؛ والرائحة الكريهة من صفات الأمينات.","الإسترات مركبات جزيئية تساهمية متطايرة، لا مركبات أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('mcq', 5, 0, 'ما يذوب من الأحماض الكربوكسيلية في الماء يتأين بشكل ضعيف منتجًا أيونات الهيدرونيوم، فتحوّل محاليلها لون ورقة تباع الشمس الزرقاء إلى حمراء، وتتميز بمذاق حمضي لاذع.', '["","الأحماض الكربوكسيلية تتأين بشكل ضعيف لا كليًّا، والتحويل من الأحمر إلى الأزرق من صفات القواعد.","الأحماض الكربوكسيلية الذائبة تتأين بشكل ضعيف منتجة أيونات الهيدرونيوم، فتؤثر في لون ورقة تباع الشمس.","وصف التأين صحيح، لكن الأحماض تحوّل ورقة تباع الشمس الزرقاء إلى الحمراء لا العكس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('mcq', 6, 1, 'الكيتونات مركبات قطبية، ومثل الألدهيدات لا تكوّن جزيئاتها روابط هيدروجينية بعضها مع بعض، لكنها تكوّن روابط هيدروجينية مع جزيئات الماء.', '["لا تحتوي جزيئات الكيتون على ذرة هيدروجين مرتبطة بذرة الأكسجين، فلا تكوّن روابط هيدروجينية بعضها مع بعض.","","الكيتونات قطبية، وتستطيع جزيئاتها تكوين روابط هيدروجينية مع جزيئات الماء.","الجزء الثاني صحيح، لكن الكيتونات مركبات قطبية لا غير قطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (63%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('mcq', 7, 2, 'المركب CH₃CH₂CH₂COOCH₂CH₃ إستر (بيوتانوات الإيثيل)؛ لأن ذرة كربون الكربونيل فيه مرتبطة بذرة أكسجين متصلة بمجموعة إيثيل. والإسترات مركبات قطبية متطايرة رائحتها عطرة.', '["المركب إستر (مجموعة الكربونيل مرتبطة بأكسجين متصل بمجموعة إيثيل)، والإسترات متطايرة ذات روائح عطرة.","التأين في الماء والمذاق الحمضي من خواص الأحماض الكربوكسيلية، والمركب ليس حمضًا لأنه لا يحتوي على ‎–COOH.","","المركب جزيئي تساهمي، والإسترات مركبات متطايرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) كلاهما قطبي لاحتوائه على مجموعة الكربونيل. (ب) الألدهيدات نشطة في التفاعل، والكيتونات أقل نشاطًا منها. (ج) لا تكوّن جزيئات أيّ منهما روابط هيدروجينية بعضها مع بعض لعدم وجود ذرة H مرتبطة بذرة الأكسجين. (د) كلاهما يكوّن روابط هيدروجينية مع جزيئات الماء. (هـ) لذلك يذوبان في الماء إلى حد ما (الألدهيدات أكثر ذوبانًا من الألكانات وأقل من الكحولات)، والأسيتون يذوب في الماء بشكل تام.', '["(أ) كلاهما قطبي","(ب) الكيتونات أقل نشاطًا من الألدهيدات","(ج) لا روابط هيدروجينية بين جزيئات أيّ منهما","(د) كلاهما يكوّن روابط هيدروجينية مع الماء","(هـ) يذوبان في الماء إلى حد ما، والأسيتون تامًّا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) كلاهما قطبي","marks":1},{"element":"(ب) الكيتونات أقل نشاطًا من الألدهيدات","marks":1},{"element":"(ج) لا روابط هيدروجينية بين جزيئات أيّ منهما","marks":1},{"element":"(د) كلاهما يكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"(هـ) يذوبان في الماء إلى حد ما، والأسيتون تامًّا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) كلاهما قطبي؛ (ب) الكيتونات أقل نشاطًا من الألدهيدات؛ (ج) لا روابط هيدروجينية بين جزيئات أيّ منهما؛ (د) كلاهما يكوّن روابط هيدروجينية مع الماء؛ (هـ) يذوبان في الماء إلى حد ما، والأسيتون تامًّا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكيتونات أكثر نشاطًا من الألدهيدات","القول إن جزيئات الألدهيد تكوّن روابط هيدروجينية بعضها مع بعض","القول إن الكيتونات لا تذوب في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأحماض الكربوكسيلية مركبات قطبية نشطة. ما يذوب منها في الماء يتأين بشكل ضعيف منتجًا أيونات الهيدرونيوم، ويكون أيون الحمض السالب في حالة اتزان مع الماء والحمض غير المتأين: CH₃COOH(aq) + H₂O(l) ⇌ CH₃COO⁻(aq) + H₃O⁺(aq). ولأنها تتأين تحوّل لون ورقة تباع الشمس الزرقاء إلى حمراء، وتتميز بمذاق حمضي لاذع.', '["قطبية نشطة","تتأين بشكل ضعيف منتجة H₃O⁺ في حالة اتزان","المعادلة الموزونة بسهم الاتزان","تحول ورقة تباع الشمس الزرقاء إلى حمراء","مذاق حمضي لاذع"]'::jsonb, '[]'::jsonb, '[{"element":"قطبية نشطة","marks":1},{"element":"تتأين بشكل ضعيف منتجة H₃O⁺ في حالة اتزان","marks":1},{"element":"المعادلة الموزونة بسهم الاتزان","marks":2},{"element":"تحول ورقة تباع الشمس الزرقاء إلى حمراء","marks":1},{"element":"مذاق حمضي لاذع","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: قطبية نشطة؛ تتأين بشكل ضعيف منتجة H₃O⁺ في حالة اتزان؛ المعادلة الموزونة بسهم الاتزان؛ تحول ورقة تباع الشمس الزرقاء إلى حمراء؛ مذاق حمضي لاذع"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة سهم باتجاه واحد (→) بدل سهم الاتزان","كتابة OH⁻ ناتجًا للتأين","القول إن الأحماض الكربوكسيلية تتأين كليًّا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) كلاهما إستر: مجموعة كربوكسيل حلت فيها مجموعة ألكيل محل ذرة الهيدروجين. (ب) (1) هكسانوات الميثيل، (2) بيوتانوات الإيثيل. (ج) الإسترات مركبات قطبية متطايرة، رائحتها عطرة؛ فتطايرها يجعل جزيئاتها تصل إلى الأنف بسهولة فتظهر رائحتها.', '["(أ) إسترات","(ب) هكسانوات الميثيل","(ب) بيوتانوات الإيثيل","(ج) متطايرة","(ج) رائحتها عطرة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) إسترات","marks":1},{"element":"(ب) هكسانوات الميثيل","marks":1},{"element":"(ب) بيوتانوات الإيثيل","marks":1},{"element":"(ج) متطايرة","marks":1},{"element":"(ج) رائحتها عطرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) إسترات؛ (ب) هكسانوات الميثيل؛ (ب) بيوتانوات الإيثيل؛ (ج) متطايرة؛ (ج) رائحتها عطرة"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية (1) ميثانوات الهكسيل بعكس جزأي الإستر","تصنيف المركبين أحماضًا كربوكسيلية","القول إن الإسترات غير متطايرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb)
