from (values
('mcq', 1, 1, 'المركب HCHO هو الميثانال (الفورمالدهيد)، واستُعمل محلوله في عمليات الحفظ عدة سنوات لحفظ العينات البيولوجية، ثم قُيّد استعماله لأنه قد يسبب السرطان.', '["لا يستعمل هذا المركب (الميثانال) في معالجة مياه الشرب، فهو قد يسبب السرطان.","","هذا من استعمالات الأسيتون (2-بروبانون)، وهو كيتون لا ألدهيد.","نكهات الفواكه ترجع غالبًا إلى الإسترات، لا إلى الميثانال."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.687Z"}'::jsonb),
('mcq', 2, 3, 'تستعمل كميات كبيرة من الفورمالدهيد للتفاعل مع اليوريا لصنع نوع من الشمع المقاوم، والمواد البلاستيكية الصلبة المستعملة في صناعة الأزرار وقطع غيار السيارات والأجهزة الكهربائية، والغراء الذي يلصق طبقات الخشب.', '["المذيب الشائع للطلاء والورنيش هو الكيتونات كالأسيتون، لا ناتج تفاعل الفورمالدهيد مع اليوريا.","اليوريا نفسها هي التي تستعمل سمادًا، أما تفاعلها مع الفورمالدهيد فينتج مواد بلاستيكية صلبة.","النكهات الصناعية تصنع غالبًا من الإسترات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('mcq', 3, 2, 'الكيتونات قطبية، لذا يعد الكيتون مذيبًا شائعًا للمواد القطبية المعتدلة كالشمع والبلاستيك والطلاء والورنيش والغراء، وأكثرها شيوعًا الأسيتون (2-بروبانون).', '["يستعمل الفورمالدهيد في حفظ العينات وصناعة البلاستيك الصلب، لا مذيبًا شائعًا.","حمض الإيثانويك هو الحمض الموجود في الخل.","","اليوريا تستعمل سمادًا وغذاءً للماشية، وهي مادة صلبة لا مذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('mcq', 4, 0, 'حمض الإيثانويك (حمض الأسيتيك) CH₃COOH حمض مألوف، وهو الحمض الموجود في الخل.', '["","حمض الميثانويك (الفورميك) يفرزه النمل وبعض الحشرات للدفاع عن نفسها.","حمض اللاكتيك موجود في اللبن.","حمض السلسليك يستعمل في تحضير الأسبرين، وليس حمض الخل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('mcq', 5, 3, 'الإسترات متطايرة رائحتها عطرة، لذا تُصنّع لاستعمالها في كثير من الأطعمة والنكهات والمشروبات والعطور والشموع العطرية والمواد المعطرة الأخرى.', '["هذا استعمال الفورمالدهيد، وهو ألدهيد.","هذا استعمال اليوريا، وهي أميد.","هذا استعمال الكيتونات كالأسيتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('mcq', 6, 0, 'بسبب احتواء اليوريا NH₂CONH₂ على نسبة عالية من النيتروجين وسهولة تحولها إلى أمونيا في التربة، فإنها تستعمل في صناعة الأسمدة الزراعية، كما تستعمل غذاءً للماشية والأغنام.', '["","اليوريا NH₂CONH₂ لا تحتوي على فوسفور.","اليوريا أميد (كارباميد)، وليست حمضًا كربوكسيليًّا.","لا تستعمل اليوريا مذيبًا؛ وسبب استعمالها سمادًا محتواها العالي من النيتروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('mcq', 7, 1, 'رائحة القرفة ومذاقها — وهي من التوابل التي تستخرج من لحاء شجرة استوائية — يمكن إنتاجهما بكميات كبيرة بواسطة السينامالدهيد.', '["البنزالدهيد يعطي اللوز نكهته، لكن اللوز ليس لحاء شجرة.","","التوابل صحيحة، لكن الفورمالدهيد يستعمل للحفظ وصناعة البلاستيك لا للنكهات.","بيوتانوات الإيثيل إستر لا ألدهيد، والأناناس ليس من التوابل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الفورمالدهيد (ميثانال) — ألدهيد. (ب) الأسيتون (2-بروبانون) — كيتون. (ج) حمض الإيثانويك (حمض الأسيتيك) — حمض كربوكسيلي. (د) الإسترات مثل بيوتانوات الإيثيل (نكهة الأناناس) أو هكسانوات الميثيل (نكهة الفراولة) — إستر؛ ويقبل البنزالدهيد (نكهة اللوز) — ألدهيد. (هـ) اليوريا (كارباميد) — أميد.', '["(أ) الفورمالدهيد — ألدهيد","(ب) الأسيتون — كيتون","(ج) حمض الإيثانويك — حمض كربوكسيلي","(د) إستر مثل بيوتانوات الإيثيل","(هـ) اليوريا — أميد"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الفورمالدهيد — ألدهيد","marks":1},{"element":"(ب) الأسيتون — كيتون","marks":1},{"element":"(ج) حمض الإيثانويك — حمض كربوكسيلي","marks":1},{"element":"(د) إستر مثل بيوتانوات الإيثيل","marks":1},{"element":"(هـ) اليوريا — أميد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الفورمالدهيد — ألدهيد؛ (ب) الأسيتون — كيتون؛ (ج) حمض الإيثانويك — حمض كربوكسيلي؛ (د) إستر مثل بيوتانوات الإيثيل؛ (هـ) اليوريا — أميد"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر حمض الميثانويك حمضًا للخل","تصنيف اليوريا أمينًا","ذكر الإيثانول مذيبًا لطلاء الأظافر وهو كحول لا مركب كربونيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('essay', 2, null::int, null, null, 'من استعمالات الفورمالدهيد: (1) استُعمل محلوله في حفظ العينات البيولوجية. (2) يتفاعل صناعيًّا مع اليوريا لصنع مواد بلاستيكية صلبة تستعمل في صناعة الأزرار وقطع غيار السيارات والأجهزة الكهربائية. (3) يدخل في صنع الغراء الذي يلصق طبقات الخشب معًا (ونوع من الشمع المقاوم). وقُيّد استعماله لأن الدراسات الأخيرة تشير إلى أنه قد يسبب السرطان.', '["حفظ العينات البيولوجية","صناعة البلاستيك الصلب مع اليوريا","الغراء لإلصاق طبقات الخشب (أو الشمع المقاوم)","سبب التقييد: قد يسبب السرطان"]'::jsonb, '[]'::jsonb, '[{"element":"حفظ العينات البيولوجية","marks":1},{"element":"صناعة البلاستيك الصلب مع اليوريا","marks":1},{"element":"الغراء لإلصاق طبقات الخشب (أو الشمع المقاوم)","marks":1},{"element":"سبب التقييد: قد يسبب السرطان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: حفظ العينات البيولوجية؛ صناعة البلاستيك الصلب مع اليوريا؛ الغراء لإلصاق طبقات الخشب (أو الشمع المقاوم)؛ سبب التقييد: قد يسبب السرطان"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر استعمال الفورمالدهيد مذيبًا للطلاء","ذكر أن سبب التقييد أنه قابل للاشتعال","ذكر استعمالات اليوريا بدل استعمالات الفورمالدهيد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) حمض الميثانويك (الفورميك): تنتجه بعض الحشرات كالنمل آلية دفاع عن نفسها. (ب) البنزالدهيد: يعطي اللوز نكهته الطبيعية. (ج) السينامالدهيد: يستعمل لإنتاج رائحة القرفة ومذاقها بكميات كبيرة. (د) الأسيتامينوفين: مسكن لتخفيف الألم (غير الأسبرين). وتُصنَّع الإسترات لأنها متطايرة ذات روائح عطرة، ولأن بعض النكهات الطبيعية يرجع سببها إلى تركيب إستر واحد فقط، فيمكن تصنيعه واستعماله في الأطعمة والنكهات والمشروبات والعطور والشموع العطرية.', '["(أ) دفاع النمل عن نفسه","(ب) نكهة اللوز","(ج) رائحة القرفة ومذاقها","(د) مسكن للألم","تفسير تصنيع الإسترات: نكهة بعض الفواكه ترجع إلى إستر واحد، فيمكن تصنيعه للأطعمة والعطور"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) دفاع النمل عن نفسه","marks":1},{"element":"(ب) نكهة اللوز","marks":1},{"element":"(ج) رائحة القرفة ومذاقها","marks":1},{"element":"(د) مسكن للألم","marks":1},{"element":"تفسير تصنيع الإسترات: نكهة بعض الفواكه ترجع إلى إستر واحد، فيمكن تصنيعه للأطعمة والعطور","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) دفاع النمل عن نفسه؛ (ب) نكهة اللوز؛ (ج) رائحة القرفة ومذاقها؛ (د) مسكن للألم؛ تفسير تصنيع الإسترات: نكهة بعض الفواكه ترجع إلى إستر واحد، فيمكن تصنيعه للأطعمة والعطور"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين البنزالدهيد (اللوز) والسينامالدهيد (القرفة)","ذكر أن الأسيتامينوفين هو الأسبرين","تفسير تصنيع الإسترات بأنها غير موجودة في الطبيعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.688Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C5-L3-O05') and x.type = v.type and x.number = v.number
