insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L3-O06'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ المركبات الآتية أقل ذائبية في الماء؟', null, null, '["البروبانال CH₃CH₂CHO","2-بروبانون CH₃COCH₃","البروبان CH₃CH₂CH₃","حمض البروبانويك CH₃CH₂COOH"]'::jsonb, 'فهم', 'تفسير الذائبية', 'سهل', 'الكتاب ص 179–180 — ذائبية مركبات الكربونيل'),
('mcq', 2, 'يبين الشكل الآتي جزيء أسيتون محاطًا بجزيئي ماء. ماذا تمثل الخطوط المتقطعة؟', null, '[{"src":"qimg/chem22/c5-l3a-acetone-water.svg","alt":"جزيء أسيتون CH₃–C(=O)–CH₃ في أسفل الشكل، وذرة أكسجين الكربونيل تتجه إلى أعلى. وفوقه جزيئا ماء، كل منهما ذرة أكسجين O مرتبطة بذرتي هيدروجين H بخطين متصلين، وتتجه ذرة هيدروجين من كل جزيء ماء نحو ذرة أكسجين الكربونيل، ويصل بين كل منهما وذرة أكسجين الكربونيل خط متقطع."}]'::jsonb, '["روابط هيدروجينية بين ذرات هيدروجين الماء وذرة أكسجين الكربونيل","روابط تساهمية أحادية تتكوّن عند ذوبان الأسيتون","روابط هيدروجينية بين جزيئات الأسيتون بعضها مع بعض","روابط أيونية بين أيونات الهيدرونيوم وجزيء الأسيتون"]'::jsonb, 'فهم', 'تفسير شكل', 'سهل', 'الكتاب ص 179 — ذائبية الكيتونات'),
('mcq', 3, 'تذوب الألدهيدات في الماء أكثر من الألكانات، لكن ذائبيتها أقل من ذائبية الكحولات التي لها عدد ذرات الكربون نفسه. أيّ الفروق الآتية بين تركيبي جزيء الألدهيد وجزيء الكحول يرتبط بهذا الاختلاف في الذائبية؟', null, null, '["جزيء الألدهيد غير قطبي، أما جزيء الكحول فقطبي","جزيء الألدهيد لا يحتوي على ذرة هيدروجين مرتبطة بذرة أكسجين، بخلاف جزيء الكحول","جزيء الألدهيد يتأين في الماء، أما جزيء الكحول فلا يتأين","الكتلة المولية للألدهيد أكبر كثيرًا من الكتلة المولية للكحول المقابل"]'::jsonb, 'فهم', 'تفسير مقارنة الذائبية', 'صعب', 'الكتاب ص 179 — ذائبية الألدهيدات'),
('mcq', 4, 'ماذا يحدث لحمض الإيثانويك عند إذابته في الماء؟', null, null, '["يتأين كليًّا، فلا تبقى في المحلول جزيئات غير متأينة","لا يتأين، بل يذوب فقط بتكوين روابط هيدروجينية","يتفكك منتجًا أيونات OH⁻، فيكون محلوله قاعديًّا","يتأين جزئيًّا منتجًا H₃O⁺ وCH₃COO⁻ في حالة اتزان مع جزيئاته غير المتأينة"]'::jsonb, 'تذكر', 'وصف سلوك في الماء', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 5, 'أيّ العبارات الآتية تصف ذوبان الكيتونات في الماء وصفًا صحيحًا؟', null, null, '["لا تذوب مطلقًا، مثل الألكانات","تذوب إلى حد ما، والأسيتون يذوب بشكل تام","تذوب جميعها بشكل تام مهما طالت سلسلتها","تذوب بالتأين منتجة أيونات الهيدرونيوم"]'::jsonb, 'تذكر', 'وصف وتفسير الذائبية', 'متوسط', 'الكتاب ص 179 — ذائبية الكيتونات'),
('mcq', 6, 'الألكانات مركبات غير قطبية لا تذوب في الماء. حمض الإيثانويك CH₃COOH عالي الذوبان في الماء، بينما حمض البالمتيك CH₃(CH₂)₁₄COOH غير ذائب فيه. ما التفسير الأنسب لذلك؟', null, null, '["حمض البالمتيك لا يحتوي على مجموعة كربوكسيل، فلا يكوّن روابط هيدروجينية مع الماء","سلسلته الهيدروكربونية الطويلة غير القطبية تطغى على أثر مجموعة الكربوكسيل القطبية","حمض البالمتيك يتأين كليًّا في الماء، فتترسب أيوناته على شكل مادة صلبة","حمض الإيثانويك غير قطبي، أما حمض البالمتيك فقطبي جدًا لكبر جزيئه"]'::jsonb, 'فهم', 'تفسير الذائبية', 'صعب', 'الكتاب ص 204 — التفكير الناقد (س64)'),
('mcq', 7, 'يبين الشكل الآتي حمضين كربوكسيليين متقاربين في التركيب. أيّهما يُتوقع أن يكون أكثر قابلية للذوبان في الماء، ولماذا؟', null, '[{"src":"qimg/chem22/c5-l3a-lactic-propanoic.svg","alt":"صيغتان بنائيتان مكثفتان مرقمتان: (1) CH₃–CH₂–C(=O)–OH: سلسلة من ثلاث ذرات كربون، الأخيرة ترتبط بذرة أكسجين برابطة ثنائية وبمجموعة OH. (2) CH₃–CH(OH)–C(=O)–OH: ذرة الكربون الثانية ترتبط من أسفل بمجموعة OH، والذرة الأخيرة ترتبط بذرة أكسجين برابطة ثنائية وبمجموعة OH."}]'::jsonb, '["الحمض (2)؛ لاحتوائه على مجموعة هيدروكسيل إضافية تكوّن روابط هيدروجينية مع الماء","الحمض (1)؛ لأنه يحتوي على عدد أقل من ذرات الأكسجين","الحمض (2)؛ لأن كتلته المولية أكبر من كتلة الحمض (1)","الحمضان متساويان؛ لأن في كل منهما مجموعة كربوكسيل واحدة"]'::jsonb, 'تحليل', 'توقع الذائبية من التركيب', 'متوسط', 'الكتاب ص 180 — حمض اللاكتيك'),
('essay', 1, 'لا تستطيع جزيئات الأسيتون تكوين روابط هيدروجينية بعضها مع بعض، ومع ذلك يذوب الأسيتون في الماء بشكل تام. فسّر ذلك، وارسم مخططًا يوضح الرابطة المتكونة بين جزيء أسيتون وجزيء ماء.', null, null, null, 'فهم', 'تفسير مع رسم', 'سهل', 'الكتاب ص 179 — ذائبية الكيتونات'),
('essay', 2, 'رتّب المركبات الآتية تصاعديًّا بحسب ذائبيتها في الماء: 1-بيوتانول، والبيوتان، والبيوتانال، ثم فسّر هذا الترتيب.', null, null, null, 'فهم', 'ترتيب وتفسير', 'صعب', 'الكتاب ص 179 — ذائبية الألدهيدات مقارنة بالألكانات والكحولات'),
('essay', 3, 'فسّر ذوبان الأحماض الكربوكسيلية الصغيرة مثل حمض الإيثانويك في الماء، ثم فسّر لماذا تكون الأحماض التي تحتوي على مجموعات وظيفية إضافية — مثل حمض اللاكتيك CH₃CH(OH)COOH أو الأحماض ثنائية الكربوكسيل — أكثر قابلية للذوبان في الماء.', null, null, null, 'فهم', 'تفسير الذائبية', 'متوسط', 'الكتاب ص 180 — الأحماض الكربوكسيلية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
