select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'البروبان ألكان غير قطبي لا يحتوي على ذرة أكسجين، فلا تكوّن جزيئات الماء روابط هيدروجينية معه، فهو الأقل ذوبانًا. أما المركبات الثلاثة الأخرى فقطبية، وتكوّن جزيئات الماء روابط هيدروجينية مع ذرات الأكسجين فيها.', '["البروبانال ألدهيد قطبي، وتكوّن جزيئات الماء روابط هيدروجينية مع ذرة أكسجين الكربونيل فيه، فهو أذوب من الألكان.","2-بروبانون (الأسيتون) كيتون قطبي يذوب في الماء بشكل تام.","","حمض البروبانويك قطبي، وتكوّن مجموعة الكربوكسيل فيه روابط هيدروجينية مع الماء، فهو أذوب من الألكان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 2, 0, 'ذرة الأكسجين في مجموعة الكربونيل تجذب ذرات الهيدروجين في جزيئات الماء، فتتكوّن روابط هيدروجينية (الخطوط المتقطعة)، وهذا سبب ذوبان الكيتونات في الماء.', '["","الذوبان لا يكوّن روابط تساهمية جديدة؛ فالخطوط تمثل تجاذبًا بين الجزيئات.","جزيئات الأسيتون لا تكوّن روابط هيدروجينية بعضها مع بعض، والخطوط تصل بين جزيء أسيتون وجزيئي ماء.","الأسيتون لا يتأين في الماء، فلا تتكوّن أيونات هيدرونيوم ترتبط به."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 3, 1, 'يحتوي الكحول على مجموعة ‎–OH فيها ذرة هيدروجين مرتبطة بذرة أكسجين، أما جزيء الألدهيد فلا يحتوي على ذرة هيدروجين مرتبطة بالأكسجين، ويرتبط بالماء فقط عن طريق ذرة أكسجين الكربونيل؛ لذا ذائبيته أقل من ذائبية الكحول.', '["الألدهيدات قطبية لاحتوائها على مجموعة الكربونيل، ولهذا هي أذوب من الألكانات.","","الألدهيدات لا تتأين في الماء؛ فالتأين من خواص الأحماض الكربوكسيلية.","الكتلة المولية للألدهيد أقل قليلًا من كتلة الكحول المقابل (مثلًا 58.08 g/mol للبروبانال و60.09 g/mol لـ1-بروبانول)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 4, 3, 'ما يذوب من الأحماض الكربوكسيلية في الماء يتأين بشكل ضعيف: CH₃COOH(aq) + H₂O(l) ⇌ CH₃COO⁻(aq) + H₃O⁺(aq)، ويكون أيون الحمض السالب في حالة اتزان مع الماء والحمض غير المتأين.', '["الأحماض الكربوكسيلية تتأين بشكل ضعيف، فتبقى معظم جزيئاتها غير متأينة.","حمض الإيثانويك يتأين بشكل ضعيف منتجًا أيونات الهيدرونيوم، ولهذا محلوله حمضي.","الحمض ينقل بروتونًا إلى الماء فينتج H₃O⁺ لا OH⁻، ومحلوله حمضي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 5, 1, 'تكوّن جزيئات الكيتونات روابط هيدروجينية مع جزيئات الماء، لذلك فالكيتونات قابلة للذوبان في الماء إلى حد ما، لكن الأسيتون (2-بروبانون) قابل للذوبان في الماء بشكل تام.', '["الكيتونات قطبية وتكوّن روابط هيدروجينية مع الماء، فهي قابلة للذوبان إلى حد ما بخلاف الألكانات.","","الكيتونات عمومًا قابلة للذوبان إلى حد ما فقط، والذوبان التام صفة الأسيتون.","الكيتونات لا تتأين في الماء؛ وإنما تذوب لتكوينها روابط هيدروجينية مع جزيئاته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 6, 1, 'في كلا الحمضين مجموعة كربوكسيل قطبية تكوّن روابط هيدروجينية مع الماء، لكن في حمض البالمتيك سلسلة طويلة من 15 ذرة كربون غير قطبية لا تتجاذب مع الماء، فتطغى على أثر المجموعة القطبية فلا يذوب.', '["صيغة حمض البالمتيك تنتهي بمجموعة ‎–COOH، فهو يحتوي على مجموعة كربوكسيل.","","الأحماض الكربوكسيلية تتأين بشكل ضعيف، والتأين لا يؤدي إلى الترسيب.","العكس هو الأقرب؛ فحمض الإيثانويك قطبي، وحمض البالمتيك تغلب عليه سلسلته غير القطبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('mcq', 7, 0, 'الحمض (2) حمض اللاكتيك CH₃CH(OH)COOH، وفيه مجموعة هيدروكسيل إضافية تكوّن روابط هيدروجينية إضافية مع الماء؛ وعادة تكون هذه الأحماض أكثر قابلية للذوبان في الماء من الأحماض التي تحتوي على مجموعة كربوكسيل واحدة فقط.', '["","قلة ذرات الأكسجين تعني روابط هيدروجينية أقل مع الماء، فتقل الذائبية لا تزيد.","الحمض (2) أذوب فعلًا، لكن السبب مجموعة OH الإضافية لا الكتلة المولية.","وجود مجموعة وظيفية إضافية كالهيدروكسيل يزيد الذائبية، فهما غير متساويين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('essay', 1, null::int, null, null, 'لا تحتوي جزيئات الأسيتون على ذرة هيدروجين مرتبطة بذرة أكسجين، لذا لا تكوّن روابط هيدروجينية بعضها مع بعض. لكن الأسيتون جزيء قطبي يحتوي على ذرة أكسجين في مجموعة الكربونيل تجذب ذرات الهيدروجين في جزيئات الماء، فتتكوّن روابط هيدروجينية بين الأسيتون والماء، ولذلك يذوب. المخطط: (CH₃)₂C=O ⋯ H–O–H، حيث تمثل النقاط الرابطة الهيدروجينية بين أكسجين الكربونيل وهيدروجين الماء.', '["لا توجد ذرة H مرتبطة بـO في الأسيتون فلا روابط هيدروجينية بين جزيئاته","الأسيتون قطبي وفيه أكسجين كربونيل","ذرات H في الماء تكوّن روابط هيدروجينية مع أكسجين الكربونيل","مخطط صحيح للرابطة الهيدروجينية بين C=O وH–O–H"]'::jsonb, '[]'::jsonb, '[{"element":"لا توجد ذرة H مرتبطة بـO في الأسيتون فلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"الأسيتون قطبي وفيه أكسجين كربونيل","marks":1},{"element":"ذرات H في الماء تكوّن روابط هيدروجينية مع أكسجين الكربونيل","marks":1},{"element":"مخطط صحيح للرابطة الهيدروجينية بين C=O وH–O–H","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: لا توجد ذرة H مرتبطة بـO في الأسيتون فلا روابط هيدروجينية بين جزيئاته؛ الأسيتون قطبي وفيه أكسجين كربونيل؛ ذرات H في الماء تكوّن روابط هيدروجينية مع أكسجين الكربونيل؛ مخطط صحيح للرابطة الهيدروجينية بين C=O وH–O–H"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الرابطة الهيدروجينية بين ذرة H في مجموعة CH₃ وأكسجين الماء","القول إن الأسيتون يتأين في الماء","رسم الرابطة الهيدروجينية خطًّا متصلًا كأنها رابطة تساهمية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.689Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الترتيب: البيوتان < البيوتانال < 1-بيوتانول. التفسير: البيوتان ألكان غير قطبي لا يكوّن روابط هيدروجينية مع الماء فهو الأقل ذوبانًا. البيوتانال قطبي، وتكوّن جزيئات الماء روابط هيدروجينية مع ذرة أكسجين الكربونيل فيه، فهو أذوب من الألكان. 1-بيوتانول يحتوي على مجموعة ‎–OH، فيه ذرة H مرتبطة بذرة O، فيكوّن روابط هيدروجينية مع الماء عن طريق ذرتي H وO معًا، لذا ذوبانيته أكبر من الألدهيد.', '["الترتيب الصحيح: البيوتان < البيوتانال < 1-بيوتانول","البيوتان غير قطبي ولا يكوّن روابط هيدروجينية مع الماء","البيوتانال يكوّن روابط هيدروجينية مع الماء عبر أكسجين الكربونيل فقط","1-بيوتانول يكوّن روابط هيدروجينية عبر H وO في ‎–OH"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح: البيوتان < البيوتانال < 1-بيوتانول","marks":1},{"element":"البيوتان غير قطبي ولا يكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"البيوتانال يكوّن روابط هيدروجينية مع الماء عبر أكسجين الكربونيل فقط","marks":1},{"element":"1-بيوتانول يكوّن روابط هيدروجينية عبر H وO في ‎–OH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الترتيب الصحيح: البيوتان < البيوتانال < 1-بيوتانول؛ البيوتان غير قطبي ولا يكوّن روابط هيدروجينية مع الماء؛ البيوتانال يكوّن روابط هيدروجينية مع الماء عبر أكسجين الكربونيل فقط؛ 1-بيوتانول يكوّن روابط هيدروجينية عبر H وO في ‎–OH"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل البيوتانال أذوب من الكحول","القول إن البيوتانال يكوّن روابط هيدروجينية بين جزيئاته","إهمال التفسير والاكتفاء بالترتيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأحماض الكربوكسيلية مركبات قطبية؛ فمجموعة الكربوكسيل تحتوي على ذرتي أكسجين وذرة H مرتبطة بالأكسجين، فتكوّن روابط هيدروجينية مع جزيئات الماء، ويتأين جزء منها بشكل ضعيف منتجًا أيونات H₃O⁺. وفي حمض الإيثانويك السلسلة الهيدروكربونية قصيرة فلا تعيق الذوبان. أما الأحماض التي تحتوي على مجموعة هيدروكسيل إضافية (اللاكتيك) أو مجموعتي كربوكسيل (الأكساليك، الأديبيك) فلديها مواقع أكثر لتكوين روابط هيدروجينية مع الماء، لذا تكون عادة أكثر قابلية للذوبان من الأحماض التي تحتوي على مجموعة كربوكسيل واحدة فقط.', '["مجموعة الكربوكسيل قطبية وتكوّن روابط هيدروجينية مع الماء","تتأين جزئيًّا في الماء","السلسلة القصيرة لا تعيق الذوبان","المجموعات الإضافية تزيد مواقع الروابط الهيدروجينية فتزيد الذائبية"]'::jsonb, '[]'::jsonb, '[{"element":"مجموعة الكربوكسيل قطبية وتكوّن روابط هيدروجينية مع الماء","marks":1},{"element":"تتأين جزئيًّا في الماء","marks":1},{"element":"السلسلة القصيرة لا تعيق الذوبان","marks":1},{"element":"المجموعات الإضافية تزيد مواقع الروابط الهيدروجينية فتزيد الذائبية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: مجموعة الكربوكسيل قطبية وتكوّن روابط هيدروجينية مع الماء؛ تتأين جزئيًّا في الماء؛ السلسلة القصيرة لا تعيق الذوبان؛ المجموعات الإضافية تزيد مواقع الروابط الهيدروجينية فتزيد الذائبية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير زيادة الذائبية بزيادة الكتلة المولية","القول إن الأحماض الكربوكسيلية تتأين كليًّا","إغفال دور الروابط الهيدروجينية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb)
