('mcq', 1, 'لماذا تكون درجات غليان الألدهيدات أقل من درجات غليان الكحولات التي لها عدد ذرات الكربون نفسه؟', null, null, '["لأن جزيئاتها غير قطبية، فالتجاذب بينها ضعيف جدًا مقارنة بالكحولات","لأن كتلتها المولية أكبر كثيرًا من الكتلة المولية للكحولات المقابلة","لأن جزيئاتها تتأين، فتضعف قوى التجاذب بينها وبين الجزيئات المجاورة","لأن جزيئاتها لا تحتوي على ذرة H مرتبطة بالأكسجين، فلا تكوّن روابط هيدروجينية بينها"]'::jsonb, 'فهم', 'تعليل خاصية', 'سهل', 'الكتاب ص 179 — درجة غليان الألدهيدات'),
('mcq', 2, 'لماذا تُصنَّف الأحماض الكربوكسيلية على أنها أحماض؟', null, null, '["لأنها تتفكك في الماء منتجة أيونات OH⁻","لأنها تتأين في الماء منتجة أيونات الهيدرونيوم H₃O⁺","لأن مجموعة الكربونيل فيها تستقبل البروتونات من جزيئات الماء","لأنها تكوّن روابط هيدروجينية مع جزيئات الماء فقط"]'::jsonb, 'تذكر', 'تعليل خاصية', 'سهل', 'الكتاب ص 180 — حمضية الأحماض الكربوكسيلية (ماذا قرأت؟)'),
('mcq', 3, 'لماذا ينتقل بروتون مجموعة ‎–OH في الحمض الكربوكسيلي إلى جزيء الماء عند ذوبانه؟', null, null, '["لأن ذرتي الأكسجين في مجموعة الكربوكسيل عاليتا الكهروسالبية، فتجذبان الإلكترونات بعيدًا عن ذرة الهيدروجين","لأن ذرة الكربون في مجموعة الكربوكسيل أعلى كهروسالبية من ذرتي الأكسجين","لأن الرابطة بين الكربون والأكسجين في مجموعة الكربونيل أحادية ضعيفة","لأن جزيء الماء لا يحتوي على أزواج من الإلكترونات غير المرتبطة"]'::jsonb, 'فهم', 'تعليل خاصية', 'صعب', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 4, 'يحتوي كل من الإيثانال CH₃CHO وحمض الإيثانويك CH₃COOH على مجموعة الكربونيل، لكن محلول حمض الإيثانويك فقط حمضي. ما سبب ذلك؟', null, null, '["الإيثانال لا يحتوي على رابطة ثنائية C=O، بينما يحتوي عليها الحمض","الإيثانال لا يذوب في الماء مطلقًا، فلا تتكوّن في محلوله أيونات","في الحمض ترتبط بذرة كربون الكربونيل مجموعة ‎–OH تفقد بروتونها، وفي الإيثانال ترتبط بها ذرة H","الكتلة المولية للإيثانال أكبر من الكتلة المولية لحمض الإيثانويك"]'::jsonb, 'فهم', 'تعليل مقارنة', 'صعب', 'الكتاب ص 180، 183 — التقويم 5-3 (س16)'),
('mcq', 5, 'لماذا تُعد الكيتونات مذيبات شائعة للمواد القطبية المعتدلة مثل الشمع والطلاء والغراء؟', null, null, '["لأن الكيتونات مركبات أيونية تتفكك إلى أيونات","لأن الكيتونات غير قطبية تمامًا مثل الألكانات","لأن الكيتونات أكثر نشاطًا كيميائيًّا من الألدهيدات","لأن جزيئات الكيتونات قطبية بسبب احتوائها على مجموعة الكربونيل"]'::jsonb, 'فهم', 'تعليل استعمال من خاصية', 'متوسط', 'الكتاب ص 179 — الكيتونات مذيبات'),
('mcq', 6, 'يبين الجدول الآتي الكتل المولية ودرجات الغليان لثلاثة مركبات. علمًا بأن قوى التجاذب بين الجزيئات القطبية أكبر منها بين الجزيئات غير القطبية المتقاربة معها في الكتلة، وأن الروابط الهيدروجينية أقوى من هذه القوى، ما التفسير الصحيح لكون درجة غليان الأسيتون أعلى من درجة غليان البيوتان وأقل من درجة غليان 2-بروبانول؟', '{"headers":["المركب","الصيغة","الكتلة المولية (g/mol)","درجة الغليان (°C)"],"rows":[["البيوتان","CH₃CH₂CH₂CH₃","58.12","−0.5"],["الأسيتون (2-بروبانون)","CH₃COCH₃","58.08","56"],["2-بروبانول","CH₃CH(OH)CH₃","60.09","82"]]}'::jsonb, null, '["الأسيتون يكوّن روابط هيدروجينية بين جزيئاته، لكنها أضعف قليلًا من روابط البيوتان","الكتلة المولية للأسيتون أكبر كثيرًا من الكتلة المولية للبيوتان","الأسيتون قطبي فتتجاذب جزيئاته أكثر من جزيئات البيوتان، لكن جزيئاته لا تكوّن روابط هيدروجينية بعضها مع بعض","الأسيتون غير قطبي مثل البيوتان، لكنه يحتوي على رابطة ثنائية"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 179 — خواص الكيتونات'),
('mcq', 7, 'يُرش عطر يحتوي على إسترات في أحد أركان غرفة، فتُشمّ رائحته بعد ثوانٍ في أرجاء الغرفة. أيّ خواص الإسترات يفسر ذلك؟', null, null, '["أنها مركبات متطايرة","أنها مركبات أيونية","أنها تتأين في الهواء","أن درجات غليانها مرتفعة جدًا"]'::jsonb, 'تطبيق', 'تعليل استعمال من خاصية', 'متوسط', 'الكتاب ص 181 — الإسترات'),
('essay', 1, 'يبين الشكل الآتي الصيغتين البنائيتين للإيثانال (1) والإيثانول (2). الكتلة المولية للإيثانال 44.05 g/mol ودرجة غليانه 20 °C، والكتلة المولية للإيثانول 46.07 g/mol ودرجة غليانه 78 °C. فسّر الفرق الكبير بين درجتي الغليان رغم تقارب الكتلتين الموليتين.', null, '[{"src":"qimg/chem22/c5-l3a-ethanal-ethanol.svg","alt":"صيغتان بنائيتان كاملتان مرقمتان: (1) ذرة كربون ترتبط بثلاث ذرات هيدروجين H، وترتبط بذرة كربون ثانية مرتبطة من أعلى بذرة أكسجين O برابطة ثنائية ومن اليمين بذرة هيدروجين H. (2) سلسلة من ذرتي كربون، الأولى ترتبط بثلاث ذرات هيدروجين والثانية بذرتي هيدروجين، وترتبط الذرة الثانية من اليمين بذرة أكسجين O ترتبط بدورها بذرة هيدروجين H."}]'::jsonb, null, 'فهم', 'تعليل مع بيانات', 'متوسط', 'الكتاب ص 179 — درجة غليان الألدهيدات مقارنة بالكحولات'),
('essay', 2, 'استنتج لماذا تكون المركبات العضوية التي تحتوي على مجموعات كربوكسيل ذات خواص حمضية عندما تذوب في الماء، بينما ليس للألدهيدات الخواص نفسها رغم تشابهها في التركيب. ادعم إجابتك بمعادلة تأين حمض الإيثانويك.', null, null, null, 'فهم', 'استنتاج وتعليل', 'صعب', 'الكتاب ص 180، 183 — التقويم 5-3 (س16)'),
('essay', 3, 'علّل كلًّا مما يأتي: (أ) تُستعمل الكيتونات مذيبات للمواد القطبية المعتدلة كالشمع والطلاء والورنيش. (ب) تنبعث من الإسترات روائح الفواكه والأزهار بسهولة. (ج) يتحول لون ورقة تباع الشمس الزرقاء إلى الأحمر في محلول حمض الإيثانويك.', null, null, null, 'فهم', 'تعليل خواص', 'سهل', 'الكتاب ص 179–181 — خواص مركبات الكربونيل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
