select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'لا تستطيع جزيئات الألدهيد تكوين روابط هيدروجينية بعضها مع بعض لأنها لا تحتوي على ذرات هيدروجين مرتبطة مباشرة مع ذرة الأكسجين؛ لذلك تكون درجة غليانها أقل من درجة غليان الكحولات التي لها عدد ذرات الكربون نفسه.', '["جزيء الألدهيد قطبي لاحتوائه على مجموعة الكربونيل.","الكتلة المولية للألدهيد أقل قليلًا من الكحول المقابل، وزيادة الكتلة لو حدثت ترفع درجة الغليان لا تخفضها.","الألدهيدات لا تتأين، والتأين ليس سبب انخفاض درجة الغليان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('mcq', 2, 1, 'تتأين الأحماض الكربوكسيلية في المحاليل المائية بشكل ضعيف منتجة أيونات الهيدرونيوم H₃O⁺، ولهذا تعد أحماضًا وتحوّل ورقة تباع الشمس الزرقاء إلى حمراء.', '["إنتاج أيونات OH⁻ من صفات القواعد، أما الحمض فينتج H₃O⁺.","","الحمض الكربوكسيلي يمنح البروتون للماء لا يستقبله منه.","الروابط الهيدروجينية مع الماء تفسر الذوبان، لكن الحمضية سببها التأين وإنتاج H₃O⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('mcq', 3, 0, 'تتأين الأحماض الكربوكسيلية لأن ذرتي الأكسجين فيها ذاتا كهروسالبية عالية، وتجذبان الإلكترونات بعيدًا عن ذرة الهيدروجين في مجموعة ‎–OH، فينتقل البروتون إلى ذرة الأكسجين في جزيء الماء التي لديها زوج من الإلكترونات غير المرتبطة.', '["","ذرة الأكسجين أعلى كهروسالبية من ذرة الكربون، لا العكس.","الرابطة في مجموعة الكربونيل ثنائية، والبروتون المنتقل هو هيدروجين مجموعة OH.","ذرة الأكسجين في الماء لديها أزواج إلكترونات غير مرتبطة، وهي التي تستقبل البروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('mcq', 4, 2, 'الحمضية سببها انتقال بروتون من مجموعة ‎–OH المرتبطة بكربون الكربونيل (مجموعة الكربوكسيل) إلى الماء؛ أما في الإيثانال فذرة الهيدروجين مرتبطة بذرة الكربون لا بالأكسجين، فلا تتأين.', '["كلا المركبين يحتوي على مجموعة الكربونيل C=O؛ فالإيثانال CH₃CHO فيه رابطة ثنائية بين الكربون والأكسجين.","الإيثانال يذوب في الماء لأنه يكوّن روابط هيدروجينية معه، لكنه لا يتأين.","","الكتلة المولية للإيثانال 44.05 g/mol أقل من 60.05 g/mol للحمض، والكتلة لا تحدد الحمضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('mcq', 5, 3, 'جزيئات الكيتونات قطبية بسبب احتوائها على مجموعة الكربونيل؛ لذا يعد الكيتون مذيبًا شائعًا للمواد القطبية المعتدلة، ومنها الشمع والبلاستيك والطلاء والورنيش والغراء.', '["الكيتونات مركبات جزيئية تساهمية لا تتفكك إلى أيونات.","الكيتونات قطبية، والمذيب غير القطبي لا يناسب المواد القطبية.","الكيتونات أقل نشاطًا من الألدهيدات، والنشاط ليس سبب استعمالها مذيبات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.690Z"}'::jsonb),
('mcq', 6, 2, 'الكتل المولية متقاربة، فالفرق سببه قوى التجاذب: البيوتان غير قطبي (−0.5 °C)، والأسيتون قطبي فتجاذب جزيئاته أكبر (56 °C)، لكنه لا يكوّن روابط هيدروجينية بين جزيئاته كما يفعل 2-بروبانول الذي فيه ذرة H مرتبطة بالأكسجين (82 °C).', '["جزيئات الأسيتون لا تكوّن روابط هيدروجينية بعضها مع بعض، والبيوتان لا يكوّن روابط هيدروجينية أصلًا.","الكتلتان متساويتان تقريبًا (58.08 g/mol و58.12 g/mol)، فالفرق ليس سببه الكتلة.","","الأسيتون قطبي لاحتوائه على مجموعة الكربونيل، وهذا سبب ارتفاع درجة غليانه مقارنة بالبيوتان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.691Z"}'::jsonb),
('mcq', 7, 0, 'الإسترات مركبات متطايرة ذات روائح عطرة، فتتبخر جزيئاتها بسرعة وتنتشر في الهواء حتى تصل إلى الأنف؛ ولهذا تُستعمل في العطور والمواد المعطرة.', '["","الإسترات مركبات جزيئية تساهمية قطبية، والمركبات الأيونية صلبة لا تتطاير.","الإسترات لا تتأين، وانتشار الرائحة سببه تبخر الجزيئات لا تكوّن أيونات.","ارتفاع درجة الغليان يقلل التبخر فيبطئ انتشار الرائحة، والإسترات متطايرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.691Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكتلتان الموليتان متقاربتان (فرق 2.02 g/mol)، فلا تفسران الفرق البالغ 58 °C. في الإيثانول ترتبط ذرة هيدروجين مباشرة بذرة الأكسجين (‎–OH)، فتكوّن جزيئاته روابط هيدروجينية قوية بعضها مع بعض تحتاج إلى طاقة أكبر للتغلب عليها. أما الإيثانال فجزيئاته قطبية لكنها لا تحتوي على ذرة H مرتبطة بالأكسجين، فلا تكوّن روابط هيدروجينية بعضها مع بعض، وتكون قوى التجاذب بينها أضعف؛ لذا درجة غليانه أقل.', '["تقارب الكتلتين الموليتين لا يفسر الفرق","الإيثانول فيه H مرتبطة بـO فيكوّن روابط هيدروجينية بين جزيئاته","الإيثانال لا يحتوي على H مرتبطة بـO فلا روابط هيدروجينية بين جزيئاته","الإيثانال قطبي لكن تجاذب جزيئاته أضعف من الروابط الهيدروجينية","الاستنتاج: الطاقة اللازمة للغليان أكبر في الإيثانول"]'::jsonb, '["فرق الكتلتين الموليتين: 46.07 − 44.05 = 2.02 g/mol","فرق درجتي الغليان: 78 − 20 = 58 °C"]'::jsonb, '[{"element":"تقارب الكتلتين الموليتين لا يفسر الفرق","marks":1},{"element":"الإيثانول فيه H مرتبطة بـO فيكوّن روابط هيدروجينية بين جزيئاته","marks":1},{"element":"الإيثانال لا يحتوي على H مرتبطة بـO فلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"الإيثانال قطبي لكن تجاذب جزيئاته أضعف من الروابط الهيدروجينية","marks":1},{"element":"الاستنتاج: الطاقة اللازمة للغليان أكبر في الإيثانول","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: تقارب الكتلتين الموليتين لا يفسر الفرق؛ الإيثانول فيه H مرتبطة بـO فيكوّن روابط هيدروجينية بين جزيئاته؛ الإيثانال لا يحتوي على H مرتبطة بـO فلا روابط هيدروجينية بين جزيئاته؛ الإيثانال قطبي لكن تجاذب جزيئاته أضعف من الروابط الهيدروجينية؛ الاستنتاج: الطاقة اللازمة للغليان أكبر في الإيثانول"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الفرق بأن كتلة الإيثانول أكبر","القول إن ذرة H المرتبطة بالكربون في الإيثانال تكوّن روابط هيدروجينية","القول إن الإيثانال غير قطبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.691Z"}'::jsonb),
('essay', 2, null::int, null, null, 'في مجموعة الكربوكسيل ‎–COOH ترتبط ذرة الهيدروجين بذرة أكسجين، وذرتا الأكسجين ذاتا كهروسالبية عالية تجذبان الإلكترونات بعيدًا عن ذرة الهيدروجين، فينتقل البروتون إلى ذرة الأكسجين في جزيء الماء (التي لديها زوج إلكترونات غير مرتبط) مكوّنًا H₃O⁺: CH₃COOH(aq) + H₂O(l) ⇌ CH₃COO⁻(aq) + H₃O⁺(aq). أما في الألدهيد ‎–CHO فذرة الهيدروجين مرتبطة بذرة الكربون لا بالأكسجين، ولا توجد مجموعة OH، فلا ينتقل بروتون إلى الماء ولا يتكوّن H₃O⁺؛ لذا لا يكون للألدهيد خواص حمضية.', '["في الكربوكسيل H مرتبطة بـO","ذرتا الأكسجين عاليتا الكهروسالبية تجذبان الإلكترونات بعيدًا عن H","المعادلة الموزونة بسهم الاتزان","في الألدهيد H مرتبطة بالكربون فلا تتأين"]'::jsonb, '[]'::jsonb, '[{"element":"في الكربوكسيل H مرتبطة بـO","marks":1},{"element":"ذرتا الأكسجين عاليتا الكهروسالبية تجذبان الإلكترونات بعيدًا عن H","marks":1},{"element":"المعادلة الموزونة بسهم الاتزان","marks":2},{"element":"في الألدهيد H مرتبطة بالكربون فلا تتأين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: في الكربوكسيل H مرتبطة بـO؛ ذرتا الأكسجين عاليتا الكهروسالبية تجذبان الإلكترونات بعيدًا عن H؛ المعادلة الموزونة بسهم الاتزان؛ في الألدهيد H مرتبطة بالكربون فلا تتأين"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الألدهيد غير حمضي لأنه لا يحتوي على C=O","كتابة ناتج التأين OH⁻ بدل H₃O⁺","كتابة سهم باتجاه واحد بدل سهم الاتزان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.691Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) لأن الكيتونات مركبات قطبية لاحتوائها على مجموعة الكربونيل، فتذيب المواد القطبية المعتدلة. (ب) لأن الإسترات مركبات متطايرة رائحتها عطرة، فتتبخر جزيئاتها بسهولة وتصل إلى الأنف. (ج) لأن حمض الإيثانويك يتأين في الماء بشكل ضعيف منتجًا أيونات الهيدرونيوم H₃O⁺ التي تجعل المحلول حمضيًّا.', '["(أ) الكيتونات قطبية لاحتوائها على الكربونيل","(ب) الإسترات متطايرة ذات روائح عطرة","(ج) تأين الحمض جزئيًّا منتجًا H₃O⁺"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) الكيتونات قطبية لاحتوائها على الكربونيل","marks":2},{"element":"(ب) الإسترات متطايرة ذات روائح عطرة","marks":2},{"element":"(ج) تأين الحمض جزئيًّا منتجًا H₃O⁺","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) الكيتونات قطبية لاحتوائها على الكربونيل؛ (ب) الإسترات متطايرة ذات روائح عطرة؛ (ج) تأين الحمض جزئيًّا منتجًا H₃O⁺"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الكيتونات غير قطبية","تعليل الرائحة بأن الإسترات أيونية","القول إن الحمض ينتج OH⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.691Z"}'::jsonb)
