('mcq', 3, 'يبين الشكل الآتي الصيغة البنائية لجزيء الأسبرين. ما المجموعتان الوظيفيتان المرتبطتان بالحلقة؟', null, '[{"src":"qimg/chem22/c5-l3b-aspirin.svg","alt":"صيغة بنائية لحلقة بنزين (سداسي داخله دائرة). ترتبط بالحلقة من أعلى ذرة كربون C ترتبط بذرة أكسجين O برابطة ثنائية وبمجموعة OH برابطة أحادية. وترتبط بالحلقة من الرأس المجاور (أعلى اليمين) ذرة أكسجين O ترتبط بذرة كربون C، وترتبط ذرة الكربون هذه بذرة أكسجين O برابطة ثنائية (إلى الأسفل) وبمجموعة CH₃."}]'::jsonb, '["الكربوكسيل والإستر","الكربوكسيل والإيثر","الهيدروكسيل والكربونيل","الأميد والإستر"]'::jsonb, 'فهم', 'تحديد مجموعات في جزيء', 'متوسط', 'الكتاب ص 183، 201 — الأسبرين (الشكل 5-12، س30)'),
('mcq', 4, 'يبين الشكل الآتي الصيغة البنائية لجزيء الأسيتامينوفين المستعمل لتخفيف الألم. ما المجموعتان الوظيفيتان فيه؟', null, '[{"src":"qimg/chem22/c5-l3b-acetaminophen.svg","alt":"صيغة بنائية لحلقة بنزين (سداسي داخله دائرة). ترتبط بالحلقة من أسفل مجموعة OH. وترتبط بها من أعلى ذرة نيتروجين N تحمل ذرة هيدروجين H، وترتبط ذرة النيتروجين بذرة كربون C ترتبط بذرة أكسجين O برابطة ثنائية (إلى الأعلى) وبمجموعة CH₃."}]'::jsonb, '["الأمين والكيتون","الأمين والهيدروكسيل","الأميد والهيدروكسيل","الأميد والكربوكسيل"]'::jsonb, 'فهم', 'تحديد مجموعات في جزيء', 'متوسط', 'الكتاب ص 182 — الأسيتامينوفين (الجدول 5-11)'),
('mcq', 5, 'أيّ المجموعات الوظيفية الآتية ليست فيها مجموعة كربونيل C=O؟', null, null, '["الكربوكسيل","الأميد","الإستر","الهيدروكسيل"]'::jsonb, 'تذكر', 'تمييز', 'سهل', 'الكتاب ص 169 — الجدول 5-1'),
('mcq', 6, 'أيّ الأزواج الآتية (نوع المركب: مجموعته الوظيفية) صحيح؟', null, null, '["الألدهيدات: الكربوكسيل","الكيتونات: الكربونيل","الإسترات: الإيثر","الأميدات: الأمين"]'::jsonb, 'تذكر', 'مطابقة', 'متوسط', 'الكتاب ص 169 — الجدول 5-1'),
('mcq', 7, 'يبين الشكل الآتي الصيغة البنائية لجزيء الليفودوبا. ما المجموعات الوظيفية الموجودة فيه؟', null, '[{"src":"qimg/chem22/c5-l3b-ldopa.svg","alt":"صيغة بنائية لجزيء الليفودوبا: حلقة بنزين (سداسي داخله دائرة) ترتبط بها مجموعتا OH (في الأسفل وفي أسفل اليمين، على ذرتي كربون متجاورتين). وترتبط بالحلقة من أعلى مجموعة CH₂ ترتبط بمجموعة CH تحمل من أعلى مجموعة NH₂، ثم ترتبط CH بذرة كربون C ترتبط بذرة أكسجين O برابطة ثنائية (إلى الأعلى) وبمجموعة OH (إلى اليمين)."}]'::jsonb, '["الأمين والكربوكسيل والهيدروكسيل","الأميد والكربوكسيل والهيدروكسيل","الأمين والإستر والهيدروكسيل","الأمين والكربونيل والهيدروكسيل"]'::jsonb, 'تحليل', 'تحديد مجموعات في جزيء', 'صعب', 'الكتاب ص 205 — س65a (الليفودوبا)'),
('essay', 1, 'قارن بين كل زوج من المجموعات الوظيفية الآتية بكتابة صيغة كل مجموعة، وذكر ما يميز إحداهما من الأخرى: (أ) الكربوكسيل والإستر (ب) الأميد والأمين (ج) الكربونيل في الألدهيدات والكربونيل في الكيتونات.', null, null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 169، 178–182 — الجدول 5-1'),
('essay', 2, 'اكتب الصيغة البنائية المكثفة لمركب يحتوي على أربع ذرات كربون من كل نوع من الأنواع الآتية، وحدّد المجموعة الوظيفية في كل منها باسمها: (أ) ألدهيد (ب) كيتون (ج) حمض كربوكسيلي (د) إستر (هـ) أميد.', null, null, null, 'تطبيق', 'كتابة صيغ وتحديد مجموعات', 'صعب', 'الكتاب ص 205 — س68 (الجدول 5-1)'),
('essay', 3, 'يبين الشكل الآتي الصيغتين البنائيتين لحمض السلسليك (1) والأسبرين (2) الذي يُحضَّر منه. (أ) حدد المجموعات الوظيفية في كل من المركبين. (ب) أيّ مجموعة وظيفية في حمض السلسليك تغيرت عند تحضير الأسبرين، وإلى أيّ مجموعة تحولت؟ (ج) أيّ مجموعة بقيت دون تغيير؟', null, '[{"src":"qimg/chem22/c5-l3b-salicylic-aspirin.svg","alt":"شكلان مفصولان بخط متقطع. (1) في اليمين: حلقة بنزين (سداسي داخله دائرة) ترتبط بها من أعلى ذرة كربون C ترتبط بذرة O برابطة ثنائية وبمجموعة OH، وترتبط بالرأس المجاور (أعلى اليمين) مجموعة OH مباشرة. (2) في اليسار: حلقة بنزين ترتبط بها من أعلى ذرة كربون C ترتبط بذرة O برابطة ثنائية وبمجموعة OH، وترتبط بالرأس المجاور ذرة أكسجين O ترتبط بذرة كربون C، وترتبط ذرة الكربون هذه بذرة O برابطة ثنائية وبمجموعة CH₃."}]'::jsonb, null, 'تحليل', 'تحليل تغير المجموعات', 'صعب', 'الكتاب ص 183، 201 — الشكل 5-12 وس30')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
