from (values
('mcq', 1, 1, 'تتكون مجموعة الكربوكسيل من مجموعة كربونيل C=O مرتبطة بمجموعة هيدروكسيل ‎–OH، وتكتب غالبًا ‎–COOH، وهي المجموعة الوظيفية للأحماض الكربوكسيلية؛ فاسمها الكربوكسيل.', '["الكربونيل هو C=O فقط، أما ‎–COOH فهي مجموعة كربونيل مرتبطة بمجموعة هيدروكسيل وتسمى الكربوكسيل.","","الهيدروكسيل ‎–OH جزء من المجموعة فقط، والمجموعة كاملة (C=O مع OH) هي الكربوكسيل.","مجموعة الإستر ‎–COO– ترتبط فيها ذرة الأكسجين بمجموعة ألكيل لا بذرة هيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 2, 3, 'في CH₃CH₂CONH₂ ترتبط ذرة النيتروجين (مجموعة NH₂) مباشرة بذرة كربون الكربونيل C=O، وهذه هي مجموعة الأميد الوظيفية؛ أما بقية الصيغ فلا ترتبط فيها ذرة نيتروجين بذرة كربون كربونيل.', '["مجموعة NH₂ هنا مرتبطة بذرة كربون لا ترتبط بأكسجين، فهي مجموعة أمين لا أميد.","ترتبط ذرة كربون الكربونيل هنا بذرة أكسجين ثانية مرتبطة بمجموعة ميثيل، فهي مجموعة إستر.","في الصيغة نيتروجين وأكسجين لكن لا توجد مجموعة كربونيل؛ ففيها مجموعة أمين ومجموعة هيدروكسيل منفصلتان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 3, 0, 'المجموعة العلوية ‎–C(=O)–OH مجموعة كربوكسيل، والمجموعة الأخرى ‎–O–C(=O)–CH₃ ترتبط فيها ذرة كربون الكربونيل بذرة أكسجين مرتبطة بذرة كربون أخرى، فهي مجموعة إستر؛ إذن المجموعتان: الكربوكسيل والإستر.', '["","ذرة الأكسجين المرتبطة بالحلقة ترتبط أيضًا بذرة كربون كربونيل C=O، فالمجموعة إستر وليست إيثرًا.","C=O وOH في الأعلى مرتبطتان بذرة الكربون نفسها فتكونان معًا مجموعة واحدة هي الكربوكسيل، وأُهملت مجموعة الإستر.","لا يحتوي الجزيء على ذرة نيتروجين، فلا توجد فيه مجموعة أميد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 4, 2, 'ترتبط ذرة النيتروجين (‎–NH–) بذرة كربون الكربونيل C=O فتتكون مجموعة الأميد، وترتبط مجموعة ‎–OH بالحلقة مباشرة فهي مجموعة الهيدروكسيل؛ إذن المجموعتان: الأميد والهيدروكسيل.', '["ذرة النيتروجين مرتبطة مباشرة بذرة كربون الكربونيل، فالمجموعتان معًا تكوّنان مجموعة أميد واحدة لا أمينًا وكيتونًا منفصلين.","أُهملت مجموعة الكربونيل المرتبطة بالنيتروجين؛ فالمجموعة ‎–NH–C(=O)– أميد لا أمين.","","مجموعة OH مرتبطة بالحلقة مباشرة لا بذرة كربون كربونيل، فهي هيدروكسيل وليست كربوكسيلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 5, 3, 'مجموعة الهيدروكسيل ‎–OH (مجموعة الكحولات) ذرة أكسجين مرتبطة بذرة هيدروجين فقط ولا تحتوي على C=O، أما الكربوكسيل والأميد والإستر فجميعها تحتوي على مجموعة الكربونيل.', '["الكربوكسيل ‎–COOH مجموعة كربونيل مرتبطة بمجموعة هيدروكسيل، ففيه C=O.","الأميد ‎–CONH– فيه ذرة كربون كربونيل مرتبطة بذرة نيتروجين، ففيه C=O.","الإستر ‎–COO– فيه ذرة كربون كربونيل مرتبطة بذرة أكسجين ثانية، ففيه C=O.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 6, 1, 'المجموعة الوظيفية للكيتونات هي مجموعة الكربونيل C=O الواقعة داخل السلسلة، ولذلك فالزوج «الكيتونات: الكربونيل» صحيح.', '["مجموعة الألدهيدات الوظيفية هي الكربونيل في آخر السلسلة، أما الكربوكسيل فهو مجموعة الأحماض الكربوكسيلية.","","مجموعة الإسترات الوظيفية هي الإستر ‎–COO–، أما الإيثر ‎–O– فمجموعة الإيثرات.","مجموعة الأميدات الوظيفية هي الأميد (نيتروجين مرتبط بكربون الكربونيل)، أما الأمين فمجموعة الأمينات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('mcq', 7, 0, 'تحتوي الصيغة على: NH₂ مرتبطة بذرة كربون مشبعة (أمين)، و‎–C(=O)–OH (كربوكسيل)، ومجموعتي ‎–OH مرتبطتين بالحلقة (هيدروكسيل)؛ إذن المجموعات: الأمين والكربوكسيل والهيدروكسيل.', '["","مجموعة NH₂ مرتبطة بذرة كربون CH غير مرتبطة بأكسجين، فهي أمين لا أميد.","المجموعة ‎–C(=O)–OH تنتهي بذرة هيدروجين لا بمجموعة ألكيل، فهي كربوكسيل لا إستر.","C=O وOH المرتبطتان بذرة الكربون نفسها تكوّنان مجموعة واحدة هي الكربوكسيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الكربوكسيل ‎–COOH: ترتبط ذرة كربون الكربونيل بمجموعة ‎–OH؛ والإستر ‎–COO–R′: ترتبط ذرة كربون الكربونيل بذرة أكسجين مرتبطة بمجموعة ألكيل بدل ذرة الهيدروجين. (ب) الأميد ‎–CO–NH–: ترتبط ذرة النيتروجين بذرة كربون الكربونيل؛ والأمين ‎–NH₂: ترتبط ذرة النيتروجين بذرة كربون لا ترتبط بأكسجين (لا يوجد C=O). (ج) كلاهما C=O؛ في الألدهيدات تقع المجموعة في آخر السلسلة وترتبط ذرة كربونها بذرة هيدروجين (‎–CHO)، وفي الكيتونات تقع داخل السلسلة وترتبط ذرة كربونها بذرتي كربون (R–CO–R′).', '["(أ) ‎–COOH مقابل ‎–COO–R′ مع بيان استبدال H بمجموعة ألكيل","(ب) ‎–CONH– مقابل ‎–NH₂ مع بيان وجود الكربونيل في الأميد فقط","(ج) ‎–CHO في آخر السلسلة مقابل R–CO–R′ داخل السلسلة"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) ‎–COOH مقابل ‎–COO–R′ مع بيان استبدال H بمجموعة ألكيل","marks":2},{"element":"(ب) ‎–CONH– مقابل ‎–NH₂ مع بيان وجود الكربونيل في الأميد فقط","marks":2},{"element":"(ج) ‎–CHO في آخر السلسلة مقابل R–CO–R′ داخل السلسلة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) ‎–COOH مقابل ‎–COO–R′ مع بيان استبدال H بمجموعة ألكيل؛ (ب) ‎–CONH– مقابل ‎–NH₂ مع بيان وجود الكربونيل في الأميد فقط؛ (ج) ‎–CHO في آخر السلسلة مقابل R–CO–R′ داخل السلسلة"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عد مجموعة الإستر مجموعة إيثر لوجود ذرة أكسجين بين ذرتي كربون","الخلط بين الأميد والأمين لاحتواء كليهما على النيتروجين","كتابة مجموعة الألدهيد ‎–COH بدل ‎–CHO"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('essay', 2, null::int, null, null, 'إجابة نموذجية (تقبل صيغ صحيحة أخرى): (أ) CH₃CH₂CH₂CHO (بيوتانال)، المجموعة: الكربونيل في آخر السلسلة. (ب) CH₃COCH₂CH₃ (2-بيوتانون)، المجموعة: الكربونيل داخل السلسلة. (ج) CH₃CH₂CH₂COOH (حمض البيوتانويك)، المجموعة: الكربوكسيل. (د) CH₃COOCH₂CH₃ (إيثانوات الإيثيل)، المجموعة: الإستر. (هـ) CH₃CH₂CH₂CONH₂ (بيوتان أميد)، المجموعة: الأميد.', '["(أ) ألدهيد رباعي الكربون، الكربونيل","(ب) كيتون رباعي الكربون، الكربونيل","(ج) حمض رباعي الكربون، الكربوكسيل","(د) إستر رباعي الكربون، الإستر","(هـ) أميد رباعي الكربون، الأميد"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) ألدهيد رباعي الكربون، الكربونيل","marks":1},{"element":"(ب) كيتون رباعي الكربون، الكربونيل","marks":1},{"element":"(ج) حمض رباعي الكربون، الكربوكسيل","marks":1},{"element":"(د) إستر رباعي الكربون، الإستر","marks":1},{"element":"(هـ) أميد رباعي الكربون، الأميد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) ألدهيد رباعي الكربون، الكربونيل؛ (ب) كيتون رباعي الكربون، الكربونيل؛ (ج) حمض رباعي الكربون، الكربوكسيل؛ (د) إستر رباعي الكربون، الإستر؛ (هـ) أميد رباعي الكربون، الأميد"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة إستر عدد ذرات الكربون فيه في جزء الحمض فقط أربع ذرات مع إضافة مجموعة ألكيل فيصبح أكثر من أربع","وضع مجموعة الكربونيل في الكيتون في آخر السلسلة فيصبح ألدهيدًا","تسمية مجموعة الحمض «كربونيل» بدل «كربوكسيل»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) حمض السلسليك (1): مجموعة كربوكسيل ‎–COOH ومجموعة هيدروكسيل ‎–OH مرتبطة بالحلقة. الأسبرين (2): مجموعة كربوكسيل ‎–COOH ومجموعة إستر ‎–O–CO–CH₃. (ب) تحولت مجموعة الهيدروكسيل المرتبطة بالحلقة إلى مجموعة إستر؛ إذ أصبحت ذرة أكسجينها مرتبطة بذرة كربون كربونيل (‎–O–C(=O)–CH₃). (ج) بقيت مجموعة الكربوكسيل دون تغيير.', '["(أ) المركب (1): كربوكسيل وهيدروكسيل","(أ) المركب (2): كربوكسيل وإستر","(ب) الهيدروكسيل تحولت إلى إستر","(ج) الكربوكسيل لم تتغير"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المركب (1): كربوكسيل وهيدروكسيل","marks":1},{"element":"(أ) المركب (2): كربوكسيل وإستر","marks":1},{"element":"(ب) الهيدروكسيل تحولت إلى إستر","marks":1},{"element":"(ج) الكربوكسيل لم تتغير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) المركب (1): كربوكسيل وهيدروكسيل؛ (أ) المركب (2): كربوكسيل وإستر؛ (ب) الهيدروكسيل تحولت إلى إستر؛ (ج) الكربوكسيل لم تتغير"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية الأكسجين المرتبط بالحلقة في الأسبرين إيثرًا","عد ‎–OH في مجموعة الكربوكسيل مجموعة هيدروكسيل مستقلة","القول إن مجموعة الكربوكسيل هي التي تحولت إلى إستر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.692Z"}'::jsonb)
