from (values
('mcq', 1, 'يبين الشكل الآتي جزيئين من حمض الإيثانويك يرتبطان برابطتين هيدروجينيتين (الخطان المتقطعان). بين أيّ ذرتين تتكون كل رابطة منهما؟', null, '[{"src":"qimg/chem22/c5-l3b-acid-dimer.svg","alt":"جزيئان من حمض الإيثانويك متقابلان. في اليسار: CH₃ ترتبط بذرة C، وترتبط C بذرة O في الأعلى برابطة ثنائية وبذرة O في الأسفل برابطة أحادية، وترتبط ذرة O السفلى بذرة H. وفي اليمين جزيء مماثل معكوس: CH₃ ثم C ترتبط بذرة O في الأسفل برابطة ثنائية وبذرة O في الأعلى برابطة أحادية تحمل ذرة H. يصل خط أزرق متقطع بين ذرة H السفلى للجزيء الأيسر وذرة O ذات الرابطة الثنائية في الجزيء الأيمن، وخط أزرق متقطع آخر بين ذرة H العليا للجزيء الأيمن وذرة O ذات الرابطة الثنائية في الجزيء الأيسر."}]'::jsonb, '["ذرة H في مجموعة CH₃ في جزيء، وذرة O في الجزيء الآخر","ذرة C الكربونيل في جزيء، وذرة O الكربونيل في الجزيء الآخر","ذرة H المرتبطة بالأكسجين في جزيء، وذرة O الكربونيل في الجزيء الآخر","ذرة O الهيدروكسيل في جزيء، وذرة O الهيدروكسيل في الجزيء الآخر"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('mcq', 2, 'ما الذي يمكّن جزيئات الأحماض الكربوكسيلية من تكوين روابط هيدروجينية بعضها مع بعض؟', null, null, '["وجود ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين في مجموعة الكربوكسيل","وجود ذرات هيدروجين كثيرة مرتبطة بذرات الكربون في السلسلة","وجود رابطة ثنائية بين ذرتي كربون متجاورتين في السلسلة","وجود ذرة كربون واحدة مرتبطة بثلاث ذرات أكسجين في المجموعة"]'::jsonb, 'تذكر', 'شرط تكوّن الرابطة', 'سهل', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('mcq', 3, 'أيّ المركبات الآتية تستطيع جزيئاته تكوين روابط هيدروجينية بعضها مع بعض؟', null, null, '["CH₃CHO","CH₃COCH₃","HCOOCH₃","CH₃COOH"]'::jsonb, 'فهم', 'تمييز', 'سهل', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('mcq', 4, 'يبين الشكل الآتي جزيء حمض الإيثانويك مع جزيئي ماء. أيّ العبارات الآتية تصف الروابط المتقطعة وصفًا صحيحًا؟', null, '[{"src":"qimg/chem22/c5-l3b-acid-water.svg","alt":"جزيء حمض الإيثانويك: CH₃ ترتبط بذرة C، وترتبط C بذرة O في الأعلى برابطة ثنائية وبذرة O في الأسفل برابطة أحادية تحمل ذرة H. يمين ذرة H هذه جزيء ماء (O مرتبطة بذرتي H) يصل بينهما خط أزرق متقطع من ذرة H الحمض إلى ذرة O الماء. وفوق الجزيء جزيء ماء ثانٍ (O مرتبطة بذرتي H) يصل خط أزرق متقطع من إحدى ذرتي H فيه إلى ذرة O ذات الرابطة الثنائية في الحمض."}]'::jsonb, '["يرتبط أكسجينا الحمض بأكسجيني جزيئي الماء مباشرة بروابط تساهمية جديدة","يرتبط هيدروجين OH الحمض بأكسجين جزيء ماء، ويرتبط هيدروجين جزيء ماء آخر بأكسجين الكربونيل","ترتبط ذرات هيدروجين مجموعة CH₃ بذرتي أكسجين جزيئي الماء بروابط هيدروجينية","ترتبط ذرتا أكسجين جزيئي الماء بذرة كربون الكربونيل بروابط هيدروجينية"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 179–180 — ذوبان مركبات الكربونيل في الماء'),
('mcq', 5, 'تتكوّن الرابطة الهيدروجينية بين ذرة هيدروجين مرتبطة بذرة أكسجين في جزيء وذرة أكسجين في جزيء آخر. أيّ أزواج الجزيئات الآتية يمكن أن تتكوّن بينها رابطة هيدروجينية؟', null, null, '["CH₃COOH مع CH₃COCH₃","CH₃CHO مع CH₃CHO","CH₃COCH₃ مع CH₃COCH₃","HCOOCH₃ مع CH₃CHO"]'::jsonb, 'تحليل', 'تحليل تراكيب', 'صعب', 'الكتاب ص 179–180 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('mcq', 6, 'لحمض البيوتانويك CH₃CH₂CH₂COOH وإيثانوات الإيثيل CH₃COOCH₂CH₃ الصيغة الجزيئية نفسها C₄H₈O₂، ودرجة غليان الحمض 163.5 °C أما درجة غليان الإستر فهي 77.1 °C. ما سبب هذا الفرق؟', null, null, '["الكتلة المولية للحمض أكبر من الكتلة المولية للإستر","جزيئات الإستر لا تحتوي على ذرات أكسجين، فهي غير قطبية تمامًا","في الحمض ذرة H مرتبطة بالأكسجين فتكوّن جزيئاته روابط هيدروجينية، ولا توجد مثلها في الإستر","يحتوي الإستر على مجموعة كربونيل، أما الحمض فلا يحتوي عليها"]'::jsonb, 'تحليل', 'مقارنة متشكلات', 'صعب', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('mcq', 7, 'يبين الشكل الآتي جزيء حمض البروبانويك، وقد رُقّمت فيه أربع ذرات هيدروجين. أيّ هذه الذرات يمكن أن تكوّن رابطة هيدروجينية مع ذرة أكسجين في جزيء حمض مجاور؟', null, '[{"src":"qimg/chem22/c5-l3b-propanoic-numbered.svg","alt":"صيغة بنائية كاملة لحمض البروبانويك: H–C–C–C(=O)–O–H؛ ذرة الكربون الأولى تحمل ذرتي H (أعلى وأسفل) وذرة H على يسارها، وذرة الكربون الثانية تحمل ذرتي H (أعلى وأسفل)، وذرة الكربون الثالثة ترتبط بذرة O في الأعلى برابطة ثنائية وبذرة O على اليمين ترتبط بذرة H. أرقام حمراء: (1) بجانب ذرة H في الطرف الأيسر المرتبطة بالكربون الأول، (2) بجانب ذرة H العليا على الكربون الثاني، (3) بجانب ذرة H السفلى على الكربون الثاني، (4) بجانب ذرة H في الطرف الأيمن المرتبطة بذرة الأكسجين."}]'::jsonb, '["(1)","(2)","(3)","(4)"]'::jsonb, 'فهم', 'تفسير شكل', 'متوسط', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('essay', 1, 'علمًا بأن الرابطة الهيدروجينية تتكوّن بين ذرة هيدروجين مرتبطة بذرة عالية الكهروسالبية كالأكسجين وذرة أكسجين لديها أزواج إلكترونات غير مرتبطة في جزيء آخر، وضّح بالرسم كيف تتكوّن الروابط الهيدروجينية بين جزيئين من حمض الإيثانويك CH₃COOH، محددًا الذرتين اللتين تشتركان في كل رابطة، ثم بيّن لماذا لا تستطيع جزيئات الإيثانال CH₃CHO تكوين روابط مماثلة بعضها مع بعض.', null, null, null, 'فهم', 'شرح مع رسم', 'متوسط', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('essay', 2, 'رتّب المركبات الآتية تصاعديًّا بحسب درجة الغليان، ثم فسّر الترتيب بدلالة قوى التجاذب بين الجزيئات: حمض الإيثانويك CH₃COOH (الكتلة المولية 60.05 g/mol)، و1-بروبانول CH₃CH₂CH₂OH (60.10 g/mol)، والبروبانال CH₃CH₂CHO (58.08 g/mol)، والبيوتان CH₃CH₂CH₂CH₃ (58.12 g/mol). علمًا بأن درجات غليانها (بلا ترتيب): 118 °C، 97 °C، 48 °C، −0.5 °C، وأن جزيئات الحمض الكربوكسيلي ترتبط بروابط هيدروجينية عبر ذرة H في ‎–OH وذرة أكسجين الكربونيل معًا، فيرتبط كل جزيئين منها برابطتين.', null, null, null, 'تحليل', 'ترتيب وتفسير', 'صعب', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية'),
('essay', 3, 'قال طالب: «بما أن الإسترات والأحماض الكربوكسيلية تحتوي كلتاهما على مجموعة كربونيل وذرتي أكسجين، فإن جزيئاتهما تكوّن روابط هيدروجينية بعضها مع بعض بالقدر نفسه». قوّم هذه العبارة مستعينًا بالصيغتين العامتين للنوعين، وبدرجتي غليان حمض الإيثانويك CH₃COOH (118 °C) وميثانوات الميثيل HCOOCH₃ (31.8 °C)، علمًا بأن لهما الصيغة الجزيئية نفسها C₂H₄O₂.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 179–180، 204 — الأحماض الكربوكسيلية والروابط الهيدروجينية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L3-O09') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يصل كل خط متقطع بين ذرة الهيدروجين في مجموعة ‎–OH لأحد الجزيئين (وهي ذرة H مرتبطة بأكسجين عالي الكهروسالبية فتحمل شحنة موجبة جزئية) وذرة أكسجين الكربونيل C=O في الجزيء الآخر (التي تحمل شحنة سالبة جزئية وأزواجًا من الإلكترونات غير المرتبطة).', '["ذرات H المرتبطة بالكربون لا تكوّن روابط هيدروجينية؛ فالرابطة تحتاج إلى H مرتبطة بذرة عالية الكهروسالبية كالأكسجين.","الرابطة الهيدروجينية تكون عبر ذرة هيدروجين، ولا تتكون بين ذرة كربون وذرة أكسجين.","","لا تتكون رابطة مباشرة بين ذرتي أكسجين؛ فالخط المتقطع يصل ذرة H بذرة O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-14T13:39:20.693Z"}'::jsonb),
('mcq', 2, 0, 'تتطلب الرابطة الهيدروجينية ذرة هيدروجين مرتبطة مباشرة بذرة عالية الكهروسالبية كالأكسجين؛ ومجموعة الكربوكسيل ‎–COOH تحتوي على ذرة H مرتبطة بذرة O، فتنجذب إلى ذرة أكسجين في جزيء مجاور.', '["","ذرات H المرتبطة بالكربون لا تحمل شحنة موجبة جزئية كافية لتكوين روابط هيدروجينية.","الأحماض الكربوكسيلية المشبعة لا تحتوي على C=C، والرابطة الثنائية بين ذرتي كربون لا تكوّن روابط هيدروجينية.","ذرة كربون الكربوكسيل ترتبط بذرتي أكسجين فقط، والرابطة الهيدروجينية تتطلب ذرة H مرتبطة بالأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.693Z"}'::jsonb),
('mcq', 3, 3, 'حمض الإيثانويك CH₃COOH هو الوحيد بين الخيارات الذي يحتوي على ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين (‎–OH في مجموعة الكربوكسيل)، فتستطيع جزيئاته تكوين روابط هيدروجينية بعضها مع بعض.', '["الإيثانال لا يحتوي على ذرة H مرتبطة بالأكسجين، فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض.","الأسيتون لا يحتوي على ذرة H مرتبطة بالأكسجين؛ فهو يكوّن روابط هيدروجينية مع الماء فقط.","في الإستر ترتبط ذرة الأكسجين بمجموعة ميثيل بدل ذرة الهيدروجين، فلا توجد H مرتبطة بالأكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-14T13:39:20.693Z"}'::jsonb),
('mcq', 4, 1, 'تمثل الخطوط المتقطعة رابطتين هيدروجينيتين: الأولى بين ذرة H في مجموعة ‎–OH للحمض وذرة أكسجين جزيء ماء، والثانية بين ذرة H في جزيء ماء آخر وذرة أكسجين الكربونيل في الحمض؛ فالحمض يشارك بذرة الهيدروجين وبذرة الأكسجين معًا.', '["الخطوط المتقطعة روابط هيدروجينية لا تساهمية، وكل منها يمر بذرة هيدروجين.","","ذرات H المرتبطة بالكربون لا تكوّن روابط هيدروجينية، ولا يصل أي خط متقطع إلى CH₃.","لا تتكون رابطة هيدروجينية مع ذرة الكربون؛ فهي تتكون بين ذرة H وذرة O."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-14T13:39:20.693Z"}'::jsonb),
('mcq', 5, 0, 'يلزم لتكوّن الرابطة أن يحتوي أحد الجزيئين على ذرة H مرتبطة بالأكسجين. حمض الإيثانويك فيه ‎–OH، فتنجذب ذرة H فيه إلى ذرة أكسجين الكربونيل في الأسيتون؛ أما بقية الأزواج فلا يحتوي أي من جزيئاتها على ذرة H مرتبطة بالأكسجين.', '["","جزيء الإيثانال لا يحتوي على ذرة H مرتبطة بالأكسجين، فلا تتكوّن رابطة هيدروجينية بين جزيئين منه رغم وجود أكسجين الكربونيل.","جزيء الأسيتون فيه أكسجين كربونيل لكن ليس فيه ذرة H مرتبطة بالأكسجين، فلا تتكوّن رابطة هيدروجينية بين جزيئين منه.","في الإستر ترتبط ذرة الأكسجين بمجموعة ميثيل لا بذرة هيدروجين، والإيثانال كذلك بلا H على الأكسجين؛ فلا يوجد في الزوج من يقدّم ذرة الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.694Z"}'::jsonb),
('mcq', 6, 2, 'المركبان متساويان في الكتلة المولية وكلاهما قطبي، لكن الحمض يحتوي على ‎–OH (ذرة H مرتبطة بالأكسجين) فتكوّن جزيئاته روابط هيدروجينية بعضها مع بعض، أما الإستر فترتبط فيه ذرة الأكسجين بمجموعة ألكيل فلا تكوّن جزيئاته هذه الروابط؛ لذا فدرجة غليان الحمض أعلى كثيرًا.', '["للمركبين الصيغة الجزيئية نفسها، فكتلتاهما الموليتان متساويتان (88.10 g/mol).","يحتوي الإستر على ذرتي أكسجين ومجموعة كربونيل قطبية، لكن لا توجد فيه ذرة H مرتبطة بالأكسجين.","","كلا المركبين يحتوي على مجموعة الكربونيل، فهي ليست سبب الفرق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.694Z"}'::jsonb),
('mcq', 7, 3, 'الذرة (4) هي ذرة الهيدروجين الوحيدة المرتبطة مباشرة بذرة أكسجين (في ‎–OH)؛ والأكسجين عالي الكهروسالبية يجذب إلكترونات الرابطة فتحمل الذرة (4) شحنة موجبة جزئية تنجذب إلى ذرة أكسجين في جزيء مجاور.', '["الذرة (1) مرتبطة بذرة كربون، والرابطة C–H قليلة القطبية فلا تكوّن روابط هيدروجينية.","الذرة (2) مرتبطة بذرة كربون في مجموعة CH₂، فلا تكوّن روابط هيدروجينية.","الذرة (3) مرتبطة بذرة كربون، ولا يكفي قربها من مجموعة الكربوكسيل لتكوين رابطة هيدروجينية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.694Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يُرسم جزيئا الحمض متقابلين: ‎CH₃–C(=O)–O–H ··· O=C(–CH₃)–O–H، وتُرسم رابطتان هيدروجينيتان (خطان متقطعان): الأولى بين ذرة H في مجموعة ‎–OH للجزيء الأول وذرة أكسجين الكربونيل في الجزيء الثاني، والثانية بين ذرة H في ‎–OH للجزيء الثاني وذرة أكسجين الكربونيل في الجزيء الأول. تتكون الرابطة لأن ذرة الأكسجين عالية الكهروسالبية تجذب إلكترونات الرابطة O–H فتصبح ذرة H موجبة جزئيًّا، وتنجذب إلى ذرة أكسجين سالبة جزئيًّا لديها أزواج إلكترونات غير مرتبطة في جزيء آخر. أما الإيثانال فيحتوي على أكسجين الكربونيل لكنه لا يحتوي على ذرة هيدروجين مرتبطة بالأكسجين (ذرات H فيه مرتبطة بالكربون)، فلا تستطيع جزيئاته تكوين روابط هيدروجينية بعضها مع بعض.', '["رسم صحيح لجزيئين بينهما رابطة هيدروجينية واحدة على الأقل","تحديد الذرتين: H في ‎–OH وO الكربونيل في الجزيء الآخر","تفسير: كهروسالبية الأكسجين تجعل H موجبة جزئيًّا تنجذب إلى O سالبة جزئيًّا","الإيثانال لا يحتوي على H مرتبطة بالأكسجين"]'::jsonb, '[]'::jsonb, '[{"element":"رسم صحيح لجزيئين بينهما رابطة هيدروجينية واحدة على الأقل","marks":1},{"element":"تحديد الذرتين: H في ‎–OH وO الكربونيل في الجزيء الآخر","marks":1},{"element":"تفسير: كهروسالبية الأكسجين تجعل H موجبة جزئيًّا تنجذب إلى O سالبة جزئيًّا","marks":1},{"element":"الإيثانال لا يحتوي على H مرتبطة بالأكسجين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: رسم صحيح لجزيئين بينهما رابطة هيدروجينية واحدة على الأقل؛ تحديد الذرتين: H في ‎–OH وO الكربونيل في الجزيء الآخر؛ تفسير: كهروسالبية الأكسجين تجعل H موجبة جزئيًّا تنجذب إلى O سالبة جزئيًّا؛ الإيثانال لا يحتوي على H مرتبطة بالأكسجين"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الرابطة الهيدروجينية بين ذرة H في CH₃ وذرة أكسجين","رسم الرابطة الهيدروجينية بخط متصل كأنها رابطة تساهمية","القول إن الإيثانال لا يكوّن روابط هيدروجينية لأنه غير قطبي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.694Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الترتيب التصاعدي: البيوتان (−0.5 °C) < البروبانال (48 °C) < 1-بروبانول (97 °C) < حمض الإيثانويك (118 °C). التفسير: الكتل المولية متقاربة، فالفرق سببه قوى التجاذب. البيوتان غير قطبي فتجاذب جزيئاته ضعيف. البروبانال قطبي (مجموعة كربونيل) لكن لا يحتوي على H مرتبطة بالأكسجين فلا تكوّن جزيئاته روابط هيدروجينية بعضها مع بعض. 1-بروبانول يكوّن روابط هيدروجينية عبر مجموعة ‎–OH. حمض الإيثانويك يكوّن روابط هيدروجينية عبر ذرة H في ‎–OH وذرة أكسجين الكربونيل معًا، فيرتبط الجزيئان برابطتين، فتكون قوى التجاذب أكبر ودرجة الغليان أعلى.', '["الترتيب الصحيح مع مطابقة درجات الغليان","البيوتان غير قطبي: تجاذب ضعيف","البروبانال قطبي لكن بلا روابط هيدروجينية بين جزيئاته","1-بروبانول يكوّن روابط هيدروجينية عبر ‎–OH","الحمض يكوّن روابط هيدروجينية أقوى عبر OH وأكسجين الكربونيل معًا"]'::jsonb, '[]'::jsonb, '[{"element":"الترتيب الصحيح مع مطابقة درجات الغليان","marks":1},{"element":"البيوتان غير قطبي: تجاذب ضعيف","marks":1},{"element":"البروبانال قطبي لكن بلا روابط هيدروجينية بين جزيئاته","marks":1},{"element":"1-بروبانول يكوّن روابط هيدروجينية عبر ‎–OH","marks":1},{"element":"الحمض يكوّن روابط هيدروجينية أقوى عبر OH وأكسجين الكربونيل معًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الترتيب الصحيح مع مطابقة درجات الغليان؛ البيوتان غير قطبي: تجاذب ضعيف؛ البروبانال قطبي لكن بلا روابط هيدروجينية بين جزيئاته؛ 1-بروبانول يكوّن روابط هيدروجينية عبر ‎–OH؛ الحمض يكوّن روابط هيدروجينية أقوى عبر OH وأكسجين الكربونيل معًا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ترتيب المركبات بحسب الكتلة المولية فقط","القول إن البروبانال يكوّن روابط هيدروجينية بين جزيئاته لاحتوائه على أكسجين","جعل درجة غليان الكحول أعلى من الحمض لاحتوائه على عدد أكبر من ذرات الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-14T13:39:20.694Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. الصيغة العامة للحمض R–COOH وفيها ذرة هيدروجين مرتبطة مباشرة بذرة أكسجين، أما الإستر R–COO–R′ فقد حلت فيه مجموعة ألكيل محل هذه الذرة. تكوين الرابطة الهيدروجينية بين جزيئين يتطلب ذرة H مرتبطة بذرة عالية الكهروسالبية كالأكسجين؛ لذا تكوّن جزيئات الحمض روابط هيدروجينية بعضها مع بعض، ولا تكوّنها جزيئات الإستر (وإن كان قطبيًّا ويستطيع أكسجينه استقبال رابطة هيدروجينية من الماء). والدليل أن المركبين متساويان في الكتلة المولية (الصيغة C₂H₄O₂ نفسها) لكن درجة غليان حمض الإيثانويك (118 °C) أعلى كثيرًا من درجة غليان ميثانوات الميثيل (31.8 °C).', '["الحكم: العبارة غير صحيحة","الحمض R–COOH فيه H مرتبطة بالأكسجين، والإستر R–COO–R′ لا يحتوي عليها","شرط الرابطة الهيدروجينية: H مرتبطة بذرة عالية الكهروسالبية","الاستدلال بدرجتي الغليان مع تساوي الكتلة المولية"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم: العبارة غير صحيحة","marks":1},{"element":"الحمض R–COOH فيه H مرتبطة بالأكسجين، والإستر R–COO–R′ لا يحتوي عليها","marks":1},{"element":"شرط الرابطة الهيدروجينية: H مرتبطة بذرة عالية الكهروسالبية","marks":1},{"element":"الاستدلال بدرجتي الغليان مع تساوي الكتلة المولية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم: العبارة غير صحيحة؛ الحمض R–COOH فيه H مرتبطة بالأكسجين، والإستر R–COO–R′ لا يحتوي عليها؛ شرط الرابطة الهيدروجينية: H مرتبطة بذرة عالية الكهروسالبية؛ الاستدلال بدرجتي الغليان مع تساوي الكتلة المولية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على صحة العبارة لأن المركبين متشكلان","تفسير فرق درجتي الغليان بالكتلة المولية","القول إن الإستر لا يكوّن روابط هيدروجينية مع الماء أيضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
