insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'جزء الحمض هو CH₃CH₂C(=O)– وفيه ثلاث ذرات كربون (مع ذرة كربون الكربونيل) فهو من حمض البروبانويك ويصبح «بروبانوات»، والمجموعة المرتبطة بذرة الأكسجين ‎–CH₃ مجموعة ميثيل؛ فالاسم: بروبانوات الميثيل.', '["","عُكس الجزآن: جزء الحمض (المرتبط بالكربونيل) فيه ثلاث ذرات كربون، والمجموعة المرتبطة بالأكسجين ميثيل.","لم تُحسب ذرة كربون الكربونيل ضمن جزء الحمض؛ فجزء الحمض فيه ثلاث ذرات كربون (بروبانوات).","يُستبدل المقطع «ويك» في اسم الحمض بالمقطع «وات» عند تسمية الإستر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb),
('mcq', 2, 2, 'جزء الحمض هو H–C(=O)– وفيه ذرة كربون واحدة فهو من حمض الميثانويك ويصبح «ميثانوات»، والمجموعة المرتبطة بذرة الأكسجين ‎–CH₂CH₃ إيثيل؛ فالاسم: ميثانوات الإيثيل.', '["عُكس الجزآن: ذرة كربون الكربونيل ترتبط بذرة H فجزء الحمض من حمض الميثانويك، والمجموعة المرتبطة بالأكسجين إيثيل.","المقطع «ويك» خاص باسم الحمض، ويُستبدل به «وات» في اسم الإستر.","","المجموعة المرتبطة بذرة الأكسجين ‎–CH₂CH₃ فيها ذرتا كربون، فهي إيثيل لا ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb),
('mcq', 3, 1, 'جزء الحمض هو الجزء الذي يحتوي على ذرة كربون الكربونيل: ‎–C(=O)–CH₃ وفيه ذرتا كربون (إيثانوات)، والمجموعة المرتبطة بذرة الأكسجين الأخرى CH₃CH₂CH₂CH₂CH₂– فيها خمس ذرات كربون (بنتيل)، مهما كان اتجاه الرسم؛ فالاسم: إيثانوات البنتيل.', '["قُرئت الصيغة من اليسار على أن الجزء الأيسر جزء الحمض؛ والصحيح أن جزء الحمض هو المرتبط بذرة كربون الكربونيل (C=O مع CH₃).","","لم تُحسب ذرة كربون الكربونيل ضمن جزء الحمض؛ فجزء الحمض فيه ذرتا كربون (إيثانوات).","أُخطئ في عدّ ذرات الكربون في المجموعة المرتبطة بذرة الأكسجين؛ ففيها خمس ذرات (بنتيل) لا أربع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb),
('mcq', 4, 3, '«بيوتانوات» تعني أن جزء الحمض مشتق من حمض البيوتانويك (أربع ذرات كربون منها ذرة كربون الكربونيل): CH₃CH₂CH₂COO–، و«الميثيل» مجموعة ‎–CH₃ ترتبط بذرة الأكسجين؛ فالصيغة CH₃CH₂CH₂COOCH₃.', '["هذه صيغة ميثانوات البيوتيل؛ عُكس الجزآن، فجزء الحمض يجب أن يحتوي على أربع ذرات كربون.","كُتبت أربع ذرات كربون إضافة إلى ذرة كربون الكربونيل، فأصبح جزء الحمض خماسي الكربون (بنتانوات).","هذه صيغة كيتون (2-بنتانون)؛ نقصتها ذرة الأكسجين التي تربط جزء الحمض بمجموعة الميثيل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb),
('mcq', 5, 2, 'يُشتق اسم الإستر من اسم الحمض بإبدال «ويك» بـ«وات» ثم اسم الألكيل: ميثانوات البروبيل؛ وصيغته: جزء الحمض HCOO– مرتبط بمجموعة البروبيل ‎–CH₂CH₂CH₃، أي HCOOCH₂CH₂CH₃.', '["عُكس الجزآن؛ فجزء الحمض من حمض الميثانويك (ذرة كربون واحدة) والبروبيل هو المرتبط بالأكسجين.","الصيغة صحيحة لكن الاسم خطأ؛ إذ يُستبدل المقطع «ويك» بالمقطع «وات» في اسم الإستر.","","الاسم صحيح لكن الصيغة لحمض البيوتانويك، وليس فيها مجموعة ألكيل مرتبطة بالأكسجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.696Z"}'::jsonb),
('mcq', 6, 0, 'جزء الحمض CH₃C(=O)O– مشتق من حمض الإيثانويك (ذرتا كربون) فيصبح «إيثانوات»، والمجموعة المرتبطة بذرة الأكسجين ‎–CH₃ ميثيل؛ فالاسم الصحيح إيثانوات الميثيل. وقد عكس الطالب الجزأين.', '["","جزء الحمض CH₃COO– فيه ذرتا كربون (مع ذرة كربون الكربونيل)، فهو إيثانوات لا ميثانوات.","المجموعة المرتبطة بذرة الأكسجين ‎–CH₃ فيها ذرة كربون واحدة، فهي ميثيل لا إيثيل.","حُسبت ذرة كربون الميثيل ضمن جزء الحمض؛ وجزء الحمض فيه ذرتا كربون فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('mcq', 7, 1, 'في المركب (2) جزء الحمض CH₃CH₂C(=O)– فيه ثلاث ذرات كربون (بروبانوات)، والمجموعة المرتبطة بذرة الأكسجين ‎–CH₂CH₂CH₃ بروبيل؛ فهو بروبانوات البروبيل.', '["المركب (1) جزء الحمض فيه ذرتا كربون والمرتبط بالأكسجين بيوتيل، فهو إيثانوات البيوتيل.","","المركب (3) جزء الحمض فيه أربع ذرات كربون والمرتبط بالأكسجين إيثيل، فهو بيوتانوات الإيثيل.","المركب (4) جزء الحمض فيه خمس ذرات كربون والمرتبط بالأكسجين ميثيل، فهو بنتانوات الميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) جزء الحمض CH₃COO– من حمض الإيثانويك، والألكيل ميثيل: إيثانوات الميثيل. (2) جزء الحمض HCOO– من حمض الميثانويك، والألكيل بيوتيل: ميثانوات البيوتيل. (3) جزء الحمض CH₃CH₂CH₂CH₂COO– (خمس ذرات كربون) من حمض البنتانويك، والألكيل إيثيل: بنتانوات الإيثيل. (4) جزء الحمض CH₃CH₂COO– من حمض البروبانويك، والألكيل بيوتيل: بروبانوات البيوتيل.', '["(1) إيثانوات الميثيل","(2) ميثانوات البيوتيل","(3) بنتانوات الإيثيل","(4) بروبانوات البيوتيل"]'::jsonb, '[]'::jsonb, '[{"element":"(1) إيثانوات الميثيل","marks":1},{"element":"(2) ميثانوات البيوتيل","marks":1},{"element":"(3) بنتانوات الإيثيل","marks":1},{"element":"(4) بروبانوات البيوتيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (1) إيثانوات الميثيل؛ (2) ميثانوات البيوتيل؛ (3) بنتانوات الإيثيل؛ (4) بروبانوات البيوتيل"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم حساب ذرة كربون الكربونيل ضمن جزء الحمض (تسمية (3) بيوتانوات الإيثيل)","عكس ترتيب الجزأين فيُسمى (2) بيوتانوات الميثيل","إبقاء المقطع «ويك» بدل «وات»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) HCOOCH₂CH₂CH₂CH₂CH₂CH₃، من حمض الميثانويك. (ب) CH₃CH₂CH₂CH₂CH₂COOCH₂CH₃ أي CH₃(CH₂)₄COOCH₂CH₃، من حمض الهكسانويك. (ج) CH₃COOCH₂CH₂CH₂CH₃، من حمض الإيثانويك. (د) CH₃CH₂CH₂COOCH₂CH₂CH₃، من حمض البيوتانويك.', '["(أ) HCOOCH₂CH₂CH₂CH₂CH₂CH₃ — حمض الميثانويك","(ب) CH₃(CH₂)₄COOCH₂CH₃ — حمض الهكسانويك","(ج) CH₃COOCH₂CH₂CH₂CH₃ — حمض الإيثانويك","(د) CH₃CH₂CH₂COOCH₂CH₂CH₃ — حمض البيوتانويك"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) HCOOCH₂CH₂CH₂CH₂CH₂CH₃ — حمض الميثانويك","marks":1},{"element":"(ب) CH₃(CH₂)₄COOCH₂CH₃ — حمض الهكسانويك","marks":1},{"element":"(ج) CH₃COOCH₂CH₂CH₂CH₃ — حمض الإيثانويك","marks":1},{"element":"(د) CH₃CH₂CH₂COOCH₂CH₂CH₃ — حمض البيوتانويك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) HCOOCH₂CH₂CH₂CH₂CH₂CH₃ — حمض الميثانويك؛ (ب) CH₃(CH₂)₄COOCH₂CH₃ — حمض الهكسانويك؛ (ج) CH₃COOCH₂CH₂CH₂CH₃ — حمض الإيثانويك؛ (د) CH₃CH₂CH₂COOCH₂CH₂CH₃ — حمض البيوتانويك"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة جزء الحمض في (ب) بست ذرات كربون إضافة إلى ذرة الكربونيل","كتابة مجموعة الألكيل على جانب الكربونيل بدل ربطها بذرة الأكسجين","الخلط بين الحمض والكحول اللذين يُشتق منهما الإستر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الإسترات الثلاثة: CH₃CH₂COOCH₃ بروبانوات الميثيل؛ CH₃COOCH₂CH₃ إيثانوات الإيثيل؛ HCOOCH₂CH₂CH₃ ميثانوات البروبيل. تختلف أسماؤها لأن اسم الإستر يعتمد على توزيع ذرات الكربون الأربع بين جزء الحمض (المرتبط بذرة كربون الكربونيل، ويُسمى من الحمض بالمقطع «وات») والمجموعة الألكيلية المرتبطة بذرة الأكسجين؛ فتغيّر هذا التوزيع يعطي مركبات مختلفة (متشكلات بنائية) بأسماء مختلفة.', '["CH₃CH₂COOCH₃ بروبانوات الميثيل","CH₃COOCH₂CH₃ إيثانوات الإيثيل","HCOOCH₂CH₂CH₃ ميثانوات البروبيل","التفسير: توزيع ذرات الكربون بين جزء الحمض والمجموعة الألكيلية"]'::jsonb, '["عدد ذرات الكربون 4: (جزء الحمض، الألكيل) = (3، 1) أو (2، 2) أو (1، 3)","كتابة صيغة كل احتمال وتسميته"]'::jsonb, '[{"element":"CH₃CH₂COOCH₃ بروبانوات الميثيل","marks":1},{"element":"CH₃COOCH₂CH₃ إيثانوات الإيثيل","marks":1},{"element":"HCOOCH₂CH₂CH₃ ميثانوات البروبيل","marks":1},{"element":"التفسير: توزيع ذرات الكربون بين جزء الحمض والمجموعة الألكيلية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: CH₃CH₂COOCH₃ بروبانوات الميثيل؛ CH₃COOCH₂CH₃ إيثانوات الإيثيل؛ HCOOCH₂CH₂CH₃ ميثانوات البروبيل؛ التفسير: توزيع ذرات الكربون بين جزء الحمض والمجموعة الألكيلية"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدراج حمض البيوتانويك ضمن الإسترات لأن صيغته الجزيئية C₄H₈O₂ أيضًا","تكرار المركب نفسه مكتوبًا بترتيب مختلف","إغفال ميثانوات البروبيل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
