from (values
('mcq', 1, 3, 'ترتبط مجموعة NH₂ بذرة كربون الكربونيل فالمركب أميد، وعدد ذرات الكربون في السلسلة ثلاث (منها ذرة كربون الكربونيل) فاسم الألكان بروبان، ثم يضاف المقطع «أميد»: بروبان أميد.', '["لم تُحسب ذرة كربون الكربونيل ضمن السلسلة؛ فالسلسلة فيها ثلاث ذرات كربون.","هذا اسم أمين؛ ومجموعة NH₂ هنا مرتبطة بذرة كربون الكربونيل فالمركب أميد.","حُسبت ذرة النيتروجين ذرة كربون؛ فعدد ذرات الكربون ثلاث فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('mcq', 2, 1, 'عدد ذرات الكربون = ذرة CH₃ + أربع ذرات في (CH₂)₄ + ذرة كربون الكربونيل = 6، فاسم الألكان هكسان، ويضاف المقطع «أميد»: هكسان أميد.', '["حُسبت ذرات الكربون داخل CH₃(CH₂)₄ فقط (خمس) ولم تُحسب ذرة كربون الكربونيل.","","حُسب الرقم 4 في (CH₂)₄ وحده عددًا لذرات الكربون؛ والصحيح 1 + 4 + 1 = 6.","حُسبت ذرة النيتروجين ذرة كربون؛ فعدد ذرات الكربون ست فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('mcq', 3, 2, 'السلسلة فيها ذرتا كربون (إيثان) وترتبط ذرة كربون الكربونيل بمجموعة NH₂، فالاسم النظامي إيثان أميد، واسمه الشائع أسيتاميد المشتق من الاسم الشائع لحمض الأسيتيك.', '["لم تُحسب ذرة كربون الكربونيل؛ ففي السلسلة ذرتا كربون.","ترتبط بذرة كربون الكربونيل مجموعة NH₂ لا OH، فالمركب أميد لا حمض.","","ترتبط بذرة كربون الكربونيل مجموعة NH₂ لا ذرة H، فالمركب أميد لا ألدهيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('mcq', 4, 0, 'هبتان أميد سلسلته سبع ذرات كربون منها ذرة كربون الكربونيل: CH₃ + (CH₂)₅ + C(=O) = 7 ذرات، وترتبط ذرة كربون الكربونيل بمجموعة NH₂؛ فالصيغة CH₃(CH₂)₅CONH₂.', '["","هذه صيغة أوكتان أميد؛ كُتبت سبع ذرات كربون إضافة إلى ذرة كربون الكربونيل.","لا تحتوي هذه الصيغة على مجموعة كربونيل، فهي صيغة أمين لا أميد.","هذه صيغة حمض الهبتانويك؛ فمجموعة OH لم تُستبدل بها مجموعة NH₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.697Z"}'::jsonb),
('mcq', 5, 1, 'في المركب HCONH₂ ذرة كربون واحدة (ذرة كربون الكربونيل) مرتبطة بذرة H وبمجموعة NH₂، فاسم الألكان ميثان ويضاف المقطع «أميد»: ميثان أميد.', '["حُسبت ذرة النيتروجين ذرة كربون؛ والمركب فيه ذرة كربون واحدة فقط.","","الميثانال HCHO ألدهيد؛ أما هنا فترتبط بذرة كربون الكربونيل مجموعة NH₂.","حمض الميثانويك صيغته HCOOH؛ وفي المركب حلت مجموعة NH₂ محل OH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('mcq', 6, 3, 'في الصيغة CH₃CH₂CH₂CH₂CONH₂ أربع ذرات كربون قبل مجموعة CONH₂ وذرة كربون خامسة هي كربون الكربونيل؛ فالسلسلة خماسية (بنتان) والاسم الصحيح بنتان أميد، وخطأ الطالب أنه لم يعدّ ذرة كربون الكربونيل.', '["المجموعة NH₂ مرتبطة بذرة كربون الكربونيل فالمركب أميد، والخطأ في عدد ذرات الكربون.","مجموعة الأميد تقع دائمًا في نهاية السلسلة فلا يلزم رقم، والخطأ في عدد ذرات الكربون.","الطالب لم يعدّ النيتروجين؛ بل أغفل ذرة كربون الكربونيل، فالعدد الصحيح خمس لا ثلاث.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('mcq', 7, 2, 'المركب (3) CH₃(CH₂)₇C(=O)NH₂ أميد عدد ذرات الكربون في سلسلته = 1 (CH₃) + 7 (CH₂)₇ + 1 (ذرة الكربونيل) = 9 (نونان)؛ فاسمه نونان أميد.', '["المركب (1) أميد سلسلته 1 + 6 + 1 = 8 ذرات كربون مع ذرة الكربونيل، فهو أوكتان أميد.","المركب (2) لا يحتوي على مجموعة كربونيل، فمجموعة NH₂ فيه مرتبطة بذرة كربون CH₂ وهو أمين لا أميد.","","المركب (4) أميد سلسلته 1 + 8 + 1 = 10 ذرات كربون مع ذرة الكربونيل، فهو ديكان أميد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('essay', 1, null::int, null, null, '(1) HCONH₂: ذرة كربون واحدة (كربون الكربونيل) ← ميثان أميد. (2) CH₃CH₂CONH₂: 1 + 1 + 1 = 3 ذرات ← بروبان أميد. (3) CH₃(CH₂)₅CONH₂: 1 + 5 + 1 = 7 ذرات ← هبتان أميد. (4) CH₃(CH₂)₆CONH₂: 1 + 6 + 1 = 8 ذرات ← أوكتان أميد. في كل مرة تُحسب ذرة كربون الكربونيل ضمن السلسلة ثم يكتب اسم الألكان متبوعًا بالمقطع «أميد».', '["(1) ميثان أميد","(2) بروبان أميد","(3) هبتان أميد","(4) أوكتان أميد"]'::jsonb, '["عدّ ذرات الكربون في كل صيغة مع ذرة كربون الكربونيل","كتابة اسم الألكان المقابل ثم المقطع «أميد»"]'::jsonb, '[{"element":"(1) ميثان أميد","marks":1},{"element":"(2) بروبان أميد","marks":1},{"element":"(3) هبتان أميد","marks":1},{"element":"(4) أوكتان أميد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (1) ميثان أميد؛ (2) بروبان أميد؛ (3) هبتان أميد؛ (4) أوكتان أميد"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ذرة كربون الكربونيل فيُسمى (3) هكسان أميد","إضافة رقم موقع لمجموعة الأميد","تسمية (1) فورمالدهيد أو ميثانال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) CH₃CONH₂، من حمض الإيثانويك. (ب) CH₃CH₂CH₂CH₂CONH₂ أي CH₃(CH₂)₃CONH₂، من حمض البنتانويك. (ج) CH₃(CH₂)₆CONH₂، من حمض الأوكتانويك. (د) CH₃(CH₂)₈CONH₂، من حمض الديكانويك. في كل منها حلت مجموعة NH₂ محل مجموعة OH في الحمض.', '["(أ) CH₃CONH₂ — حمض الإيثانويك","(ب) CH₃(CH₂)₃CONH₂ — حمض البنتانويك","(ج) CH₃(CH₂)₆CONH₂ — حمض الأوكتانويك","(د) CH₃(CH₂)₈CONH₂ — حمض الديكانويك"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) CH₃CONH₂ — حمض الإيثانويك","marks":1},{"element":"(ب) CH₃(CH₂)₃CONH₂ — حمض البنتانويك","marks":1},{"element":"(ج) CH₃(CH₂)₆CONH₂ — حمض الأوكتانويك","marks":1},{"element":"(د) CH₃(CH₂)₈CONH₂ — حمض الديكانويك","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) CH₃CONH₂ — حمض الإيثانويك؛ (ب) CH₃(CH₂)₃CONH₂ — حمض البنتانويك؛ (ج) CH₃(CH₂)₆CONH₂ — حمض الأوكتانويك؛ (د) CH₃(CH₂)₈CONH₂ — حمض الديكانويك"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة عدد مجموعات CH₂ يساوي عدد ذرات الكربون ناقص واحد (نسيان ذرة الكربونيل)","كتابة CH₂NH₂ بدل CONH₂","ذكر الكحول بدل الحمض الكربوكسيلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) CH₃CH₂CONH₂، واسمه بروبان أميد (ثلاث ذرات كربون منها ذرة كربون الكربونيل ثم المقطع «أميد»). (ب) في بروبان أميد ترتبط مجموعة NH₂ بذرة كربون الكربونيل فالمجموعة الوظيفية أميد والمركب أميد، أما CH₃CH₂CH₂NH₂ فترتبط فيه NH₂ بذرة كربون لا ترتبط بأكسجين (لا توجد مجموعة كربونيل) فالمجموعة أمين والمركب أمين، مع أن لكليهما ثلاث ذرات كربون. (ج) CH₃CH₂CH₂CONH₂، واسمه بيوتان أميد.', '["(أ) CH₃CH₂CONH₂ بروبان أميد","(ب) الأميد فيه NH₂ على كربون الكربونيل، والأمين بلا كربونيل","(ج) CH₃CH₂CH₂CONH₂ بيوتان أميد"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) CH₃CH₂CONH₂ بروبان أميد","marks":2},{"element":"(ب) الأميد فيه NH₂ على كربون الكربونيل، والأمين بلا كربونيل","marks":2},{"element":"(ج) CH₃CH₂CH₂CONH₂ بيوتان أميد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) CH₃CH₂CONH₂ بروبان أميد؛ (ب) الأميد فيه NH₂ على كربون الكربونيل، والأمين بلا كربونيل؛ (ج) CH₃CH₂CH₂CONH₂ بيوتان أميد"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية CH₃CH₂CONH₂ إيثان أميد بإغفال ذرة كربون الكربونيل","عدّ CH₃CH₂CH₂NH₂ أميدًا لاحتوائه على NH₂","استبدال ذرة أكسجين الكربونيل بمجموعة NH₂ بدل مجموعة OH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb)
