('mcq', 3, 'ما المعادلة التي تمثل تأين حمض الميثانويك HCOOH في الماء؟', null, null, '["HCOOH + H₂O ⇌ COOH⁻ + H₃O⁺","HCOOH ⇌ HCO⁺ + OH⁻","HCOOH + H₂O → HCOO⁻ + H₃O⁺","HCOOH + H₂O ⇌ HCOO⁻ + H₃O⁺"]'::jsonb, 'تطبيق', 'كتابة معادلة', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 4, 'يتأين حمض الإيثانويك في الماء بشكل ضعيف: CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺. أيّ الدقائق الآتية يكون تركيزه هو الأكبر في محلول الحمض عند الاتزان (باستثناء جزيئات الماء)؟', null, null, '["أيونات CH₃COO⁻ الناتجة عن التأين","أيونات H₃O⁺ الناتجة عن التأين","جزيئات CH₃COOH غير المتأينة","أيونات OH⁻ الناتجة عن تأين الماء"]'::jsonb, 'فهم', 'تفسير اتزان التأين', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 5, 'في معادلة تأين حمض الإيثانويك CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺ يدل السهم المزدوج على حدوث تفاعل عكسي أيضًا. ما الذي يحدث في هذا التفاعل العكسي؟', null, null, '["يعطي H₃O⁺ بروتونًا للأيون CH₃COO⁻ فيتكوّن CH₃COOH وH₂O","يتحد CH₃COO⁻ وH₃O⁺ فيتكوّن ملح صلب يترسب في قاع الإناء","يتفكك H₃O⁺ إلى غاز الهيدروجين وجزيء OH⁻","يفقد CH₃COO⁻ بروتونًا آخر فيتكوّن CH₂COO²⁻"]'::jsonb, 'فهم', 'تفسير معادلة التأين', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 6, 'عند تأين جزيء حمض الإيثانويك CH₃COOH في الماء، كم ذرة هيدروجين من ذراته الأربع تنتقل إلى جزيء الماء، ولماذا؟', null, null, '["أربع ذرات، لأن جميع ذرات الهيدروجين في الحمض متماثلة","ذرة واحدة، هي ذرة H المرتبطة بأكسجين مجموعة الكربوكسيل","ثلاث ذرات، هي ذرات H المرتبطة بذرة الكربون في CH₃","ذرتان، لأن مجموعة الكربوكسيل فيها ذرتا أكسجين"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('mcq', 7, 'الأحماض التي تحتوي على مجموعتي كربوكسيل أو أكثر تكون عادة أكثر حمضية من الأحماض التي تحتوي على مجموعة كربوكسيل واحدة. أيّ المركبات الآتية يُتوقع أن يكون محلوله المائي الأكثر حمضية عند التركيز نفسه؟', null, null, '["CH₃COOH","CH₃CH₂OH","HOOC–COOH","CH₃CHO"]'::jsonb, 'تطبيق', 'مقارنة الحمضية', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('essay', 1, 'اكتب معادلة تأين كل من حمض الميثانويك HCOOH وحمض البروبانويك CH₃CH₂COOH في الماء، وحدّد في كل معادلة أيون الحمض السالب وأيون الهيدرونيوم، ثم فسّر استعمال السهم ⇌ في المعادلتين.', null, null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية'),
('essay', 2, 'في تجربة، وُضعت ثلاثة محاليل مائية بتراكيز متساوية للإيثانول CH₃CH₂OH، والإيثانال CH₃CHO، وحمض الإيثانويك CH₃COOH، وأضيفت قطرة من كل محلول إلى ورقة تباع الشمس زرقاء. توقع ما يحدث لكل ورقة، وفسّر الخاصية الحمضية للمحلول الذي غيّر لون الورقة مستعينًا بمعادلة تأينه، وبيّن سبب انتقال البروتون.', null, null, null, 'فهم', 'توقع وتفسير', 'صعب', 'الكتاب ص 180، 183 — تأين الأحماض الكربوكسيلية (س16)'),
('essay', 3, 'قال طالب: «يحتوي جزيء حمض البيوتانويك CH₃CH₂CH₂COOH على ثماني ذرات هيدروجين، لذا يطلق كل جزيء منه ثمانية بروتونات عندما يذوب في الماء، ويتأين تأينًا تامًّا». قوّم هذه العبارة، واكتب معادلة التأين الصحيحة.', null, null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 180 — تأين الأحماض الكربوكسيلية')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C5-L3-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يتأين حمض الإيثانويك جزئيًّا: ينتقل بروتون مجموعة ‎–OH إلى جزيء الماء فيتكون أيون الحمض السالب CH₃COO⁻ وأيون الهيدرونيوم H₃O⁺، في حالة اتزان: CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺.', '["السهم الأحادي يعني تأينًا تامًّا، وحمض الإيثانويك يتأين بشكل ضعيف ويصل إلى حالة اتزان (⇌).","","هذه المعادلة تجعل الحمض يستقبل بروتونًا من الماء، والصحيح أن الحمض يعطي بروتونه للماء فيتكون H₃O⁺.","البروتون المنتقل هو ذرة H في مجموعة ‎–OH لا ذرة H المرتبطة بالكربون في CH₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('mcq', 2, 0, 'عندما يعطي الحمض بروتون مجموعة ‎–OH لجزيء الماء يتكون H₃O⁺، ويبقى من الحمض أيون الحمض السالب CH₃COO⁻؛ فالمعادلة: CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺.', '["","هذا أيون موجب ينتج لو استقبل الحمض بروتونًا؛ والحمض في هذا التفاعل يعطي بروتونه للماء.","هذا أيون حمض الميثانويك؛ أما أيون حمض الإيثانويك فيحتفظ بمجموعة CH₃ ولا يفقد إلا بروتون ‎–OH.","لا تنفصل مجموعة ‎–OH كاملة؛ بل ينفصل بروتون H⁺ وحده ويبقى الأيون السالب CH₃COO⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-14T13:39:20.698Z"}'::jsonb),
('mcq', 3, 3, 'كما في حمض الإيثانويك، ينتقل بروتون مجموعة ‎–OH في حمض الميثانويك إلى جزيء الماء، فيتكون أيون الحمض السالب HCOO⁻ وأيون الهيدرونيوم H₃O⁺ في حالة اتزان: HCOOH + H₂O ⇌ HCOO⁻ + H₃O⁺.', '["البروتون المنتقل هو ذرة H في ‎–OH، أما ذرة H المرتبطة بالكربون فلا تتأين.","الحمض الكربوكسيلي لا يفقد مجموعة ‎–OH كاملة؛ بل يفقد بروتونًا فيتكون أيون الهيدرونيوم.","السهم الأحادي يعني تأينًا تامًّا، والأحماض الكربوكسيلية تتأين بشكل ضعيف وتصل إلى حالة اتزان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('mcq', 4, 2, 'لأن حمض الإيثانويك يتأين بشكل ضعيف، يبقى معظم جزيئاته دون تأين في حالة اتزان مع قليل من أيونات CH₃COO⁻ وH₃O⁺ (المتساوية في العدد)؛ فأكبر تركيز (بعد الماء) هو لجزيئات CH₃COOH غير المتأينة.', '["لا يتأين إلا جزء صغير من جزيئات الحمض، فتركيز أيونات CH₃COO⁻ صغير مقارنة بالحمض غير المتأين.","كل جزيء متأين يعطي أيون H₃O⁺ واحدًا، ولأن التأين ضعيف يبقى تركيز H₃O⁺ صغيرًا مقارنة بالحمض غير المتأين.","","تأين الحمض ينتج أيونات H₃O⁺ لا OH⁻، فتركيز OH⁻ في المحلول الحمضي صغير جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('mcq', 5, 0, 'التفاعل العكسي عكس الأمامي: ينتقل بروتون من أيون الهيدرونيوم H₃O⁺ إلى أيون الحمض السالب CH₃COO⁻ فيتكوّن جزيء CH₃COOH وجزيء H₂O؛ ولهذا يكون أيون الحمض السالب في حالة اتزان مع الماء والحمض غير المتأين.', '["","التفاعل العكسي يعيد تكوين الحمض غير المتأين والماء، ولا يتكوّن أي ملح صلب.","أيون الهيدرونيوم لا يتفكك إلى غاز؛ بل يعطي بروتونه لأيون الحمض السالب فيعود جزيء ماء.","هذا ليس عكس التفاعل الأمامي؛ ثم إن ذرات H المرتبطة بالكربون لا تنفصل بروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('mcq', 6, 1, 'ذرتا الأكسجين عاليتا الكهروسالبية تجذبان الإلكترونات بعيدًا عن ذرة الهيدروجين في ‎–OH، فينتقل بروتونها وحده إلى زوج الإلكترونات غير المرتبط لذرة أكسجين الماء؛ أما ذرات H الثلاث المرتبطة بالكربون فلا تنتقل. إذن تنتقل ذرة واحدة فقط، هي ذرة H المرتبطة بأكسجين مجموعة الكربوكسيل.', '["ذرات الهيدروجين غير متماثلة: ثلاث منها مرتبطة بالكربون، وواحدة فقط مرتبطة بالأكسجين.","","روابط C–H قليلة القطبية فلا تنتقل ذرات هيدروجينها إلى الماء.","عدد ذرات الأكسجين لا يحدد عدد البروتونات؛ ففي مجموعة الكربوكسيل ذرة H واحدة فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('mcq', 7, 2, 'الإيثانول والإيثانال لا يحتويان على مجموعة كربوكسيل فليس لهما خواص حمضية، وحمض الإيثانويك فيه مجموعة كربوكسيل واحدة، أما حمض الأكساليك HOOC–COOH ففيه مجموعتا كربوكسيل؛ لذا يُتوقع أن يكون محلوله الأكثر حمضية.', '["حمض الإيثانويك حمضي، لكنه يحتوي على مجموعة كربوكسيل واحدة فقط، فهو أقل حمضية من حمض الأكساليك.","الإيثانول لا يحتوي على مجموعة كربوكسيل، ومحلوله لا يغير لون ورقة تباع الشمس الزرقاء.","","الإيثانال يحتوي على مجموعة كربونيل لا كربوكسيل، فليست له خواص حمضية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('essay', 1, null::int, null, null, 'HCOOH + H₂O ⇌ HCOO⁻ + H₃O⁺ (أيون الحمض السالب HCOO⁻، وأيون الهيدرونيوم H₃O⁺). CH₃CH₂COOH + H₂O ⇌ CH₃CH₂COO⁻ + H₃O⁺ (أيون الحمض السالب CH₃CH₂COO⁻، وأيون الهيدرونيوم H₃O⁺). يُستعمل السهم ⇌ لأن الأحماض الكربوكسيلية تتأين بشكل ضعيف؛ فجزء صغير فقط من جزيئاتها يعطي بروتونه للماء، ويكون أيون الحمض السالب في حالة اتزان مع الماء والحمض غير المتأين.', '["معادلة تأين حمض الميثانويك صحيحة","معادلة تأين حمض البروبانويك صحيحة","تحديد أيوني الحمض السالبين وأيون الهيدرونيوم","تفسير ⇌: تأين ضعيف واتزان"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة تأين حمض الميثانويك صحيحة","marks":1},{"element":"معادلة تأين حمض البروبانويك صحيحة","marks":1},{"element":"تحديد أيوني الحمض السالبين وأيون الهيدرونيوم","marks":1},{"element":"تفسير ⇌: تأين ضعيف واتزان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: معادلة تأين حمض الميثانويك صحيحة؛ معادلة تأين حمض البروبانويك صحيحة؛ تحديد أيوني الحمض السالبين وأيون الهيدرونيوم؛ تفسير ⇌: تأين ضعيف واتزان"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة سهم أحادي كأن التأين تام","نزع ذرة هيدروجين مرتبطة بالكربون بدل هيدروجين ‎–OH","كتابة H⁺ وOH⁻ ناتجين بدل H₃O⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يبقى لون الورقتين في محلولي الإيثانول والإيثانال أزرق، ويتحول لون الورقة في محلول حمض الإيثانويك إلى الأحمر. السبب أن الحمض يتأين في الماء: CH₃COOH + H₂O ⇌ CH₃COO⁻ + H₃O⁺، فينتج أيونات الهيدرونيوم التي تحول لون ورقة تباع الشمس الزرقاء إلى الأحمر (وتعطي المحلول مذاقًا حمضيًّا لاذعًا). ينتقل البروتون لأن ذرتي الأكسجين في مجموعة الكربوكسيل ذاتا كهروسالبية عالية فتجذبان الإلكترونات بعيدًا عن ذرة الهيدروجين في ‎–OH، فينتقل البروتون إلى ذرة أكسجين جزيء الماء التي لديها زوج من الإلكترونات غير المرتبطة. أما الإيثانال فلا يحتوي على مجموعة كربوكسيل، فلا يتأين بهذه الطريقة.', '["الإيثانول والإيثانال: لا تغير في اللون","حمض الإيثانويك: يتحول اللون إلى الأحمر","معادلة التأين الصحيحة مع ⇌","تفسير انتقال البروتون بكهروسالبية ذرتي الأكسجين وزوج إلكترونات الماء"]'::jsonb, '[]'::jsonb, '[{"element":"الإيثانول والإيثانال: لا تغير في اللون","marks":1},{"element":"حمض الإيثانويك: يتحول اللون إلى الأحمر","marks":1},{"element":"معادلة التأين الصحيحة مع ⇌","marks":1},{"element":"تفسير انتقال البروتون بكهروسالبية ذرتي الأكسجين وزوج إلكترونات الماء","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الإيثانول والإيثانال: لا تغير في اللون؛ حمض الإيثانويك: يتحول اللون إلى الأحمر؛ معادلة التأين الصحيحة مع ⇌؛ تفسير انتقال البروتون بكهروسالبية ذرتي الأكسجين وزوج إلكترونات الماء"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["توقع أن الإيثانال حمضي لاحتوائه على مجموعة كربونيل","القول إن الحمض يحول الورقة الحمراء إلى زرقاء","كتابة OH⁻ ناتجًا عن تأين الحمض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.699Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة من وجهين: (1) لا يطلق الجزيء إلا بروتونًا واحدًا، هو ذرة الهيدروجين المرتبطة بالأكسجين في مجموعة الكربوكسيل؛ لأن ذرتي الأكسجين ذاتي الكهروسالبية العالية تجذبان الإلكترونات بعيدًا عنها، أما ذرات الهيدروجين السبع المرتبطة بذرات الكربون فلا تتأين. (2) التأين ليس تامًّا؛ فالحمض الكربوكسيلي يتأين بشكل ضعيف ويصل إلى حالة اتزان. المعادلة الصحيحة: CH₃CH₂CH₂COOH + H₂O ⇌ CH₃CH₂CH₂COO⁻ + H₃O⁺.', '["الحكم: العبارة غير صحيحة","بروتون واحد فقط من ‎–OH مع التعليل","التأين ضعيف (اتزان) لا تام","المعادلة الصحيحة مع ⇌"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم: العبارة غير صحيحة","marks":1},{"element":"بروتون واحد فقط من ‎–OH مع التعليل","marks":1},{"element":"التأين ضعيف (اتزان) لا تام","marks":1},{"element":"المعادلة الصحيحة مع ⇌","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة صحيحة تشمل: الحكم: العبارة غير صحيحة؛ بروتون واحد فقط من ‎–OH مع التعليل؛ التأين ضعيف (اتزان) لا تام؛ المعادلة الصحيحة مع ⇌"},{"level":"1–3 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قبول أن جميع ذرات الهيدروجين تتأين","كتابة المعادلة بسهم أحادي","كتابة أيون الحمض السالب بفقد ذرة H من سلسلة الكربون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
