insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C5-L3-O13'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'يُعزى طعم إحدى الفواكه إلى الإستر المبين في الشكل الآتي (هكسانوات الميثيل). ما هذه الفاكهة؟', null, '[{"src":"qimg/chem22/c5-l3b-methyl-hexanoate.svg","alt":"صيغة بنائية مكثفة لإستر: المجموعة CH₃(CH₂)₄ ترتبط بذرة كربون C، وترتبط C من أعلى بذرة أكسجين O برابطة ثنائية، ثم ذرة أكسجين O ثم CH₃، أي CH₃(CH₂)₄–C(=O)–O–CH₃ (هكسانوات الميثيل)."}]'::jsonb, '["الأناناس","التفاح","الفراولة","الموز"]'::jsonb, 'تذكر', 'استدعاء مثال', 'سهل', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('mcq', 2, 'أين توجد أنواع كثيرة من الإسترات في الطبيعة؟', null, null, '["في النفط والغاز الطبيعي","في صخور القشرة الأرضية","في عظام الحيوانات وأصدافها","في الفواكه والأزهار"]'::jsonb, 'تذكر', 'استرجاع حقيقة', 'سهل', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('mcq', 3, 'إلى أيّ أصناف المركبات العضوية يُعزى مصدر الروائح الطبيعية للفواكه؟', null, null, '["خليط من الإسترات والألدهيدات والكحولات","خليط من الألكانات والألكينات غير القطبية","الأميدات والأمينات وحدها","هاليدات الألكيل والإيثرات وحدها"]'::jsonb, 'تذكر', 'استدعاء', 'متوسط', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('mcq', 4, 'لماذا يمكن تصنيع بعض نكهات الفواكه وإنتاجها بكميات كبيرة بسهولة نسبيًّا؟', null, null, '["لأن الإسترات الصناعية تختلف في تركيبها عن الإسترات الطبيعية","لأن سبب بعض هذه النكهات قد يكون تركيب إستر واحد فقط","لأن جميع النكهات الطبيعية مصدرها الأحماض الكربوكسيلية وحدها","لأن الإسترات مركبات غير متطايرة يسهل حفظها في العبوات"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('mcq', 5, 'في تجربة لتحضير إستر، سُخّن خليط من حمض السلسليك والميثانول وقطرات من حمض الكبريتيك المركز في حمام مائي، ثم أُفرغ الخليط فوق كرات قطنية في طبق بتري. ما الغرض من الخطوة الأخيرة؟', null, null, '["قياس درجة غليان الإستر الناتج","التخلص من حمض الكبريتيك قبل التسخين","تحويل الإستر إلى حمض كربوكسيلي وكحول","تمييز الإستر الناتج من رائحته المميزة"]'::jsonb, 'فهم', 'تفسير خطوة تجريبية', 'متوسط', 'الكتاب ص 182 — تجربة تحضير الإستر'),
('mcq', 6, 'تريد شركة أغذية إنتاج نكهة الأناناس صناعيًّا بتصنيع الإستر المسؤول عن هذا الطعم. ما الصيغة البنائية المكثفة لهذا الإستر؟', null, null, '["CH₃COOCH₂CH₂CH₂CH₃","CH₃(CH₂)₄COOCH₃","CH₃CH₂CH₂COOCH₂CH₃","CH₃CH₂CH₂COOCH₃"]'::jsonb, 'تطبيق', 'تطبيق: ربط النكهة بالإستر وصيغته', 'صعب', 'الكتاب ص 181 — الإسترات في النكهات (الشكل 5-11، الجدول 5-10)'),
('mcq', 7, 'قد يختلف طعم نكهة فاكهة صناعية لا تحتوي إلا على الإستر الرئيس المسؤول عن طعم تلك الفاكهة عن طعم الفاكهة الطبيعية. ما التفسير الأنسب لذلك؟', null, null, '["النكهة الطبيعية مزيج من مركبات عديدة، والصناعية فيها الإستر الرئيس فقط","الإستر المصنّع يختلف تركيبه عن الإستر الطبيعي الذي يحمل الاسم نفسه","الإسترات المصنّعة غير متطايرة فلا تصل رائحتها إلى الأنف","الإستر الرئيس يتأين في الماء فيعطي النكهة طعمًا حمضيًّا لاذعًا"]'::jsonb, 'تحليل', 'مقارنة وتفسير', 'صعب', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('essay', 1, 'اشرح دور الإسترات في كل من: (أ) النكهات والروائح الطبيعية للفواكه والأزهار، مع مثالين لفاكهتين واسم الإستر المسؤول عن طعم كل منهما. (ب) النكهات والروائح الصناعية، مع ذكر ثلاثة أنواع من المنتجات تُستعمل فيها الإسترات المصنّعة.', null, null, null, 'فهم', 'شرح', 'متوسط', 'الكتاب ص 181 — الإسترات في النكهات والروائح (الشكل 5-11)'),
('essay', 2, 'في تجربة تحضير الإستر، يُضاف حمض السلسليك والماء والميثانول إلى أنبوب اختبار مع ثلاث قطرات من حمض الكبريتيك المركز، ويُسخَّن الأنبوب في حمام مائي، ثم يُفرغ محتواه فوق كرات قطنية. (أ) ما نوع التفاعل الذي يتكون به الإستر؟ (ب) لماذا يُسخَّن الخليط في حمام مائي ويُحفظ بعيدًا عن اللهب؟ (ج) كيف يُستدل على تكون الإستر، ولماذا تصلح هذه الطريقة؟ (د) لماذا يجب التعامل مع حمض الكبريتيك المركز بحذر؟', null, null, null, 'تطبيق', 'تحليل تجربة', 'متوسط', 'الكتاب ص 182 — تجربة تحضير الإستر'),
('essay', 3, 'قوّم فوائد استعمال الإسترات الصناعية في الأطعمة والمشروبات والعطور ومضارها على المستهلك، مقارنة بالإسترات الطبيعية الموجودة في الفواكه، واذكر رأيك مدعّمًا بسببين.', null, null, null, 'تقويم', 'تقويم وإبداء رأي', 'صعب', 'الكتاب ص 182 — تجربة تحضير الإستر (التحليل 2)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
