from (values
('mcq', 1, 2, 'الإسترات مصدر روائح وطعم كثير من الفواكه؛ إذ يُعزى طعم الفراولة إلى هكسانوات الميثيل CH₃(CH₂)₄COOCH₃، وطعم الأناناس إلى بيوتانوات الإيثيل.', '["طعم الأناناس يُعزى إلى بيوتانوات الإيثيل لا إلى هكسانوات الميثيل.","نكهة التفاح الطبيعية تنتج عن مزيج من جزيئات عضوية مختلفة، ولا تُعزى إلى هكسانوات الميثيل وحده.","","نكهة الموز الطبيعية تنتج عن مزيج من جزيئات عضوية مختلفة، ولا تُعزى إلى هذا الإستر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb),
('mcq', 2, 3, 'الإسترات مركبات قطبية متطايرة روائحها عطرة، وتوجد أنواع كثيرة منها في العطور والنكهات الطبيعية وفي الفواكه والأزهار، فهي مصدر روائح وطعم كثير منها.', '["النفط والغاز الطبيعي مصدر الهيدروكربونات، لا الإسترات ذات الروائح العطرة.","الإسترات مركبات عضوية متطايرة، ولا تكوّن صخور القشرة الأرضية.","العظام والأصداف مصدرها مواد غير عضوية كأملاح الكالسيوم، لا الإسترات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb),
('mcq', 3, 0, 'تُعد الإسترات مصدر روائح وطعم كثير من الفواكه، ويُعزى مصدر الروائح الطبيعية إلى خليط من الإسترات والألدهيدات والكحولات.', '["","الهيدروكربونات ليست مصدر روائح الفواكه؛ فمصدرها خليط من الإسترات والألدهيدات والكحولات.","الأميدات توجد في البروتينات، والأمينات معروفة بروائحها الكريهة لا بروائح الفواكه.","هذه المركبات ليست مصدر الروائح الطبيعية للفواكه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb),
('mcq', 4, 1, 'تنتج النكهات الطبيعية غالبًا عن مزيج من جزيئات عضوية مختلفة منها الإسترات، لكن قد يكون سبب بعض النكهات تركيب إستر واحد فقط؛ لذا يُصنَّع هذا الإستر ويُستعمل في الأطعمة والمشروبات والعطور والشموع العطرية.', '["الإستر المصنّع له تركيب الإستر الطبيعي نفسه، ولا يفسر ذلك سهولة إنتاج النكهة.","","النكهات الطبيعية مصدرها مزيج يشمل الإسترات، ولا يقتصر على الأحماض الكربوكسيلية.","الإسترات مركبات متطايرة، ولهذا تنتشر روائحها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb),
('mcq', 5, 3, 'الإسترات مركبات متطايرة ذات روائح عطرة؛ فبنشر ناتج التفاعل على كرات قطنية تتطاير جزيئات الإستر ويمكن تمييزه من رائحته المميزة وتسجيل الملاحظات حولها.', '["الكرات القطنية لا تقيس درجة الغليان؛ بل تنشر السائل فتسهل ملاحظة رائحته.","هذه الخطوة تأتي بعد التسخين، وغرضها ملاحظة الرائحة لا التخلص من الحمض.","وضع الخليط على القطن لا يحلل الإستر؛ بل يسمح بتطاير الإستر وشم رائحته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.700Z"}'::jsonb),
('mcq', 6, 2, 'يُعزى طعم الأناناس إلى بيوتانوات الإيثيل: جزء الحمض من حمض البيوتانويك CH₃CH₂CH₂COO– (أربع ذرات كربون منها ذرة الكربونيل)، ومجموعة الإيثيل ‎–CH₂CH₃ مرتبطة بذرة الأكسجين؛ فالصيغة CH₃CH₂CH₂COOCH₂CH₃.', '["هذه صيغة إيثانوات البيوتيل؛ عُكس الجزآن، فجزء الحمض في إستر الأناناس رباعي الكربون والمرتبط بالأكسجين إيثيل.","هذه صيغة هكسانوات الميثيل الذي يُعزى إليه طعم الفراولة لا الأناناس.","","هذه صيغة بيوتانوات الميثيل؛ المجموعة المرتبطة بالأكسجين في إستر الأناناس إيثيل لا ميثيل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.701Z"}'::jsonb),
('mcq', 7, 0, 'مصدر الروائح والنكهات الطبيعية خليط من الإسترات والألدهيدات والكحولات وغيرها، أما النكهة الصناعية التي تحتوي على الإستر الرئيس وحده فتفتقد بقية مكونات هذا الخليط، فقد يختلف طعمها قليلًا مع أن الإستر المصنّع مماثل للطبيعي في تركيبه.', '["","المركب الواحد له التركيب نفسه سواء أكان طبيعيًّا أم مصنّعًا.","الإسترات متطايرة سواء أكانت طبيعية أم مصنّعة.","الإسترات لا تحتوي على ذرة H مرتبطة بالأكسجين، فلا تتأين كالأحماض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-14T13:39:20.701Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) الإسترات مركبات قطبية متطايرة ذات روائح عطرة، وتوجد بكثرة في الفواكه والأزهار وهي مصدر روائح كثير منها وطعمها؛ فطعم الفراولة يُعزى إلى هكسانوات الميثيل CH₃(CH₂)₄COOCH₃، وطعم الأناناس إلى بيوتانوات الإيثيل CH₃CH₂CH₂COOCH₂CH₃. وتنتج النكهات الطبيعية غالبًا عن مزيج من جزيئات مختلفة (إسترات وألدهيدات وكحولات). (ب) لأن سبب بعض النكهات قد يكون إسترًا واحدًا، تُصنَّع الإسترات وتُضاف إلى منتجات كثيرة، مثل: الأطعمة، والمشروبات، والعطور، والشموع العطرية، والمواد المعطرة الأخرى.', '["الإسترات متطايرة ذات روائح عطرة ومصدر روائح الفواكه والأزهار","الفراولة: هكسانوات الميثيل","الأناناس: بيوتانوات الإيثيل","سبب تصنيعها: بعض النكهات سببها إستر واحد","ثلاثة منتجات (أطعمة، مشروبات، عطور، شموع عطرية)"]'::jsonb, '[]'::jsonb, '[{"element":"الإسترات متطايرة ذات روائح عطرة ومصدر روائح الفواكه والأزهار","marks":1},{"element":"الفراولة: هكسانوات الميثيل","marks":1},{"element":"الأناناس: بيوتانوات الإيثيل","marks":1},{"element":"سبب تصنيعها: بعض النكهات سببها إستر واحد","marks":1},{"element":"ثلاثة منتجات (أطعمة، مشروبات، عطور، شموع عطرية)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: الإسترات متطايرة ذات روائح عطرة ومصدر روائح الفواكه والأزهار؛ الفراولة: هكسانوات الميثيل؛ الأناناس: بيوتانوات الإيثيل؛ سبب تصنيعها: بعض النكهات سببها إستر واحد؛ ثلاثة منتجات (أطعمة، مشروبات، عطور، شموع عطرية)"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الإسترين بين الفراولة والأناناس","القول إن كل نكهة طبيعية سببها إستر واحد فقط","ذكر الأسمدة أو حفظ العينات استعمالًا للإسترات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-14T13:39:20.701Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) تفاعل تكثف بين حمض كربوكسيلي (حمض السلسليك) وكحول (الميثانول). (ب) لأن الميثانول مادة قابلة للاشتعال وقد يسبب انفجارًا قرب مصدر اللهب، والحمام المائي يسخّن الخليط تسخينًا هادئًا متجانسًا. (ج) بشمّ الرائحة المميزة المنبعثة من الكرات القطنية؛ لأن الإسترات مركبات متطايرة ذات روائح عطرة تختلف عن رائحة المواد المتفاعلة. (د) لأنه قد يسبب حروقًا.', '["(أ) تفاعل تكثف بين حمض وكحول","(ب) الميثانول قابل للاشتعال/الانفجار","(ج) الرائحة المميزة لأن الإسترات متطايرة عطرة","(د) حمض الكبريتيك المركز يسبب حروقًا"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تفاعل تكثف بين حمض وكحول","marks":1},{"element":"(ب) الميثانول قابل للاشتعال/الانفجار","marks":1},{"element":"(ج) الرائحة المميزة لأن الإسترات متطايرة عطرة","marks":2},{"element":"(د) حمض الكبريتيك المركز يسبب حروقًا","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة صحيحة تشمل: (أ) تفاعل تكثف بين حمض وكحول؛ (ب) الميثانول قابل للاشتعال/الانفجار؛ (ج) الرائحة المميزة لأن الإسترات متطايرة عطرة؛ (د) حمض الكبريتيك المركز يسبب حروقًا"},{"level":"1–4 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية التفاعل تفاعل إضافة","القول إن الحمام المائي يستعمل لتبريد الخليط","الاستدلال على الإستر بتغير لون ورقة تباع الشمس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-14T13:39:20.701Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الفوائد: يمكن إنتاج الإسترات الصناعية بكميات كبيرة وبتكلفة أقل، وتتوافر طوال العام، ويكون طعمها ورائحتها ثابتين في كل دفعة، ولأن بعض النكهات سببها إستر واحد يمكن تقليدها بدقة دون الحاجة إلى كميات كبيرة من الفاكهة. المضار: النكهة الطبيعية مزيج من مركبات عديدة (إسترات وألدهيدات وكحولات) فقد لا تطابقها النكهة الصناعية تمامًا؛ وقد يتحسس بعض الأشخاص من بعض الإضافات؛ وقد تشجع النكهات الصناعية على استهلاك أطعمة ومشروبات قليلة القيمة الغذائية لأنها تعطي طعم الفاكهة دون فوائدها. الرأي (مثال): استعمالها مقبول عند الالتزام بالكميات المسموح بها، لأن الإستر المصنّع مماثل في تركيبه للإستر الطبيعي، لكن لا ينبغي أن تحل المنتجات المنكهة محل الفاكهة الطبيعية لأنها لا تحتوي على قيمتها الغذائية.', '["فائدتان صحيحتان على الأقل","مضرتان صحيحتان على الأقل","رأي مدعّم بسببين منطقيين"]'::jsonb, '[]'::jsonb, '[{"element":"فائدتان صحيحتان على الأقل","marks":2},{"element":"مضرتان صحيحتان على الأقل","marks":2},{"element":"رأي مدعّم بسببين منطقيين","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"إجابة كاملة صحيحة تشمل: فائدتان صحيحتان على الأقل؛ مضرتان صحيحتان على الأقل؛ رأي مدعّم بسببين منطقيين"},{"level":"1–5 درجات","description":"إجابة صحيحة جزئيًّا: تُمنح الدرجات للعناصر الصحيحة وفق توزيع الدرجات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الادعاء بأن الإستر الصناعي يختلف كيميائيًّا عن الطبيعي المماثل له في التركيب","ذكر فوائد دون مضار أو العكس","إبداء رأي دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-14T13:39:20.701Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
